INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饭店", "is_correct": true, "explanation": "“饭店”是可以住宿的旅馆，“五星级”也是旅馆的评级，符合语境。"}, {"text": "文具店", "is_correct": false, "explanation": "语义：文具店卖文具，没有可出租的房间，“房间很贵”不合。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市不出租房间，不能说房间很贵。"}, {"text": "书店", "is_correct": false, "explanation": "搭配：“五星级”是旅馆的评级，不用于书店。"}], "explanations": {"饭店": "“饭店”是可以住宿的旅馆，“五星级”也是旅馆的评级，符合语境。", "文具店": "语义：文具店卖文具，没有可出租的房间，“房间很贵”不合。", "超市": "语义：超市不出租房间，不能说房间很贵。", "书店": "搭配：“五星级”是旅馆的评级，不用于书店。"}, "sentence_index": 6, "correct_answer": "饭店"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生在饭店给病人看病。", "explanation": "这里应该用〈医院〉。给病人看病要在医院；饭店是住宿的旅馆，不是看病的地方。"}, {"text": "我去饭店剪头发。", "explanation": "这里应该用〈理发店〉。剪头发要去理发店；饭店不是理发的地方。"}, {"text": "她穿着饭店出门。", "explanation": "这里应该用〈衣服〉。“穿”的是衣服；饭店是店铺，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在海边订了一只饭店。", "corrected_sentence": "我们在海边订了一家饭店。", "error_description": "量词错误：“饭店”用“家”计量，说“一家饭店”，不说“一只饭店”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在一份饭店住了两天。", "corrected_sentence": "我们在一家饭店住了两天。", "error_description": "量词错误：“饭店”用“家”计量，说“一家饭店”，不说“一份饭店”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
