INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90394, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "企业中负责经营管理的人。", "primary_collocate": null, "pronunciation": "jīng lǐ", "ipa": "tɕiŋ˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是这家公司的经理，负责经营管理。", "target_word": "经理", "complexity_tier": "T3", "furigana": "tā shì zhè jiā gōngsī de jīnglǐ, fùzé jīngyíng guǎnlǐ.", "sentence_source": "generated"}, {"text": "经理要对公司的利润负责。", "target_word": "经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的经理做了一个计划。", "target_word": "经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请了一位新经理。", "target_word": "经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理每个月都要看账目。", "target_word": "经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位很有经验的经理。", "target_word": "经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位经理管着两百个人。", "target_word": "经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把工作分给了大家。", "target_word": "经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从工人做到了经理。", "target_word": "经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，今年公司要开新店。", "target_word": "经理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "副经理", "label": "复合"}, {"form": "經理", "label": "繁体"}], "register": "中性", "sense_fingerprint": "企业里负责经营管理的职位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4928fe74-fd92-43fa-8886-52fe0aa8b3e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90394, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "经理", "is_correct": true, "explanation": "经理是企业中负责经营管理的人，即本词。"}, {"text": "精力", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，精力意思是体力和精神。"}, {"text": "净利", "is_correct": false, "explanation": "jīng 与 jìng、lǐ 与 lì 声调都不同，净利意思是扣除成本后的利润。"}, {"text": "清理", "is_correct": false, "explanation": "jīng 与 qīng 声母不同（j 与 q），清理意思是整理、清除。"}], "explanations": {"经理": "经理是企业中负责经营管理的人，即本词。", "精力": "lǐ（第三声）与 lì（第四声）声调不同，精力意思是体力和精神。", "净利": "jīng 与 jìng、lǐ 与 lì 声调都不同，净利意思是扣除成本后的利润。", "清理": "jīng 与 qīng 声母不同（j 与 q），清理意思是整理、清除。"}, "sentence_index": null, "correct_answer": "经理"}, "level_3": {"options": [{"text": "经理", "is_correct": true, "explanation": "经理：负责经营管理的人，与句中“负责经营管理”相符。"}, {"text": "工人", "is_correct": false, "explanation": "语义：工人从事生产劳动，不负责企业的经营管理。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“负责经营管理”的人员是管理者，不会说厨师负责经营管理。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生在学校读书，不负责企业的经营管理。"}], "explanations": {"经理": "经理：负责经营管理的人，与句中“负责经营管理”相符。", "工人": "语义：工人从事生产劳动，不负责企业的经营管理。", "厨师": "搭配：“负责经营管理”的人员是管理者，不会说厨师负责经营管理。", "学生": "语义：学生在学校读书，不负责企业的经营管理。"}, "sentence_index": 0, "correct_answer": "经理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们班的经理，每天带大家一起打扫教室。", "explanation": "这里应该用〈班长〉。经理指企业中负责经营管理的人，班级里带大家做事的人应称班长，不能称经理。"}, {"text": "这位经理每天在医院看病。", "explanation": "这里应该用〈医生〉。经理指企业中负责经营管理的人，在医院看病的是医生，不能称经理。"}, {"text": "我们的经理还在上小学。", "explanation": "这里应该用〈学生〉。经理指企业中的管理职务，还在上小学的是学生，不能担任这一职务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90394, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "经理", "is_correct": true, "explanation": "经理是企业中负责经营管理的人，即本词。"}, {"text": "经历", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，经历意思是亲身经过的事情。"}, {"text": "敬礼", "is_correct": false, "explanation": "jīng（第一声）与 jìng（第四声）声调不同，敬礼意思是行礼致敬。"}, {"text": "警力", "is_correct": false, "explanation": "jīng 与 jǐng、lǐ 与 lì 声调都不同，警力意思是警察的人力。"}], "explanations": {"经理": "经理是企业中负责经营管理的人，即本词。", "经历": "lǐ（第三声）与 lì（第四声）声调不同，经历意思是亲身经过的事情。", "敬礼": "jīng（第一声）与 jìng（第四声）声调不同，敬礼意思是行礼致敬。", "警力": "jīng 与 jǐng、lǐ 与 lì 声调都不同，警力意思是警察的人力。"}, "sentence_index": null, "correct_answer": "经理"}, "level_3": {"options": [{"text": "经理", "is_correct": true, "explanation": "经理：管理一群员工的人，与“管着两百个人”相符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是乘车的人，不管理他人。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：孩子还未成年，不能管理两百个人。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：“管着两百个人”的主语多是管理者，学生一般不这样搭配。"}], "explanations": {"经理": "经理：管理一群员工的人，与“管着两百个人”相符。", "乘客": "语义：乘客是乘车的人，不管理他人。", "孩子": "语义：孩子还未成年，不能管理两百个人。", "学生": "搭配：“管着两百个人”的主语多是管理者，学生一般不这样搭配。"}, "sentence_index": 6, "correct_answer": "经理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位经理每天在厨房里炒菜，做饭给客人吃。", "explanation": "这里应该用〈厨师〉。经理负责企业的经营管理，在厨房炒菜做饭的是厨师，不能称经理。"}, {"text": "这所学校的经理每天在教室里给学生上课。", "explanation": "这里应该用〈老师〉。经理负责经营管理，给学生上课的是老师，不能称经理。"}, {"text": "这位经理每天认真改作业。", "explanation": "这里应该用〈老师〉。经理负责经营管理，每天认真改作业的是老师，不能称经理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司有两位经理们，负责经营管理。", "corrected_sentence": "这家公司有两位经理，负责经营管理。", "error_description": "“们”不能与数量词“两位”一起用于“经理”，应去掉“们”。错误形式是“两位经理们”，正确形式是“两位经理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我认识一条经理，他负责采购。", "corrected_sentence": "我认识一位经理，他负责采购。", "error_description": "“经理”指人，量词应用“位”，不能用“条”（“条”多用于长形物体）。错误形式是“一条经理”，正确形式是“一位经理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
