INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90396, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "爬行动物，背腹有硬甲，头尾和四肢能缩进壳里。", "primary_collocate": null, "pronunciation": "guī", "ipa": "kweɪ˥", "syllable_count": 1, "sentences": [{"text": "龟遇到危险就缩进壳里。", "target_word": "龟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "龟的头和四肢都能缩进壳里。", "target_word": "龟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只龟已经活了很多年。", "target_word": "龟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "龟是爬行动物，不会飞。", "target_word": "龟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看过一只大龟。", "target_word": "龟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "龟在冬天会睡很久。", "target_word": "龟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的龟晚上上岸下蛋。", "target_word": "龟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里的龟喜欢晒太阳。", "target_word": "龟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩把龟放进了水盆里。", "target_word": "龟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "龟的寿命比很多动物都长。", "target_word": "龟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海龟", "label": "复合"}, {"form": "龜", "label": "繁体"}], "register": "通用", "sense_fingerprint": "龟：爬行动物，有硬甲，头尾四肢能缩进壳里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4f307f-eef1-48f7-ab9e-281d3bff4d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90396, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "龟", "is_correct": true, "explanation": "龟（guī，第一声）：爬行动物，有硬甲，头尾和四肢能缩进壳里，正是这里要选的词。"}, {"text": "柜", "is_correct": false, "explanation": "guì（第四声）与 guī（第一声）声调不同，意思是柜子。"}, {"text": "亏", "is_correct": false, "explanation": "kuī 与 guī 声母不同（k 与 g），意思是吃亏。"}, {"text": "挥", "is_correct": false, "explanation": "huī 与 guī 声母不同（h 与 g），意思是挥动。"}, {"text": "轨", "is_correct": false, "explanation": "guǐ（第三声）与 guī（第一声）声调不同，意思是轨道。"}], "explanations": {"龟": "龟（guī，第一声）：爬行动物，有硬甲，头尾和四肢能缩进壳里，正是这里要选的词。", "柜": "guì（第四声）与 guī（第一声）声调不同，意思是柜子。", "亏": "kuī 与 guī 声母不同（k 与 g），意思是吃亏。", "挥": "huī 与 guī 声母不同（h 与 g），意思是挥动。", "轨": "guǐ（第三声）与 guī（第一声）声调不同，意思是轨道。"}, "sentence_index": null, "correct_answer": "龟"}, "level_3": {"options": [{"text": "龟", "is_correct": true, "explanation": "龟遇到危险就缩进壳里，龟有壳，句意完整。"}, {"text": "刺猬", "is_correct": false, "explanation": "搭配：刺猬没有壳，不能说“缩进壳里”。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋不会遇到危险，也不会主动缩进壳里，语义不合。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫身上没有硬壳，不能缩进壳里。"}], "explanations": {"龟": "龟遇到危险就缩进壳里，龟有壳，句意完整。", "刺猬": "搭配：刺猬没有壳，不能说“缩进壳里”。", "鸡蛋": "语义：鸡蛋不会遇到危险，也不会主动缩进壳里，语义不合。", "小猫": "语义：小猫身上没有硬壳，不能缩进壳里。"}, "sentence_index": 0, "correct_answer": "龟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "哥哥在河边抓到一把龟。", "explanation": "这里应该用〈只〉。“把”用于有柄的东西，不用于龟。"}, {"text": "我家养了一棵龟。", "explanation": "这里应该用〈只〉。“棵”用于植物，不用于龟，龟用“只”。"}, {"text": "我在池子里看到一头龟。", "explanation": "这里应该用〈只〉。“头”用于牛、猪等大型动物，龟用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90396, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "龟", "is_correct": true, "explanation": "龟（guī，第一声）：爬行动物，有硬甲，头尾和四肢能缩进壳里，正是这里要选的词。"}, {"text": "跪", "is_correct": false, "explanation": "guì（第四声）与 guī（第一声）声调不同，意思是双膝着地。"}, {"text": "贵", "is_correct": false, "explanation": "guì（第四声）与 guī（第一声）声调不同，意思是价格高。"}, {"text": "灰", "is_correct": false, "explanation": "huī 与 guī 声母不同（h 与 g），意思是灰色。"}, {"text": "鬼", "is_correct": false, "explanation": "guǐ（第三声）与 guī（第一声）声调不同，意思是鬼魂。"}], "explanations": {"龟": "龟（guī，第一声）：爬行动物，有硬甲，头尾和四肢能缩进壳里，正是这里要选的词。", "跪": "guì（第四声）与 guī（第一声）声调不同，意思是双膝着地。", "贵": "guì（第四声）与 guī（第一声）声调不同，意思是价格高。", "灰": "huī 与 guī 声母不同（h 与 g），意思是灰色。", "鬼": "guǐ（第三声）与 guī（第一声）声调不同，意思是鬼魂。"}, "sentence_index": null, "correct_answer": "龟"}, "level_3": {"options": [{"text": "龟", "is_correct": true, "explanation": "海边的龟晚上上岸下蛋，龟会上岸产卵，句意完整。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：多数鱼在水中产卵，“上岸下蛋”与鱼的习性不合。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗不会下蛋，“下蛋”与狗的习性不合。"}, {"text": "海豚", "is_correct": false, "explanation": "搭配：海豚生下的是幼崽，不说“下蛋”，与“下蛋”搭配不当。"}], "explanations": {"龟": "海边的龟晚上上岸下蛋，龟会上岸产卵，句意完整。", "鱼": "语义：多数鱼在水中产卵，“上岸下蛋”与鱼的习性不合。", "狗": "语义：狗不会下蛋，“下蛋”与狗的习性不合。", "海豚": "搭配：海豚生下的是幼崽，不说“下蛋”，与“下蛋”搭配不当。"}, "sentence_index": 6, "correct_answer": "龟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在海边捡到一片龟。", "explanation": "这里应该用〈只〉。“片”用于扁平的东西，不用于龟，龟用“只”。"}, {"text": "池塘里有一块龟。", "explanation": "这里应该用〈只〉。“块”用于块状物，龟用“只”。"}, {"text": "河里有一根龟。", "explanation": "这里应该用〈只〉。“根”用于长条状物，龟用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条龟的壳很厚。", "corrected_sentence": "这只龟的壳很厚。", "error_description": "量词错误：“龟”的量词应为“只”，不能用“条”。应说“这只龟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "龟受到惊吓就缩出壳里。", "corrected_sentence": "龟受到惊吓就缩进壳里。", "error_description": "补语错误：“缩”后的趋向补语应为“进”，表示向壳里收缩；“出”表示由内向外，与“壳里”矛盾，应说“缩进壳里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
