INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90398, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "按顺序排在自己之后的人，多指牌局或交易中的下一方。", "primary_collocate": null, "pronunciation": "xià jiā", "ipa": "ɕja˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "打麻将时，我的下家总是出错牌。", "target_word": "下家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批货我已经找到下家了。", "target_word": "下家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我的下家，该他出牌了。", "target_word": "下家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你出完牌，就轮到下家了。", "target_word": "下家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把手里的货卖给了下家。", "target_word": "下家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要先找好下家，再进货。", "target_word": "下家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在牌桌上一直盯着下家。", "target_word": "下家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的下家笑着把牌放在桌上。", "target_word": "下家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次轮到你的下家发牌了。", "target_word": "下家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货到了他手上，他马上联系了下家。", "target_word": "下家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个下家", "label": "量词（个）"}], "register": "口语", "sense_fingerprint": "下家：顺序在后的人，牌局或交易的下一方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed144756-53d4-4300-bd5f-f63fe54a21d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电视", "is_correct": false, "explanation": "语义：电视不是牌局中的人，不能“出错牌”。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶不是牌局中的人，不能“出错牌”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是牌局中的人，不能“出错牌”。"}, {"text": "下家", "is_correct": true, "explanation": "“下家”指牌局中排在我后面出牌的人，与“出错牌”相合。"}], "explanations": {"电视": "语义：电视不是牌局中的人，不能“出错牌”。", "花瓶": "语义：花瓶不是牌局中的人，不能“出错牌”。", "窗户": "语义：窗户不是牌局中的人，不能“出错牌”。", "下家": "“下家”指牌局中排在我后面出牌的人，与“出错牌”相合。"}, "sentence_index": 0, "correct_answer": "下家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下家出了一张红桃，我得跟一张红桃。", "explanation": "这里应该用〈上家〉。跟牌跟的是上家刚出的牌，下家排在我之后，不会先出牌。"}, {"text": "他是我的一条下家，很会打牌。", "explanation": "这里应该用〈个〉。下家指人，量词用“个”或“位”，“条”用于长形物。"}, {"text": "他是公司的下家，要听领导的话。", "explanation": "这里应该用〈下级〉。下家指牌局或交易中排在后面的一方，不指公司里的下属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db9e259-24f8-4873-845d-be6bf865173b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大海", "is_correct": false, "explanation": "语义：牌桌上看不到大海，与“牌桌上”相矛盾。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：牌桌上看不到月亮，与语境不符。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：牌桌上没有沙漠，“在牌桌上盯着沙漠”与语境矛盾。"}, {"text": "下家", "is_correct": true, "explanation": "“下家”指牌局中排在我后面的人，与“盯着”的对象相合。"}], "explanations": {"大海": "语义：牌桌上看不到大海，与“牌桌上”相矛盾。", "月亮": "语义：牌桌上看不到月亮，与语境不符。", "沙漠": "语义：牌桌上没有沙漠，“在牌桌上盯着沙漠”与语境矛盾。", "下家": "“下家”指牌局中排在我后面的人，与“盯着”的对象相合。"}, "sentence_index": 6, "correct_answer": "下家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "故事的下家很精彩。", "explanation": "这里应该用〈开头〉。下家指牌局或交易中排在后面的一方，不指故事的起始部分。"}, {"text": "这件事的下家还没有消息。", "explanation": "这里应该用〈后续〉。下家指牌局或交易中排在后面的一方，不指事情的后续发展。"}, {"text": "我家的下家种了很多花。", "explanation": "这里应该用〈后院〉。下家指排在后面的一方，不指房屋的一部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db9e259-24f8-4873-845d-be6bf865173b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我出完一张红桃，我的一条下家就跟着出了。", "corrected_sentence": "我出完一张红桃，我的下家就跟着出了。", "error_description": "量词错误：“下家”指人，不能用量词“条”修饰（“条”用于长形物）；正确句中“我的下家”前不加数量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db9e259-24f8-4873-845d-be6bf865173b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一条下家，每次都出得很快。", "corrected_sentence": "他有一个下家，每次都出得很快。", "error_description": "量词错误：“下家”指人，应用“个”；“条”用于长形物，不能修饰人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db9e259-24f8-4873-845d-be6bf865173b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
