INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90399, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "记载是把事情写下来，让大家以后能看到。", "primary_collocate": null, "pronunciation": "jì zǎi", "ipa": "tɕi˥˩ tsaɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他每天把学校的事记载下来。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书记载了很多古代的事。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的人记载了这次大雨。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本日记记载着我的生活。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把家里的故事记载下来，留给孩子们看。", "target_word": "记载", "complexity_tier": "T3", "furigana": "lǎo rén bǎ jiā lǐ de gù shì jì zǎi xià lái，liú gěi hái zi men kàn。", "sentence_source": "generated"}, {"text": "报告里记载了今天的天气。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的牌子记载着这座楼的历史。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用笔记载了旅行中的每一天。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把这次活动记载下来，以后给大家看。", "target_word": "记载", "complexity_tier": "T3", "furigana": "wǒ men yào bǎ zhè cì huó dòng jì zǎi xià lái，yǐ hòu gěi dà jiā kàn。", "sentence_source": "generated"}, {"text": "这个本子没有记载你的名字。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "记载了", "label": "体标"}, {"form": "记载着", "label": "体标"}, {"form": "记载过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "把事情写下来，留给以后的人看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '477a65e0-38ea-45c0-b671-a699ad3bfba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90399, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "记载", "is_correct": true, "explanation": "正确。“记载下来”指把事情写下来保存，与“每天把学校的事”相符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“记下来”意思相反，“忘记下来”不合逻辑。"}, {"text": "拆卸", "is_correct": false, "explanation": "搭配：“拆卸”的对象是机器或零件，不能用来说“学校的事”。"}, {"text": "切割", "is_correct": false, "explanation": "语义：“切割”是把东西割开，不能用于把事情写下来。"}], "explanations": {"记载": "正确。“记载下来”指把事情写下来保存，与“每天把学校的事”相符。", "忘记": "语义：“忘记”与“记下来”意思相反，“忘记下来”不合逻辑。", "拆卸": "搭配：“拆卸”的对象是机器或零件，不能用来说“学校的事”。", "切割": "语义：“切割”是把东西割开，不能用于把事情写下来。"}, "sentence_index": 0, "correct_answer": "记载"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一眼就记载我的脸。", "explanation": "这里应该用〈记得〉。“记得”指留在脑子里，“记载”指写成文字，不能说“记载脸”。"}, {"text": "工人把钢筋记载上车。", "explanation": "这里应该用〈装载〉。“装载”指把货物搬上车船，“记载”只指写下事情。"}, {"text": "他记载了一枚古币。", "explanation": "这里应该用〈珍藏〉。“珍藏”指把珍贵的物品留存起来，“记载”指把事情写下来，不用于说收存古币。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90399, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "记载", "is_correct": true, "explanation": "正确。“记载着”指写明或刻明历史，牌子上写着这座楼的历史，与句意相符。"}, {"text": "悬挂", "is_correct": false, "explanation": "语义：“悬挂”指吊挂东西，不能用来说“历史”。"}, {"text": "粘贴", "is_correct": false, "explanation": "语义：“粘贴”指贴在表面，与“这座楼的历史”不搭。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是货物，不能说搬运历史。"}], "explanations": {"记载": "正确。“记载着”指写明或刻明历史，牌子上写着这座楼的历史，与句意相符。", "悬挂": "语义：“悬挂”指吊挂东西，不能用来说“历史”。", "粘贴": "语义：“粘贴”指贴在表面，与“这座楼的历史”不搭。", "搬运": "搭配：“搬运”的对象是货物，不能说搬运历史。"}, "sentence_index": 6, "correct_answer": "记载"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生把课本记载进了书包。", "explanation": "这里应该用〈装〉。“装”指把东西放进容器，“记载”指写下事情，不能用于书包。"}, {"text": "学生把课文记载得很响亮。", "explanation": "这里应该用〈朗读〉。“朗读”可以“读得很响亮”，“记载”指写下事情，不能形容声音。"}, {"text": "他用彩纸记载了教室的墙壁。", "explanation": "这里应该用〈装饰〉。“装饰”指美化物体的外表，“记载”指写下事情，不能用于墙壁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90399, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天把看到的事记载上来。", "corrected_sentence": "他每天把看到的事记载下来。", "error_description": "“记载”后要用趋向补语“下来”，表示把事情保存下来；“记载上来”不能这样说，应说“记载下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90399, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这次旅行的经过记载笔记本上。", "corrected_sentence": "我把这次旅行的经过记载在笔记本上。", "error_description": "“记载”后的处所宾语前要加“在”，应说“记载在笔记本上”，不能省去“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
