INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90403, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在中间的那一部分。", "primary_collocate": null, "pronunciation": "zhōng bù", "ipa": "ʈʂʊŋ˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "中国的中部有很多大城市。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的中部是平原。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图的中部画着一条河。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋楼的中部是大厅。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在城市的中部。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林的中部有一个湖。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街的中部有点窄。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在教室的中部。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岛的中部很高。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的中部正在修。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "地区或空间位于中间的那一块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4928fe74-fd92-43fa-8886-52fe0aa8b3e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90403, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史", "is_correct": false, "explanation": "语义：历史指过去的时间，不指地理区域，句子说的是地区有城市。"}, {"text": "中部", "is_correct": true, "explanation": "中部指中国中间的地区，“有很多大城市”说的是这一地区。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“有很多大城市”要求主语是地区，人口不能拥有城市。"}, {"text": "语言", "is_correct": false, "explanation": "语义：语言是交流的工具，不指地区，无法拥有城市。"}], "explanations": {"历史": "语义：历史指过去的时间，不指地理区域，句子说的是地区有城市。", "中部": "中部指中国中间的地区，“有很多大城市”说的是这一地区。", "人口": "搭配：“有很多大城市”要求主语是地区，人口不能拥有城市。", "语言": "语义：语言是交流的工具，不指地区，无法拥有城市。"}, "sentence_index": 0, "correct_answer": "中部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在两节课的中部休息了一会儿。", "explanation": "这里应该用〈课间〉。中部指较大事物的中间部分，两节课之间的休息要用课间。"}, {"text": "他的中部很痛，所以请假了。", "explanation": "这里应该用〈腹部〉。中部指地域或空间的中间，身体的部位要用腹部等词，不说中部。"}, {"text": "这个想法的中部很清楚。", "explanation": "这里应该用〈核心〉。中部指空间或地域的中间，想法没有空间上的中间，不能说中部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90403, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：「有点窄」说的是宽窄，不能用来形容颜色。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「有点窄」不能用来形容价格。"}, {"text": "中部", "is_correct": true, "explanation": "中部指街道中间的一段，「有点窄」描述这一段的宽度。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道指口感，与街道的宽窄无关。"}], "explanations": {"颜色": "搭配：「有点窄」说的是宽窄，不能用来形容颜色。", "价格": "搭配：「有点窄」不能用来形容价格。", "中部": "中部指街道中间的一段，「有点窄」描述这一段的宽度。", "味道": "语义：味道指口感，与街道的宽窄无关。"}, "sentence_index": 6, "correct_answer": "中部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的弟弟坐在我的中部。", "explanation": "这里应该用〈旁边〉。中部指较大事物的中间地带，人与人之间的位置要用旁边。"}, {"text": "那只猫的中部很饿。", "explanation": "这里应该用〈肚子〉。中部指空间的中间，动物的饥饿感要说肚子，不说中部。"}, {"text": "我的中部很累。", "explanation": "这里应该用〈身体〉。中部指空间或地域的中间，人的疲劳要说身体，不说中部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90403, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的朋友住在中国的中部上。", "corrected_sentence": "我的朋友住在中国的中部。", "error_description": "错误形式：“中国的中部上”，多加了方位词“上”；正确形式：“中国的中部”。“中部”后面不加“上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90403, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块木板的两个中部有一道裂缝。", "corrected_sentence": "这块木板的中部有一道裂缝。", "error_description": "错误形式：「两个中部」。「中部」是指一个区域的名词，前面加「两个」这样的数量短语不自然；正确形式：「中部」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
