INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90404, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中间的部分。", "primary_collocate": null, "pronunciation": "zhōng bù", "ipa": "ʈʂʊŋ˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "这条河的中部很宽。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山的中部有一个小村子。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的中部很有意思。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的中部有一个大公园。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把桌子放在房间的中部。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的中部讲了一个故事。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的船开到了湖的中部。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕的中部是软的。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥的中部最高。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的中部我还没看完。", "target_word": "中部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事物中间的那一段或那一块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4928fe74-fd92-43fa-8886-52fe0aa8b3e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90404, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：年龄指人或生物存在的时间，河的一段不能有年龄。"}, {"text": "中部", "is_correct": true, "explanation": "中部指河的中间一段，句中“很宽”描述这一段的宽度，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“宽”说的是宽窄，不能用来形容颜色。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道指口感，与河的宽窄无关。"}], "explanations": {"年龄": "语义：年龄指人或生物存在的时间，河的一段不能有年龄。", "中部": "中部指河的中间一段，句中“很宽”描述这一段的宽度，与句意相符。", "颜色": "搭配：“宽”说的是宽窄，不能用来形容颜色。", "味道": "语义：味道指口感，与河的宽窄无关。"}, "sentence_index": 0, "correct_answer": "中部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我坐在两个朋友的中部。", "explanation": "这里应该用〈中间〉。中部指较大区域的中间地带，两个人之间的位置要用中间。"}, {"text": "他的中部受伤了，要马上去医院。", "explanation": "这里应该用〈腰部〉。中部指地域或空间的中间，人体的部位要用腰部等词，不说中部。"}, {"text": "这个问题的中部我还没想明白。", "explanation": "这里应该用〈核心〉。中部指空间或地域的中间，问题没有空间上的中间，不能说中部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名字", "is_correct": false, "explanation": "语义：名字不是地点，船不能开到名字上。"}, {"text": "颜色", "is_correct": false, "explanation": "配价：“开到”要求处所作宾语，颜色不是处所。"}, {"text": "中部", "is_correct": true, "explanation": "中部指湖的中间一带，“开到了”后面的处所正是这一区域。"}, {"text": "作者", "is_correct": false, "explanation": "语义：作者指写作的人，与湖的位置无关。"}], "explanations": {"名字": "语义：名字不是地点，船不能开到名字上。", "颜色": "配价：“开到”要求处所作宾语，颜色不是处所。", "中部": "中部指湖的中间一带，“开到了”后面的处所正是这一区域。", "作者": "语义：作者指写作的人，与湖的位置无关。"}, "sentence_index": 6, "correct_answer": "中部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的同桌坐在我的中部。", "explanation": "这里应该用〈旁边〉。中部指较大事物的中间地带，人与人之间的位置要用旁边。"}, {"text": "他的中部很快就睡着了。", "explanation": "这里应该用〈他〉。中部指空间的中间部分，不能作睡觉的主语。"}, {"text": "他是我们公司的中部员工。", "explanation": "这里应该用〈中层〉。中部指空间上的中间部分，表示职位等级居中要用中层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家在城市的中部上。", "corrected_sentence": "我家在城市的中部。", "error_description": "错误形式：“中部上”，多加了方位词“上”；正确形式：“中部”。“中部”本身已表示位置，后面不再加“上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座山的中部里很陡。", "corrected_sentence": "这座山的中部很陡。", "error_description": "错误形式：「中部里」，多加了方位词「里」；正确形式：「中部」。「中部」本身已表示位置，后面不再加「里」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f9d8cb0-97a0-47dc-8880-2a9b542198d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90405, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "数量", "is_correct": true, "explanation": "正确：“质”指东西的好坏，与之相对的是“数量”，“重质不重量”即此对立。"}, {"text": "颜色", "is_correct": false, "explanation": "颜色指东西的色彩，与“质”的好坏不构成反义关系。"}, {"text": "形状", "is_correct": false, "explanation": "形状描述外形，与“质”的好坏不构成反义关系。"}, {"text": "价格", "is_correct": false, "explanation": "价格是商品的标价，不是“质”的反义词。"}], "correct_answer": "数量", "explanations": {"数量": "正确：“质”指东西的好坏，与之相对的是“数量”，“重质不重量”即此对立。", "颜色": "颜色指东西的色彩，与“质”的好坏不构成反义关系。", "形状": "形状描述外形，与“质”的好坏不构成反义关系。", "价格": "价格是商品的标价，不是“质”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90405, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "数量", "is_correct": true, "explanation": "正确：“质”指东西的好坏，与之相对的是“数量”，“比起量，我更看重质”即此对立。"}, {"text": "温度", "is_correct": false, "explanation": "温度指冷热程度，与“质”的好坏不构成反义关系。"}, {"text": "距离", "is_correct": false, "explanation": "距离指两地之间的长短，与“质”不构成反义关系。"}, {"text": "声音", "is_correct": false, "explanation": "声音指耳朵能听到的声响，与“质”不构成反义关系。"}], "correct_answer": "数量", "explanations": {"数量": "正确：“质”指东西的好坏，与之相对的是“数量”，“比起量，我更看重质”即此对立。", "温度": "温度指冷热程度，与“质”的好坏不构成反义关系。", "距离": "距离指两地之间的长短，与“质”不构成反义关系。", "声音": "声音指耳朵能听到的声响，与“质”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90405, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "质是东西的好坏、质量高低，与数量相对。", "primary_collocate": null, "pronunciation": "zhì", "ipa": "tʂʐ̩˥˩", "syllable_count": 1, "sentences": [{"text": "买东西，我重质不重量。", "target_word": "质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店东西不多，但是质很好。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，写作文不能只看量，也要看质。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数量可以慢慢增加，质却不能马虎。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司要的是质，不是量。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两家店衣服的量差不多，质却差很多。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做的东西，量不大，质很高。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比起量来，工作的质更重要。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水果的量够了，可是质不太好。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我选这个，因为比起量，我更看重质。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "质量", "label": "复合"}, {"form": "质变", "label": "复合"}, {"form": "質", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "与数量相对的东西的好坏、质量高低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb45aab-75ed-4f65-a859-450e1280774f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90405, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "质", "is_correct": true, "explanation": "正确：zhì（第四声），意思是质量、好坏。"}, {"text": "纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是纸。"}, {"text": "字", "is_correct": false, "explanation": "zì 与 zhì 声母不同（z 与 zh），声调相同，意思是字。"}, {"text": "直", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，意思是直。"}, {"text": "猪", "is_correct": false, "explanation": "zhū（第一声）与 zhì（第四声）声调不同，意思是猪。"}], "explanations": {"质": "正确：zhì（第四声），意思是质量、好坏。", "纸": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是纸。", "字": "zì 与 zhì 声母不同（z 与 zh），声调相同，意思是字。", "直": "zhí（第二声）与 zhì（第四声）声调不同，意思是直。", "猪": "zhū（第一声）与 zhì（第四声）声调不同，意思是猪。"}, "sentence_index": null, "correct_answer": "质"}, "level_3": {"options": [{"text": "质", "is_correct": true, "explanation": "正确：“重质不重量”中“重”带宾语“质”，指看重商品的好坏。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“看重”的宾语须是名词性的价值方面，“吃”是动词，“重吃不重量”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“重”作“看重”讲时，“体重”不是可以被看重的对象，“重体重”不成搭配。"}, {"text": "睡", "is_correct": false, "explanation": "搭配：“看重”的宾语须是名词性的价值方面，“睡”是不及物动词，“重睡不重量”不成立。"}], "explanations": {"质": "正确：“重质不重量”中“重”带宾语“质”，指看重商品的好坏。", "吃": "搭配：“看重”的宾语须是名词性的价值方面，“吃”是动词，“重吃不重量”不成立。", "体重": "搭配：“重”作“看重”讲时，“体重”不是可以被看重的对象，“重体重”不成搭配。", "睡": "搭配：“看重”的宾语须是名词性的价值方面，“睡”是不及物动词，“重睡不重量”不成立。"}, "sentence_index": 0, "correct_answer": "质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个厂的质增加了一倍。", "explanation": "这里应该用〈产量〉。“质”指好坏，不能说“增加一倍”，能增加的是产量。"}, {"text": "这件衣服的质是两百元。", "explanation": "这里应该用〈价格〉。“质”指东西的好坏，不是价钱，不能说“质是两百元”。"}, {"text": "这根绳子的质是三米。", "explanation": "这里应该用〈长度〉。“质”指东西的好坏，不能用来说长度，要说“长度是三米”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90405, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "质", "is_correct": true, "explanation": "正确：zhì（第四声），意思是质量、好坏。"}, {"text": "织", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，意思是织。"}, {"text": "事", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），声调相同，意思是事情。"}, {"text": "翅", "is_correct": false, "explanation": "chì 与 zhì 声母不同（ch 与 zh），声调相同，意思是翅膀。"}, {"text": "主", "is_correct": false, "explanation": "zhǔ（第三声）与 zhì（第四声）声调不同，意思是主人。"}], "explanations": {"质": "正确：zhì（第四声），意思是质量、好坏。", "织": "zhī（第一声）与 zhì（第四声）声调不同，意思是织。", "事": "shì 与 zhì 声母不同（sh 与 zh），声调相同，意思是事情。", "翅": "chì 与 zhì 声母不同（ch 与 zh），声调相同，意思是翅膀。", "主": "zhǔ（第三声）与 zhì（第四声）声调不同，意思是主人。"}, "sentence_index": null, "correct_answer": "质"}, "level_3": {"options": [{"text": "质", "is_correct": true, "explanation": "正确：“他做的东西，量不大，质很高”中“质”作主语，指东西的好坏。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用“高”来形容，“颜色很高”不成搭配。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能用“高”来形容，“天气很高”不成搭配。"}, {"text": "身高", "is_correct": false, "explanation": "语义：东西没有“身高”，“身高很高”与“东西”的说法不符。"}], "explanations": {"质": "正确：“他做的东西，量不大，质很高”中“质”作主语，指东西的好坏。", "颜色": "搭配：“颜色”不能用“高”来形容，“颜色很高”不成搭配。", "天气": "搭配：“天气”不能用“高”来形容，“天气很高”不成搭配。", "身高": "语义：东西没有“身高”，“身高很高”与“东西”的说法不符。"}, "sentence_index": 6, "correct_answer": "质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水的质是六十度。", "explanation": "这里应该用〈温度〉。“质”指东西的好坏，不能用来说温度。"}, {"text": "这次活动的质很多。", "explanation": "这里应该用〈数量〉。“质”不能用“很多”来形容，要说“数量很多”。"}, {"text": "他的质是六十公斤。", "explanation": "这里应该用〈体重〉。“质”不能用来表示重量，要说“体重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90405, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店东西不多，质的却很好。", "corrected_sentence": "这家店东西不多，质却很好。", "error_description": "“的”多余：“质”直接作主语时不用“的”，应说“质却很好”，不能在“质”后加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90405, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们提高了这批零件质。", "corrected_sentence": "我们提高了这批零件的质。", "error_description": "“的”漏掉：“这批零件”修饰“质”时要加“的”，应说“这批零件的质”，不能直接说“零件质”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90406, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "量", "is_correct": true, "explanation": "正确：“量”指事物的多少，与“质”（事物本身的性质）相对，“这是质的差别，不是多少的差别”即此对立。"}, {"text": "价格", "is_correct": false, "explanation": "价格是商品的标价，与“质”不构成反义关系。"}, {"text": "颜色", "is_correct": false, "explanation": "颜色指事物的色彩，与“质”不构成反义关系。"}, {"text": "温度", "is_correct": false, "explanation": "温度指冷热程度，与“质”不构成反义关系。"}], "correct_answer": "量", "explanations": {"量": "正确：“量”指事物的多少，与“质”（事物本身的性质）相对，“这是质的差别，不是多少的差别”即此对立。", "价格": "价格是商品的标价，与“质”不构成反义关系。", "颜色": "颜色指事物的色彩，与“质”不构成反义关系。", "温度": "温度指冷热程度，与“质”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90406, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "量", "is_correct": true, "explanation": "正确：“量”指事物的多少，与“质”相对，“这是质的差别，不是多少的差别”即此对立。"}, {"text": "距离", "is_correct": false, "explanation": "距离指两地之间的长短，与“质”不构成反义关系。"}, {"text": "声音", "is_correct": false, "explanation": "声音指耳朵能听到的声响，与“质”不构成反义关系。"}, {"text": "形状", "is_correct": false, "explanation": "形状描述外形，与“质”不构成反义关系。"}], "correct_answer": "量", "explanations": {"量": "正确：“量”指事物的多少，与“质”相对，“这是质的差别，不是多少的差别”即此对立。", "距离": "距离指两地之间的长短，与“质”不构成反义关系。", "声音": "声音指耳朵能听到的声响，与“质”不构成反义关系。", "形状": "形状描述外形，与“质”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90406, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物的本体、性质，与量相对。", "primary_collocate": null, "pronunciation": "zhì", "ipa": "tʂʐ̩˥˩", "syllable_count": 1, "sentences": [{"text": "水变成冰，只是样子变了，质没有变。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个问题，在质上完全不同。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有些变化只是量的变化，有些是质的变化。", "target_word": "质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，量到了一定程度，质就会改变。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两种东西看起来像，质却不同。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话没有改变问题的质。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是质的差别，不是多少的差别。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只看表面，看不到事物的质。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光看数量的变化不够，还要看质有没有变。", "target_word": "质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三年来，这座城市的发展有了质的飞跃。", "target_word": "质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "质量", "label": "复合"}, {"form": "质变", "label": "复合"}, {"form": "質", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "与量相对的事物本身的性质、本质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb45aab-75ed-4f65-a859-450e1280774f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90406, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "质", "is_correct": true, "explanation": "正确：zhì（第四声），意思是事物的本体、性质。"}, {"text": "只", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是只有。"}, {"text": "字", "is_correct": false, "explanation": "zì 与 zhì 声母不同（z 与 zh），声调相同，意思是字。"}, {"text": "值", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，意思是价值。"}, {"text": "猪", "is_correct": false, "explanation": "zhū（第一声）与 zhì（第四声）声调不同，意思是猪。"}], "explanations": {"质": "正确：zhì（第四声），意思是事物的本体、性质。", "只": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是只有。", "字": "zì 与 zhì 声母不同（z 与 zh），声调相同，意思是字。", "值": "zhí（第二声）与 zhì（第四声）声调不同，意思是价值。", "猪": "zhū（第一声）与 zhì（第四声）声调不同，意思是猪。"}, "sentence_index": null, "correct_answer": "质"}, "level_3": {"options": [{"text": "质", "is_correct": true, "explanation": "正确：“水变成冰，只是样子变了，质没有变”中“质”指事物本身的性质。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：水没有“年龄”，“年龄没有变”与水的变化无关，句子不通。"}, {"text": "国籍", "is_correct": false, "explanation": "语义：水没有“国籍”，“国籍没有变”与句子所说的事物不符。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“座位”用于人或交通工具，与水的变化无关。"}], "explanations": {"质": "正确：“水变成冰，只是样子变了，质没有变”中“质”指事物本身的性质。", "年龄": "语义：水没有“年龄”，“年龄没有变”与水的变化无关，句子不通。", "国籍": "语义：水没有“国籍”，“国籍没有变”与句子所说的事物不符。", "座位": "语义：“座位”用于人或交通工具，与水的变化无关。"}, "sentence_index": 0, "correct_answer": "质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的质很精彩。", "explanation": "这里应该用〈内容〉。“精彩”形容的是内容，“质”指事物本身的性质，不能说“质很精彩”。"}, {"text": "他的质是六十公斤。", "explanation": "这里应该用〈体重〉。“质”指事物本身的性质，不能用来表示重量。"}, {"text": "这块布的质很鲜艳。", "explanation": "这里应该用〈颜色〉。“质”指事物本身的性质，不能用来形容颜色，要说“颜色很鲜艳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90406, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "质", "is_correct": true, "explanation": "正确：zhì（第四声），意思是事物的本体、性质。"}, {"text": "知", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，意思是知道。"}, {"text": "是", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），声调相同，意思是是。"}, {"text": "赤", "is_correct": false, "explanation": "chì 与 zhì 声母不同（ch 与 zh），声调相同，意思是红色。"}, {"text": "主", "is_correct": false, "explanation": "zhǔ（第三声）与 zhì（第四声）声调不同，意思是主人。"}], "explanations": {"质": "正确：zhì（第四声），意思是事物的本体、性质。", "知": "zhī（第一声）与 zhì（第四声）声调不同，意思是知道。", "是": "shì 与 zhì 声母不同（sh 与 zh），声调相同，意思是是。", "赤": "chì 与 zhì 声母不同（ch 与 zh），声调相同，意思是红色。", "主": "zhǔ（第三声）与 zhì（第四声）声调不同，意思是主人。"}, "sentence_index": null, "correct_answer": "质"}, "level_3": {"options": [{"text": "质", "is_correct": true, "explanation": "正确：“这是质的差别，不是多少的差别”中“质”指事物本身的性质。"}, {"text": "面积", "is_correct": false, "explanation": "语义：“面积”也属于“多少”的范畴，与“不是多少的差别”自相矛盾。"}, {"text": "人数", "is_correct": false, "explanation": "语义：“人数”同样是“多少”，与后半句“不是多少的差别”矛盾。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”属于“多少”的范畴，“这是重量的差别，不是多少的差别”自相矛盾。"}], "explanations": {"质": "正确：“这是质的差别，不是多少的差别”中“质”指事物本身的性质。", "面积": "语义：“面积”也属于“多少”的范畴，与“不是多少的差别”自相矛盾。", "人数": "语义：“人数”同样是“多少”，与后半句“不是多少的差别”矛盾。", "重量": "语义：“重量”属于“多少”的范畴，“这是重量的差别，不是多少的差别”自相矛盾。"}, "sentence_index": 6, "correct_answer": "质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的质很快。", "explanation": "这里应该用〈速度〉。“质”指事物本身的性质，不能用来形容快慢。"}, {"text": "两地的质很远。", "explanation": "这里应该用〈距离〉。“质”不能用来表示远近，要说“距离很远”。"}, {"text": "这块地的质是两亩。", "explanation": "这里应该用〈面积〉。“质”不能用来表示面积的大小，要说“面积是两亩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种变化改变了事物质。", "corrected_sentence": "这种变化改变了事物的质。", "error_description": "“的”漏掉：“事物”修饰“质”时要加“的”，应说“事物的质”，不能说“事物质”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是质飞跃，不是量的增加。", "corrected_sentence": "这是质的飞跃，不是量的增加。", "error_description": "“的”漏掉：“质”修饰“飞跃”时要加“的”，应说“质的飞跃”，不能直接说“质飞跃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
