INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90407, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "交付是把东西交到别人手里。", "primary_collocate": null, "pronunciation": "jiāo fù", "ipa": "tɕjɑʊ˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "师傅把修好的自行车交付给我了。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员当面交付了包裹。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这份文件交付给王经理。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机坏了，店里答应后天交付新的。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先做好蛋糕，再交付给客人。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "装修完成后，公司才会交付房屋。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机已经交付了所有行李。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂家一周后交付这批桌椅。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师把合同交付给了对方。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物交付以后，我们就付款。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交付了", "label": "体标"}, {"form": "交付过", "label": "体标"}, {"form": "交付使用", "label": "复合词"}], "register": "书面", "sense_fingerprint": "交付：把东西亲手交到别人手里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b588376-c1a7-4853-aa69-24c24846ed71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90407, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "擦", "is_correct": false, "explanation": "语义：「擦」是抹去污渍，不表示把东西交到别人手里，句子不通。"}, {"text": "喝", "is_correct": false, "explanation": "语义：「喝」的对象是液体，自行车不能喝，句子不通。"}, {"text": "交付", "is_correct": true, "explanation": "正确：「交付」指亲手把东西交到别人手里，与「把……给我了」搭配。"}, {"text": "停", "is_correct": false, "explanation": "语义：「停」表示使静止，不能表示交接，句子不通。"}], "explanations": {"擦": "语义：「擦」是抹去污渍，不表示把东西交到别人手里，句子不通。", "喝": "语义：「喝」的对象是液体，自行车不能喝，句子不通。", "交付": "正确：「交付」指亲手把东西交到别人手里，与「把……给我了」搭配。", "停": "语义：「停」表示使静止，不能表示交接，句子不通。"}, "sentence_index": 0, "correct_answer": "交付"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上把孩子交付到学校。", "explanation": "这里应该用〈送〉。交付指把物品交给对方，把人送到某地要用〈送〉。"}, {"text": "我把钥匙交付在桌子上。", "explanation": "这里应该用〈放〉。交付需要接收的人，不能指把东西放在某处。"}, {"text": "我把这份快乐交付给了朋友。", "explanation": "这里应该用〈分享〉。交付指把实物移交给对方，快乐是感受，应说〈分享〉给朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90407, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：「吃」不能用来指把行李交出去，「吃了所有行李」不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」与行李无关，「唱了所有行李」句子不通。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：「讨论」指商议，与「司机已经……了所有行李」中把行李交给别人的动作不符。"}, {"text": "交付", "is_correct": true, "explanation": "正确：「交付」指把东西交到对方手里，与「司机已经……了所有行李」搭配。"}], "explanations": {"吃": "语义：「吃」不能用来指把行李交出去，「吃了所有行李」不通。", "唱": "语义：「唱」与行李无关，「唱了所有行李」句子不通。", "讨论": "语义：「讨论」指商议，与「司机已经……了所有行李」中把行李交给别人的动作不符。", "交付": "正确：「交付」指把东西交到对方手里，与「司机已经……了所有行李」搭配。"}, "sentence_index": 6, "correct_answer": "交付"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这封信已经交付了三天。", "explanation": "这里应该用〈寄〉。交付指把物品交到对方手中，信件在途经过的时间应说〈寄了三天〉。"}, {"text": "他把一场比赛交付给了观众。", "explanation": "这里应该用〈献〉。交付指把实物交给对方，比赛是活动，把比赛献给观众应说〈献〉。"}, {"text": "我把天气交付给了朋友。", "explanation": "这里应该用〈告诉〉。交付指把实物交到对方手中，天气是信息，应说〈告诉〉朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90407, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店家会把修好的手机交付的给我。", "corrected_sentence": "店家会把修好的手机交付给我。", "error_description": "错误：「交付」后多加了「的」，不能接「的」再接「给我」。应去掉「的」，说「店家会把修好的手机交付给我」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90407, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们会把这批桌椅交付给了客户。", "corrected_sentence": "我们会把这批桌椅交付给客户。", "error_description": "错误：句中有「会」表示将来，「给了」表示已完成，二者不能同用。应去掉「了」，说「我们会把这批桌椅交付给客户」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
