INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90408, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "交给，付给。", "primary_collocate": null, "pronunciation": "jiāo fù", "ipa": "tɕjɑʊ˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "公司明天会把新车交付给客户。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们按时交付了所有的货物。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱要在三天内交付给对方。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子已经交付给买房的人了。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，下个月才能交付这批产品。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钥匙交付给了新来的邻居。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们保证按合同交付全部家具。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂今天上午交付了一百台电脑。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买家付钱以后，商家马上交付商品。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店交付过很多大订单。", "target_word": "交付", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交付了", "label": "体标"}, {"form": "交付过", "label": "体标"}, {"form": "交付日期", "label": "复合词"}], "register": "书面", "sense_fingerprint": "交付：把货物、房子、款项等交给对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b588376-c1a7-4853-aa69-24c24846ed71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90408, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "装修", "is_correct": false, "explanation": "配价：「装修」的对象是房屋等场所，不能带「把……给客户」的结构。"}, {"text": "鉴定", "is_correct": false, "explanation": "语义：「鉴定」是评定真伪或质量，不表示把东西交到对方手里。"}, {"text": "交付", "is_correct": true, "explanation": "正确：「交付」指交给、付给，与「把新车……给客户」搭配。"}, {"text": "修理", "is_correct": false, "explanation": "配价：「修理」只带受事宾语，不能说「修理……给客户」。"}], "explanations": {"装修": "配价：「装修」的对象是房屋等场所，不能带「把……给客户」的结构。", "鉴定": "语义：「鉴定」是评定真伪或质量，不表示把东西交到对方手里。", "交付": "正确：「交付」指交给、付给，与「把新车……给客户」搭配。", "修理": "配价：「修理」只带受事宾语，不能说「修理……给客户」。"}, "sentence_index": 0, "correct_answer": "交付"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天交付我一个温暖的拥抱。", "explanation": "这里应该用〈给〉。交付指把货物、房屋等实物移交给对方，拥抱是动作，不能交付，应说〈给〉我一个拥抱。"}, {"text": "我想交付你一个问题。", "explanation": "这里应该用〈问〉。交付指把实物或任务移交给对方，提问是言语行为，应说〈问〉你一个问题。"}, {"text": "他把那个笑话交付给了大家。", "explanation": "这里应该用〈讲〉。交付是把实物移交给对方，笑话是口头内容，应说〈讲给〉大家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：「欣赏」指欣赏美好之物，与「保证按合同」的履约义务不符。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：「讨论」指商议，与「保证按合同……全部家具」的履约义务不符。"}, {"text": "交付", "is_correct": true, "explanation": "正确：「交付」指把东西交给对方，与「保证按合同……全部家具」搭配。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：「保证」与「忘记」语义矛盾，不能用于履约承诺。"}], "explanations": {"欣赏": "语义：「欣赏」指欣赏美好之物，与「保证按合同」的履约义务不符。", "讨论": "语义：「讨论」指商议，与「保证按合同……全部家具」的履约义务不符。", "交付": "正确：「交付」指把东西交给对方，与「保证按合同……全部家具」搭配。", "忘记": "语义：「保证」与「忘记」语义矛盾，不能用于履约承诺。"}, "sentence_index": 6, "correct_answer": "交付"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店交付了三年的时间。", "explanation": "这里应该用〈度过〉。交付指把实物移交给对方，时间不能移交，说明经过了多久应说〈度过〉三年。"}, {"text": "这家店交付过很多好心情。", "explanation": "这里应该用〈带给〉。交付指把实物移交给对方，心情是感受，应说〈带给〉顾客好心情。"}, {"text": "这家店交付过很多好消息。", "explanation": "这里应该用〈传递〉。交付指把实物移交给对方，消息要说〈传递〉，如〈传递好消息〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂明天会把这批货交付了给客户。", "corrected_sentence": "工厂明天会把这批货交付给客户。", "error_description": "「交付了」错误。句中有「明天会」表示将来，「交付」后不能加「了」，应说「会把这批货交付给客户」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店已经把订单交付对客户了。", "corrected_sentence": "这家店已经把订单交付给客户了。", "error_description": "错误：「交付」引出接受者要用「给」，不能用「对」。应说「这家店已经把订单交付给客户了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
