INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90409, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "站在最前面，带着大家往前走，让事情照他的想法做。", "primary_collocate": null, "pronunciation": "zhǔ dǎo", "ipa": "tʂu˨˩ taʊ˨˩", "syllable_count": 2, "sentences": [{"text": "这次会议由王经理主导。", "target_word": "主导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直主导着我们小组的讨论。", "target_word": "主导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁主导这个项目，谁就要负责。", "target_word": "主导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在家里，妈妈主导所有的大事。", "target_word": "主导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他太想主导一切，没有人愿意听他的。", "target_word": "主导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "整场比赛，中国队一直主导着节奏。", "target_word": "主导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人主导了这次活动的计划。", "target_word": "主导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师不想主导学生的想法，只想帮助他们。", "target_word": "主导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢主导谈话，别人很难说话。", "target_word": "主导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个人合作时，应该由谁来主导？", "target_word": "主导", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "主导着", "label": "体标"}, {"form": "主导了", "label": "体标"}, {"form": "主导过", "label": "体标"}, {"form": "主导作用", "label": "复合"}, {"form": "主導", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "某人站在最前面带领大家，让事情照自己的想法进行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb45aab-75ed-4f65-a859-450e1280774f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90409, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主导", "is_correct": true, "explanation": "正确：“主导”指站在前面带领、掌控，“由王经理主导”即由他带头负责这次会议。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与“由王经理……”所说的负责组织的语境相冲突，句子不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象应是食物，不能与“会议”搭配，“会议由王经理吃”不成立。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能用“由……”引出会议的负责人，“会议由王经理哭”不成立。"}], "explanations": {"主导": "正确：“主导”指站在前面带领、掌控，“由王经理主导”即由他带头负责这次会议。", "讨厌": "语义：“讨厌”表示厌恶，与“由王经理……”所说的负责组织的语境相冲突，句子不通。", "吃": "搭配：“吃”的对象应是食物，不能与“会议”搭配，“会议由王经理吃”不成立。", "哭": "配价：“哭”是不及物动词，不能用“由……”引出会议的负责人，“会议由王经理哭”不成立。"}, "sentence_index": 0, "correct_answer": "主导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我主导了一碗面。", "explanation": "这里应该用〈吃〉。“主导”指带领众人或掌控事情的方向，不能用来说吃面，要说“吃一碗面”。"}, {"text": "妈妈主导了所有的旧书。", "explanation": "这里应该用〈整理〉。“主导”指带领、掌控事情的方向，不能用来说对旧书做整理。"}, {"text": "他主导了那把椅子。", "explanation": "这里应该用〈搬〉。“主导”指带领众人或掌控事情的方向，不能用来说搬动具体的物品，要说“搬那把椅子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90409, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主导", "is_correct": true, "explanation": "正确：“主导了这次活动的计划”指年轻人带头决定了计划的走向。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱计划”，句子不通。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“计划”作宾语。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”不带宾语，不能说“哭了这次活动的计划”。"}], "explanations": {"主导": "正确：“主导了这次活动的计划”指年轻人带头决定了计划的走向。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱计划”，句子不通。", "睡": "配价：“睡”是不及物动词，不能带“计划”作宾语。", "哭": "配价：“哭”不带宾语，不能说“哭了这次活动的计划”。"}, "sentence_index": 6, "correct_answer": "主导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我主导了一张照片。", "explanation": "这里应该用〈拍〉。“主导”指带领众人或掌控事情的方向，不能用来说拍照，要说“拍一张照片”。"}, {"text": "我主导那只小猫。", "explanation": "这里应该用〈喂〉。“主导”不能用来表示照料动物，要说“喂那只小猫”。"}, {"text": "我主导了一觉。", "explanation": "这里应该用〈睡〉。“主导”不能和“一觉”搭配，睡觉要说“睡了一觉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90409, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动，她主导很成功。", "corrected_sentence": "这次活动，她主导得很成功。", "error_description": "“得”漏掉：“主导”后接程度补语时要用“得”，应说“她主导得很成功”，不能直接说“她主导很成功”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90409, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年轻人主导着了这次展览的计划。", "corrected_sentence": "年轻人主导了这次展览的计划。", "error_description": "体标重复：“主导”后已用“了”表示完成，不能再加“着”，应只说“主导了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
