INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90410, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "引导事物向某方向发展；起主要作用。", "primary_collocate": null, "pronunciation": "zhǔ dǎo", "ipa": "tʂu˨˩ taʊ˨˩", "syllable_count": 2, "sentences": [{"text": "市场需求主导着产品的方向。", "target_word": "主导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科技正在主导未来的发展。", "target_word": "主导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "价格由市场主导，不是由政府决定。", "target_word": "主导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题上，文化因素主导着事情的走向。", "target_word": "主导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小公司很难主导行业的发展。", "target_word": "主导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "语言的变化主要由使用者主导。", "target_word": "主导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人的消费主导了今年的市场。", "target_word": "主导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济增长主导着这个城市的发展。", "target_word": "主导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游业正在主导这个地区的发展方向。", "target_word": "主导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过去二十年，手机主导了我们的生活。", "target_word": "主导", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "主导着", "label": "体标"}, {"form": "主导了", "label": "体标"}, {"form": "主导作用", "label": "复合"}, {"form": "主导地位", "label": "复合"}, {"form": "主導", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "某种力量或因素对事物的发展方向起主要作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb45aab-75ed-4f65-a859-450e1280774f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主导", "is_correct": true, "explanation": "正确：“市场需求主导着产品的方向”指市场需求决定了产品的发展走向。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”要求有立场的主体和对立的对象，“需求反对方向”说不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“需求”和“方向”搭配，“吃着产品的方向”不成立。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”带的是场所或展览作宾语，不能带“方向”作宾语。"}], "explanations": {"主导": "正确：“市场需求主导着产品的方向”指市场需求决定了产品的发展走向。", "反对": "语义：“反对”要求有立场的主体和对立的对象，“需求反对方向”说不通。", "吃": "搭配：“吃”不能与“需求”和“方向”搭配，“吃着产品的方向”不成立。", "参观": "配价：“参观”带的是场所或展览作宾语，不能带“方向”作宾语。"}, "sentence_index": 0, "correct_answer": "主导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈主导了房间。", "explanation": "这里应该用〈打扫〉。“主导”表示引导事物的发展方向，不能用来指对房间做清洁。"}, {"text": "他主导了一封信。", "explanation": "这里应该用〈写〉。“主导”用于事物的发展方向或作用，不能用来说写信，要说“写一封信”。"}, {"text": "我主导了一杯咖啡。", "explanation": "这里应该用〈喝〉。“主导”用于事物的发展方向或作用，不能用来说喝饮料，要说“喝一杯咖啡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主导", "is_correct": true, "explanation": "正确：“年轻人的消费主导了今年的市场”指年轻人的消费起了决定性作用。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱了今年的市场”。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”不带宾语，不能带“市场”作宾语。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“市场”作宾语。"}], "explanations": {"主导": "正确：“年轻人的消费主导了今年的市场”指年轻人的消费起了决定性作用。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱了今年的市场”。", "哭": "配价：“哭”不带宾语，不能带“市场”作宾语。", "睡": "配价：“睡”是不及物动词，不能带“市场”作宾语。"}, "sentence_index": 6, "correct_answer": "主导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我主导明天去北京。", "explanation": "这里应该用〈决定〉。“主导”用于事物的发展方向或作用，后面不能接具体的行程安排。"}, {"text": "我主导了一百分。", "explanation": "这里应该用〈考〉。“主导”用于事物的发展方向或作用，不能用来说考试成绩，要说“考了一百分”。"}, {"text": "我主导了一个小时。", "explanation": "这里应该用〈花〉。“主导”不能用来说花费时间，要说“花了一个小时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市场需求将主导了这个产品的方向。", "corrected_sentence": "市场需求将主导这个产品的方向。", "error_description": "体标错误：“将”表示将来，不能与表示完成的“了”同用，应说“将主导这个产品的方向”，不能说“将主导了这个产品的方向”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经济增长主导着了这个城市的未来。", "corrected_sentence": "经济增长主导着这个城市的未来。", "error_description": "体标重复：“主导”后已用“着”，不能再加“了”，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
