INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90415, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用一个东西来换另一个，做原来那个的事。", "primary_collocate": null, "pronunciation": "dài tì", "ipa": "taɪ̯˥˩ tʰi˥˩", "syllable_count": 2, "sentences": [{"text": "我用手机代替了手表。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人用微信代替打电话。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头不够，就用石头代替。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用笔记本代替了课本。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多人用电子书代替纸书。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有糖，可以用蜂蜜代替。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子可以代替碗用。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用新电脑代替旧电脑。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以用水代替咖啡。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用小盒子代替了大箱子。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "代替了", "label": "体标"}, {"form": "代替着", "label": "体标"}], "register": "中性", "sense_fingerprint": "用一个东西换掉另一个，让它做原来那个的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a22d3499-ca45-4e80-9518-98ccdc905de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90415, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代替", "is_correct": true, "explanation": "正确：“代替”表示用手机顶替手表，与前面的“用”和宾语搭配自然。"}, {"text": "使用", "is_correct": false, "explanation": "搭配：“用手机”已经说明工具，再说“使用了手表”语义重复，而且手表不能这样被“使用”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象不能是手表，“我用手机吃了手表”不通。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”的对象应是人，不能说感谢手表。"}], "explanations": {"代替": "正确：“代替”表示用手机顶替手表，与前面的“用”和宾语搭配自然。", "使用": "搭配：“用手机”已经说明工具，再说“使用了手表”语义重复，而且手表不能这样被“使用”。", "吃": "语义：“吃”的对象不能是手表，“我用手机吃了手表”不通。", "感谢": "语义：“感谢”的对象应是人，不能说感谢手表。"}, "sentence_index": 0, "correct_answer": "代替"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个骗子代替了老人的钱。", "explanation": "这里应该用〈骗走〉。代替指一物顶替另一物承担其作用，骗取钱财要说骗走。"}, {"text": "我们代替了那辆车的轮胎。", "explanation": "这里应该用〈更换〉。代替强调由另一物承担原来的作用，只是换掉旧零件要说更换。"}, {"text": "他和妹妹代替了座位。", "explanation": "这里应该用〈交换〉。代替是一方顶替另一方，双方互换座位要说交换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90415, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代替", "is_correct": true, "explanation": "正确：“代替”表示杯子可以顶替碗来用。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”指破坏完整的东西，“打破碗用”不成搭配。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是审美态度，不能表示把杯子当碗用。"}, {"text": "检查", "is_correct": false, "explanation": "语义：“检查”的对象不能是碗，“检查碗用”不通。"}], "explanations": {"代替": "正确：“代替”表示杯子可以顶替碗来用。", "打破": "搭配：“打破”指破坏完整的东西，“打破碗用”不成搭配。", "欣赏": "语义：“欣赏”是审美态度，不能表示把杯子当碗用。", "检查": "语义：“检查”的对象不能是碗，“检查碗用”不通。"}, "sentence_index": 6, "correct_answer": "代替"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他代替了屋顶的那个漏洞。", "explanation": "这里应该用〈修补〉。代替指由另一物顶替原来的作用，把屋顶的漏洞补好要说修补。"}, {"text": "这一年季节代替了两次。", "explanation": "这里应该用〈更替〉。代替需要一个东西顶替另一个，季节交替要说更替。"}, {"text": "这辆汽车代替了那些汽油。", "explanation": "这里应该用〈消耗〉。代替指用一物顶替另一物，汽车耗用汽油要说消耗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90415, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用新电脑代替了的旧电脑。", "corrected_sentence": "他用新电脑代替了旧电脑。", "error_description": "错误形式：“代替了的旧电脑”。“代替”带宾语“旧电脑”，“代替了”后不能再加“的”构成定语，应说“代替了旧电脑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90415, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小碗可以代替了杯子用。", "corrected_sentence": "这个小碗可以代替杯子用。", "error_description": "错误形式：“可以代替了杯子用”。正确形式：“可以代替杯子用”。这里说的是一种可能的用法，还没有完成，“代替”后不能加表示完成的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90416, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
