INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90416, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用甲换乙，起乙的作用。", "primary_collocate": null, "pronunciation": "dài tì", "ipa": "taɪ̯˥˩ tʰi˥˩", "syllable_count": 2, "sentences": [{"text": "汽车代替了马，成了主要的交通工具。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器代替人做了很多重活。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机代替了照相机和地图。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的老师代替王老师上课。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我代替哥哥去机场接朋友。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天你代替我去开会，好吗？", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有谁能代替妈妈在我心里的位置。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，小李代替他参加比赛。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小机器人代替了过去的服务员。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸出差了，我来代替他做饭。", "target_word": "代替", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "代替了", "label": "体标"}, {"form": "代替着", "label": "体标"}], "register": "中性", "sense_fingerprint": "甲取代乙，担当乙原来的作用或位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a22d3499-ca45-4e80-9518-98ccdc905de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90416, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代替", "is_correct": true, "explanation": "正确：汽车顶替了马原来的交通作用。"}, {"text": "驯服", "is_correct": false, "explanation": "语义：“驯服”指使动物服从，汽车不能驯服马。"}, {"text": "训练", "is_correct": false, "explanation": "配价：“训练”需要施训者，“汽车”不能作训练马的施事。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”要求施事能给对象东西吃，汽车不能喂马。"}], "explanations": {"代替": "正确：汽车顶替了马原来的交通作用。", "驯服": "语义：“驯服”指使动物服从，汽车不能驯服马。", "训练": "配价：“训练”需要施训者，“汽车”不能作训练马的施事。", "喂": "搭配：“喂”要求施事能给对象东西吃，汽车不能喂马。"}, "sentence_index": 0, "correct_answer": "代替"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班的人数代替了三十个人。", "explanation": "这里应该用〈增加〉。代替指由一物顶替另一物，班里人数变多要说增加。"}, {"text": "这台机器代替了那批旧设备的价格。", "explanation": "这里应该用〈提高〉。代替指顶替原来的事物，让价格变高要说提高价格。"}, {"text": "妈妈代替了我的生日。", "explanation": "这里应该用〈庆祝〉。代替指顶替别人承担作用，生日要说庆祝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90416, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代替", "is_correct": true, "explanation": "正确：“代替”表示没有谁能顶替妈妈在我心里的位置。"}, {"text": "测量", "is_correct": false, "explanation": "语义：“测量”需要可以量度的对象，心里的位置不能被测量。"}, {"text": "背叛", "is_correct": false, "explanation": "配价：“背叛”的对象是人，不能说背叛“妈妈的位置”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象不能是位置，“吃妈妈的位置”不通。"}], "explanations": {"代替": "正确：“代替”表示没有谁能顶替妈妈在我心里的位置。", "测量": "语义：“测量”需要可以量度的对象，心里的位置不能被测量。", "背叛": "配价：“背叛”的对象是人，不能说背叛“妈妈的位置”。", "吃": "搭配：“吃”的对象不能是位置，“吃妈妈的位置”不通。"}, "sentence_index": 6, "correct_answer": "代替"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他代替了一场比赛。", "explanation": "这里应该用〈参加〉。代替指顶替别人去做事，参加比赛要说参加。"}, {"text": "他代替了那次演讲的题目。", "explanation": "这里应该用〈拟定〉。代替指顶替别人做事，给演讲定题目要说拟定。"}, {"text": "他代替了那个剧本。", "explanation": "这里应该用〈编写〉。代替指顶替别人做事，写剧本要说编写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新来的经理代替把老经理开会。", "corrected_sentence": "新来的经理代替老经理开会。", "error_description": "错误形式：“代替把老经理开会”。正确形式：“代替老经理开会”。“老经理”是“代替”的宾语，直接放在“代替”后面，前面不能加“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐给代替我照顾弟弟。", "corrected_sentence": "姐姐代替我照顾弟弟。", "error_description": "错误形式：“给代替我”。正确形式：“代替我”前不加“给”，应说“姐姐代替我照顾弟弟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
