INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90417, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "高就是一句有礼貌的话，说别人去了更好的地方工作。", "primary_collocate": null, "pronunciation": "gāo jiù", "ipa": "kɑʊ˥˥ tɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "请问您现在在哪家公司高就？", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说您在大医院高就，真让人羡慕。", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老同学，现在在哪里高就呢？", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "久不见面，不知您在何处高就？", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你另有高就，真为你高兴。", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您换了工作，在哪家银行高就？", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友见面时，他笑着问：“在哪儿高就？”", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想问问，您毕业以后在哪儿高就？", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王，听说你在新单位高就，工资一定不低。", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李的父亲问客人在哪里高就。", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高就了", "label": "完成体"}], "register": "敬辞", "sense_fingerprint": "高就：有礼貌地问或说别人在更好的地方工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc92a6b-6dc2-4a5f-9877-7bf97a1744bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90417, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高就", "is_correct": true, "explanation": "正确：“高就”是敬辞，礼貌地询问对方现在任职的地方，符合问句语境。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”指没有工作，与“在哪家公司”的提问相冲突，无法回答。"}, {"text": "跳槽", "is_correct": false, "explanation": "语义：“跳槽”指离开旧单位另谋他处，问“现在在哪家公司跳槽”与“现在”的任职状态相冲突，搭配不通。"}, {"text": "辞掉", "is_correct": false, "explanation": "配价：“辞掉”需要工作作宾语，“在哪家公司辞掉”不完整，无法作答。"}], "explanations": {"高就": "正确：“高就”是敬辞，礼貌地询问对方现在任职的地方，符合问句语境。", "失业": "语义：“失业”指没有工作，与“在哪家公司”的提问相冲突，无法回答。", "跳槽": "语义：“跳槽”指离开旧单位另谋他处，问“现在在哪家公司跳槽”与“现在”的任职状态相冲突，搭配不通。", "辞掉": "配价：“辞掉”需要工作作宾语，“在哪家公司辞掉”不完整，无法作答。"}, "sentence_index": 0, "correct_answer": "高就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我上个月在一家新公司高就了，现在很忙。", "explanation": "这里应该用〈跳槽〉。高就是敬辞，只用于称对方，自己换工作不能说高就。"}, {"text": "老张在公司内部高就了，还在原来的办公室。", "explanation": "这里应该用〈升职〉。高就指离开原单位去就任更高的职位，留在公司内部晋升不能说高就。"}, {"text": "我们部门的小李上周高就了，现在每天在家找工作。", "explanation": "这里应该用〈下岗〉。高就指去了更好的地方工作，而“在家找工作”说明已经失去原来的工作，应该说下岗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90417, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高就", "is_correct": true, "explanation": "正确：“高就”是敬辞，礼貌地问朋友在哪里任职，符合见面问候的语境。"}, {"text": "下岗", "is_correct": false, "explanation": "语义：“下岗”指失去岗位，问“在哪儿下岗”与问候的语境不合。"}, {"text": "躺平", "is_correct": false, "explanation": "语域：“躺平”是带消极态度的网络口语，不适合在笑着问候时使用。"}, {"text": "倒闭", "is_correct": false, "explanation": "搭配：“倒闭”用于单位或店铺，不能用来问人在哪里“倒闭”。"}], "explanations": {"高就": "正确：“高就”是敬辞，礼貌地问朋友在哪里任职，符合见面问候的语境。", "下岗": "语义：“下岗”指失去岗位，问“在哪儿下岗”与问候的语境不合。", "躺平": "语域：“躺平”是带消极态度的网络口语，不适合在笑着问候时使用。", "倒闭": "搭配：“倒闭”用于单位或店铺，不能用来问人在哪里“倒闭”。"}, "sentence_index": 6, "correct_answer": "高就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从科长高就为办事员，大家都很意外。", "explanation": "这里应该用〈降职〉。高就指就任更高的职位，职位降低不能用高就。"}, {"text": "我的父亲去年高就了，现在每天在家养花。", "explanation": "这里应该用〈退休〉。高就指去了更好的地方工作，退休后不再工作，不能用高就。"}, {"text": "那家商店高就了，搬到了市中心。", "explanation": "这里〈高就〉被用来指商店搬到市中心、经营升级，但高就只说人去了更好的地方工作，主语只能是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90417, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "张老师一所大学高就，真让人羡慕。", "corrected_sentence": "张老师在一所大学高就，真让人羡慕。", "error_description": "错误：缺少介词“在”。处所要用“在”引出，正确说法是“在一所大学高就”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90417, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老同学，你现在在银行很高就吗？", "corrected_sentence": "老同学，你现在在银行高就吗？", "error_description": "错误：程度副词「很」不能修饰动词「高就」，多出的「很」是错误的。应删去「很」，说「在银行高就」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
