INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90418, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "敬辞，称对方离开原职就任更高的职位。", "primary_collocate": null, "pronunciation": "gāo jiù", "ipa": "kɑʊ˥˥ tɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "听说您已经高就了，恭喜恭喜！", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王经理，听说您高就了，祝您前程似锦。", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您离开公司后，现在在哪儿高就？", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恭喜您高就，以后请多联系。", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老同学，听说你高就了，请客吧！", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您上个月高就的消息，我今天才知道。", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张总，您高就以后，还常回来看看吗？", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年不见，请问您现在在何处高就？", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陈先生，听说您高就了，请别忘了老朋友。", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您高就以后，我们都很想念您。", "target_word": "高就", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高就了", "label": "完成体"}], "register": "敬辞", "sense_fingerprint": "高就：敬辞，称对方离开原职、就任更高的职位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc92a6b-6dc2-4a5f-9877-7bf97a1744bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90418, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高就", "is_correct": true, "explanation": "正确：“高就”是敬辞，指对方离开原职就任更高职位，与“恭喜恭喜”的语境相合。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”指失去工作，与“恭喜恭喜”的喜庆语境正好相反。"}, {"text": "打工", "is_correct": false, "explanation": "语域：“打工”是口语，多用于自称，对“您”说“您已经打工了”显得不敬，也不合祝贺语境。"}, {"text": "辞退", "is_correct": false, "explanation": "配价：“辞退”需要被辞退的人作宾语，“您已经辞退了”会被理解为您辞退了别人，与恭喜不合。"}], "explanations": {"高就": "正确：“高就”是敬辞，指对方离开原职就任更高职位，与“恭喜恭喜”的语境相合。", "失业": "语义：“失业”指失去工作，与“恭喜恭喜”的喜庆语境正好相反。", "打工": "语域：“打工”是口语，多用于自称，对“您”说“您已经打工了”显得不敬，也不合祝贺语境。", "辞退": "配价：“辞退”需要被辞退的人作宾语，“您已经辞退了”会被理解为您辞退了别人，与恭喜不合。"}, "sentence_index": 0, "correct_answer": "高就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我上个月高就了，现在在一家新公司工作。", "explanation": "这里应该用〈跳槽〉。高就是敬辞，只用于称对方离开原职，自己换工作不能说高就。"}, {"text": "王经理在本公司高就为总经理，还在原来的楼里办公。", "explanation": "这里应该用〈升职〉。高就指离开原单位去就任更高的职位，留在原公司晋升不能说高就。"}, {"text": "他工作出了大错，上周被公司高就了。", "explanation": "这里应该用〈辞退〉。高就是敬辞，指对方主动离开原职、就任更高职位，被公司开除不能说高就。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高就", "is_correct": true, "explanation": "正确：“高就”是敬辞，用于询问或祝愿对方的新职位，符合“张总”的语境。"}, {"text": "倒闭", "is_correct": false, "explanation": "搭配：“倒闭”用于企业或店铺，不能用来说人“倒闭”。"}, {"text": "下岗", "is_correct": false, "explanation": "语义：“下岗”指失去岗位，与“张总”的尊称以及“常回来看看”的语境冲突。"}, {"text": "混", "is_correct": false, "explanation": "语域：“混”是口语，带随意之意，对张总说不合敬语语域。"}], "explanations": {"高就": "正确：“高就”是敬辞，用于询问或祝愿对方的新职位，符合“张总”的语境。", "倒闭": "搭配：“倒闭”用于企业或店铺，不能用来说人“倒闭”。", "下岗": "语义：“下岗”指失去岗位，与“张总”的尊称以及“常回来看看”的语境冲突。", "混": "语域：“混”是口语，带随意之意，对张总说不合敬语语域。"}, "sentence_index": 6, "correct_answer": "高就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从副总高就为普通职员，大家都很惊讶。", "explanation": "这里应该用〈降职〉。高就指就任更高的职位，职位下降不能用高就。"}, {"text": "张师傅前年高就了，现在每天去公园下棋。", "explanation": "这里应该用〈退休〉。高就指离开原职、就任更高的职位，退休后不再任职，不能用高就。"}, {"text": "那家餐厅高就了，生意越来越好。", "explanation": "这里〈高就〉被用来指餐厅生意好转、扩大经营，但高就只用于人离开原职、就任更高职位，主语只能是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "王经理一家大银行高就了。", "corrected_sentence": "王经理在一家大银行高就了。", "error_description": "错误：缺少介词“在”。处所要先用“在”引出，正确说法是“在一家大银行高就了”；“高就”不能直接带处所宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "刘教授，听说您把北大高就了，真是喜事。", "corrected_sentence": "刘教授，听说您在北大高就了，真是喜事。", "error_description": "错误：把“在”误用为“把”。“高就”是不及物动词，不能用“把”字句；正确是“在北大高就了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90419, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
