INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90419, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "占先是比别人先得到好处，排在前面。", "primary_collocate": null, "pronunciation": "zhàn xiān", "ipa": "tʂan˥˩ ɕiɛn˥", "syllable_count": 2, "sentences": [{"text": "他跑得快，一开始就占先了。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排队时他想占先，就挤到了前面。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店送礼物，早到的人能占先。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李早点出发，想在路上占先。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁先报名谁就占先，大家别晚了。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总想占先，不愿意排在别人后面。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛一开始，我们队就想占先。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提前准备材料，面试时就能占先。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都抢着上车，想占先坐好位子。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "占先的人拿到了最好的座位。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "占过先", "label": "体标"}, {"form": "佔先", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比别人先得到好处、排在前面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36662012-8007-41fe-a78e-aaa6e4d441d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90419, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "占先", "is_correct": true, "explanation": "正确。“占先”指比别人先得到好处、排在前面，与“跑得快，一开始就”相符。"}, {"text": "落后", "is_correct": false, "explanation": "语义：“跑得快”与“落后”相矛盾，跑得快的人不会落后。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”与“跑得快，一开始就”矛盾，跑得快的人不会迟到。"}, {"text": "脸红", "is_correct": false, "explanation": "体貌：“脸红”描述脸色的变化，与比赛中跑得快的动作无关。"}], "explanations": {"占先": "正确。“占先”指比别人先得到好处、排在前面，与“跑得快，一开始就”相符。", "落后": "语义：“跑得快”与“落后”相矛盾，跑得快的人不会落后。", "迟到": "语义：“迟到”与“跑得快，一开始就”矛盾，跑得快的人不会迟到。", "脸红": "体貌：“脸红”描述脸色的变化，与比赛中跑得快的动作无关。"}, "sentence_index": 0, "correct_answer": "占先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他迟到了很久，一直占先。", "explanation": "语义：占先指先得到好处、排在前面，迟到的人不可能占先，这里应该用〈落后〉。"}, {"text": "我们这场比赛输得很惨，最后却占先了。", "explanation": "语义：输得很惨的一方不会占先，这里应该用〈落后〉。"}, {"text": "他考试时睡着了，结果占先了。", "explanation": "语义：睡着的人不可能先得到好处，这里应该用〈落后〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90419, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "占先", "is_correct": true, "explanation": "正确。比赛一开始就想先得到好处，与“占先”相符。"}, {"text": "认输", "is_correct": false, "explanation": "语义：比赛一开始就想认输，与本句的积极意图矛盾。"}, {"text": "打盹", "is_correct": false, "explanation": "语义：比赛刚开始就打盹，不符合“想占先”的意图。"}, {"text": "发胖", "is_correct": false, "explanation": "体貌：“发胖”指身体外形的变化，与比赛中的争先无关。"}], "explanations": {"占先": "正确。比赛一开始就想先得到好处，与“占先”相符。", "认输": "语义：比赛一开始就想认输，与本句的积极意图矛盾。", "打盹": "语义：比赛刚开始就打盹，不符合“想占先”的意图。", "发胖": "体貌：“发胖”指身体外形的变化，与比赛中的争先无关。"}, "sentence_index": 6, "correct_answer": "占先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了赶火车，我们占先睡过了头。", "explanation": "语义：占先指先得到好处，睡过头错过火车不是得好处，此处不能用“占先”。"}, {"text": "他占先摔了一跤，爬不起来。", "explanation": "语义：摔跤不是得到好处，此处不能用“占先”。"}, {"text": "他占先丢了钱包，只好向朋友借钱。", "explanation": "语义：丢钱包不是得到好处，此处不能用“占先”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90419, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她早到一步，占先了前排。", "corrected_sentence": "她早到一步，占先了。", "error_description": "错误：“占先”是不及物动词，后面不能直接带宾语“前排”。正确说法是“她早到一步，占先了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90419, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先到的人把占先，拿到了最好的座位。", "corrected_sentence": "先到的人占先，拿到了最好的座位。", "error_description": "错误：“占先”是不及物动词，不能放在“把”字结构中作宾语，应直接作谓语：“先到的人占先，拿到了最好的座位。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
