INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90420, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "占据优先地位；抢先。", "primary_collocate": null, "pronunciation": "zhàn xiān", "ipa": "tʂan˥˩ ɕiɛn˥", "syllable_count": 2, "sentences": [{"text": "这家公司在市场上占先，别人很难追上。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在比赛中占先，所以一开始就用力跑。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先发球的一方更容易占先。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们抢着发言，都想占先。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在新产品上，我们公司已经占先了。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下棋时先走的人往往占先。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她动作快，在谈判中一直占先。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁先到那里，谁就占先。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两队都想占先，比分咬得很紧。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他占先之后，就不再着急了。", "target_word": "占先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "占过先", "label": "体标"}, {"form": "佔先", "label": "繁体"}], "register": "中性", "sense_fingerprint": "占据优先地位、抢先", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36662012-8007-41fe-a78e-aaa6e4d441d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "占先", "is_correct": true, "explanation": "正确。“占先”表示在市场上占据优先地位，与“别人很难追上”相符。"}, {"text": "退步", "is_correct": false, "explanation": "语义：退步会让别人更容易追上，与“别人很难追上”矛盾。"}, {"text": "失利", "is_correct": false, "explanation": "语义：失利指输掉，与句中占据优势的意思不符。"}, {"text": "成交", "is_correct": false, "explanation": "搭配：“成交”指达成买卖，不用来说市场上的优先地位。"}], "explanations": {"占先": "正确。“占先”表示在市场上占据优先地位，与“别人很难追上”相符。", "退步": "语义：退步会让别人更容易追上，与“别人很难追上”矛盾。", "失利": "语义：失利指输掉，与句中占据优势的意思不符。", "成交": "搭配：“成交”指达成买卖，不用来说市场上的优先地位。"}, "sentence_index": 0, "correct_answer": "占先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛他们输得很惨，却总是占先。", "explanation": "语义：占先表示先得到好处，输得很惨的一方不能占先，这里应该用〈落后〉。"}, {"text": "我们每天都睡懒觉，所以总是占先。", "explanation": "语义：睡懒觉与先得到好处相矛盾，这里应该用〈落后〉。"}, {"text": "他跑得最慢，结果次次占先。", "explanation": "语义：跑得最慢的人不可能占先，这里应该用〈落后〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "占先", "is_correct": true, "explanation": "正确。在谈判中一直抢先得利，与“占先”相符。"}, {"text": "掉队", "is_correct": false, "explanation": "语义：动作快却一直掉队，与句中积极争先的状态矛盾。"}, {"text": "落后", "is_correct": false, "explanation": "语义：“动作快”却“一直落后”，与句意矛盾。"}, {"text": "发呆", "is_correct": false, "explanation": "搭配：“发呆”描述静止的状态，不能用来说谈判中的争先。"}], "explanations": {"占先": "正确。在谈判中一直抢先得利，与“占先”相符。", "掉队": "语义：动作快却一直掉队，与句中积极争先的状态矛盾。", "落后": "语义：“动作快”却“一直落后”，与句意矛盾。", "发呆": "搭配：“发呆”描述静止的状态，不能用来说谈判中的争先。"}, "sentence_index": 6, "correct_answer": "占先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他占先生病住院了，没能来上课。", "explanation": "语义：生病住院不是得到好处，此处不能用“占先”。"}, {"text": "他动作最慢，从头到尾都占先。", "explanation": "语义：占先表示占据优先地位，动作最慢的人不可能一直占先，这里应该用〈落后〉。"}, {"text": "他占先忘了带钥匙，只好在门口等。", "explanation": "语义：占先表示占据优先地位，忘带钥匙与此无关，此处不能用“占先”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司在这一点上很占先。", "corrected_sentence": "我们公司在这一点上占先。", "error_description": "错误：“占先”是动词，前面不能加程度副词“很”，应去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他了占先，就不再着急了。", "corrected_sentence": "他占了先，就不再着急了。", "error_description": "错误：“了”放在“占先”前面，应为“占了先”，把“了”放在“占”和“先”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
