INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90421, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人做某件工作，说好可以做多久的那段时间。", "primary_collocate": null, "pronunciation": "rèn qī", "ipa": "ʐən˥˩ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "班长的任期是一年。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的任期还有三个月就到了。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在任期里，他把公司管得很好。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理的任期结束后，大家选了新人。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在任期内多做几件好事。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位校长的任期很长，做了十年。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新班长的任期从下个月开始。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在任期中学到了很多东西。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长的任期只有半年，时间不长。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的任期快到了，不想再做下去。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "任期制", "label": "复合"}], "register": "中性", "sense_fingerprint": "任期：日常工作岗位（班长、经理等）说好能做多久的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '472a9012-31ef-4449-9907-721337a9f32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90421, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "职务", "is_correct": false, "explanation": "语义：“职务”指职位与职责，不指任职的时长，不能说“是一年”。"}, {"text": "任期", "is_correct": true, "explanation": "任期：班长担任职务的规定期限，这里是一年，与“是一年”相符。"}, {"text": "任务", "is_correct": false, "explanation": "搭配：“任务”可以布置、完成，但不能说“任务是一年”，说明时长要用“任期”。"}, {"text": "班级", "is_correct": false, "explanation": "语义：“班级”指一个集体，不能用“是一年”来说明它的时长。"}], "explanations": {"职务": "语义：“职务”指职位与职责，不指任职的时长，不能说“是一年”。", "任期": "任期：班长担任职务的规定期限，这里是一年，与“是一年”相符。", "任务": "搭配：“任务”可以布置、完成，但不能说“任务是一年”，说明时长要用“任期”。", "班级": "语义：“班级”指一个集体，不能用“是一年”来说明它的时长。"}, "sentence_index": 0, "correct_answer": "任期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个项目的任期是三个月，必须在这段时间内完成。", "explanation": "这里应该用〈期限〉。任期只指担任职务的时间，项目的时限要用期限。"}, {"text": "这次培训的任期是一周，大家都要按时参加。", "explanation": "这里应该用〈时间〉。培训、活动的时长不用任期，任期只用于担任职务的期限。"}, {"text": "这座大桥的任期是两年，今年已经完成了一半。", "explanation": "这里应该用〈工期〉。任期指担任职务的期限，施工的时限要用工期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90421, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是人的岁数，不会“从下个月开始”。"}, {"text": "学期", "is_correct": false, "explanation": "语义：“学期”指学校的一个学段，不是班长的任职时段。"}, {"text": "任期", "is_correct": true, "explanation": "任期：担任班长的规定期限，从下个月起算，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是身体特征，不能用“从下个月开始”来说明。"}], "explanations": {"年龄": "语义：“年龄”是人的岁数，不会“从下个月开始”。", "学期": "语义：“学期”指学校的一个学段，不是班长的任职时段。", "任期": "任期：担任班长的规定期限，从下个月起算，符合句意。", "身高": "体貌：“身高”是身体特征，不能用“从下个月开始”来说明。"}, "sentence_index": 6, "correct_answer": "任期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家小店的任期是十年，到期后要重新签约。", "explanation": "这里应该用〈租期〉。任期只指担任职务的时间，店铺的租赁时限要用租期。"}, {"text": "这部电影的任期是两个小时，中间没有休息。", "explanation": "这里应该用〈片长〉。影视作品的时长不用任期，任期只指担任职务的时间。"}, {"text": "这张会员卡的任期是一年，到期要重新办理。", "explanation": "这里应该用〈有效期〉。会员卡等凭证的期限不用任期，任期只指担任职务的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90421, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经完成了一只任期。", "corrected_sentence": "他已经完成了一届任期。", "error_description": "量词错误。“任期”应搭配“届”（一届任期）或“段”，“只”用于动物等，不能修饰“任期”。正确说法是“他已经完成了一届任期”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90421, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他当了两本任期的班长。", "corrected_sentence": "他当了两届任期的班长。", "error_description": "量词错误。“任期”应搭配“届”（两届任期），“本”用于书本等，不能修饰“任期”。正确说法是“他当了两届任期的班长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
