INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90422, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "担任某职务的规定期限。", "primary_collocate": null, "pronunciation": "rèn qī", "ipa": "ʐən˥˩ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "市长的任期是五年。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统的任期有明确的规定。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律规定，主席每届任期四年。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在任期内推动了很多改革。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位部长的任期将在明年结束。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任期届满后，他离开了这个岗位。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家对领导人的任期有限制。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "委员会主任的任期不能超过两届。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他任期未满，就因病辞职了。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新校长的任期从九月一日开始。", "target_word": "任期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "任期制", "label": "复合"}], "register": "书面", "sense_fingerprint": "任期：市长、总统、主席等职务由法律或章程规定的任职期限", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '472a9012-31ef-4449-9907-721337a9f32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90422, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是身体特征，不能说“市长的身高是五年”。"}, {"text": "任期", "is_correct": true, "explanation": "任期：市长担任职务的规定年限，即五年，与句意相符。"}, {"text": "差事", "is_correct": false, "explanation": "语域：“差事”是口语，指工作本身，书面语境中不用它表示任职期限。"}, {"text": "职责", "is_correct": false, "explanation": "语义：“职责”指应尽的责任，不指时长，不能说“是五年”。"}], "explanations": {"身高": "体貌：“身高”是身体特征，不能说“市长的身高是五年”。", "任期": "任期：市长担任职务的规定年限，即五年，与句意相符。", "差事": "语域：“差事”是口语，指工作本身，书面语境中不用它表示任职期限。", "职责": "语义：“职责”指应尽的责任，不指时长，不能说“是五年”。"}, "sentence_index": 0, "correct_answer": "任期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次大会的任期是三天，大家都要准时参加。", "explanation": "这里应该用〈会期〉。任期只指担任职务的时间，会议延续的时间要用会期。"}, {"text": "他入伍后，任期是两年，到期就能退伍。", "explanation": "这里应该用〈服役期〉。入伍后的服役时限称服役期，任期只用于担任职务。"}, {"text": "这台电脑的任期是三年，过了这段时间就不能免费维修。", "explanation": "这里应该用〈保修期〉。任期用于担任职务，商品的保修时限要用保修期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课程", "is_correct": false, "explanation": "语义：“课程”是学习的内容，“领导人的课程”不成立，句意无法理解。"}, {"text": "任期", "is_correct": true, "explanation": "任期：领导人担任职务的期限，国家对其有规定，与句意相符。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”是体态特征，“国家对领导人的身材有限制”说不通。"}, {"text": "活儿", "is_correct": false, "explanation": "语域：“活儿”是口语，书面语境中不用，也不指任职期限。"}], "explanations": {"课程": "语义：“课程”是学习的内容，“领导人的课程”不成立，句意无法理解。", "任期": "任期：领导人担任职务的期限，国家对其有规定，与句意相符。", "身材": "体貌：“身材”是体态特征，“国家对领导人的身材有限制”说不通。", "活儿": "语域：“活儿”是口语，书面语境中不用，也不指任职期限。"}, "sentence_index": 6, "correct_answer": "任期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份合同的任期是三年，到期可以续签。", "explanation": "这里应该用〈期限〉。合同的时限不用任期，任期只指担任职务的规定期限。"}, {"text": "这块手表的任期是两年，过了这段时间就要收费维修。", "explanation": "这里应该用〈保修期〉。商品的免费维修时限要用保修期，任期只用于担任职务。"}, {"text": "这所学校的任期是三年，学生毕业后就离开。", "explanation": "这里应该用〈学制〉。学校的修业年限称学制，任期只用于担任职务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他完成了一条任期，回到了家乡。", "corrected_sentence": "他完成了一段任期，回到了家乡。", "error_description": "量词错误。“任期”应搭配“段”或“届”（一段任期、一届任期），“条”用于细长的物件，不能修饰“任期”。正确说法是“他完成了一段任期”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她做满了两张任期，才离开委员会。", "corrected_sentence": "她做满了两届任期，才离开委员会。", "error_description": "量词错误。“任期”应搭配“届”（两届任期），“张”用于纸、桌子等平面物件，不能修饰“任期”。正确说法是“她做满了两届任期”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
