INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90425, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示实际情况与预想或常理不同，带有出乎意料的语气。", "primary_collocate": null, "pronunciation": "dào shì", "ipa": "tɑʊ˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "我以为他会生气，他倒是笑了。", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我以为这道菜很辣，吃起来倒是不辣。", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都累坏了，他倒是一点儿也不累。", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我以为会很难，做起来倒是很简单。", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他平时话很多，今天倒是很安静。", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我担心天气不好，今天倒是个大晴天。", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我以为你早就忘了这件事，你倒是记得很清楚。", "target_word": "倒是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那家饭馆很贵，价钱倒是不高。", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都说他很懒，他倒是干活很快。", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我以为这家店很小，进去倒是挺大的。", "target_word": "倒是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "倒是：表示实际情况与预想或常理不同，带有出乎意料的语气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20f9c372-ecc3-4b34-9028-39b875025280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90425, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "倒是", "is_correct": true, "explanation": "倒是：副词，表示实际情况与预想或常理不同，带有出乎意料的语气，读作 dào shì。"}, {"text": "大事", "is_correct": false, "explanation": "dà（第四声）与 dào 韵母不同（a 与 ao），意思是大事。"}, {"text": "导师", "is_correct": false, "explanation": "dǎo（第三声）与 dào（第四声）声调不同，shī（第一声）与 shì（第四声）声调也不同，意思是导师。"}, {"text": "闹事", "is_correct": false, "explanation": "nào 与 dào 声母不同（n 与 d），意思是闹事、捣乱。"}], "explanations": {"倒是": "倒是：副词，表示实际情况与预想或常理不同，带有出乎意料的语气，读作 dào shì。", "大事": "dà（第四声）与 dào 韵母不同（a 与 ao），意思是大事。", "导师": "dǎo（第三声）与 dào（第四声）声调不同，shī（第一声）与 shì（第四声）声调也不同，意思是导师。", "闹事": "nào 与 dào 声母不同（n 与 d），意思是闹事、捣乱。"}, "sentence_index": null, "correct_answer": "倒是"}, "level_3": {"options": [{"text": "倒是", "is_correct": true, "explanation": "倒是：表示「我以为他会生气」之后，实际他却笑了，与预想不同。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：「从来」须与否定词连用，不能与「笑了」这样的肯定句搭配。"}, {"text": "常常", "is_correct": false, "explanation": "体貌：「常常」表示经常发生，与表示一次完成的「了」不相容。"}, {"text": "一向", "is_correct": false, "explanation": "体貌：「一向」描述长期习惯，与「笑了」表示的具体一次动作矛盾。"}], "explanations": {"倒是": "倒是：表示「我以为他会生气」之后，实际他却笑了，与预想不同。", "从来": "搭配：「从来」须与否定词连用，不能与「笑了」这样的肯定句搭配。", "常常": "体貌：「常常」表示经常发生，与表示一次完成的「了」不相容。", "一向": "体貌：「一向」描述长期习惯，与「笑了」表示的具体一次动作矛盾。"}, "sentence_index": 0, "correct_answer": "倒是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我以为会下雨，倒是下雨了。", "explanation": "这里应该用〈果然〉。倒是表示实际与预想不同，而这里下雨正在预料之中，应用〈果然〉。"}, {"text": "我早就知道他很守时，他倒是准时到了。", "explanation": "这里应该用〈果然〉。他准时到达正在预料之中，倒是表示出乎意料，不能用于此处。"}, {"text": "我猜这台旧电脑会很慢，倒是运行得很慢。", "explanation": "这里应该用〈果然〉。电脑慢正在预料之中，倒是表示出乎意料，不能用于此处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90425, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "倒是", "is_correct": true, "explanation": "倒是：副词，表示实际情况与预想或常理不同，带有出乎意料的语气，读作 dào shì。"}, {"text": "斗士", "is_correct": false, "explanation": "dòu 与 dào 韵母不同（ou 与 ao），意思是为某种事业奋斗的人。"}, {"text": "大势", "is_correct": false, "explanation": "dà 与 dào 韵母不同（a 与 ao），意思是局势、趋势。"}, {"text": "大市", "is_correct": false, "explanation": "dà 与 dào 韵母不同（a 与 ao），意思是市场行情。"}], "explanations": {"倒是": "倒是：副词，表示实际情况与预想或常理不同，带有出乎意料的语气，读作 dào shì。", "斗士": "dòu 与 dào 韵母不同（ou 与 ao），意思是为某种事业奋斗的人。", "大势": "dà 与 dào 韵母不同（a 与 ao），意思是局势、趋势。", "大市": "dà 与 dào 韵母不同（a 与 ao），意思是市场行情。"}, "sentence_index": null, "correct_answer": "倒是"}, "level_3": {"options": [{"text": "倒是", "is_correct": true, "explanation": "倒是：表示「我以为你早就忘了」之后，实际你却记得很清楚，与预想不同。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示频率，与「记得很清楚」的确定程度相矛盾。"}, {"text": "不必", "is_correct": false, "explanation": "语义：「不必」表示无需，与「记得很清楚」的陈述相悖，句意不通。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：「一起」表示同时，不能修饰「记得」的程度。"}], "explanations": {"倒是": "倒是：表示「我以为你早就忘了」之后，实际你却记得很清楚，与预想不同。", "偶尔": "语义：「偶尔」表示频率，与「记得很清楚」的确定程度相矛盾。", "不必": "语义：「不必」表示无需，与「记得很清楚」的陈述相悖，句意不通。", "一起": "搭配：「一起」表示同时，不能修饰「记得」的程度。"}, "sentence_index": 6, "correct_answer": "倒是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直是好学生，作业倒是交得很及时。", "explanation": "这里应该用〈理应〉。好学生按时交作业本在预料之中，倒是表示出乎意料，此处应用〈理应〉。"}, {"text": "天气预报说今天下雨，今天倒是下雨了。", "explanation": "这里应该用〈果然〉。下雨正在预料之中，倒是表示出乎意料，不能用于此处。"}, {"text": "他每次都准时来，今天倒是准时来了。", "explanation": "这里应该用〈照常〉。他一向准时，今天准时是照常，不是出乎意料，倒是不能用于此处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90425, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以为她跑得很慢，她很倒是跑得挺快。", "corrected_sentence": "我以为她跑得很慢，她倒是跑得挺快。", "error_description": "错误形式：「很倒是」；正确形式：「倒是」。「倒是」是副词，前面不能再加程度副词「很」修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90425, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子看着小，住进去很倒是挺宽敞的。", "corrected_sentence": "这间屋子看着小，住进去倒是挺宽敞的。", "error_description": "错误形式：「很倒是」；正确形式：「倒是」。「倒是」是副词，前面不能再加程度副词「很」修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
