INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90426, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示转折、让步或催促等语气。", "primary_collocate": null, "pronunciation": "dào shì", "ipa": "tɑʊ˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这个办法倒是不错，就是太贵了。", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你倒是说话啊，别光看着我。", "target_word": "倒是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子小倒是小，不过很干净。", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他倒是答应了，可是一直没来。", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你倒是快点儿走啊，要迟到了。", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服好看倒是好看，就是太贵。", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说得倒是容易，做起来就难了。", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你倒是想想办法，不要只是生气。", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "东西倒是不少，可惜都用不上。", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你倒是给我个答复，到底去不去？", "target_word": "倒是", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "倒是：表示让步后接转折，或带着不耐烦的语气催促对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20f9c372-ecc3-4b34-9028-39b875025280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90426, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "倒是", "is_correct": true, "explanation": "倒是：副词，表示让步后接转折，或带着不耐烦的语气催促对方，读作 dào shì。"}, {"text": "大事", "is_correct": false, "explanation": "dà（第四声）与 dào 韵母不同（a 与 ao），意思是大事，指重要的事情。"}, {"text": "到时", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是到了那个时候。"}, {"text": "导师", "is_correct": false, "explanation": "dǎo（第三声）与 dào（第四声）声调不同，shī（第一声）与 shì（第四声）声调也不同，意思是导师。"}, {"text": "闹事", "is_correct": false, "explanation": "nào 与 dào 声母不同（n 与 d），意思是闹事、捣乱。"}], "explanations": {"倒是": "倒是：副词，表示让步后接转折，或带着不耐烦的语气催促对方，读作 dào shì。", "大事": "dà（第四声）与 dào 韵母不同（a 与 ao），意思是大事，指重要的事情。", "到时": "shí（第二声）与 shì（第四声）声调不同，意思是到了那个时候。", "导师": "dǎo（第三声）与 dào（第四声）声调不同，shī（第一声）与 shì（第四声）声调也不同，意思是导师。", "闹事": "nào 与 dào 声母不同（n 与 d），意思是闹事、捣乱。"}, "sentence_index": null, "correct_answer": "倒是"}, "level_3": {"options": [{"text": "倒是", "is_correct": true, "explanation": "倒是：先承认「办法不错」，再用「就是」转折，正好表达让步语气。"}, {"text": "马上", "is_correct": false, "explanation": "语义：「马上」表示时间紧迫，与「办法不错」的评价无关，句中也没有时间语境。"}, {"text": "很快", "is_correct": false, "explanation": "语义：「很快」描述速度，不能用来评价「办法」的好坏。"}, {"text": "只", "is_correct": false, "explanation": "搭配：「只」要限定范围，后面须接「是」或数量短语，不能直接修饰「不错」。"}], "explanations": {"倒是": "倒是：先承认「办法不错」，再用「就是」转折，正好表达让步语气。", "马上": "语义：「马上」表示时间紧迫，与「办法不错」的评价无关，句中也没有时间语境。", "很快": "语义：「很快」描述速度，不能用来评价「办法」的好坏。", "只": "搭配：「只」要限定范围，后面须接「是」或数量短语，不能直接修饰「不错」。"}, "sentence_index": 0, "correct_answer": "倒是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他先吃了饭，倒是再去上班。", "explanation": "这里应该用〈然后〉。倒是表示转折或让步，不能表示动作的先后顺序，此处应用〈然后〉。"}, {"text": "为了省钱，倒是我们每天走路上班。", "explanation": "这里应该用〈所以〉。倒是表示转折或让步，不能引出结果，此处应用〈所以〉。"}, {"text": "车坏了，我们倒是走路。", "explanation": "这里应该用〈只好〉。「只好」表示没有别的办法而被迫如此，倒是不能表达这种无奈的选择。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90426, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "倒是", "is_correct": true, "explanation": "倒是：副词，表示让步后接转折，或带着不耐烦的语气催促对方，读作 dào shì。"}, {"text": "斗士", "is_correct": false, "explanation": "dòu 与 dào 韵母不同（ou 与 ao），意思是为某种事业奋斗的人。"}, {"text": "大势", "is_correct": false, "explanation": "dà 与 dào 韵母不同（a 与 ao），意思是局势、趋势。"}, {"text": "大市", "is_correct": false, "explanation": "dà 与 dào 韵母不同（a 与 ao），意思是市场行情。"}], "explanations": {"倒是": "倒是：副词，表示让步后接转折，或带着不耐烦的语气催促对方，读作 dào shì。", "斗士": "dòu 与 dào 韵母不同（ou 与 ao），意思是为某种事业奋斗的人。", "大势": "dà 与 dào 韵母不同（a 与 ao），意思是局势、趋势。", "大市": "dà 与 dào 韵母不同（a 与 ao），意思是市场行情。"}, "sentence_index": null, "correct_answer": "倒是"}, "level_3": {"options": [{"text": "倒是", "is_correct": true, "explanation": "倒是：表示「说起来确实容易」的让步语气，后接「做起来就难了」转折。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：「立刻」表示时间上马上，不能修饰「容易」的程度。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示频率，与「说得容易」这种程度评价不搭。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：「一起」表示同时发生，不能放在「说得」和「容易」之间。"}], "explanations": {"倒是": "倒是：表示「说起来确实容易」的让步语气，后接「做起来就难了」转折。", "立刻": "语义：「立刻」表示时间上马上，不能修饰「容易」的程度。", "偶尔": "语义：「偶尔」表示频率，与「说得容易」这种程度评价不搭。", "一起": "搭配：「一起」表示同时发生，不能放在「说得」和「容易」之间。"}, "sentence_index": 6, "correct_answer": "倒是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我早点儿来，倒是为了早点儿走。", "explanation": "这里应该用〈为的是〉。倒是表示转折或让步，不能引出目的，此处应用〈为的是〉。"}, {"text": "倒是下雨了，我们就不去公园了。", "explanation": "这里应该用〈因为〉。倒是表示转折、让步或催促，不能引出原因，此处应用〈因为〉。"}, {"text": "他先洗了手，倒是开始吃饭。", "explanation": "这里应该用〈然后〉。倒是表示转折、让步或催促，不能表示动作先后，此处应用〈然后〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你很倒是快点儿吃吧，菜要凉了。", "corrected_sentence": "你倒是快点儿吃吧，菜要凉了。", "error_description": "错误形式：「很倒是」；正确形式：「倒是」。「倒是」是副词，前面不能再加程度副词「很」修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她说得很倒是轻松，干起来可不容易。", "corrected_sentence": "她说得倒是轻松，干起来可不容易。", "error_description": "错误形式：「说得很倒是轻松」；正确形式：「说得倒是轻松」。「倒是」是副词，前面不能再加程度副词「很」修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
