INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90427, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90427, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "走进去的那个地方。", "primary_collocate": null, "pronunciation": "rù kǒu", "ipa": "ʐu˥˩ kʰoʊ˨˩", "syllable_count": 2, "sentences": [{"text": "看到前面的入口了吗？我们从那里进去。", "target_word": "入口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆有两个入口，你从哪个进去？", "target_word": "入口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "入口前面有一个小花园。", "target_word": "入口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店的入口藏在一条小路里。", "target_word": "入口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "入口很窄，一次只能过一个人。", "target_word": "入口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人在入口坐了一会儿，才慢慢走进去。", "target_word": "入口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们跑到入口，等着老师来。", "target_word": "入口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下的入口是一扇小门。", "target_word": "入口", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请从东边的入口进去，西边的是出口。", "target_word": "入口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自行车放在入口旁边。", "target_word": "入口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个入口", "label": "量词"}, {"form": "入口处", "label": "复合"}], "register": "通用", "sense_fingerprint": "人走进某个地方时经过的那个位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb45aab-75ed-4f65-a859-450e1280774f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90427, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "入口", "is_correct": true, "explanation": "「入口」指走进去的地方，符合“看到前面的入口了吗？我们从那里进去”。"}, {"text": "出口", "is_correct": false, "explanation": "语义：「出口」是出去的地方，与后句“我们从那里进去”相冲突。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：「身高」指人的高矮，不能指可以看到并走进去的地方。"}, {"text": "票价", "is_correct": false, "explanation": "语义：「票价」是钱，不是可以走进去的地方。"}], "explanations": {"入口": "「入口」指走进去的地方，符合“看到前面的入口了吗？我们从那里进去”。", "出口": "语义：「出口」是出去的地方，与后句“我们从那里进去”相冲突。", "身高": "体貌：「身高」指人的高矮，不能指可以看到并走进去的地方。", "票价": "语义：「票价」是钱，不是可以走进去的地方。"}, "sentence_index": 0, "correct_answer": "入口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们从入口出去。", "explanation": "这里应该用〈出口〉。入口是进去的地方，从这里出去要用出口。"}, {"text": "这个入口很好吃。", "explanation": "这里应该用〈面包〉。入口是走进去的地方，不能吃。"}, {"text": "他张开入口说话。", "explanation": "这里应该用〈嘴〉。入口是走进去的地方，不指嘴，说话时张开的是嘴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90427, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "入口", "is_correct": true, "explanation": "「入口」指走进去的地方，符合“孩子们跑到入口，等着老师来”。"}, {"text": "学费", "is_correct": false, "explanation": "语义：「学费」是钱，不是可以跑到的地方。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」指人的岁数，不能说跑到年龄那里。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：「身材」指人的体形，不能用来指地点。"}], "explanations": {"入口": "「入口」指走进去的地方，符合“孩子们跑到入口，等着老师来”。", "学费": "语义：「学费」是钱，不是可以跑到的地方。", "年龄": "语义：「年龄」指人的岁数，不能说跑到年龄那里。", "身材": "体貌：「身材」指人的体形，不能用来指地点。"}, "sentence_index": 6, "correct_answer": "入口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天入口办公室。", "explanation": "这里应该用〈进入〉。入口作动词只表示进口货物，不能说人入口办公室。"}, {"text": "他每天都喝两杯入口。", "explanation": "这里应该用〈咖啡〉。入口是走进去的地方，不能喝。"}, {"text": "我把入口吃完了。", "explanation": "这里应该用〈饭〉。入口是走进去的地方，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90427, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座剧院有两张入口，都在街道的东边。", "corrected_sentence": "这座剧院有两个入口，都在街道的东边。", "error_description": "量词错误：“入口”的量词应为“个”，说“两张入口”不对，应为“两个入口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90427, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他站入口前面，停下来看了看。", "corrected_sentence": "他站在入口前面，停下来看了看。", "error_description": "介词缺失：“站”后表示处所要用介词“在”，应说“站在入口前面”，不能说“站入口前面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
