INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90428, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "进入某处的通道口。", "primary_collocate": null, "pronunciation": "rù kǒu", "ipa": "ʐu˥˩ kʰoʊ˨˩", "syllable_count": 2, "sentences": [{"text": "地铁站的入口在银行旁边。", "target_word": "入口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请问，公园的入口在哪儿？", "target_word": "入口", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我在商场入口等你。", "target_word": "入口", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们找不到停车场的入口。", "target_word": "入口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影院的入口人很多，排了很长的队。", "target_word": "入口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个山洞的入口很小，大人要低着头进去。", "target_word": "入口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在学校的入口，看着学生们走进来。", "target_word": "入口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "入口在左边，出口在右边。", "target_word": "入口", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "为什么这家店的入口这么难找？", "target_word": "入口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把车停在山谷的入口。", "target_word": "入口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个入口", "label": "量词"}, {"form": "入口处", "label": "复合"}], "register": "通用", "sense_fingerprint": "建筑、场所或洞穴等供人进入的通道口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb45aab-75ed-4f65-a859-450e1280774f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90428, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "入口", "is_correct": true, "explanation": "「入口」指进入某处的通道口，符合“地铁站的入口在银行旁边”这一位置。"}, {"text": "票价", "is_correct": false, "explanation": "语义：「票价」指车票的价钱，不指地点，不能说在银行旁边。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：「身材」指人的体形，不能用来指地铁站的位置。"}, {"text": "性格", "is_correct": false, "explanation": "语义：「性格」指人的性情特点，不能用来指车站的某个地方。"}], "explanations": {"入口": "「入口」指进入某处的通道口，符合“地铁站的入口在银行旁边”这一位置。", "票价": "语义：「票价」指车票的价钱，不指地点，不能说在银行旁边。", "身材": "体貌：「身材」指人的体形，不能用来指地铁站的位置。", "性格": "语义：「性格」指人的性情特点，不能用来指车站的某个地方。"}, "sentence_index": 0, "correct_answer": "入口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们喝了一杯入口。", "explanation": "这里应该用〈茶〉。入口是进去的通道口，不能喝。"}, {"text": "我们在入口做饭。", "explanation": "这里应该用〈厨房〉。入口是进去的通道口，做饭要在厨房，不能在入口。"}, {"text": "他张开入口吃饭。", "explanation": "这里应该用〈嘴〉。入口是通道口，不指嘴，吃饭时张开的是嘴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90428, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "入口", "is_correct": true, "explanation": "「入口」指进入的通道口，符合“他站在学校的入口，看着学生们走进来”的语境。"}, {"text": "学费", "is_correct": false, "explanation": "语义：「学费」是上学交的钱，不是可以站立的地方。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：「身高」指人的高矮，不能用来指学校的一个地点。"}, {"text": "课本", "is_correct": false, "explanation": "语义：「课本」是书，不能作为站立和观看的地点。"}], "explanations": {"入口": "「入口」指进入的通道口，符合“他站在学校的入口，看着学生们走进来”的语境。", "学费": "语义：「学费」是上学交的钱，不是可以站立的地方。", "身高": "体貌：「身高」指人的高矮，不能用来指学校的一个地点。", "课本": "语义：「课本」是书，不能作为站立和观看的地点。"}, "sentence_index": 6, "correct_answer": "入口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每天入口学校。", "explanation": "这里应该用〈进入〉。入口作动词只表示进口货物，不能说人入口学校。"}, {"text": "妈妈给我做了一个入口当早饭。", "explanation": "这里应该用〈蛋糕〉。入口是进去的通道口，不能做来吃。"}, {"text": "我们在入口上课。", "explanation": "这里应该用〈教室〉。入口是通道口，不是上课的地方，上课要在教室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车站有三只入口，分别通向不同的街道。", "corrected_sentence": "车站有三个入口，分别通向不同的街道。", "error_description": "量词错误：“入口”的量词应为“个”，说“三只入口”不对，应为“三个入口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把车停入口旁边。", "corrected_sentence": "我们把车停在入口旁边。", "error_description": "介词缺失：表示停放的地点要用介词“在”，应说“停在入口旁边”，不能说“停入口旁边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
