INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90429, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一路是从开始走到最后，中间一直这样。", "primary_collocate": null, "pronunciation": "yí lù", "ipa": "i˧˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "他一路领先，最后得了第一。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年我一路走来，很不容易。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中，我们队一路赢到了最后。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一路哭个不停，哄了很久才停。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一路都在跑，累坏了。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司一路发展，现在很大了。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一路笑着，心情特别好。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你一路帮助我。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我这个冬天一路咳嗽，直到春天才好。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气一路变冷，大家穿上了厚衣服。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一路上", "label": "复合"}], "register": "中性", "sense_fingerprint": "从头到尾一直保持同一状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb45aab-75ed-4f65-a859-450e1280774f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90429, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一路", "is_correct": true, "explanation": "正确：一路 yí lù，与听到的读音相同，指从头到尾一直。"}, {"text": "一律", "is_correct": false, "explanation": "lǜ 与 lù 的韵母不同（ü 与 u），意思是一律、全都一样。"}, {"text": "一度", "is_correct": false, "explanation": "dù 与 lù 声母不同（d 与 l），意思是一度、一次。"}, {"text": "一户", "is_correct": false, "explanation": "hù 与 lù 声母不同（h 与 l），意思是一户人家。"}], "explanations": {"一路": "正确：一路 yí lù，与听到的读音相同，指从头到尾一直。", "一律": "lǜ 与 lù 的韵母不同（ü 与 u），意思是一律、全都一样。", "一度": "dù 与 lù 声母不同（d 与 l），意思是一度、一次。", "一户": "hù 与 lù 声母不同（h 与 l），意思是一户人家。"}, "sentence_index": null, "correct_answer": "一路"}, "level_3": {"options": [{"text": "一路", "is_correct": true, "explanation": "「一路」表示从头到尾一直保持，与“领先，最后得了第一”的语境相符。"}, {"text": "同时", "is_correct": false, "explanation": "搭配：「同时」要求两件事并列进行，不能用来说明一直领先。"}, {"text": "一边", "is_correct": false, "explanation": "搭配：「一边」须与另一动作配对出现，不能单独修饰「领先」。"}, {"text": "连忙", "is_correct": false, "explanation": "语义：「连忙」表示急忙，不能修饰“领先”这种持续的状态。"}], "explanations": {"一路": "「一路」表示从头到尾一直保持，与“领先，最后得了第一”的语境相符。", "同时": "搭配：「同时」要求两件事并列进行，不能用来说明一直领先。", "一边": "搭配：「一边」须与另一动作配对出现，不能单独修饰「领先」。", "连忙": "语义：「连忙」表示急忙，不能修饰“领先”这种持续的状态。"}, "sentence_index": 0, "correct_answer": "一路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一路明天才到北京。", "explanation": "这里应该用〈直到〉。一路表示从头到尾持续，不能说到明天才发生的事。"}, {"text": "雨一路昨天就停了。", "explanation": "这里应该用〈早就〉。一路表示从头到尾持续，不能表示昨天就停了这样的时点。"}, {"text": "他一路站起来，走向门口。", "explanation": "这里应该用〈立刻〉。一路强调从头到尾的持续，不能表示马上站起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90429, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一路", "is_correct": true, "explanation": "「一路」表示从头到尾一直保持，符合“她一路笑着，心情特别好”的语境。"}, {"text": "很", "is_correct": false, "explanation": "搭配：「很」是程度副词，不能修饰“笑着”这样的动作，说“很笑着”不通。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：「十分」同样是程度副词，不能修饰“笑着”。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：「赶紧」表示急着做某事，与“心情特别好”的持续状态不符。"}], "explanations": {"一路": "「一路」表示从头到尾一直保持，符合“她一路笑着，心情特别好”的语境。", "很": "搭配：「很」是程度副词，不能修饰“笑着”这样的动作，说“很笑着”不通。", "十分": "搭配：「十分」同样是程度副词，不能修饰“笑着”。", "赶紧": "语义：「赶紧」表示急着做某事，与“心情特别好”的持续状态不符。"}, "sentence_index": 6, "correct_answer": "一路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一路很快就回来了。", "explanation": "这里应该用〈立刻〉。一路强调从头到尾持续，不能表示马上就回来。"}, {"text": "我们一路出发。", "explanation": "这里应该用〈马上〉。一路不表示即刻发生，说“一路出发”不符合语义。"}, {"text": "我一路三天就学会了游泳。", "explanation": "这里应该用〈一下子〉。一路表示从头到尾持续，不能表示这种短时间内完成的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一路的在努力，从没停下来。", "corrected_sentence": "他一路都在努力，从没停下来。", "error_description": "助词错误：「一路」是副词，后面不能直接加「的」，应把「的」换成「都」，写作“他一路都在努力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90429, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一路的都很高兴。", "corrected_sentence": "我一路都很高兴。", "error_description": "助词错误：“一路”是副词，后面不能加“的”，应说“一路都很高兴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
