INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90430, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "整个路程中；沿途。", "primary_collocate": null, "pronunciation": "yí lù", "ipa": "i˧˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "我们一路都看到很多漂亮的花。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开车去海边，一路都有好风景。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一路问了很多问题。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一路看着窗外，没有说话。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一路遇到了很多热心人。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时，我一路拍了不少照片。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从学校回家，一路都是树。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友一路送我到车站。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一路都是好天气，大家很高兴。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们一路参观了很多地方。", "target_word": "一路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一路上", "label": "复合"}], "register": "中性", "sense_fingerprint": "旅途中沿途一直", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb45aab-75ed-4f65-a859-450e1280774f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90430, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一路", "is_correct": true, "explanation": "正确：一路 yí lù，与听到的读音相同，指旅途中沿途。"}, {"text": "一律", "is_correct": false, "explanation": "lǜ 与 lù 的韵母不同（ü 与 u），意思是一律、全都一样。"}, {"text": "一度", "is_correct": false, "explanation": "dù 与 lù 声母不同（d 与 l），意思是一度、一次。"}, {"text": "一户", "is_correct": false, "explanation": "hù 与 lù 声母不同（h 与 l），意思是一户人家。"}], "explanations": {"一路": "正确：一路 yí lù，与听到的读音相同，指旅途中沿途。", "一律": "lǜ 与 lù 的韵母不同（ü 与 u），意思是一律、全都一样。", "一度": "dù 与 lù 声母不同（d 与 l），意思是一度、一次。", "一户": "hù 与 lù 声母不同（h 与 l），意思是一户人家。"}, "sentence_index": null, "correct_answer": "一路"}, "level_3": {"options": [{"text": "一路", "is_correct": true, "explanation": "「一路」表示旅途中沿途，与“我们一路都看到很多漂亮的花”的语境相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示间或发生，与沿途一直看到很多花的意思冲突。"}, {"text": "一边", "is_correct": false, "explanation": "搭配：「一边」须与另一动作配对出现，不能单独修饰「看到」。"}, {"text": "连忙", "is_correct": false, "explanation": "语义：「连忙」表示急忙，与沿途一直看到很多花的意思不符。"}], "explanations": {"一路": "「一路」表示旅途中沿途，与“我们一路都看到很多漂亮的花”的语境相符。", "偶尔": "语义：「偶尔」表示间或发生，与沿途一直看到很多花的意思冲突。", "一边": "搭配：「一边」须与另一动作配对出现，不能单独修饰「看到」。", "连忙": "语义：「连忙」表示急忙，与沿途一直看到很多花的意思不符。"}, "sentence_index": 0, "correct_answer": "一路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一路明天才到。", "explanation": "这里应该用〈直到〉。一路表示沿途或持续，不能用来说某事到某个时间才发生。"}, {"text": "我一路昨天就到了。", "explanation": "这里应该用〈早就〉。一路表示沿途或持续，不能说昨天就到了这样的时点。"}, {"text": "他一路醒了。", "explanation": "这里应该用〈忽然〉。一路表示沿途或持续，不能表示一下子醒来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一路", "is_correct": true, "explanation": "「一路」表示旅途中沿途，符合“从学校回家，一路都是树”的语境。"}, {"text": "突然", "is_correct": false, "explanation": "语义：「突然」表示事情出乎意料地发生，不能说明一路上一直都是树。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：「立刻」表示马上，不能表示沿途的范围。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：「马上」多与动作或即将发生的事搭配，不能用来说明“都是树”这种状态。"}], "explanations": {"一路": "「一路」表示旅途中沿途，符合“从学校回家，一路都是树”的语境。", "突然": "语义：「突然」表示事情出乎意料地发生，不能说明一路上一直都是树。", "立刻": "语义：「立刻」表示马上，不能表示沿途的范围。", "马上": "搭配：「马上」多与动作或即将发生的事搭配，不能用来说明“都是树”这种状态。"}, "sentence_index": 6, "correct_answer": "一路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门一路开了。", "explanation": "这里应该用〈突然〉。一路表示沿途或持续，不能表示门突然开了。"}, {"text": "两个人一路举起了手。", "explanation": "这里应该用〈同时〉。一路不能表示两个人同时做某事。"}, {"text": "我一路明天才来。", "explanation": "这里应该用〈直到〉。一路表示沿途或持续，不能说到明天才来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一路的唱着歌，心情很好。", "corrected_sentence": "她一路唱着歌，心情很好。", "error_description": "修饰成分错误：副词“一路”后不能加“的”，应说“一路唱着歌”，不能说“一路的唱着歌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一路的看着风景，没有说话。", "corrected_sentence": "他一路看着风景，没有说话。", "error_description": "助词错误：副词“一路”直接修饰动词，后面不能加“的”，应说“一路看着风景”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
