INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90431, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "借款是向别人借钱。", "primary_collocate": null, "pronunciation": "jiè kuǎn", "ipa": "tɕjɛ˥˩ kʰwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "他没钱了，只好向同事借款。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢向别人借款。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了看病，向朋友借款。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王借款买了一台电脑。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要借款的人得先写清楚还钱的时间。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张借款开了一家饭店。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想借款，可是没人愿意借给他。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "向别人借款以后，要按时还钱。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李借款交了房租。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家去年为了盖房子向银行借款。", "target_word": "借款", "complexity_tier": "T3", "furigana": "wǒ men jiā qù nián wèi le gài fáng zi xiàng yín háng jiè kuǎn", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "借款：向别人借钱，日常说法（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4f307f-eef1-48f7-ab9e-281d3bff4d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90431, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "借款", "is_correct": true, "explanation": "正确答案：借款（jiè kuǎn），向别人借钱。"}, {"text": "进款", "is_correct": false, "explanation": "jìn（第四声）与 jiè（第四声）韵母不同，意思是进账、收入的钱。"}, {"text": "结款", "is_correct": false, "explanation": "jié（第二声）与 jiè（第四声）声调不同，意思是结算付款。"}, {"text": "价款", "is_correct": false, "explanation": "jià（第四声）与 jiè（第四声）韵母不同，意思是货物的价钱。"}], "explanations": {"借款": "正确答案：借款（jiè kuǎn），向别人借钱。", "进款": "jìn（第四声）与 jiè（第四声）韵母不同，意思是进账、收入的钱。", "结款": "jié（第二声）与 jiè（第四声）声调不同，意思是结算付款。", "价款": "jià（第四声）与 jiè（第四声）韵母不同，意思是货物的价钱。"}, "sentence_index": null, "correct_answer": "借款"}, "level_3": {"options": [{"text": "借款", "is_correct": true, "explanation": "正确：没钱了，只好向同事借钱，与语境相符。"}, {"text": "还款", "is_correct": false, "explanation": "语义：还款是偿还钱，与「没钱了」需要借钱的语境不符。"}, {"text": "放款", "is_correct": false, "explanation": "配价：放款是出借方的动作，「向同事」放款的方向相反。"}, {"text": "申请", "is_correct": false, "explanation": "搭配：「申请」后缺少宾语，「只好向同事申请」不成立。"}], "explanations": {"借款": "正确：没钱了，只好向同事借钱，与语境相符。", "还款": "语义：还款是偿还钱，与「没钱了」需要借钱的语境不符。", "放款": "配价：放款是出借方的动作，「向同事」放款的方向相反。", "申请": "搭配：「申请」后缺少宾语，「只好向同事申请」不成立。"}, "sentence_index": 0, "correct_answer": "借款"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他借款了一支笔。", "explanation": "这里应该用〈借〉。借款只用于钱款，借笔这类东西要说「借」。"}, {"text": "他向邻居借款了一把椅子。", "explanation": "这里应该用〈借〉。借款只用于借钱，借椅子这类东西要说「借」。"}, {"text": "我借款了一本词典。", "explanation": "这里应该用〈借〉。借款只用于钱款，借词典要用「借」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90431, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "借款", "is_correct": true, "explanation": "正确答案：借款（jiè kuǎn），向别人借钱。"}, {"text": "寄款", "is_correct": false, "explanation": "jì 与 jiè 韵母不同，意思是邮寄汇款。"}, {"text": "结款", "is_correct": false, "explanation": "jié（第二声）与 jiè（第四声）声调不同，意思是结算付款。"}, {"text": "解款", "is_correct": false, "explanation": "jiě（第三声）与 jiè（第四声）声调不同，意思是解送款项。"}], "explanations": {"借款": "正确答案：借款（jiè kuǎn），向别人借钱。", "寄款": "jì 与 jiè 韵母不同，意思是邮寄汇款。", "结款": "jié（第二声）与 jiè（第四声）声调不同，意思是结算付款。", "解款": "jiě（第三声）与 jiè（第四声）声调不同，意思是解送款项。"}, "sentence_index": null, "correct_answer": "借款"}, "level_3": {"options": [{"text": "借款", "is_correct": true, "explanation": "正确：没人愿意借给他，说明他是想借钱，与语境相符。"}, {"text": "还钱", "is_correct": false, "explanation": "语义：还钱是偿还，与「没人愿意借给他」的借入语境不符。"}, {"text": "放贷", "is_correct": false, "explanation": "配价：放贷是出借方的行为，与「他」作为借入方矛盾。"}, {"text": "存钱", "is_correct": false, "explanation": "语义：存钱与借钱无关，句子讲的是借钱困难。"}], "explanations": {"借款": "正确：没人愿意借给他，说明他是想借钱，与语境相符。", "还钱": "语义：还钱是偿还，与「没人愿意借给他」的借入语境不符。", "放贷": "配价：放贷是出借方的行为，与「他」作为借入方矛盾。", "存钱": "语义：存钱与借钱无关，句子讲的是借钱困难。"}, "sentence_index": 6, "correct_answer": "借款"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们借款了一把伞。", "explanation": "这里应该用〈借〉。借款只用于钱款，借伞这类东西要说「借」。"}, {"text": "他向同学借款了一辆自行车。", "explanation": "这里应该用〈借〉。借款只用于钱款，借自行车这类东西要说「借」。"}, {"text": "他借款了一套课本。", "explanation": "这里应该用〈借〉。借款只用于钱款，借课本这类东西要说「借」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90431, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他向同事借款一千个，下个月就还。", "corrected_sentence": "他向同事借款一千元，下个月就还。", "error_description": "量词错误：借款的金额要用量词“元”，“一千个”不能用来计量钱款，应说“一千元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90431, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想在朋友借款一千元。", "corrected_sentence": "我想向朋友借款一千元。", "error_description": "介词错误：借款的对象要用介词「向」引出，应说「向朋友借款一千元」，不能用「在」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
