INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90432, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向他人或机构借钱。", "primary_collocate": null, "pronunciation": "jiè kuǎn", "ipa": "tɕjɛ˥˩ kʰwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "他向银行借款买了房子。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想向朋友借款。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向银行借款五万元。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店需要借款才能开业。", "target_word": "借款", "complexity_tier": "T3", "furigana": "zhè jiā xiǎo diàn xū yào jiè kuǎn cái néng kāi yè", "sentence_source": "generated"}, {"text": "他不想向家人借款。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打算借款买一辆车。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了开店，他向亲戚借款十万元。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生可以向银行借款交学费。", "target_word": "借款", "complexity_tier": "T3", "furigana": "xué shēng kě yǐ xiàng yín háng jiè kuǎn jiāo xué fèi", "sentence_source": "generated"}, {"text": "农民春天常常向银行借款买种子。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她要借款的时候，先看了利率。", "target_word": "借款", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "借款：向他人或机构借钱（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4f307f-eef1-48f7-ab9e-281d3bff4d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90432, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "借款", "is_correct": true, "explanation": "正确答案：借款（jiè kuǎn），向他人或机构借钱。"}, {"text": "进款", "is_correct": false, "explanation": "jìn（第四声）与 jiè（第四声）韵母不同，意思是进账、收入的钱。"}, {"text": "结款", "is_correct": false, "explanation": "jié（第二声）与 jiè（第四声）声调不同，意思是结算付款。"}, {"text": "价款", "is_correct": false, "explanation": "jià（第四声）与 jiè（第四声）韵母不同，意思是货物的价钱。"}], "explanations": {"借款": "正确答案：借款（jiè kuǎn），向他人或机构借钱。", "进款": "jìn（第四声）与 jiè（第四声）韵母不同，意思是进账、收入的钱。", "结款": "jié（第二声）与 jiè（第四声）声调不同，意思是结算付款。", "价款": "jià（第四声）与 jiè（第四声）韵母不同，意思是货物的价钱。"}, "sentence_index": null, "correct_answer": "借款"}, "level_3": {"options": [{"text": "借款", "is_correct": true, "explanation": "正确：向银行借钱，与后面「买了房子」的因果一致。"}, {"text": "还款", "is_correct": false, "explanation": "语义：还款是偿还已借的钱，不能用来买房。"}, {"text": "放款", "is_correct": false, "explanation": "配价：放款是出借方的动作，不能说「向银行放款」来表示借钱。"}, {"text": "申请", "is_correct": false, "explanation": "搭配：「申请」后要带宾语，不能直接接「买了房子」这样的结果。"}], "explanations": {"借款": "正确：向银行借钱，与后面「买了房子」的因果一致。", "还款": "语义：还款是偿还已借的钱，不能用来买房。", "放款": "配价：放款是出借方的动作，不能说「向银行放款」来表示借钱。", "申请": "搭配：「申请」后要带宾语，不能直接接「买了房子」这样的结果。"}, "sentence_index": 0, "correct_answer": "借款"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我向图书馆借款了三本书。", "explanation": "这里应该用〈借〉。借款只用于钱款，借书要用「借」。"}, {"text": "他向银行借款了一台电脑。", "explanation": "这里应该用〈借〉。借款只用于借钱，借电脑这类东西要说「借」。"}, {"text": "他借款了一把雨伞。", "explanation": "这里应该用〈借〉。借款只用于钱款，借雨伞要说「借」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EX