INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90432, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "借款", "is_correct": true, "explanation": "正确答案：借款（jiè kuǎn），向他人或机构借钱。"}, {"text": "寄款", "is_correct": false, "explanation": "jì 与 jiè 韵母不同，意思是邮寄汇款。"}, {"text": "结款", "is_correct": false, "explanation": "jié（第二声）与 jiè（第四声）声调不同，意思是结算付款。"}, {"text": "解款", "is_correct": false, "explanation": "jiě（第三声）与 jiè（第四声）声调不同，意思是解送款项。"}], "explanations": {"借款": "正确答案：借款（jiè kuǎn），向他人或机构借钱。", "寄款": "jì 与 jiè 韵母不同，意思是邮寄汇款。", "结款": "jié（第二声）与 jiè（第四声）声调不同，意思是结算付款。", "解款": "jiě（第三声）与 jiè（第四声）声调不同，意思是解送款项。"}, "sentence_index": null, "correct_answer": "借款"}, "level_3": {"options": [{"text": "借款", "is_correct": true, "explanation": "正确：为了开店需要钱，向亲戚借款与语境相符。"}, {"text": "偿还", "is_correct": false, "explanation": "语义：偿还是还钱，与「为了开店」需要资金的语境不符。"}, {"text": "贷出", "is_correct": false, "explanation": "语义：贷出是把钱借给别人，与「为了开店」需要钱的语境矛盾。"}, {"text": "花费", "is_correct": false, "explanation": "搭配：「花费」不能直接引出「向亲戚」这样的对象。"}], "explanations": {"借款": "正确：为了开店需要钱，向亲戚借款与语境相符。", "偿还": "语义：偿还是还钱，与「为了开店」需要资金的语境不符。", "贷出": "语义：贷出是把钱借给别人，与「为了开店」需要钱的语境矛盾。", "花费": "搭配：「花费」不能直接引出「向亲戚」这样的对象。"}, "sentence_index": 6, "correct_answer": "借款"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她借款了一双鞋。", "explanation": "这里应该用〈借〉。借款只用于钱款，借鞋子这类东西要说「借」。"}, {"text": "他借款了一瓶酱油。", "explanation": "这里应该用〈借〉。借款只借钱款，借酱油这类东西要说「借」。"}, {"text": "他借款了一本字典。", "explanation": "这里应该用〈借〉。借款只用于钱款，借字典要说「借」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
