INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90434, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开创并建立。", "primary_collocate": null, "pronunciation": "chuàng bàn", "ipa": "ʈʂʰuɑŋ˥˩ pan˥˩", "syllable_count": 2, "sentences": [{"text": "这位作家创办了一本杂志。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们创办了一个爱心基金会。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们创办了一个读书会。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她创办的网站帮助了很多人。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几位老人创办了社区合唱团。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个协会是谁创办的？", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回国后创办了自己的事业。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校创办了一份校报。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家决定创办一个环保小组。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家基金会由几位老师创办，至今已有十年。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "创办了", "label": "完成体"}, {"form": "创办过", "label": "经历体"}, {"form": "创办人", "label": "复合"}, {"form": "创办者", "label": "复合"}], "register": "中性", "sense_fingerprint": "开创并建立杂志、基金会、协会、事业等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d7edf-4df1-41f1-b1d8-d079da48dec8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "创办", "is_correct": true, "explanation": "创办：开办杂志，与“作家”办刊的语境相符。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：吃掉是把食物咽下，杂志不能被吃掉。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：摘多用于果实、花朵，杂志不能被摘。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：修剪用于树枝、头发，杂志不能被修剪。"}], "explanations": {"创办": "创办：开办杂志，与“作家”办刊的语境相符。", "吃掉": "语义：吃掉是把食物咽下，杂志不能被吃掉。", "摘": "搭配：摘多用于果实、花朵，杂志不能被摘。", "修剪": "搭配：修剪用于树枝、头发，杂志不能被修剪。"}, "sentence_index": 0, "correct_answer": "创办"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司创办了一款新软件。", "explanation": "这里应该用〈开发〉。软件是开发出来的，创办指开办机构或事业，不说创办软件。"}, {"text": "作者创办了一篇论文。", "explanation": "这里应该用〈撰写〉。论文是撰写出来的，创办不用于文章的写作。"}, {"text": "他在院子里创办了一棵树。", "explanation": "这里应该用〈种〉。树是种植的，创办不能用于植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fbe845-3fbb-4abf-be61-dd4245c079c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "创办", "is_correct": true, "explanation": "创办：开创事业，与“回国后”的语境相符。"}, {"text": "哭泣", "is_correct": false, "explanation": "配价：哭泣是不及物动词，不能带“自己的事业”作宾语。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：“烘焙”指用火烤制食物，与事业无关。"}, {"text": "切开", "is_correct": false, "explanation": "语义：切开是把实物分割，事业不能被切开。"}], "explanations": {"创办": "创办：开创事业，与“回国后”的语境相符。", "哭泣": "配价：哭泣是不及物动词，不能带“自己的事业”作宾语。", "烘焙": "语义：“烘焙”指用火烤制食物，与事业无关。", "切开": "语义：切开是把实物分割，事业不能被切开。"}, "sentence_index": 6, "correct_answer": "创办"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人创办了一条路。", "explanation": "这里应该用〈修〉。路是修出来的，创办指开办机构或事业，不说创办一条路。"}, {"text": "她创办了一幅画。", "explanation": "这里应该用〈绘制〉。画是绘制出来的，创办指开办机构或事业，不能用于绘画作品。"}, {"text": "他创办了一首歌。", "explanation": "这里应该用〈写〉。歌是写出来的作品，创办指开办机构或事业，不能用于歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fbe845-3fbb-4abf-be61-dd4245c079c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位作家创办很成功，杂志销量很好。", "corrected_sentence": "这位作家创办得很成功，杂志销量很好。", "error_description": "错误：“创办”后表示程度的补语要用“得”连接，缺少“得”。应为“创办得很成功”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fbe845-3fbb-4abf-be61-dd4245c079c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在创办了一个俱乐部，想让大家一起运动。", "corrected_sentence": "他正在创办一个俱乐部，想让大家一起运动。", "error_description": "错误：“正在”表示动作进行中，不能与“了”同用。应为“正在创办一个俱乐部”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fbe845-3fbb-4abf-be61-dd4245c079c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90435, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下载", "is_correct": true, "explanation": "反义：下载是把网上的内容取到本地，与上传方向相反。"}, {"text": "删除", "is_correct": false, "explanation": "无关：删除是去掉文件，与上传不构成反义关系。"}, {"text": "保存", "is_correct": false, "explanation": "无关：保存是存放起来，并非与上传相反。"}, {"text": "拍摄", "is_correct": false, "explanation": "无关：拍摄是用相机取得照片，与上传没有反义关系。"}], "correct_answer": "下载", "explanations": {"下载": "反义：下载是把网上的内容取到本地，与上传方向相反。", "删除": "无关：删除是去掉文件，与上传不构成反义关系。", "保存": "无关：保存是存放起来，并非与上传相反。", "拍摄": "无关：拍摄是用相机取得照片，与上传没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90435, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下载", "is_correct": true, "explanation": "反义：下载是把网上的内容取到本地，与上传方向相反。"}, {"text": "修改", "is_correct": false, "explanation": "无关：修改是改动内容，与上传不构成反义关系。"}, {"text": "录制", "is_correct": false, "explanation": "无关：录制是把声音或影像记录下来，与上传没有反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "无关：整理是把东西理顺归类，与上传没有反义关系。"}], "correct_answer": "下载", "explanations": {"下载": "反义：下载是把网上的内容取到本地，与上传方向相反。", "修改": "无关：修改是改动内容，与上传不构成反义关系。", "录制": "无关：录制是把声音或影像记录下来，与上传没有反义关系。", "整理": "无关：整理是把东西理顺归类，与上传没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90435, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上传是把照片或文件从你的手机送到网络上。", "primary_collocate": null, "pronunciation": "shàng chuán", "ipa": "ʂɑŋ˥˩ ʈʂʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "我想把这张照片上传到网上。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都上传一张新照片。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把手机里的视频上传一下。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上传了昨天拍的风景照。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片太大了，上传很慢。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你上传过自己的视频吗？", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正在上传旅行照片，请等一下。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教我怎么上传照片到朋友圈。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把全家福上传到了网上。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没有网络，照片上传不了。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上传了", "label": "体标"}, {"form": "上传过", "label": "体标"}], "register": "口语", "sense_fingerprint": "把手机里的照片、视频等送到网上分享", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53db9dd3-8e45-4d0b-b8b6-d4711d195280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90435, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上传", "is_correct": true, "explanation": "上传：把照片送到网上，与“到网上”搭配，符合句意。"}, {"text": "删除", "is_correct": false, "explanation": "配价：删除只带事物宾语，不能用“到网上”表示去向。"}, {"text": "打印", "is_correct": false, "explanation": "语义：打印是印在纸上，不能印到网上。"}, {"text": "寄", "is_correct": false, "explanation": "搭配：寄是邮寄给人或地址，不能说寄到网上。"}], "explanations": {"上传": "上传：把照片送到网上，与“到网上”搭配，符合句意。", "删除": "配价：删除只带事物宾语，不能用“到网上”表示去向。", "打印": "语义：打印是印在纸上，不能印到网上。", "寄": "搭配：寄是邮寄给人或地址，不能说寄到网上。"}, "sentence_index": 0, "correct_answer": "上传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把蛋糕上传到了朋友家。", "explanation": "这里应该用〈送〉。上传指把文件、数据送到网络或服务器上，实物送到朋友家要用〈送〉。"}, {"text": "我把行李上传到了二楼。", "explanation": "这里应该用〈搬〉。上传只指把文件或数据送到网络上，行李是实物，搬到楼上要用〈搬〉。"}, {"text": "球员把球上传给了队友。", "explanation": "这里应该用〈传〉。上传专指把文件、数据送到网络上，传球要用〈传〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90435, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上传", "is_correct": true, "explanation": "上传：把照片送到网上，与“旅行照片”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃照片”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应是饮品，不能说“喝照片”。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，后面不能直接带“旅行照片”作宾语。"}], "explanations": {"上传": "上传：把照片送到网上，与“旅行照片”的语境相符。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃照片”。", "喝": "搭配：“喝”的宾语应是饮品，不能说“喝照片”。", "跑": "配价：“跑”是不及物动词，后面不能直接带“旅行照片”作宾语。"}, "sentence_index": 6, "correct_answer": "上传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙上传给了我。", "explanation": "这里应该用〈递〉。钥匙是实物，递给别人要用〈递〉，上传只指送到网络上。"}, {"text": "她给我上传了一条短信。", "explanation": "这里应该用〈发送〉。短信是发给某个人的，上传不能用于发给个人。"}, {"text": "工厂把机器上传到了码头。", "explanation": "这里应该用〈运〉。机器是实物，运到码头要用〈运〉，上传不用于实物运输。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90435, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天把作业上传了到网上。", "corrected_sentence": "我昨天把作业上传到了网上。", "error_description": "体标位置错误：“上传到网上”中，“了”要放在“到”的后面，应说“上传到了网上”，不能说“上传了到网上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90435, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经上传了过这些照片。", "corrected_sentence": "我已经上传过这些照片。", "error_description": "体标错误：“了”和“过”不能同时用在动词后，应说“上传过这些照片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
