INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90436, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把本地的文件或数据通过网络传送到远程服务器。", "primary_collocate": null, "pronunciation": "shàng chuán", "ipa": "ʂɑŋ˥˩ ʈʂʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "请把这个文件上传到服务器。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员正在上传今天的数据。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把代码上传到了公司的服务器。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文件太大，上传失败了。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你以前上传过文件到这个系统吗？", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据上传完以后，系统会自动保存。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要求我们把作业上传到网站。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上传文件时，网络不能断。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上传了一份新的资料到服务器。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先登录，然后上传你的简历。", "target_word": "上传", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上传了", "label": "体标"}, {"form": "上传过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把文件、数据等从本地传送到服务器或系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53db9dd3-8e45-4d0b-b8b6-d4711d195280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90436, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上传", "is_correct": true, "explanation": "上传：把文件送到服务器，与“到服务器”搭配，符合句意。"}, {"text": "阅读", "is_correct": false, "explanation": "配价：阅读只带事物宾语，不能用“到服务器”表示去向。"}, {"text": "删除", "is_correct": false, "explanation": "配价：删除只带事物宾语，不能用“到服务器”表示去向。"}, {"text": "复印", "is_correct": false, "explanation": "语义：复印是印在纸上，不能复印到服务器。"}], "explanations": {"上传": "上传：把文件送到服务器，与“到服务器”搭配，符合句意。", "阅读": "配价：阅读只带事物宾语，不能用“到服务器”表示去向。", "删除": "配价：删除只带事物宾语，不能用“到服务器”表示去向。", "复印": "语义：复印是印在纸上，不能复印到服务器。"}, "sentence_index": 0, "correct_answer": "上传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "邮局把信件上传到了家里。", "explanation": "这里应该用〈投递〉。信件是实物，要由邮局投递到家里，上传只指送到网络或服务器。"}, {"text": "我把伞上传到了学校。", "explanation": "这里应该用〈带〉。伞是实物，要带到学校，不能用上传。"}, {"text": "我把花上传到了医院。", "explanation": "这里应该用〈送〉。花是实物，要送到医院，上传不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上传", "is_correct": true, "explanation": "上传：把作业送到网站，与“到网站”搭配，符合句意。"}, {"text": "批改", "is_correct": false, "explanation": "语义：批改是改正作业，不能批改到网站。"}, {"text": "寄", "is_correct": false, "explanation": "搭配：寄是邮寄给人或地址，不能寄到网站。"}, {"text": "清空", "is_correct": false, "explanation": "配价：清空只带事物宾语，不能用“到网站”表示去向。"}], "explanations": {"上传": "上传：把作业送到网站，与“到网站”搭配，符合句意。", "批改": "语义：批改是改正作业，不能批改到网站。", "寄": "搭配：寄是邮寄给人或地址，不能寄到网站。", "清空": "配价：清空只带事物宾语，不能用“到网站”表示去向。"}, "sentence_index": 6, "correct_answer": "上传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把课本上传给了我。", "explanation": "这里应该用〈递〉。课本是实物，递给别人要用〈递〉，上传只指送到网络上。"}, {"text": "工厂把钢材上传到了仓库。", "explanation": "这里应该用〈运〉。钢材是实物，运到仓库要用〈运〉，上传不用于实物运输。"}, {"text": "他给老板上传了一封邮件。", "explanation": "这里应该用〈发送〉。邮件是发给某人的，上传不能用于发给个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这份资料上传了到公司的系统里。", "corrected_sentence": "我把这份资料上传到了公司的系统里。", "error_description": "体标位置错误：“了”要放在“到”的后面，应说“上传到了……里”，不能说“上传了到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些视频上传的很快。", "corrected_sentence": "这些视频上传得很快。", "error_description": "补语错误：“上传”后引出程度补语要用结构助词“得”，不能用“的”，应说“上传得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
