INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90437, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "兑现是说到做到，真的把答应的事办好。", "primary_collocate": null, "pronunciation": "duì xiàn", "ipa": "tweɪ˥˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他答应带我去玩，今天终于兑现了。", "target_word": "兑现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板说会加工资，可是一直没兑现。", "target_word": "兑现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要兑现自己的承诺。", "target_word": "兑现", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈兑现了她的诺言，给我买了新书包。", "target_word": "兑现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司答应的奖金，月底就会兑现。", "target_word": "兑现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你答应过我的事，什么时候兑现？", "target_word": "兑现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话算数，答应的事都会兑现。", "target_word": "兑现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说考好了就请我们吃饭，她真的兑现了。", "target_word": "兑现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个承诺太大，我怕没法兑现。", "target_word": "兑现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是个守信用的人，说过的话都兑现。", "target_word": "兑现", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兑现了", "label": "完成体"}, {"form": "兑现过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "说到做到，把答应的事真正办好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d88c77-461f-4c74-96b2-9f5f37a1c376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90437, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兑现", "is_correct": true, "explanation": "“兑现”指把答应的事真正办到，与前文“答应带我去玩”前后呼应。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与前文“答应带我去玩”相反，与“终于”表示期望实现的语气也不合。"}, {"text": "违背", "is_correct": false, "explanation": "语义：“违背”指违反约定，与“终于”表示期望实现的语气矛盾。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“终于”所表达的期望实现相悖，句意应是承诺被办到，而不是被遗忘。"}], "explanations": {"兑现": "“兑现”指把答应的事真正办到，与前文“答应带我去玩”前后呼应。", "拒绝": "语义：“拒绝”与前文“答应带我去玩”相反，与“终于”表示期望实现的语气也不合。", "违背": "语义：“违背”指违反约定，与“终于”表示期望实现的语气矛盾。", "忘记": "语义：“忘记”与“终于”所表达的期望实现相悖，句意应是承诺被办到，而不是被遗忘。"}, "sentence_index": 0, "correct_answer": "兑现"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于兑现了自己的愿望。", "explanation": "这里应该用〈实现〉。兑现指把许下的承诺办到，愿望、理想要用实现。"}, {"text": "他认真兑现了自己的职责。", "explanation": "这里应该用〈履行〉。兑现针对许下的承诺或应付的款项，职责、义务要用履行。"}, {"text": "他一直兑现学校的规则。", "explanation": "这里应该用〈遵守〉。兑现针对许下的承诺或应付的款项，规则要用遵守。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90437, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兑现", "is_correct": true, "explanation": "“兑现”与“说话算数”呼应，表示答应的事真正办到。"}, {"text": "辜负", "is_correct": false, "explanation": "配价：“辜负”需要带“期望”“信任”之类的宾语，且与“说话算数”语义相反。"}, {"text": "怀疑", "is_correct": false, "explanation": "搭配：“怀疑”的施事应是人，不能说“答应的事都会怀疑”。"}, {"text": "推翻", "is_correct": false, "explanation": "语义：“推翻”指否定、颠覆，与“说话算数”正好相反。"}], "explanations": {"兑现": "“兑现”与“说话算数”呼应，表示答应的事真正办到。", "辜负": "配价：“辜负”需要带“期望”“信任”之类的宾语，且与“说话算数”语义相反。", "怀疑": "搭配：“怀疑”的施事应是人，不能说“答应的事都会怀疑”。", "推翻": "语义：“推翻”指否定、颠覆，与“说话算数”正好相反。"}, "sentence_index": 6, "correct_answer": "兑现"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校兑现了新的规定。", "explanation": "这里应该用〈实施〉。兑现针对许下的承诺或应付的款项，规定、政策要用实施。"}, {"text": "他终于兑现了作业。", "explanation": "这里应该用〈完成〉。兑现强调把许下的事办到，作业、任务要用完成。"}, {"text": "她终于兑现了自己的理想。", "explanation": "这里应该用〈实现〉。兑现针对许下的承诺，理想、抱负要用实现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90437, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她最后没有兑现了诺言。", "corrected_sentence": "她最后没有兑现诺言。", "error_description": "错误：否定句“没有兑现”之后不能再加“了”，写成“没有兑现了诺言”。正确：“没有兑现诺言”，否定句中动词后不用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90437, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他明天兑现了诺言。", "corrected_sentence": "他明天兑现诺言。", "error_description": "错误：“明天”指将来，动作尚未发生，动词后不能加“了”，应为“明天兑现诺言”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
