INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90440, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使受到损害；损害。", "primary_collocate": null, "pronunciation": "wēi hài", "ipa": "weɪ˥ xaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这种做法危害了公司的利益。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的行为危害公共安全。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假货危害消费者的权利。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不能做危害国家的事。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏消息危害了学校的名声。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要做危害别人利益的事。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种行为会危害他人的生命安全。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乱扔垃圾危害城市的环境。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话危害了朋友的名誉。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种广告危害青少年的成长。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "危害了", "label": "体标"}, {"form": "危害着", "label": "体标"}, {"form": "危害过", "label": "体标"}], "register": "书面", "sense_fingerprint": "损害利益、安全、名誉等抽象事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5695439c-db40-4c72-952c-6632c53558c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感动", "is_correct": false, "explanation": "配价：“感动”的对象应是人，“利益”不能被感动，句子说不通。"}, {"text": "危害", "is_correct": true, "explanation": "“危害”表示使利益受到损害，与“这种做法”的负面结果相合。"}, {"text": "遵守", "is_correct": false, "explanation": "搭配：“遵守”的对象是规则或法律，不说“遵守公司的利益”。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是喜爱、赞赏，与“做法”损害公司利益的语境相反。"}], "explanations": {"感动": "配价：“感动”的对象应是人，“利益”不能被感动，句子说不通。", "危害": "“危害”表示使利益受到损害，与“这种做法”的负面结果相合。", "遵守": "搭配：“遵守”的对象是规则或法律，不说“遵守公司的利益”。", "欣赏": "语义：“欣赏”是喜爱、赞赏，与“做法”损害公司利益的语境相反。"}, "sentence_index": 0, "correct_answer": "危害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师危害了我的作业，因为写错了很多字。", "explanation": "这里应该用〈批评〉。危害指损害利益、安全、名誉等，老师指出作业的问题要说批评。"}, {"text": "他危害了朋友的秘密，还要说出去。", "explanation": "这里应该用〈泄露〉。危害指对利益、安全、名誉的损害，秘密被说出去要用泄露。"}, {"text": "堵车危害了我们的行程。", "explanation": "这里应该用〈妨碍〉。妨碍指阻挡或影响事情进行，危害指严重损害人或安全，行程的顺利与否要用妨碍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思考", "is_correct": false, "explanation": "语义：“思考”是人的思维活动，不能用来处理“生命安全”，句子说不通。"}, {"text": "危害", "is_correct": true, "explanation": "“危害”表示使他人的生命安全受到威胁，与“这种行为”的语境相合。"}, {"text": "体会", "is_correct": false, "explanation": "语义：“体会”指亲身感受，行为本身不能去体会他人的生命安全。"}, {"text": "感激", "is_correct": false, "explanation": "配价：“感激”的对象应是人或恩情，不能感激“生命安全”。"}], "explanations": {"思考": "语义：“思考”是人的思维活动，不能用来处理“生命安全”，句子说不通。", "危害": "“危害”表示使他人的生命安全受到威胁，与“这种行为”的语境相合。", "体会": "语义：“体会”指亲身感受，行为本身不能去体会他人的生命安全。", "感激": "配价：“感激”的对象应是人或恩情，不能感激“生命安全”。"}, "sentence_index": 6, "correct_answer": "危害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈的决定危害了我的意愿。", "explanation": "这里应该用〈违背〉。违背指不顺从别人的意愿，危害指造成损害，意愿不能被危害，此处应说违背。"}, {"text": "我危害了你的午睡，真抱歉。", "explanation": "这里应该用〈打扰〉。危害指造成严重损害，打扰指妨碍别人休息，此处不能用危害。"}, {"text": "他不小心危害了那场考试。", "explanation": "这里应该用〈耽误〉。危害指造成严重损害，此处是考试被耽误，应说耽误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种行为很危害了社会秩序。", "corrected_sentence": "这种行为严重危害了社会秩序。", "error_description": "错误：副词“很”不能修饰动词“危害”，应改为“严重”。应说“这种行为严重危害了社会秩序”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种广告以后会危害了青少年的成长。", "corrected_sentence": "这种广告以后会危害青少年的成长。", "error_description": "体标错误：“以后会”表示将来，“危害”后不能加表示完成的“了”。应说“以后会危害青少年的成长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90442, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下午", "is_correct": true, "explanation": "正确：“下午”与“上午”相对，指中午十二点以后到傍晚前的时间。"}, {"text": "明天", "is_correct": false, "explanation": "“明天”指将来的一天，与“上午”不构成反义。"}, {"text": "昨天", "is_correct": false, "explanation": "“昨天”指过去的一天，不是“上午”的反义词。"}, {"text": "深夜", "is_correct": false, "explanation": "“深夜”指夜里很晚的时间，不与“上午”相对。"}], "correct_answer": "下午", "explanations": {"下午": "正确：“下午”与“上午”相对，指中午十二点以后到傍晚前的时间。", "明天": "“明天”指将来的一天，与“上午”不构成反义。", "昨天": "“昨天”指过去的一天，不是“上午”的反义词。", "深夜": "“深夜”指夜里很晚的时间，不与“上午”相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90442, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下午", "is_correct": true, "explanation": "正确：“下午”与“上午”相对，指中午十二点以后到傍晚前的时间。"}, {"text": "傍晚", "is_correct": false, "explanation": "“傍晚”指日落前后，与“上午”不构成反义。"}, {"text": "去年", "is_correct": false, "explanation": "“去年”指过去的一年，不是“上午”的反义词。"}, {"text": "周末", "is_correct": false, "explanation": "“周末”指一周的休息日，与“上午”不构成反义。"}], "correct_answer": "下午", "explanations": {"下午": "正确：“下午”与“上午”相对，指中午十二点以后到傍晚前的时间。", "傍晚": "“傍晚”指日落前后，与“上午”不构成反义。", "去年": "“去年”指过去的一年，不是“上午”的反义词。", "周末": "“周末”指一周的休息日，与“上午”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90442, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从清晨到正午十二点以前的一段时间。", "primary_collocate": null, "pronunciation": "shàng wǔ", "ipa": "ʂaŋ˥˩ u˨˩˦", "syllable_count": 2, "sentences": [{"text": "上午十一点，我们在车站见面。", "target_word": "上午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个星期六上午，他都去跑步。", "target_word": "上午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上午的太阳不太热。", "target_word": "上午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天上午下过一场小雨。", "target_word": "上午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师上午给我们讲了一个故事。", "target_word": "上午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店上午八点开门。", "target_word": "上午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我习惯在上午写作业。", "target_word": "上午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期天上午我睡到了十点。", "target_word": "上午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上午我去医院看了医生。", "target_word": "上午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们上午在教室里画画。", "target_word": "上午", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一上午", "label": "复合词"}, {"form": "大上午", "label": "复合词"}], "register": "通用", "sense_fingerprint": "从清晨到正午十二点以前的时段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '477a65e0-38ea-45c0-b671-a699ad3bfba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90442, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上午", "is_correct": true, "explanation": "正确：上午（shàng wǔ），指从清晨到正午十二点以前的时段。"}, {"text": "商务", "is_correct": false, "explanation": "shāng（第一声）与 shàng（第四声）声调不同，意思是商业事务。"}, {"text": "晌午", "is_correct": false, "explanation": "shǎng（第三声）与 shàng（第四声）声调不同，意思是中午。"}, {"text": "尚无", "is_correct": false, "explanation": "wú（第二声）与 wǔ（第三声）声调不同，意思是还没有。"}, {"text": "上古", "is_correct": false, "explanation": "gǔ 与 wǔ 声母不同（g 与 w），意思是远古时期。"}], "explanations": {"上午": "正确：上午（shàng wǔ），指从清晨到正午十二点以前的时段。", "商务": "shāng（第一声）与 shàng（第四声）声调不同，意思是商业事务。", "晌午": "shǎng（第三声）与 shàng（第四声）声调不同，意思是中午。", "尚无": "wú（第二声）与 wǔ（第三声）声调不同，意思是还没有。", "上古": "gǔ 与 wǔ 声母不同（g 与 w），意思是远古时期。"}, "sentence_index": null, "correct_answer": "上午"}, "level_3": {"options": [{"text": "上午", "is_correct": true, "explanation": "正确：“上午”指早上到中午前，与“十一点”搭配，表示上午十一点。"}, {"text": "凌晨", "is_correct": false, "explanation": "语义：“凌晨”指0至6点，与“十一点”矛盾。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：“午夜”指夜里零点前后，与“十一点”不符。"}, {"text": "傍晚", "is_correct": false, "explanation": "搭配：“傍晚”指日落前后，一般到七点左右，十一点已不属于傍晚。"}], "explanations": {"上午": "正确：“上午”指早上到中午前，与“十一点”搭配，表示上午十一点。", "凌晨": "语义：“凌晨”指0至6点，与“十一点”矛盾。", "午夜": "语义：“午夜”指夜里零点前后，与“十一点”不符。", "傍晚": "搭配：“傍晚”指日落前后，一般到七点左右，十一点已不属于傍晚。"}, "sentence_index": 0, "correct_answer": "上午"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上午十二点半，我们一起吃饭。", "explanation": "这里应该用〈中午〉。上午指正午十二点以前，十二点半已经不属于上午。"}, {"text": "今天上午三点，我还在看书。", "explanation": "这里应该用〈凌晨〉。上午指白天，“凌晨”指半夜到天亮前，不能说“上午三点”。"}, {"text": "今天上午日落的时候下过一场小雨。", "explanation": "这里应该用〈傍晚〉。上午指白天，日落时已不属于上午。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上午", "is_correct": true, "explanation": "正确：“习惯在上午写作业”指每天上午的固定时间，符合句意。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”是一次性的过去，不能说“习惯在昨天”。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”是一次性的将来，与“习惯”不合。"}, {"text": "刚才", "is_correct": false, "explanation": "搭配：“刚才”指刚过去的一小段时间，不与“习惯在……”连用。"}], "explanations": {"上午": "正确：“习惯在上午写作业”指每天上午的固定时间，符合句意。", "昨天": "语义：“昨天”是一次性的过去，不能说“习惯在昨天”。", "明天": "语义：“明天”是一次性的将来，与“习惯”不合。", "刚才": "搭配：“刚才”指刚过去的一小段时间，不与“习惯在……”连用。"}, "sentence_index": 6, "correct_answer": "上午"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们上午在教室里睡午觉。", "explanation": "这里应该用〈下午〉。午觉在午饭后，上午不能说“睡午觉”。"}, {"text": "孩子们上午在教室里过夜。", "explanation": "这里应该用〈夜里〉。上午指白天，不能说在上午过夜。"}, {"text": "孩子们上午在教室里吃晚饭。", "explanation": "这里应该用〈晚上〉。晚饭在傍晚吃，上午不能吃晚饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在图书馆学了一件上午。", "corrected_sentence": "他在图书馆学了一个上午。", "error_description": "量词错误：“上午”是一段时间，应用量词“个”，不能用“件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在厨房忙了一座上午。", "corrected_sentence": "她在厨房忙了一个上午。", "error_description": "量词错误：“上午”是一段时间，应用量词“个”，不能用“座”（“座”用于山、楼等大型固定物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
