INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90443, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "全本是一本完整的书，从头到尾都有。", "primary_collocate": null, "pronunciation": "quán běn", "ipa": "tɕʰɥɛn˧˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "我在书店买到了《西游记》全本。", "target_word": "全本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本是全本，不是缩写本。", "target_word": "全本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上有这本小说的全本。", "target_word": "全本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷有一套《红楼梦》全本。", "target_word": "全本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆的这本书是全本，每页都在。", "target_word": "全本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找《三国演义》的全本。", "target_word": "全本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这不是全本，后面少了十页。", "target_word": "全本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你读的是全本还是节选？", "target_word": "全本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全本太厚了，我先看简单版。", "target_word": "全本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们读全本，不要只看故事简介。", "target_word": "全本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全本小说", "label": "复合"}], "register": "中性", "sense_fingerprint": "从头到尾都有的完整书籍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb690da-b4fb-44a8-8915-e03b8c08ddd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90443, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全本", "is_correct": true, "explanation": "正确：“买到了《西游记》全本”指买到完整的书，与书名和“买到了”搭配。"}, {"text": "电饭煲", "is_correct": false, "explanation": "语义：电饭煲是家电，不是书，与“买到了《西游记》”的书籍语境不符。"}, {"text": "洗衣液", "is_correct": false, "explanation": "语义：洗衣液是日用品，不是书，与“买到了《西游记》”的书籍语境不符。"}, {"text": "拖把", "is_correct": false, "explanation": "语义：拖把是清洁工具，不是书，与“买到了《西游记》”的书籍语境不符。"}], "explanations": {"全本": "正确：“买到了《西游记》全本”指买到完整的书，与书名和“买到了”搭配。", "电饭煲": "语义：电饭煲是家电，不是书，与“买到了《西游记》”的书籍语境不符。", "洗衣液": "语义：洗衣液是日用品，不是书，与“买到了《西游记》”的书籍语境不符。", "拖把": "语义：拖把是清洁工具，不是书，与“买到了《西游记》”的书籍语境不符。"}, "sentence_index": 0, "correct_answer": "全本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买到了一只全本。", "explanation": "这里应该用〈本〉。书籍的量词是“本”，“只”用于动物或成对东西中的一个。"}, {"text": "我买到了一块全本。", "explanation": "这里应该用〈本〉。“块”用于块状的东西，书要用“本”来计量。"}, {"text": "我在网上买了一台全本。", "explanation": "这里应该用〈本〉。“台”用于机器、电器，书不能用“台”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90443, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全本", "is_correct": true, "explanation": "正确：“这不是全本，后面少了十页”否定的是完整版，与“后面少了十页”的说明一致。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不是书，不能说“后面少了十页”。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干没有“页”，“后面少了十页”说的是书籍或文稿。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：“页”只计量纸张或书，“手套”没有页数，不能说“少了十页”。"}], "explanations": {"全本": "正确：“这不是全本，后面少了十页”否定的是完整版，与“后面少了十页”的说明一致。", "玻璃": "语义：玻璃不是书，不能说“后面少了十页”。", "饼干": "语义：饼干没有“页”，“后面少了十页”说的是书籍或文稿。", "手套": "搭配：“页”只计量纸张或书，“手套”没有页数，不能说“少了十页”。"}, "sentence_index": 6, "correct_answer": "全本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间房子是全本，四面都有窗。", "explanation": "这里应该用〈完整〉。全本只指书或剧本，房子不能用全本。"}, {"text": "这篇论文的全本已经发表。", "explanation": "这里应该用〈全文〉。论文是单篇文字，用全文；全本只用于书和剧本。"}, {"text": "这张照片拍下了城市的全本。", "explanation": "这里应该用〈全景〉。全景指整体景象，照片不是书，不能用全本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90443, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书店里有很多全本们。", "corrected_sentence": "书店里有很多全本。", "error_description": "多余的“们”：“全本”指书，不是指人，不能加“们”；表示数量多用“很多”即可，应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90443, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一张全本，不是节选。", "corrected_sentence": "这是一本全本，不是节选。", "error_description": "量词错误：书籍用“本”计量，“张”用于纸张、桌子等平面的东西，不能用于“全本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
