INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90444, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "完整的书或剧本，没有缺少的部分。", "primary_collocate": null, "pronunciation": "quán běn", "ipa": "tɕʰɥɛn˧˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个剧团今晚演出《牡丹亭》全本。", "target_word": "全本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要演全本，不删任何一幕。", "target_word": "全本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖的是全本，没有缺页。", "target_word": "全本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找到了那部京剧的全本。", "target_word": "全本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全本演完要四个小时。", "target_word": "全本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旧书摊上有《水浒传》的全本，我买下了。", "target_word": "全本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份剧本是全本，每一场都有。", "target_word": "全本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这出戏今天演全本，不是选段。", "target_word": "全本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆想收藏这本书的全本。", "target_word": "全本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把全本给我，我想看结尾。", "target_word": "全本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全本小说", "label": "复合"}], "register": "中性", "sense_fingerprint": "没有缺少部分的完整书或剧本", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb690da-b4fb-44a8-8915-e03b8c08ddd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90444, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全本", "is_correct": true, "explanation": "正确：“演出《牡丹亭》全本”指整出戏完整上演，与“演出”的对象搭配。"}, {"text": "戏服", "is_correct": false, "explanation": "语义：戏服是演员穿的衣服，不是可以演出的剧目。"}, {"text": "布景", "is_correct": false, "explanation": "搭配：“演出”的对象是剧目，不说“演出布景”，布景是搭设的。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不能被演出，《牡丹亭》是戏曲。"}], "explanations": {"全本": "正确：“演出《牡丹亭》全本”指整出戏完整上演，与“演出”的对象搭配。", "戏服": "语义：戏服是演员穿的衣服，不是可以演出的剧目。", "布景": "搭配：“演出”的对象是剧目，不说“演出布景”，布景是搭设的。", "饮料": "语义：饮料不能被演出，《牡丹亭》是戏曲。"}, "sentence_index": 0, "correct_answer": "全本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他找到了一首京剧的全本。", "explanation": "这里应该用〈部〉或〈本〉。“首”用于诗歌、歌曲，不用于剧本。"}, {"text": "他找到了一张京剧的全本。", "explanation": "这里应该用〈部〉或〈本〉。“张”用于纸张、桌子等平面的东西，不用于剧本。"}, {"text": "他找到了一把京剧的全本。", "explanation": "这里应该用〈部〉或〈本〉。“把”用于有柄或可握的东西，不用于剧本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90444, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全本", "is_correct": true, "explanation": "正确：“这份剧本是全本，每一场都有”说的是完整的剧本，与“每一场都有”一致。"}, {"text": "舞台", "is_correct": false, "explanation": "语义：舞台是表演的场所，不能说“剧本是舞台”。"}, {"text": "道具", "is_correct": false, "explanation": "语义：道具是演出用的物件，不是剧本的类别。"}, {"text": "幕间", "is_correct": false, "explanation": "搭配：“幕间”指两幕之间的休息，“剧本是X”的X应是剧本的类别，不能用它。"}], "explanations": {"全本": "正确：“这份剧本是全本，每一场都有”说的是完整的剧本，与“每一场都有”一致。", "舞台": "语义：舞台是表演的场所，不能说“剧本是舞台”。", "道具": "语义：道具是演出用的物件，不是剧本的类别。", "幕间": "搭配：“幕间”指两幕之间的休息，“剧本是X”的X应是剧本的类别，不能用它。"}, "sentence_index": 6, "correct_answer": "全本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇论文的全本已经发表。", "explanation": "这里应该用〈全文〉。论文是单篇文字，用全文；全本只用于书和剧本。"}, {"text": "他把这台电脑的全本装好了。", "explanation": "这里不能用“全本”。全本只指完整的书或剧本，电脑不属于这一类。"}, {"text": "这张照片拍下了城市的全本。", "explanation": "这里应该用〈全景〉。全景指整体景象，照片不是书或剧本，不能用全本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "剧团要演三部全本们。", "corrected_sentence": "剧团要演三部全本。", "error_description": "多余的“们”：“全本”是剧本或书，不指人，不能加“们”表示复数；数量已由“三部”表示，应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份剧本很全本，每一幕都在。", "corrected_sentence": "这份剧本是全本，每一幕都在。", "error_description": "判断词错误：“全本”是名词，不能被“很”修饰；说明剧本的类别应用“是”，应把“很”改为“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90445, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db9e259-24f8-4873-845d-be6bf865173b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90445, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db9e259-24f8-4873-845d-be6bf865173b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90445, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人死了，不再活着，这是一种好听的说法。", "primary_collocate": null, "pronunciation": "qù shì", "ipa": "tɕʰy˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷去年冬天去世了。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他父亲三年前去世了。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶去世后，家里变得很安静。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说老师的妈妈昨天去世了。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十岁时，爷爷就去世了。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外公去世的那天，下着大雨。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的丈夫五十岁就去世了。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人去世前，把家人都叫到身边。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家在北京去世，活了九十岁。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我叔叔去世以后，我们常去看婶婶。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "去世了", "label": "体标（了）"}], "register": "委婉", "sense_fingerprint": "去世：人死亡的好听说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed144756-53d4-4300-bd5f-f63fe54a21d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90445, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "去世", "is_correct": true, "explanation": "去世 qù shì：正确答案，指人死亡，是委婉的说法。"}, {"text": "驱使", "is_correct": false, "explanation": "驱使 qūshǐ：两个音节都只是声调不同，第一个是第一声，第二个是第三声，意思是支使、役使，不是去世。"}, {"text": "句式", "is_correct": false, "explanation": "句式 jùshì：j 与 q 声母不同，其余音节和声调都相同，意思是句子的结构形式。"}, {"text": "叙事", "is_correct": false, "explanation": "叙事 xùshì：x 与 q 声母不同，声调相同，意思是叙述事情。"}, {"text": "曲式", "is_correct": false, "explanation": "曲式 qǔshì：第一个音节 qǔ 是第三声，与 qù（第四声）声调不同，意思是乐曲的结构形式。"}], "explanations": {"去世": "去世 qù shì：正确答案，指人死亡，是委婉的说法。", "驱使": "驱使 qūshǐ：两个音节都只是声调不同，第一个是第一声，第二个是第三声，意思是支使、役使，不是去世。", "句式": "句式 jùshì：j 与 q 声母不同，其余音节和声调都相同，意思是句子的结构形式。", "叙事": "叙事 xùshì：x 与 q 声母不同，声调相同，意思是叙述事情。", "曲式": "曲式 qǔshì：第一个音节 qǔ 是第三声，与 qù（第四声）声调不同，意思是乐曲的结构形式。"}, "sentence_index": null, "correct_answer": "去世"}, "level_3": {"options": [{"text": "出生", "is_correct": false, "explanation": "语义：“出生”指刚来到世上，爷爷去年冬天出生，与常理不符。"}, {"text": "去世", "is_correct": true, "explanation": "去世：人死亡的委婉说法，与“爷爷”和“去年冬天”搭配自然。"}, {"text": "变成", "is_correct": false, "explanation": "配价：“变成”后面要带出结果，“爷爷去年冬天变成了”句子不完整。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指学业结束，爷爷去年毕业与语境不符。"}], "explanations": {"出生": "语义：“出生”指刚来到世上，爷爷去年冬天出生，与常理不符。", "去世": "去世：人死亡的委婉说法，与“爷爷”和“去年冬天”搭配自然。", "变成": "配价：“变成”后面要带出结果，“爷爷去年冬天变成了”句子不完整。", "毕业": "语义：“毕业”指学业结束，爷爷去年毕业与语境不符。"}, "sentence_index": 0, "correct_answer": "去世"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只小鸡昨天去世了。", "explanation": "这里应该用〈死〉。去世是对人的委婉说法，小鸡等动物死亡只说“死”。"}, {"text": "那棵老槐树去年去世了。", "explanation": "这里应该用〈枯死〉。去世只用于人，树木因枯萎死亡要说“枯死”。"}, {"text": "那座老房子去年去世了。", "explanation": "这里应该用〈拆除〉。去世只用于人，房屋被拆掉要说“拆除”，不能说“去世”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db9e259-24f8-4873-845d-be6bf865173b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90445, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长大", "is_correct": false, "explanation": "语义：“长大”指成长，丈夫五十岁才“长大”，与“五十岁就”的语境矛盾。"}, {"text": "怀孕", "is_correct": false, "explanation": "搭配：“怀孕”只能用于女性，不能用于“她的丈夫”。"}, {"text": "去世", "is_correct": true, "explanation": "去世：人死亡的委婉说法，“五十岁就去世了”说法自然。"}, {"text": "出嫁", "is_correct": false, "explanation": "搭配：“出嫁”指女子结婚到夫家，不能用于男子“丈夫”。"}], "explanations": {"长大": "语义：“长大”指成长，丈夫五十岁才“长大”，与“五十岁就”的语境矛盾。", "怀孕": "搭配：“怀孕”只能用于女性，不能用于“她的丈夫”。", "去世": "去世：人死亡的委婉说法，“五十岁就去世了”说法自然。", "出嫁": "搭配：“出嫁”指女子结婚到夫家，不能用于男子“丈夫”。"}, "sentence_index": 6, "correct_answer": "去世"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那朵玫瑰昨天去世了。", "explanation": "这里应该用〈凋谢〉。去世只用于人，花草凋谢要说“凋谢”。"}, {"text": "蜡烛在风里去世了。", "explanation": "这里应该用〈熄灭〉。去世只用于人，蜡烛、火焰熄灭要说“熄灭”。"}, {"text": "那家工厂去年去世了。", "explanation": "这里应该用〈倒闭〉。去世只用于人，企业停止经营要说“倒闭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db9e259-24f8-4873-845d-be6bf865173b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我外婆前年去世着，我一直很想她。", "corrected_sentence": "我外婆前年去世了，我一直很想她。", "error_description": "“去世着”错误，应为“去世了”：去世表示已经发生的变化，要用“了”，不用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db9e259-24f8-4873-845d-be6bf865173b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90445, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我舅舅去年很去世了，大家都很难过。", "corrected_sentence": "我舅舅去年去世了，大家都很难过。", "error_description": "“去世”是表示死亡的动词，不能用程度副词“很”修饰，应删去“很”，说“去年去世了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db9e259-24f8-4873-845d-be6bf865173b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90448, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有所作为", "is_correct": true, "explanation": "「有所作为」指积极履行职责、做出成绩，与「不作为」构成反义。"}, {"text": "散步", "is_correct": false, "explanation": "「散步」指悠闲地走动，与履行职责无关，不是「不作为」的反义词。"}, {"text": "旅行", "is_correct": false, "explanation": "「旅行」指出门游览，与履行职责的意义无关，不构成反义。"}, {"text": "唱歌", "is_correct": false, "explanation": "「唱歌」指发出歌声，与「不作为」的意义无关，不构成反义。"}], "correct_answer": "有所作为", "explanations": {"有所作为": "「有所作为」指积极履行职责、做出成绩，与「不作为」构成反义。", "散步": "「散步」指悠闲地走动，与履行职责无关，不是「不作为」的反义词。", "旅行": "「旅行」指出门游览，与履行职责的意义无关，不构成反义。", "唱歌": "「唱歌」指发出歌声，与「不作为」的意义无关，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90448, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有所作为", "is_correct": true, "explanation": "「有所作为」指积极履行职责、做出成绩，与「不作为」构成反义。"}, {"text": "读书", "is_correct": false, "explanation": "「读书」指阅读书籍，与履行职责的意义无关，不构成反义。"}, {"text": "游泳", "is_correct": false, "explanation": "「游泳」指在水中运动，与「不作为」的意义无关，不构成反义。"}, {"text": "写字", "is_correct": false, "explanation": "「写字」指书写文字，与「不作为」的意义无关，不构成反义。"}], "correct_answer": "有所作为", "explanations": {"有所作为": "「有所作为」指积极履行职责、做出成绩，与「不作为」构成反义。", "读书": "「读书」指阅读书籍，与履行职责的意义无关，不构成反义。", "游泳": "「游泳」指在水中运动，与「不作为」的意义无关，不构成反义。", "写字": "「写字」指书写文字，与「不作为」的意义无关，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90448, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "负有职责的人该做而不做；不履行职责。", "primary_collocate": null, "pronunciation": "bú zuò wéi", "ipa": "pu˧˥ tswɔ˥˩ weɪ˧˥", "syllable_count": 3, "sentences": [{"text": "有些官员不作为，老百姓很生气。", "target_word": "不作为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个部门长期不作为，问题一直没解决。", "target_word": "不作为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路灯坏了好久，管理人员却不作为。", "target_word": "不作为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府不作为，会让人们失去信心。", "target_word": "不作为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是负责人，不能对安全问题不作为。", "target_word": "不作为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群众投诉了很多次，相关单位还是不作为。", "target_word": "不作为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发现问题却不作为，是不对的。", "target_word": "不作为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察不作为，大家都觉得不公平。", "target_word": "不作为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司经理不作为，工作越来越乱。", "target_word": "不作为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民批评这些干部不作为。", "target_word": "不作为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "有职责的人不履行职责", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb45aab-75ed-4f65-a859-450e1280774f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90448, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不作为", "is_correct": true, "explanation": "「不作为」指负有职责的人该做而不做，与“老百姓很生气”的结果相符。"}, {"text": "尽责", "is_correct": false, "explanation": "语义：「尽责」指认真履行职责，与“老百姓很生气”的结果相矛盾。"}, {"text": "勤政", "is_correct": false, "explanation": "语义：「勤政」指勤于政务，与“老百姓很生气”的结果不协调。"}, {"text": "奉公", "is_correct": false, "explanation": "搭配：「奉公」多用于“奉公守法”等固定说法，单独用于“有些官员奉公”不自然，且与“老百姓很生气”矛盾。"}], "explanations": {"不作为": "「不作为」指负有职责的人该做而不做，与“老百姓很生气”的结果相符。", "尽责": "语义：「尽责」指认真履行职责，与“老百姓很生气”的结果相矛盾。", "勤政": "语义：「勤政」指勤于政务，与“老百姓很生气”的结果不协调。", "奉公": "搭配：「奉公」多用于“奉公守法”等固定说法，单独用于“有些官员奉公”不自然，且与“老百姓很生气”矛盾。"}, "sentence_index": 0, "correct_answer": "不作为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不作为，每天都很努力地工作。", "explanation": "用法错误：这里应用〈勤奋〉。「不作为」指负有职责的人该做而不做，与“很努力地工作”意思相反。"}, {"text": "这台机器不作为，所以不能工作。", "explanation": "用法错误：「不作为」指负有职责的人不履行职责，机器没有职责可言，这里应说“坏了”或“失灵”。"}, {"text": "他不作为，因此受到了表扬。", "explanation": "用法错误：这里应用〈主动〉。「不作为」是贬义，指该做的事不去做，不能用来表示受表扬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不作为", "is_correct": true, "explanation": "「不作为」指负有职责的人该做而不做，与“是不对的”的评价相符。"}, {"text": "解决", "is_correct": false, "explanation": "语义：「解决问题」是正确的做法，与“是不对的”的评价相矛盾。"}, {"text": "修复", "is_correct": false, "explanation": "语义：「修复」同样是积极处理问题，与“是不对的”的评价冲突。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：「完成」一般带“任务、工作”作宾语，不说“完成问题”，且与“是不对的”也不协调。"}], "explanations": {"不作为": "「不作为」指负有职责的人该做而不做，与“是不对的”的评价相符。", "解决": "语义：「解决问题」是正确的做法，与“是不对的”的评价相矛盾。", "修复": "语义：「修复」同样是积极处理问题，与“是不对的”的评价冲突。", "完成": "搭配：「完成」一般带“任务、工作”作宾语，不说“完成问题”，且与“是不对的”也不协调。"}, "sentence_index": 6, "correct_answer": "不作为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不作为，每天都在认真工作。", "explanation": "用法错误：这里应用〈勤奋〉。「不作为」指该做的事不去做，与“认真工作”意思相反。"}, {"text": "市民不作为，批评这些干部。", "explanation": "用法错误：这里应用〈不参与〉。「不作为」只指负有职责的人该做而不做，普通市民没有这类职责，应说“市民不参与”或“市民批评”。"}, {"text": "这些不作为的干部很受欢迎。", "explanation": "用法错误：这里应用〈勤勉〉。「不作为」是贬义，指干部不履行职责，说“很受欢迎”与语义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些官员群众的困难不作为。", "corrected_sentence": "这些官员对群众的困难不作为。", "error_description": "介词漏用：「不作为」的对象要用「对」引出，应写作“对群众的困难不作为”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些干部被不作为，市民很生气。", "corrected_sentence": "这些干部不作为，市民很生气。", "error_description": "用法错误：「不作为」是不及物动词，不能用于「被」字句，这里应删去“被”，写作“这些干部不作为，市民很生气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
