INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90449, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公务是国家或单位里的工作。", "primary_collocate": null, "pronunciation": "gōng wù", "ipa": "kʊŋ˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "他的公务很多，常常加班到很晚。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她刚到单位，还不熟悉公务。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李退休后，不再管公务了。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公务要认真，不能马虎。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把公务交给同事，自己去医院了。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有两部手机，一部办公务，一部办私事。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公务办完以后，他才和朋友见面。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局长今天有公务，不能来开会。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了公务，去过很多城市。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公务和私事要分开，这是单位的规定。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公务员", "label": "复合"}, {"form": "公务车", "label": "复合"}, {"form": "公务舱", "label": "复合"}], "register": "书面", "sense_fingerprint": "国家或单位里分内的工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9b14e92-3a0f-44e7-b1c6-121a5b382a86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90449, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公务", "is_correct": true, "explanation": "公务指国家或单位里分内的工作，是正确答案。"}, {"text": "公寓", "is_correct": false, "explanation": "gōngyù 与 gōngwù 的韵母不同（ü 与 u），意思是公寓。"}, {"text": "共舞", "is_correct": false, "explanation": "gòngwǔ 与 gōngwù 两个音节的声调都不同，意思是共同跳舞。"}, {"text": "贡物", "is_correct": false, "explanation": "gòngwù 与 gōngwù 第一个音节声调不同（第四声与第一声），意思是进贡的物品。"}], "explanations": {"公务": "公务指国家或单位里分内的工作，是正确答案。", "公寓": "gōngyù 与 gōngwù 的韵母不同（ü 与 u），意思是公寓。", "共舞": "gòngwǔ 与 gōngwù 两个音节的声调都不同，意思是共同跳舞。", "贡物": "gòngwù 与 gōngwù 第一个音节声调不同（第四声与第一声），意思是进贡的物品。"}, "sentence_index": null, "correct_answer": "公务"}, "level_3": {"options": [{"text": "公务", "is_correct": true, "explanation": "公务指国家或单位里的工作，与“很多、常常加班”的句意相符。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏不会导致加班到很晚，句子说不通。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜多不会导致加班，“蔬菜很多，加班到很晚”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“他的窗户很多”不是常用说法，且与“加班”无关。"}], "explanations": {"公务": "公务指国家或单位里的工作，与“很多、常常加班”的句意相符。", "游戏": "语义：游戏不会导致加班到很晚，句子说不通。", "蔬菜": "语义：蔬菜多不会导致加班，“蔬菜很多，加班到很晚”说不通。", "窗户": "搭配：“他的窗户很多”不是常用说法，且与“加班”无关。"}, "sentence_index": 0, "correct_answer": "公务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每周去学生家做公务，教数学。", "explanation": "这里应该用〈家教〉。公务指国家或单位里的工作，去学生家补课不叫公务。"}, {"text": "孩子每天放学后做公务。", "explanation": "这里应该用〈游戏〉。公务指国家或单位里的工作，孩子玩游戏不是公务。"}, {"text": "学生每天晚上做公务。", "explanation": "这里应该用〈作业〉。学生的作业不是国家或单位里的工作，不能说公务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90449, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "公务", "is_correct": true, "explanation": "公务指国家或单位里分内的工作，是正确答案。"}, {"text": "公屋", "is_correct": false, "explanation": "gōngwū 与 gōngwù 第二个音节声调不同（第一声与第四声），意思是香港的公共住房。"}, {"text": "供物", "is_correct": false, "explanation": "gòngwù 与 gōngwù 第一个音节声调不同（第四声与第一声），意思是供奉的物品。"}, {"text": "公寓", "is_correct": false, "explanation": "gōngyù 与 gōngwù 的韵母不同（ü 与 u），意思是公寓。"}], "explanations": {"公务": "公务指国家或单位里分内的工作，是正确答案。", "公屋": "gōngwū 与 gōngwù 第二个音节声调不同（第一声与第四声），意思是香港的公共住房。", "供物": "gòngwù 与 gōngwù 第一个音节声调不同（第四声与第一声），意思是供奉的物品。", "公寓": "gōngyù 与 gōngwù 的韵母不同（ü 与 u），意思是公寓。"}, "sentence_index": null, "correct_answer": "公务"}, "level_3": {"options": [{"text": "公务", "is_correct": true, "explanation": "公务指国家或单位里的工作，“办完以后”才见朋友，符合句意。"}, {"text": "卡车", "is_correct": false, "explanation": "语义：卡车不能“办完”，句子说不通。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不能“办完”，句子说不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“办”一般接事务，“钥匙”不能这样搭配。"}], "explanations": {"公务": "公务指国家或单位里的工作，“办完以后”才见朋友，符合句意。", "卡车": "语义：卡车不能“办完”，句子说不通。", "水果": "语义：水果不能“办完”，句子说不通。", "钥匙": "搭配：“办”一般接事务，“钥匙”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "公务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我表姐的公务是开美容院。", "explanation": "这里应该用〈职业〉。公务指国家或单位里的工作，个人开店的营生要说职业，不叫公务。"}, {"text": "周末我们去公园，享受公务。", "explanation": "这个词不这么用。公务是必须办理的事务，不能拿来享受。"}, {"text": "家长的公务是管教孩子。", "explanation": "这里应该用〈职责〉。公务指国家或单位里的工作，家长管教孩子是家庭责任，不叫公务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90449, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我这个月有两条公务要办。", "corrected_sentence": "我这个月有两项公务要办。", "error_description": "错误：“两条公务”；正确：“两项公务”。公务是事务，计量应用“项”，“条”用于细长的东西或消息等，不用于公务。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90449, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐已经处理了完公务，可以下班了。", "corrected_sentence": "我姐姐已经处理完了公务，可以下班了。", "error_description": "错误：“处理了完公务”；正确：“处理完了公务”。结果补语“完”须紧跟动词“处理”，“了”放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
