INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90450, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "关于国家、集体的事务。", "primary_collocate": null, "pronunciation": "gōng wù", "ipa": "kʊŋ˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "他因为公务出差，下周才能回来。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公务繁忙，经理没有时间吃午饭。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车只能用来办公务，不能私用。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天忙于公务，很少回家。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王正在处理公务，请你等一下。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为公务在身，他不能参加朋友的婚礼。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公务之余，他喜欢在家写字。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上班时间不要做私事，以免耽误公务。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次去北京是为了公务，费用由单位出。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长把公务放在第一位，从不迟到。", "target_word": "公务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公务员", "label": "复合"}, {"form": "公务车", "label": "复合"}, {"form": "公务舱", "label": "复合"}], "register": "书面", "sense_fingerprint": "关于国家或集体的事务，与私事相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9b14e92-3a0f-44e7-b1c6-121a5b382a86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90450, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公务", "is_correct": true, "explanation": "公务指关于国家、集体的事务，是正确答案。"}, {"text": "公寓", "is_correct": false, "explanation": "gōngyù 与 gōngwù 的韵母不同（ü 与 u），意思是公寓。"}, {"text": "共舞", "is_correct": false, "explanation": "gòngwǔ 与 gōngwù 两个音节的声调都不同，意思是共同跳舞。"}, {"text": "公屋", "is_correct": false, "explanation": "gōngwū 与 gōngwù 第二个音节声调不同（第一声与第四声），意思是香港的公共住房。"}], "explanations": {"公务": "公务指关于国家、集体的事务，是正确答案。", "公寓": "gōngyù 与 gōngwù 的韵母不同（ü 与 u），意思是公寓。", "共舞": "gòngwǔ 与 gōngwù 两个音节的声调都不同，意思是共同跳舞。", "公屋": "gōngwū 与 gōngwù 第二个音节声调不同（第一声与第四声），意思是香港的公共住房。"}, "sentence_index": null, "correct_answer": "公务"}, "level_3": {"options": [{"text": "公务", "is_correct": true, "explanation": "公务指关于国家、集体的事务，是他出差的原因，符合句意。"}, {"text": "家务", "is_correct": false, "explanation": "语义：家务是家里的事，不是出差的原因，句子说不通。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费不是出差的原因，“因为学费出差”说不通。"}, {"text": "假期", "is_correct": false, "explanation": "搭配：“因为……出差”的原因多是工作事务，“假期”不能作出差的原因。"}], "explanations": {"公务": "公务指关于国家、集体的事务，是他出差的原因，符合句意。", "家务": "语义：家务是家里的事，不是出差的原因，句子说不通。", "学费": "语义：学费不是出差的原因，“因为学费出差”说不通。", "假期": "搭配：“因为……出差”的原因多是工作事务，“假期”不能作出差的原因。"}, "sentence_index": 0, "correct_answer": "公务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的公务是照顾孩子。", "explanation": "这里应该用〈家务〉。公务指国家、集体的事务，照顾孩子属于家务，不能说公务。"}, {"text": "这家餐厅提供免费公务。", "explanation": "这里应该用〈服务〉。公务不是面向顾客的服务，不能说“提供公务”。"}, {"text": "他的公务提高了，从科员升到了科长。", "explanation": "这里应该用〈职务〉。公务指国家、集体的事务，表示官职高低要说职务；职务可以提高，公务不能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90450, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "公务", "is_correct": true, "explanation": "公务指关于国家、集体的事务，是正确答案。"}, {"text": "公布", "is_correct": false, "explanation": "gōngbù 与 gōngwù 第二个音节声母不同（b 与 w），意思是公开发布。"}, {"text": "供物", "is_correct": false, "explanation": "gòngwù 与 gōngwù 第一个音节声调不同（第四声与第一声），意思是供奉的物品。"}, {"text": "公墓", "is_correct": false, "explanation": "gōngmù 与 gōngwù 第二个音节声母不同（m 与 w），意思是公共墓地。"}], "explanations": {"公务": "公务指关于国家、集体的事务，是正确答案。", "公布": "gōngbù 与 gōngwù 第二个音节声母不同（b 与 w），意思是公开发布。", "供物": "gòngwù 与 gōngwù 第一个音节声调不同（第四声与第一声），意思是供奉的物品。", "公墓": "gōngmù 与 gōngwù 第二个音节声母不同（m 与 w），意思是公共墓地。"}, "sentence_index": null, "correct_answer": "公务"}, "level_3": {"options": [{"text": "公务", "is_correct": true, "explanation": "公务指关于国家、集体的事务，“公务之余”指工作之外，符合句意。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“之余”要接活动或事务，“窗户”是物件，不能这样搭配。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不是可以“之余”的活动，句子说不通。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：“之余”要接活动或事务，“雨水”是自然现象，不能这样搭配。"}], "explanations": {"公务": "公务指关于国家、集体的事务，“公务之余”指工作之外，符合句意。", "窗户": "搭配：“之余”要接活动或事务，“窗户”是物件，不能这样搭配。", "汽油": "语义：汽油不是可以“之余”的活动，句子说不通。", "雨水": "搭配：“之余”要接活动或事务，“雨水”是自然现象，不能这样搭配。"}, "sentence_index": 6, "correct_answer": "公务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我爸爸的公务是卖菜。", "explanation": "这里应该用〈职业〉。公务指国家、集体的事务，卖菜是个人营生，不指公务。"}, {"text": "他每天擦公务，把桌子擦得很干净。", "explanation": "这个词不这么用。擦的对象是桌子、窗子之类的具体东西，公务是事务，不能擦。"}, {"text": "政府昨天发布了公务，请大家注意安全。", "explanation": "这里应该用〈公告〉。公务指国家、集体的事务，不能被发布；发给大家看的通知要说公告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天有三条公务要处理。", "corrected_sentence": "他今天有三件公务要处理。", "error_description": "错误：“三条公务”；正确：“三件公务”。公务是事务，计量应用“件”，“条”用于细长的东西或消息等，不用于公务。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下午要去办一只公务。", "corrected_sentence": "他下午要去办一件公务。", "error_description": "错误：“一只公务”；正确：“一件公务”。公务是事务，计量应用“件”，“只”用于单个的动物等，不用于公务。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
