INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90451, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很重要的事。", "primary_collocate": null, "pronunciation": "dà shì", "ipa": "ta˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "结婚是人生的大事。", "target_word": "大事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "上大学是他家的大事。", "target_word": "大事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是一件大事，别忘了。", "target_word": "大事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全家的大事都由我来决定。", "target_word": "大事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子上学是家里的大事。", "target_word": "大事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年回家是我们家的大事。", "target_word": "大事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的家庭会议要谈一件大事。", "target_word": "大事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有大事的时候，大家都会来帮忙。", "target_word": "大事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很会办家里的大事，不爱管小事。", "target_word": "大事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买房子是一家人的大事，要想清楚。", "target_word": "大事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件大事", "label": "量词搭配"}, {"form": "大事儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "个人或家庭生活中很重要的事：结婚、上学是大事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2a424d-fb6a-4c27-a32b-e3eed49ee37f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90451, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "零食", "is_correct": false, "explanation": "语义：零食是吃的东西，与“人生中的大事”的意思不符。"}, {"text": "大事", "is_correct": true, "explanation": "正确：“大事”指个人或家庭生活中很重要的事，与“人生”搭配。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：厕所指地点，句中不指地点，“人生的厕所”说不通。"}, {"text": "袜子", "is_correct": false, "explanation": "搭配：“是……的”后接的应是重要的事情，不能接具体的衣物，“人生的袜子”说不通。"}], "explanations": {"零食": "语义：零食是吃的东西，与“人生中的大事”的意思不符。", "大事": "正确：“大事”指个人或家庭生活中很重要的事，与“人生”搭配。", "厕所": "语义：厕所指地点，句中不指地点，“人生的厕所”说不通。", "袜子": "搭配：“是……的”后接的应是重要的事情，不能接具体的衣物，“人生的袜子”说不通。"}, "sentence_index": 0, "correct_answer": "大事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天我们吃了一顿大事。", "explanation": "这里应该用〈大餐〉。大事指很重要的事，不用于指一顿饭。"}, {"text": "他得了大事，要住院。", "explanation": "这里应该用〈大病〉。大事指很重要的事，不用于说疾病。"}, {"text": "他在纸上写了一张大事。", "explanation": "这里应该用〈大字〉。大事指很重要的事，不能用来指字的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90451, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩笑", "is_correct": false, "explanation": "搭配：“谈”的对象是问题或事情，不说“谈玩笑”，这句说不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾指废弃物，不能作为家庭会议要讨论的内容。"}, {"text": "大事", "is_correct": true, "explanation": "正确：“谈一件大事”指家庭会议要讨论的重要事情，符合句意。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋是食物，不能作为会议上要谈的内容，“要谈一件鸡蛋”说不通。"}], "explanations": {"玩笑": "搭配：“谈”的对象是问题或事情，不说“谈玩笑”，这句说不通。", "垃圾": "语义：垃圾指废弃物，不能作为家庭会议要讨论的内容。", "大事": "正确：“谈一件大事”指家庭会议要讨论的重要事情，符合句意。", "鸡蛋": "语义：鸡蛋是食物，不能作为会议上要谈的内容，“要谈一件鸡蛋”说不通。"}, "sentence_index": 6, "correct_answer": "大事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨天刮了大事。", "explanation": "这里应该用〈大风〉。大事指值得重视的事件，不用于说天气。"}, {"text": "我们今天开了一个大事。", "explanation": "这里应该用〈大会〉。大事指很重要的事，不能用来指会议。"}, {"text": "他是个大事。", "explanation": "这里应该用〈大人〉。大事指很重要的事，不能用来指成年人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90451, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是我们家的一只大事。", "corrected_sentence": "这是我们家的一件大事。", "error_description": "错误：“大事”的量词应用“件”，“只”用于动物或小的物品，不能修饰“大事”。应为“一件大事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90451, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "搬新家是一家人大事。", "corrected_sentence": "搬新家是一家人的大事。", "error_description": "错误：修饰语“一家人”后面要加“的”，应写作“一家人的大事”，不能直接接“大事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
