INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90452, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "重大的事情。", "primary_collocate": null, "pronunciation": "dà shì", "ipa": "ta˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这次选举是全市的大事，大家都很关心。", "target_word": "大事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天新闻里有一件大事。", "target_word": "大事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种大事要大家一起商量。", "target_word": "大事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里出了大事，警察马上来了。", "target_word": "大事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当了市长，要管全市的大事。", "target_word": "大事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史上的大事，我们都要记住。", "target_word": "大事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市最近发生了一件大事。", "target_word": "大事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上写了今年的十件大事。", "target_word": "大事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市运动会是城里的一件大事。", "target_word": "大事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上发生大事时，人们都会看新闻。", "target_word": "大事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件大事", "label": "量词搭配"}, {"form": "大事儿", "label": "儿化"}], "register": "中性", "sense_fingerprint": "国家、社会、历史上影响很大的重大事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2a424d-fb6a-4c27-a32b-e3eed49ee37f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90452, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "袜子", "is_correct": false, "explanation": "语义：袜子是衣物，不能指选举这类社会层面的事件，“全市的袜子”说不通。"}, {"text": "大事", "is_correct": true, "explanation": "正确：“大事”指国家或地方社会层面的重大事件，选举符合此义。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：厕所指地点，不能指选举，“全市的厕所”说不通。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“全市的……”后接的应是事件，饮料不能作为选举类的事件。"}], "explanations": {"袜子": "语义：袜子是衣物，不能指选举这类社会层面的事件，“全市的袜子”说不通。", "大事": "正确：“大事”指国家或地方社会层面的重大事件，选举符合此义。", "厕所": "语义：厕所指地点，不能指选举，“全市的厕所”说不通。", "饮料": "搭配：“全市的……”后接的应是事件，饮料不能作为选举类的事件。"}, "sentence_index": 0, "correct_answer": "大事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班请客吃了一顿大事。", "explanation": "这里应该用〈大餐〉。大事指重大的事情，不用于指一顿饭。"}, {"text": "他得了大事，要住院。", "explanation": "这里应该用〈大病〉。大事指重大事件，不用于说个人患病。"}, {"text": "他是个大事。", "explanation": "这里应该用〈大人〉。大事指重大的事情，不能用来指成年人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾指废弃物，不能指“发生”的事件，“发生了一件垃圾”说不通。"}, {"text": "大事", "is_correct": true, "explanation": "正确：“发生了一件大事”指城市里出现了重要的事件，符合句意。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋是食物，不能指“发生”的事件，“发生了一件鸡蛋”说不通。"}, {"text": "夜宵", "is_correct": false, "explanation": "搭配：“发生”后接的应是事件，夜宵不能用“发生”来说，这句说不通。"}], "explanations": {"垃圾": "语义：垃圾指废弃物，不能指“发生”的事件，“发生了一件垃圾”说不通。", "大事": "正确：“发生了一件大事”指城市里出现了重要的事件，符合句意。", "鸡蛋": "语义：鸡蛋是食物，不能指“发生”的事件，“发生了一件鸡蛋”说不通。", "夜宵": "搭配：“发生”后接的应是事件，夜宵不能用“发生”来说，这句说不通。"}, "sentence_index": 6, "correct_answer": "大事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天刮了大事。", "explanation": "这里应该用〈大风〉。大事指值得重视的事件，不用于说天气。"}, {"text": "我们今天开了一个大事。", "explanation": "这里应该用〈大会〉。大事指重大的事情，不能用来指会议。"}, {"text": "他在纸上写了一张大事。", "explanation": "这里应该用〈大字〉。大事指重大的事情，不能用来指字的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次地震是全国的一只大事。", "corrected_sentence": "这次地震是全国的一件大事。", "error_description": "错误：“大事”的量词应用“件”，“只”不能修饰“大事”。应为“一件大事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次投票是一条大事，大家都要参加。", "corrected_sentence": "这次投票是一件大事，大家都要参加。", "error_description": "错误：“大事”的量词应用“件”，“条”用于细长的东西，不能修饰“大事”。应为“一件大事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
