INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90453, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90453, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，引出任意的条件，表示在任何条件下结果都不变，常与“都、也”呼应。", "primary_collocate": null, "pronunciation": "bú lùn", "ipa": "pu˧˥ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "不论天气怎么样，他每天都跑步。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论谁来，我都欢迎。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论你说什么，我都不会生气。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论走到哪里，她都带着那本书。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论多晚，妈妈都会等我回家。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论做什么事，他都很认真。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论别人怎么看，我都相信你。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论去哪儿，我们都坐地铁。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论什么时候来，这里都有人。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论你喜不喜欢，今天都得吃药。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不管怎样结果都一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb45aab-75ed-4f65-a859-450e1280774f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90453, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不论", "is_correct": true, "explanation": "「不论」表示条件不同结果不变，与后面的「都」呼应，符合“不管天气怎么样他都跑步”的意思。"}, {"text": "因为", "is_correct": false, "explanation": "语义：「因为」表示原因，“天气怎么样”不能作为“他每天都跑步”的原因。"}, {"text": "所以", "is_correct": false, "explanation": "语义：「所以」表示结果，前面需要有原因，这里没有可以引出结果的分句。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：「而且」连接并列的陈述，“天气怎么样”不构成可以与“他每天都跑步”并列的陈述句。"}], "explanations": {"不论": "「不论」表示条件不同结果不变，与后面的「都」呼应，符合“不管天气怎么样他都跑步”的意思。", "因为": "语义：「因为」表示原因，“天气怎么样”不能作为“他每天都跑步”的原因。", "所以": "语义：「所以」表示结果，前面需要有原因，这里没有可以引出结果的分句。", "而且": "搭配：「而且」连接并列的陈述，“天气怎么样”不构成可以与“他每天都跑步”并列的陈述句。"}, "sentence_index": 0, "correct_answer": "不论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "不论昨天下大雨，我们都在图书馆学习。", "explanation": "用法错误：「不论」引出的条件应是尚未确定、可能有多种情况的，“昨天下大雨”是已经发生的事实，这里应改用「因为」。"}, {"text": "不论他成绩好，而且人也好。", "explanation": "用法错误：这里应用〈不但〉。「不论」表示条件不同、结果不变，要与「都」「也」呼应；表示递进的「不但……而且……」才用于并列的优点。"}, {"text": "不论他已经回家了，我们还在等他。", "explanation": "用法错误：「不论」后面接的是已经确定的事实，“他已经回家了”不是可以不论的条件，这里应改用「既然」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90453, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不论", "is_correct": true, "explanation": "「不论」表示条件不同结果不变，与后面的「都」呼应，符合“别人怎么看，我都相信你”的意思。"}, {"text": "然后", "is_correct": false, "explanation": "语义：「然后」表示时间先后，“别人怎么看”与“我都相信你”之间没有先后顺序，句子意思不通。"}, {"text": "因此", "is_correct": false, "explanation": "语义：「因此」表示结果，前面需要有原因，“别人怎么看”不能引出“我都相信你”这个结果。"}, {"text": "只有", "is_correct": false, "explanation": "搭配：「只有」要与「才」呼应，句中用的是「都」，搭配不成立。"}], "explanations": {"不论": "「不论」表示条件不同结果不变，与后面的「都」呼应，符合“别人怎么看，我都相信你”的意思。", "然后": "语义：「然后」表示时间先后，“别人怎么看”与“我都相信你”之间没有先后顺序，句子意思不通。", "因此": "语义：「因此」表示结果，前面需要有原因，“别人怎么看”不能引出“我都相信你”这个结果。", "只有": "搭配：「只有」要与「才」呼应，句中用的是「都」，搭配不成立。"}, "sentence_index": 6, "correct_answer": "不论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "不论学习，大家都要认真。", "explanation": "用法错误：这里应用〈对于〉。「不论」引出的是有选择的条件，要与「都」呼应；只提出话题时用〈对于〉，如「对于学习，大家都要认真」。"}, {"text": "不论老师，我们都很尊敬他。", "explanation": "用法错误：这里应用〈凡是〉。「不论」要接有选择的条件（如「是……还是……」），单独一个名词不能作条件；表示“所有的”要用〈凡是〉，如「凡是老师，我们都很尊敬他」。"}, {"text": "不论因为天冷，我们也要去跑步。", "explanation": "用法错误：「不论」引出的是条件，不能接表示原因的“因为天冷”；这里应用〈即使〉，如「即使天冷，我们也要去跑步」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "不论明天下雨和下雪，我都要去跑步。", "corrected_sentence": "不论明天下雨还是下雪，我都要去跑步。", "error_description": "连接词错误：「不论」引出的选择关系要用「还是」，「和」只能连接并列的成分，不能表示选择，应写作“不论明天下雨还是下雪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90453, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不论下不下雨，我们才要出门。", "corrected_sentence": "不论下不下雨，我们都要出门。", "error_description": "关联词错误：「不论」应与「都」呼应，「才」不能与「不论」搭配，应写作“不论下不下雨，我们都要出门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
