INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90454, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示条件不同而结果不变，相当于“无论”。", "primary_collocate": null, "pronunciation": "bú lùn", "ipa": "pu˧˥ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "不论春天还是秋天，这里都很美。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论大人还是小孩，都喜欢这个游戏。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论路有多远，我们都要走过去。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论是冷是热，他都穿同一件衣服。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论贵不贵，我都想买这本书。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论工作多忙，她都会陪孩子吃饭。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论成绩好不好，爸爸都会鼓励我。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论下雨还是下雪，学校都不放假。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论男生女生，都可以参加比赛。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不论你多聪明，也要努力学习。", "target_word": "不论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "条件不同结果不变，同无论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb45aab-75ed-4f65-a859-450e1280774f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90454, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不论", "is_correct": true, "explanation": "「不论」表示条件不同结果不变，相当于「无论」，与“春天还是秋天”的选择关系和“这里都很美”的结果相符。"}, {"text": "因为", "is_correct": false, "explanation": "语义：「因为」表示原因，“春天还是秋天”的选择关系不能作为“这里都很美”的原因。"}, {"text": "并且", "is_correct": false, "explanation": "搭配：「并且」连接并列的陈述，与表示选择的「还是」不搭配，句子不通顺。"}, {"text": "然而", "is_correct": false, "explanation": "搭配：「然而」表示转折，要求前后是对立的陈述；“春天还是秋天”是选择结构，与「然而」不搭配，句子不通顺。"}], "explanations": {"不论": "「不论」表示条件不同结果不变，相当于「无论」，与“春天还是秋天”的选择关系和“这里都很美”的结果相符。", "因为": "语义：「因为」表示原因，“春天还是秋天”的选择关系不能作为“这里都很美”的原因。", "并且": "搭配：「并且」连接并列的陈述，与表示选择的「还是」不搭配，句子不通顺。", "然而": "搭配：「然而」表示转折，要求前后是对立的陈述；“春天还是秋天”是选择结构，与「然而」不搭配，句子不通顺。"}, "sentence_index": 0, "correct_answer": "不论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "不论他会说英语，还会说法语。", "explanation": "用法错误：这里应用〈不但〉。「不论」要与「都」「也」呼应、表示结果不变；表示递进要用「不但……而且……」。"}, {"text": "不论天气不好，我们还是去爬山了。", "explanation": "用法错误：这里应用〈尽管〉或〈即使〉。「不论」要接有选择或不确定的条件，“天气不好”是具体情况，表示让步应用〈尽管〉或〈即使〉。"}, {"text": "不论昨天下大雨，他都穿了雨衣。", "explanation": "用法错误：「不论」引出的条件应是不确定、有多种可能的情况，“昨天下大雨”是已经发生的事实，这里应改用「因为」，并删去「都」：“因为昨天下大雨，他穿了雨衣。”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90454, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不论", "is_correct": true, "explanation": "「不论」表示条件不同结果不变，与后面的「都」呼应，符合“不管成绩好不好，爸爸都会鼓励我”的意思。"}, {"text": "所以", "is_correct": false, "explanation": "语义：「所以」表示结果，前面需要有原因，“成绩好不好”不能引出“爸爸都会鼓励我”这个结果。"}, {"text": "因此", "is_correct": false, "explanation": "语义：「因此」表示结果，前面需要有原因，这里“成绩好不好”不能作为鼓励的原因。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：「而且」连接并列的陈述，“成绩好不好”是一个条件，不能与“爸爸都会鼓励我”并列。"}], "explanations": {"不论": "「不论」表示条件不同结果不变，与后面的「都」呼应，符合“不管成绩好不好，爸爸都会鼓励我”的意思。", "所以": "语义：「所以」表示结果，前面需要有原因，“成绩好不好”不能引出“爸爸都会鼓励我”这个结果。", "因此": "语义：「因此」表示结果，前面需要有原因，这里“成绩好不好”不能作为鼓励的原因。", "而且": "搭配：「而且」连接并列的陈述，“成绩好不好”是一个条件，不能与“爸爸都会鼓励我”并列。"}, "sentence_index": 6, "correct_answer": "不论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "不论学习，大家都要认真。", "explanation": "用法错误：这里应用〈对于〉。「不论」引出的是有选择的条件，要与「都」呼应；只提出话题时用〈对于〉，如「对于学习，大家都要认真」。"}, {"text": "不论老师，我们都很尊敬他。", "explanation": "用法错误：这里应用〈凡是〉。「不论」要接有选择的条件，单独一个名词不能作条件；表示“所有的”要用〈凡是〉，如「凡是老师，我们都很尊敬他」。"}, {"text": "不论你努力，你能进步。", "explanation": "用法错误：这里应用〈只要〉。「只要」表示有了条件就有结果，「不论」表示条件不同、结果不变；“你努力”只是充分条件，应用〈只要〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "不论是晴天，我们都去野餐。", "corrected_sentence": "不论是晴天还是雨天，我们都去野餐。", "error_description": "「不论是」后面要用「还是」列出另一种情况，这里漏掉了“还是雨天”，应补全为“不论是晴天还是雨天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不论天气好坏，因此我们都要按时到校。", "corrected_sentence": "不论天气好坏，我们都要按时到校。", "error_description": "「因此」表示结果，与「不论」（条件不同、结果不变）的意思相冲突，应删去，写作“不论天气好坏，我们都要按时到校”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdca5037-6732-456b-b7cf-2827bd5c9391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
