INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90455, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在国王身边帮他做事的大官。", "primary_collocate": null, "pronunciation": "dà chén", "ipa": "ta˥˩ ʈʂʰən˧˥", "syllable_count": 2, "sentences": [{"text": "国王身边有一位聪明的大臣。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大臣每天都陪着国王看书。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王很相信他的大臣。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大臣帮国王想了一个办法。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大臣对国王说：“请您放心。”", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王生病了，大臣们很着急。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老国王把大事交给了大臣。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大臣每天早上先去见国王。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位大臣给国王讲了一个故事。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王问大臣：“今天有什么事？”", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "大臣们", "label": "复数"}], "register": "书面", "sense_fingerprint": "国王身边帮他做事的大官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b382258-1d1c-4078-8cdf-3ee7f594def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90455, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大臣", "is_correct": true, "explanation": "正确：大臣是在国王身边帮他做事的大官，与句中“国王身边”的语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有智慧，不能说“聪明的石头”，且“一位”只用于人。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“聪明的”用来形容人，不能说“聪明的厨房”，而且“一位”也只用于人。"}, {"text": "狗", "is_correct": false, "explanation": "搭配：量词“一位”只用于人，动物应说“一只”，不能说“一位狗”。"}], "explanations": {"大臣": "正确：大臣是在国王身边帮他做事的大官，与句中“国王身边”的语境相符。", "石头": "语义：石头没有智慧，不能说“聪明的石头”，且“一位”只用于人。", "厨房": "搭配：“聪明的”用来形容人，不能说“聪明的厨房”，而且“一位”也只用于人。", "狗": "搭配：量词“一位”只用于人，动物应说“一只”，不能说“一位狗”。"}, "sentence_index": 0, "correct_answer": "大臣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位大臣每天在医院里给病人看病。", "explanation": "这里应该用〈大夫〉。大臣是在国王身边帮他做事的大官，不是给病人看病的人，看病要用“大夫”。"}, {"text": "我家来了一只大臣。", "explanation": "这里应该用〈位〉。大臣指人，量词要用“位”，不能用“只”（“只”多用于动物或物品）。"}, {"text": "这位大臣每天替我家打理家里的大小事务。", "explanation": "这里应该用〈管家〉。大臣在国王身边辅佐国王治理国家，不替普通人家打理家务；打理家务的人要用“管家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90455, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大臣", "is_correct": true, "explanation": "正确：把大事交给他的人应是能承担事务的大臣，与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能接受交付的大事，与“把大事交给”的语境矛盾。"}, {"text": "宫殿", "is_correct": false, "explanation": "配价：“交给”的接受者要能承担事务，宫殿是建筑，不能作为交付对象。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：国王不会把大事交给小偷，与“老国王”的信任语境矛盾。"}], "explanations": {"大臣": "正确：把大事交给他的人应是能承担事务的大臣，与句意相符。", "石头": "语义：石头不能接受交付的大事，与“把大事交给”的语境矛盾。", "宫殿": "配价：“交给”的接受者要能承担事务，宫殿是建筑，不能作为交付对象。", "小偷": "语义：国王不会把大事交给小偷，与“老国王”的信任语境矛盾。"}, "sentence_index": 6, "correct_answer": "大臣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位大臣每天在县里处理百姓的纠纷。", "explanation": "这里应该用〈县令〉。大臣是在国王身边辅佐国王的高级官员，不在地方上处理百姓的纠纷；地方上处理百姓纠纷的长官要用“县令”。"}, {"text": "这位大臣每天在店里招呼客人。", "explanation": "这里应该用〈掌柜〉。大臣是在国王身边辅佐国王的高级官员，不在店里招呼客人；经营店铺、招呼客人的人要用“掌柜”。"}, {"text": "这位大臣每天在城门口站岗。", "explanation": "这里应该用〈卫兵〉。大臣是在国王身边辅佐国王的高级官员，不负责在城门口站岗；守卫城门的人要用“卫兵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90455, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宫里有一只老大臣。", "corrected_sentence": "宫里有一位老大臣。", "error_description": "“大臣”指人，量词应用“位”，不能用“只”（“只”多用于动物或物品）。应改为：宫里有一位老大臣。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90455, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宫里有一个大臣们。", "corrected_sentence": "宫里有一个大臣。", "error_description": "“一个”是数量短语，“大臣”前已有数量修饰，后面不能再加复数词尾“们”，应说“一个大臣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
