INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90456, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "君主国家中的高级官员。", "primary_collocate": null, "pronunciation": "dà chén", "ipa": "ta˥˩ ʈʂʰən˧˥", "syllable_count": 2, "sentences": [{"text": "古代皇帝的大臣要管理国家。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大臣是国家的高级官员。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大臣在会上说了国家的新办法。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想当国家的大臣。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英国有一位管钱的大臣。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新大臣今天开始工作。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位大臣为国家做了很多事。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大臣们开会讨论国家的大事。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王换了几位大臣。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大臣明天要去别的国家开会。", "target_word": "大臣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "大臣们", "label": "复数"}], "register": "书面", "sense_fingerprint": "君主国家的高级官员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b382258-1d1c-4078-8cdf-3ee7f594def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90456, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大臣", "is_correct": true, "explanation": "正确：大臣是君主国家的高级官员，负责管理国家，与句意相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师负责做饭，不管理国家，与“要管理国家”矛盾。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“管理国家”的主体应是人，不能说“房子管理国家”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有管理能力，与“要管理国家”矛盾。"}], "explanations": {"大臣": "正确：大臣是君主国家的高级官员，负责管理国家，与句意相符。", "厨师": "语义：厨师负责做饭，不管理国家，与“要管理国家”矛盾。", "房子": "搭配：“管理国家”的主体应是人，不能说“房子管理国家”。", "石头": "语义：石头没有管理能力，与“要管理国家”矛盾。"}, "sentence_index": 0, "correct_answer": "大臣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位大臣每天在船上掌舵。", "explanation": "这里应该用〈船长〉。大臣是君主国家的高级官员，不在船上掌舵；掌舵驾船的人要用“船长”。"}, {"text": "宫里来了一只大臣，很有学问。", "explanation": "这里应该用〈位〉。大臣指人，量词要用“位”，不能用“只”（“只”多用于动物或物品）。"}, {"text": "这位大臣每天在街上叫卖包子。", "explanation": "这里应该用〈小贩〉。大臣是君主国家的高级官员，不会在街上叫卖；沿街卖东西的人要用“小贩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90456, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大臣", "is_correct": true, "explanation": "正确：大臣是为国家做事的高级官员，与“为国家做了很多事”相符。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷做的事与“为国家做了很多事”相反，句意矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能为国家做事，与句意矛盾。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：乞丐没有能力为国家做事，与句意矛盾。"}], "explanations": {"大臣": "正确：大臣是为国家做事的高级官员，与“为国家做了很多事”相符。", "小偷": "语义：小偷做的事与“为国家做了很多事”相反，句意矛盾。", "石头": "语义：石头不能为国家做事，与句意矛盾。", "乞丐": "语义：乞丐没有能力为国家做事，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "大臣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位大臣明天要去别的城市抓坏人。", "explanation": "这里应该用〈警察〉。大臣是君主国家的高级官员，不去别的城市抓坏人；抓捕坏人的人要用“警察”。"}, {"text": "这位大臣每天开车送客人。", "explanation": "这里应该用〈司机〉。大臣是高级官员，不负责开车送人，开车的人要用“司机”。"}, {"text": "这位大臣去别的国家做生意。", "explanation": "这里应该用〈商人〉。大臣的职责是治理国家，不做生意，做生意的人要用“商人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90456, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "皇帝身边有一位忠诚地大臣。", "corrected_sentence": "皇帝身边有一位忠诚的大臣。", "error_description": "“忠诚”修饰“大臣”，应用“的”，说“忠诚的大臣”；这里误用“地”，“地”用于修饰动词、形容词，不能接在名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90456, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宫里来了两大臣。", "corrected_sentence": "宫里来了两位大臣。", "error_description": "数词“两”后面要有量词，应说“两位大臣”，不能说“两大臣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
