INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90458, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "正确，精确；符合标准。", "primary_collocate": null, "pronunciation": "zhǔn", "ipa": "ʈʂuən˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个钟很准，从来不快也不慢。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的发音很准，像中国人一样。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张地图画得不准，我们走错路了。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的手表不准，快了五分钟。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用这个尺子量，才能量得准。", "target_word": "准", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的汉语声调很准，老师常常表扬他。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导航不准，把我们带到了别的地方。", "target_word": "准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的电子秤很准，买东西不会吃亏。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "翻译要准，不能随便改原来的意思。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他口算又快又准，同学们都很佩服。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "準", "label": "繁体"}, {"form": "准确", "label": "复合"}], "register": "中性", "sense_fingerprint": "仪器、发音、翻译等精确，符合标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '388a63b1-0373-4e8f-9a4b-1f114645e9ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90458, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "准", "is_correct": true, "explanation": "正确：“准”表示精确、符合标准，与“这个钟很……，从来不快也不慢”的语境相符。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”与后半句“从来不快也不慢”的说法自相矛盾。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”形容光线，不能用来形容钟表的精确程度。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用来形容钟表的精确程度。"}], "explanations": {"准": "正确：“准”表示精确、符合标准，与“这个钟很……，从来不快也不慢”的语境相符。", "快": "语义：“快”与后半句“从来不快也不慢”的说法自相矛盾。", "亮": "搭配：“亮”形容光线，不能用来形容钟表的精确程度。", "甜": "搭配：“甜”形容味道，不能用来形容钟表的精确程度。"}, "sentence_index": 0, "correct_answer": "准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的书包很准。", "explanation": "这里应该用〈整齐〉。“准”只用于测量、发音、猜测等说得对或精确的情况，书包不能用“准”来形容。"}, {"text": "这台秤的按钮很准。", "explanation": "这里应该用〈灵敏〉。“准”形容精确或正确，按钮不能用“准”来形容。"}, {"text": "他的爱好很准，什么都喜欢。", "explanation": "这里应该用〈广泛〉。“准”形容精确或正确，爱好不能用“准”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "准", "is_correct": true, "explanation": "正确：“准”表示精确、可靠，与“导航不准，把我们带到了别的地方”的语境相符。"}, {"text": "热", "is_correct": false, "explanation": "搭配：“热”形容温度，不能用来形容导航的精确程度。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”形容质地，不能用来形容导航的精确程度。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，与导航能否准确指路无关。"}], "explanations": {"准": "正确：“准”表示精确、可靠，与“导航不准，把我们带到了别的地方”的语境相符。", "热": "搭配：“热”形容温度，不能用来形容导航的精确程度。", "软": "搭配：“软”形容质地，不能用来形容导航的精确程度。", "咸": "语义：“咸”指味道，与导航能否准确指路无关。"}, "sentence_index": 6, "correct_answer": "准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的汗水很准。", "explanation": "这里应该用〈多〉。“准”形容精确或正确，汗水的多少不能用“准”来形容。"}, {"text": "这个月的工资很准。", "explanation": "这里应该用〈高〉。“准”形容精确或正确，工资的多少不能用“准”来形容。"}, {"text": "这次口算题很准，大家都做得很累。", "explanation": "这里应该用〈难〉。“准”形容精确或正确，题目的难易不能用“准”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把尺子量得很准得。", "corrected_sentence": "这把尺子量得很准。", "error_description": "错误：补语“得”重复出现，“很准”后不能再加“得”。正确：说“量得很准”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个天平称地很准。", "corrected_sentence": "这个天平称得很准。", "error_description": "错误：补语前的“地”误用，应为表示程度补语的“得”。正确：说“称得很准”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
