INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90461, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "结了婚的一个男人和一个女人。", "primary_collocate": null, "pronunciation": "fū qī", "ipa": "fu˥ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "这对夫妻住在我家楼上。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那对老夫妻每天早上一起去公园走路。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是一对很幸福的夫妻。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生和王太太是夫妻，他们有两个孩子。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店是一对夫妻开的。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻两个人都在医院工作。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对夫妻刚结婚一年，还没有孩子。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我父母做了三十年夫妻，感情一直很好。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻俩今天晚上要去看电影。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居家的夫妻常常带着孩子去海边玩。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对夫妻", "label": "量词搭配"}, {"form": "夫妻俩", "label": "复合词"}, {"form": "老夫妻", "label": "复合词"}, {"form": "小夫妻", "label": "复合词"}], "register": "中性", "sense_fingerprint": "结了婚的一男一女，指一对已婚的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b74abb-82e7-47f8-a7df-97bad8dedd21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90461, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公司", "is_correct": false, "explanation": "语义：“公司”不指成对的人，不能说“住在我家楼上”。"}, {"text": "夫妻", "is_correct": true, "explanation": "夫妻：一对已婚的男女，可以用“这对”计数，也能住在楼上。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“房间”要用“个”计数，不能说“这对房间”。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”不能居住，不能说“住在我家楼上”。"}], "explanations": {"公司": "语义：“公司”不指成对的人，不能说“住在我家楼上”。", "夫妻": "夫妻：一对已婚的男女，可以用“这对”计数，也能住在楼上。", "房间": "搭配：“房间”要用“个”计数，不能说“这对房间”。", "汽车": "语义：“汽车”不能居住，不能说“住在我家楼上”。"}, "sentence_index": 0, "correct_answer": "夫妻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们还没结婚，只是一对夫妻，还在谈恋爱。", "explanation": "这里应该用〈情侣〉。夫妻指已经结婚的一男一女，还没结婚、只是谈恋爱的要用“情侣”。"}, {"text": "这只夫妻很恩爱，每天一起去散步。", "explanation": "这里应该用〈对〉。夫妻指一对人，量词要用“对”，不能用“只”。"}, {"text": "我的夫妻今天生病了，没来上班。", "explanation": "夫妻指一对已婚的人，不能只指其中一个；说“我的丈夫”或“我的妻子”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90461, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”不能结婚，与“刚结婚一年”矛盾。"}, {"text": "夫妻", "is_correct": true, "explanation": "夫妻：已经结婚的一对配偶，与“刚结婚一年”相符。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”不会结婚，与“刚结婚一年”矛盾。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“房子”不能用“这对”计数，也不能结婚。"}], "explanations": {"汽车": "语义：“汽车”不能结婚，与“刚结婚一年”矛盾。", "夫妻": "夫妻：已经结婚的一对配偶，与“刚结婚一年”相符。", "学生": "语义：“学生”不会结婚，与“刚结婚一年”矛盾。", "房子": "搭配：“房子”不能用“这对”计数，也不能结婚。"}, "sentence_index": 6, "correct_answer": "夫妻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们三年前就离婚了，现在还是夫妻，每天一起吃早饭。", "explanation": "这里应该用〈前夫〉或〈前妻〉。夫妻指现在有婚姻关系的一对人，离婚后就不再是夫妻了。"}, {"text": "这两个人是夫妻，其实是亲兄弟。", "explanation": "夫妻只指配偶关系，同胞兄弟之间不能用“夫妻”来称呼。"}, {"text": "我和同事是夫妻，每天一起加班。", "explanation": "夫妻只指配偶关系，工作关系不能说“夫妻”，应说“搭档”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90461, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们是一个夫妻，感情很好。", "corrected_sentence": "他们是一对夫妻，感情很好。", "error_description": "量词错误：“夫妻”指一对人，应说“一对夫妻”，不能说“一个夫妻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90461, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老张夫妻俩个每天都早起锻炼。", "corrected_sentence": "老张夫妻俩每天都早起锻炼。", "error_description": "重复计数：“俩”已含“两个”，后面不能再加“个”，应说“夫妻俩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90462, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90462, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90462, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "结为配偶的男女；丈夫和妻子。", "primary_collocate": null, "pronunciation": "fū qī", "ipa": "fu˥ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "夫妻之间应该互相帮助。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们做了十年夫妻，从来没有吵过架。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻之间要多说话，多听对方的想法。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻二人一起把房子打扫干净了。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对夫妻的感情非常好。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生请夫妻两个人一起来谈谈。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们结婚后，就成了夫妻。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻吵架以后，很快就会和好。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对夫妻每个周末都去看爷爷奶奶。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻夫妻买房子，需要很多钱。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对夫妻", "label": "量词搭配"}, {"form": "夫妻俩", "label": "复合词"}, {"form": "夫妻关系", "label": "复合词"}, {"form": "小夫妻", "label": "复合词"}], "register": "中性", "sense_fingerprint": "丈夫和妻子之间的配偶关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b74abb-82e7-47f8-a7df-97bad8dedd21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”没有行为能力，不能“互相帮助”。"}, {"text": "夫妻", "is_correct": true, "explanation": "夫妻：配偶关系中的双方，“夫妻之间”与“互相帮助”语境相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”不能“互相帮助”，与“应该”的主体不符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“互相帮助”要求有行动能力的主体，“石头”不能搭配。"}], "explanations": {"桌子": "语义：“桌子”没有行为能力，不能“互相帮助”。", "夫妻": "夫妻：配偶关系中的双方，“夫妻之间”与“互相帮助”语境相符。", "手机": "语义：“手机”不能“互相帮助”，与“应该”的主体不符。", "石头": "搭配：“互相帮助”要求有行动能力的主体，“石头”不能搭配。"}, "sentence_index": 0, "correct_answer": "夫妻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们还没有领证，还是夫妻，只是在谈恋爱。", "explanation": "这里应该用〈情侣〉。夫妻指已经结婚的关系，还没领证、只是谈恋爱的要用“情侣”。"}, {"text": "我和父母是夫妻，关系很亲近。", "explanation": "夫妻指配偶关系，父母与子女是亲子关系，不能说“夫妻”。"}, {"text": "我们结婚十年，是一个夫妻。", "explanation": "这里应该用〈对〉。夫妻指一对配偶，量词要用“对”，不能用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：结婚后不会变成“学生”，与语境矛盾。"}, {"text": "夫妻", "is_correct": true, "explanation": "夫妻：结婚后双方就成为配偶，与“结婚后”相符。"}, {"text": "司机", "is_correct": false, "explanation": "语义：“结婚”不会使人成为“司机”。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：人结婚后不会变成“礼物”，与语境矛盾。"}], "explanations": {"学生": "语义：结婚后不会变成“学生”，与语境矛盾。", "夫妻": "夫妻：结婚后双方就成为配偶，与“结婚后”相符。", "司机": "语义：“结婚”不会使人成为“司机”。", "礼物": "语义：人结婚后不会变成“礼物”，与语境矛盾。"}, "sentence_index": 6, "correct_answer": "夫妻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天生病了，他的夫妻也没来上班。", "explanation": "夫妻指一对配偶，不能只指其中一个人；这里应该说“他的妻子”或“他的丈夫”。"}, {"text": "他们离婚三年了，现在还是夫妻。", "explanation": "这里应该用〈前夫〉或〈前妻〉。夫妻指现在有婚姻关系的一对人，离婚后就不再是夫妻了。"}, {"text": "我和同学是夫妻，每天一起上课。", "explanation": "夫妻只指配偶关系，同学之间不能说“夫妻”，应说“朋友”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们做的夫妻已经十年了。", "corrected_sentence": "他们做夫妻已经十年了。", "error_description": "结构助词错误：“做夫妻”是动宾结构，中间不能加“的”，应说“他们做夫妻已经十年了”；加“的”会把“做夫妻”变成修饰语，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "结婚以后，他们很快就成了一个夫妻。", "corrected_sentence": "结婚以后，他们很快就成了一对夫妻。", "error_description": "量词错误：“夫妻”指一对人，应说“一对夫妻”，不能说“一个夫妻”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
