INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90463, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90463, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "单独是只有一个人，不跟别人在一起。", "primary_collocate": null, "pronunciation": "dān dú", "ipa": "tan˥ tu˧˥", "syllable_count": 2, "sentences": [{"text": "孩子还小，不能单独留在家里。", "target_word": "单独", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她第一次单独坐飞机去北京。", "target_word": "单独", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢单独待在房间里看书。", "target_word": "单独", "complexity_tier": "T3", "furigana": "tā xǐ huan dān dú dāi zài fáng jiān lǐ kàn shū", "sentence_source": "generated"}, {"text": "老人单独住在山里，很少见到别人。", "target_word": "单独", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想和你单独说几句话。", "target_word": "单独", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下课后，老师把小明单独留下了。", "target_word": "单独", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，你一个女孩子不要单独出门。", "target_word": "单独", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他单独在家的时候，常常不做饭。", "target_word": "单独", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不怕黑，敢单独睡一个房间。", "target_word": "单独", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末他没有朋友陪，只好单独去看电影。", "target_word": "单独", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "單獨", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人只有自己一个，身边没有别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '388a63b1-0373-4e8f-9a4b-1f114645e9ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90463, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "单独", "is_correct": true, "explanation": "正确：“单独”表示只有一个人、身边没有别人，与“孩子还小，不能……留在家里”相符。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，与“不能”所表达的禁止语义相冲突。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已完成，与“不能”所表达的禁止不相容。"}, {"text": "一定", "is_correct": false, "explanation": "语义：“一定”表示必然，与“不能”的禁止语义正好相反。"}], "explanations": {"单独": "正确：“单独”表示只有一个人、身边没有别人，与“孩子还小，不能……留在家里”相符。", "竟然": "语义：“竟然”表示出乎意料，与“不能”所表达的禁止语义相冲突。", "已经": "体貌：“已经”表示动作已完成，与“不能”所表达的禁止不相容。", "一定": "语义：“一定”表示必然，与“不能”的禁止语义正好相反。"}, "sentence_index": 0, "correct_answer": "单独"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "几位朋友单独结伴去了北京。", "explanation": "“单独”只说一个人独自行动，与此处多人同行的意思相矛盾，应去掉“单独”。"}, {"text": "全班同学单独集体参加了比赛。", "explanation": "“单独”只说一个人独自行动，与此处全班多人一起参加的意思相矛盾。"}, {"text": "我们全家人单独一起去公园玩了。", "explanation": "“单独”只说一个人独自行动，与此处全家人一起去的意思相矛盾，应去掉“单独”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90463, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "单独", "is_correct": true, "explanation": "正确：“单独”表示独自一人，与“你一个女孩子不要……出门”的劝阻语境相符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，与“不要”的禁止语义不能共现。"}, {"text": "一齐", "is_correct": false, "explanation": "语义：“一齐”表示多人同时，与主语“你一个女孩子”只有一人相矛盾。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已完成，与“不要”的禁止语义不相容。"}], "explanations": {"单独": "正确：“单独”表示独自一人，与“你一个女孩子不要……出门”的劝阻语境相符。", "正在": "体貌：“正在”表示动作进行中，与“不要”的禁止语义不能共现。", "一齐": "语义：“一齐”表示多人同时，与主语“你一个女孩子”只有一人相矛盾。", "已经": "体貌：“已经”表示动作已完成，与“不要”的禁止语义不相容。"}, "sentence_index": 6, "correct_answer": "单独"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "几个同学相约单独去看电影。", "explanation": "“单独”只说一个人独自行动，与此处几人相约同去的意思相矛盾，应去掉“单独”。"}, {"text": "两位老人同行单独去医院。", "explanation": "“单独”只说一个人独自行动，与此处两人同去的意思相矛盾，应去掉“单独”。"}, {"text": "全班三十个同学单独去登山了。", "explanation": "这里应该用〈一起〉。“单独”只指一个人，主语是三十个同学，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90463, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈不让我单独的出门。", "corrected_sentence": "妈妈不让我单独出门。", "error_description": "错误：“单独”修饰动词时后面不加“的”。正确：说“单独出门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90463, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他只好单独的在家吃饭。", "corrected_sentence": "他只好单独在家吃饭。", "error_description": "错误：“单独”修饰动词时后面不加“的”。正确：说“只好单独在家吃饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
