INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90465, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出资是拿出钱来做一件事。", "primary_collocate": null, "pronunciation": "chū zī", "ipa": "tʂʰu˥ tsɹ̩˥", "syllable_count": 2, "sentences": [{"text": "我们几个朋友出资办了一个画展。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出资拍了一部电影。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司出资让员工去学习。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民出资请人修了水井。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出资开了一家花店。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁出资，谁就有权决定。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥出资，我来负责管理。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司一起出资成立了新厂。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只出资，从不参加会议。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们出资买了一台新电脑，放在教室里。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出了资", "label": "了体"}, {"form": "出过资", "label": "过体"}], "register": "中性", "sense_fingerprint": "出资：拿出钱来办成一件事或开办事业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3040b130-1c83-4aba-a0d1-f87d0f162c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90465, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出版", "is_correct": false, "explanation": "配价：“出版”要求出版物作宾语，句中没有可以出版的对象。"}, {"text": "出售", "is_correct": false, "explanation": "配价：“出售”要求货物作宾语，“办画展”不是可以出售的东西。"}, {"text": "出院", "is_correct": false, "explanation": "语义：出院指离开医院，与朋友们办画展的语境无关。"}, {"text": "出资", "is_correct": true, "explanation": "出资指拿出钱来。朋友们出钱办画展，符合句意。"}], "explanations": {"出版": "配价：“出版”要求出版物作宾语，句中没有可以出版的对象。", "出售": "配价：“出售”要求货物作宾语，“办画展”不是可以出售的东西。", "出院": "语义：出院指离开医院，与朋友们办画展的语境无关。", "出资": "出资指拿出钱来。朋友们出钱办画展，符合句意。"}, "sentence_index": 0, "correct_answer": "出资"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我出资了三次地铁。", "explanation": "这里应该用〈乘〉。出资的宾语是钱财，乘坐地铁要说乘。"}, {"text": "他为这件事出资了很多心血。", "explanation": "这里应该用〈付出〉。出资的宾语是钱财，投入心血、精力要说付出。"}, {"text": "我们已经出资了这个问题。", "explanation": "这里应该用〈解决〉。出资的对象是钱财，解决问题要说解决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90465, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出嫁", "is_correct": false, "explanation": "语义：出嫁指女子结婚离家，不能用于哥哥，句子说不通。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生指降生，与“我来负责管理”没有关系，句子不通。"}, {"text": "出卖", "is_correct": false, "explanation": "配价：“出卖”要求被卖的对象作宾语，句中没有，且含背叛之意，与语境不符。"}, {"text": "出资", "is_correct": true, "explanation": "出资指拿出钱财。哥哥出资、我负责管理，分工合理，符合句意。"}], "explanations": {"出嫁": "语义：出嫁指女子结婚离家，不能用于哥哥，句子说不通。", "出生": "语义：出生指降生，与“我来负责管理”没有关系，句子不通。", "出卖": "配价：“出卖”要求被卖的对象作宾语，句中没有，且含背叛之意，与语境不符。", "出资": "出资指拿出钱财。哥哥出资、我负责管理，分工合理，符合句意。"}, "sentence_index": 6, "correct_answer": "出资"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家基金会出资了两位画家。", "explanation": "这里应该用〈资助〉。出资的对象是钱财或事业，支持个人要说资助。"}, {"text": "他向同事出资了一个通知。", "explanation": "这里应该用〈发〉。出资的对象是钱财，发通知要说发。"}, {"text": "他把那个孩子出资了。", "explanation": "这里应该用〈抚养〉。出资的对象是钱财或事业，抚养孩子要说抚养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90465, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们几个朋友没出了资办画展。", "corrected_sentence": "我们几个朋友没出资办画展。", "error_description": "错误在于“没出了资”中多用了“了”。“没”与“了”不能同时用在这个结构里，应改为“没出资”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90465, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥明天出了资，我来负责管理。", "corrected_sentence": "哥哥明天出资，我来负责管理。", "error_description": "错误在于“明天”指将来，不能与完成体“了”同用，应去掉“了”，改为“哥哥明天出资”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
