INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90466, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿出钱财。", "primary_collocate": null, "pronunciation": "chū zī", "ipa": "tʂʰu˥ tsɹ̩˥", "syllable_count": 2, "sentences": [{"text": "为了修路，村里的人都愿意出资。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司出资一百万建了学校。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出资帮助了很多穷孩子。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们一起出资，给老师买了礼物。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁愿意出资，就请举手。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们三个人出资开了一家小店。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府出资修了这座桥。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想出资，只想帮忙做事。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王出资买下了那块地。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校友们出资建了一座图书馆。", "target_word": "出资", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出了资", "label": "了体"}, {"form": "出过资", "label": "过体"}], "register": "中性", "sense_fingerprint": "出资：拿出钱财来帮助或支持某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3040b130-1c83-4aba-a0d1-f87d0f162c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出院", "is_correct": false, "explanation": "语义：出院指病人离开医院，与为修路集资的语境不符，句子说不通。"}, {"text": "出资", "is_correct": true, "explanation": "出资指拿出钱财。“为了修路”和“愿意”说明村民愿意拿钱支持修路，符合句意。"}, {"text": "出版", "is_correct": false, "explanation": "配价：“出版”要求出版物作宾语，句中没有可以出版的对象。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生指降生，不是主动愿意去做的事，不能说“愿意出生”。"}], "explanations": {"出院": "语义：出院指病人离开医院，与为修路集资的语境不符，句子说不通。", "出资": "出资指拿出钱财。“为了修路”和“愿意”说明村民愿意拿钱支持修路，符合句意。", "出版": "配价：“出版”要求出版物作宾语，句中没有可以出版的对象。", "出生": "语义：出生指降生，不是主动愿意去做的事，不能说“愿意出生”。"}, "sentence_index": 0, "correct_answer": "出资"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她出资了一个好主意。", "explanation": "这里应该用〈拿出〉。出资的宾语是钱财，拿出想法、主意要说拿出。"}, {"text": "他为这个项目出资了很多时间。", "explanation": "这里应该用〈付出〉。出资的对象是钱财，投入时间、精力要说付出。"}, {"text": "我昨天出资了一个电话。", "explanation": "这里应该用〈打〉。出资的宾语是钱财，打电话要说打。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出差", "is_correct": false, "explanation": "语义：出差是因公外出，政府“出差”去修桥说不通，与句意不符。"}, {"text": "出土", "is_correct": false, "explanation": "语义：出土指从地下挖掘出来，与修桥的语境毫无关系。"}, {"text": "出资", "is_correct": true, "explanation": "出资指拿出钱财。政府出资修桥符合常理，是正确答案。"}, {"text": "出租", "is_correct": false, "explanation": "配价：“出租”要求出租物作宾语，“修了这座桥”不能充当它的对象。"}], "explanations": {"出差": "语义：出差是因公外出，政府“出差”去修桥说不通，与句意不符。", "出土": "语义：出土指从地下挖掘出来，与修桥的语境毫无关系。", "出资": "出资指拿出钱财。政府出资修桥符合常理，是正确答案。", "出租": "配价：“出租”要求出租物作宾语，“修了这座桥”不能充当它的对象。"}, "sentence_index": 6, "correct_answer": "出资"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他出资了三个贫困学生。", "explanation": "这里应该用〈资助〉。出资的对象是钱财或事业，帮助人要说资助。"}, {"text": "他向我出资了一封信。", "explanation": "这里应该用〈寄〉。出资的宾语是钱财，寄信要说寄。"}, {"text": "他把那只狗出资了。", "explanation": "这里应该用〈送〉。出资的对象是钱财或事业，把动物送人要说送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他明天出了资修路。", "corrected_sentence": "他明天出资修路。", "error_description": "错误在于“出了资”用了完成体“了”，而“明天”指将来，应改为“出资”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校友们下个月出了资建一座体育馆。", "corrected_sentence": "校友们下个月出资建一座体育馆。", "error_description": "错误在于“出了资”用了完成体“了”，而“下个月”指将来，应改为“出资”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
