INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90467, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "结了婚的男人和女人。", "primary_collocate": null, "pronunciation": "fū fù", "ipa": "fu˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "这对夫妇的孩子已经上小学了。", "target_word": "夫妇", "complexity_tier": "T3", "furigana": "zhè duì fū fù de háizi yǐjīng shàng xiǎoxué le", "sentence_source": "generated"}, {"text": "邻居是一对年轻夫妇，很友好。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那对夫妇带着两个孩子去旅行。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对夫妇刚买了一套新房子。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一对夫妇在公园里散步。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对夫妇每天一起去超市买菜。", "target_word": "夫妇", "complexity_tier": "T3", "furigana": "zhè duì fū fù měitiān yìqǐ qù chāoshì mǎi cài", "sentence_source": "generated"}, {"text": "那对夫妇开了一家小饭店。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是结婚三十年的夫妇。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对夫妇都喜欢养猫。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的夫妇住在我家楼上。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对夫妇", "label": "量词（对）"}, {"form": "年轻夫妇", "label": "复合"}], "register": "中性", "sense_fingerprint": "结了婚的一男一女", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9007a2d-4d18-4039-ac90-907ce20042f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90467, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夫妇", "is_correct": true, "explanation": "正确。“这对夫妇的孩子”指一对夫妻的孩子，已经上小学，符合句意。"}, {"text": "幼儿", "is_correct": false, "explanation": "语义：幼儿还很小，不可能有已经上小学的孩子。"}, {"text": "新生儿", "is_correct": false, "explanation": "语义：新生儿刚出生，不可能有已经上小学的孩子。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫的孩子是小猫，不可能已经上小学。"}], "explanations": {"夫妇": "正确。“这对夫妇的孩子”指一对夫妻的孩子，已经上小学，符合句意。", "幼儿": "语义：幼儿还很小，不可能有已经上小学的孩子。", "新生儿": "语义：新生儿刚出生，不可能有已经上小学的孩子。", "猫": "语义：猫的孩子是小猫，不可能已经上小学。"}, "sentence_index": 0, "correct_answer": "夫妇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个夫妇刚买了一套新房子。", "explanation": "这里应该用〈对〉。夫妇是成对计算的，应说“这对夫妇”，用“个”不对。"}, {"text": "这对夫妇还没有结婚，刚买了一套新房子。", "explanation": "这里应该用〈伴侣〉。夫妇要求两人已结婚，未婚的一对只能说“伴侣”或“情侣”。"}, {"text": "这对夫妇只有一个人，刚买了一套新房子。", "explanation": "这里应该用〈丈夫〉或〈妻子〉。夫妇指两个人，只剩一人时要说“丈夫”或“妻子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90467, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夫妇", "is_correct": true, "explanation": "正确。“那对夫妇”指一对丈夫和妻子，可以一起开餐馆。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗是动物，不能开饭店。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不能开饭店。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“开”可以用于饭店，但“花”不能作为开饭店的主体，搭配不当。"}], "explanations": {"夫妇": "正确。“那对夫妇”指一对丈夫和妻子，可以一起开餐馆。", "小狗": "语义：小狗是动物，不能开饭店。", "婴儿": "语义：婴儿不能开饭店。", "花": "搭配：“开”可以用于饭店，但“花”不能作为开饭店的主体，搭配不当。"}, "sentence_index": 6, "correct_answer": "夫妇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新来的夫妇是一对双胞胎姐妹，住在我家楼上。", "explanation": "这里误用了夫妇的指称范围：它只指结了婚的丈夫和妻子，不能用于姐妹。"}, {"text": "新来的夫妇只有一位老奶奶，住在我家楼上。", "explanation": "这里误用了夫妇的指称对象：夫妇指丈夫和妻子两个人，一个人不能叫夫妇。"}, {"text": "新来的夫妇是两个同学，住在我家楼上。", "explanation": "这里误用了夫妇的指称范围：同学之间没有婚姻关系，不能叫夫妇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90467, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个夫妇昨天搬了家。", "corrected_sentence": "那对夫妇昨天搬了家。", "error_description": "量词用错。“夫妇”应该用量词“对”，不能用“个”，应说“那对夫妇”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90467, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那对的夫妇在楼下开了一家小店。", "corrected_sentence": "那对夫妇在楼下开了一家小店。", "error_description": "“那对”和“夫妇”之间多加了“的”。量词短语修饰“夫妇”时不加“的”，应去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
