INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90469, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90469, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "塔是又高又尖的大房子，一层一层往上盖。", "primary_collocate": null, "pronunciation": "tǎ", "ipa": "tʰa˨˩˦", "syllable_count": 1, "sentences": [{"text": "这座塔很高。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山上有一座白色的塔。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们爬上塔，看见了整个城市。", "target_word": "塔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座塔有七层，每一层都很大。", "target_word": "塔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上塔上的灯亮了，非常漂亮。", "target_word": "塔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友在塔前面照相。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那座塔已经有一千年的历史了。", "target_word": "塔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天都看着那座塔，想起家乡。", "target_word": "塔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塔的旁边有一个小公园。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想把这座塔画下来。", "target_word": "塔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座塔", "label": "量词"}, {"form": "铁塔", "label": "复合"}, {"form": "宝塔", "label": "复合"}], "register": "通用", "sense_fingerprint": "塔：又高又尖、一层一层盖起来的高大建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d48bf1a-fcce-4795-8810-0494f4f470de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90469, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "塔", "is_correct": true, "explanation": "正确答案。塔（第三声）指又高又尖、一层一层往上盖的建筑。"}, {"text": "他", "is_correct": false, "explanation": "他 tā（第一声）与 tǎ（第三声）声调不同，意思是“他”（人称代词）。"}, {"text": "踏", "is_correct": false, "explanation": "踏 tà（第四声）与 tǎ（第三声）声调不同，意思是“踩”。"}, {"text": "哪", "is_correct": false, "explanation": "哪 nǎ 与 tǎ 声母不同（n 与 t），意思是“哪里”。"}, {"text": "把", "is_correct": false, "explanation": "把 bǎ 与 tǎ 声母不同（b 与 t），意思是“把手”或“把握”。"}, {"text": "躺", "is_correct": false, "explanation": "躺 tǎng 与 tǎ 韵母不同（多了 ng），意思是“躺下”。"}], "explanations": {"塔": "正确答案。塔（第三声）指又高又尖、一层一层往上盖的建筑。", "他": "他 tā（第一声）与 tǎ（第三声）声调不同，意思是“他”（人称代词）。", "踏": "踏 tà（第四声）与 tǎ（第三声）声调不同，意思是“踩”。", "哪": "哪 nǎ 与 tǎ 声母不同（n 与 t），意思是“哪里”。", "把": "把 bǎ 与 tǎ 声母不同（b 与 t），意思是“把手”或“把握”。", "躺": "躺 tǎng 与 tǎ 韵母不同（多了 ng），意思是“躺下”。"}, "sentence_index": null, "correct_answer": "塔"}, "level_3": {"options": [{"text": "塔", "is_correct": true, "explanation": "正确。“这座”的量词用于大型建筑，“很高”描述塔的高度，与句意一致。"}, {"text": "书", "is_correct": false, "explanation": "语义：书没有“很高”的高度义，“这座书”也不成立。"}, {"text": "河", "is_correct": false, "explanation": "语义：河的特征是长、宽，不说“很高”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”用量词“张”，不能用“座”。"}], "explanations": {"塔": "正确。“这座”的量词用于大型建筑，“很高”描述塔的高度，与句意一致。", "书": "语义：书没有“很高”的高度义，“这座书”也不成立。", "河": "语义：河的特征是长、宽，不说“很高”。", "桌子": "搭配：“桌子”用量词“张”，不能用“座”。"}, "sentence_index": 0, "correct_answer": "塔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座塔很长，连接着河的两岸。", "explanation": "这里应该用〈桥〉。桥横跨河流、连接两岸；塔是又高又尖的建筑，不能用来连接两岸。"}, {"text": "我每天坐塔去上班。", "explanation": "这里应该用〈地铁〉（或其他交通工具）。塔是建筑，不能当作交通工具乘坐。"}, {"text": "我家是一座塔，只有一层。", "explanation": "这里应该用〈平房〉。平房是一层的低矮房子；塔又高又尖、一层一层往上盖，不能用来指只有一层的房子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90469, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "塔", "is_correct": true, "explanation": "正确答案。塔（第三声）指又高又尖、一层一层往上盖的建筑。"}, {"text": "她", "is_correct": false, "explanation": "她 tā（第一声）与 tǎ（第三声）声调不同，意思是“她”（女性人称代词）。"}, {"text": "打", "is_correct": false, "explanation": "打 dǎ 与 tǎ 声母不同（d 与 t），意思是“打”。"}, {"text": "卡", "is_correct": false, "explanation": "卡 kǎ 与 tǎ 声母不同（k 与 t），意思是“卡住”或“卡片”。"}, {"text": "讨", "is_correct": false, "explanation": "讨 tǎo 与 tǎ 韵母不同（多了 o），意思是“讨论”或“讨好”。"}], "explanations": {"塔": "正确答案。塔（第三声）指又高又尖、一层一层往上盖的建筑。", "她": "她 tā（第一声）与 tǎ（第三声）声调不同，意思是“她”（女性人称代词）。", "打": "打 dǎ 与 tǎ 声母不同（d 与 t），意思是“打”。", "卡": "卡 kǎ 与 tǎ 声母不同（k 与 t），意思是“卡住”或“卡片”。", "讨": "讨 tǎo 与 tǎ 韵母不同（多了 o），意思是“讨论”或“讨好”。"}, "sentence_index": null, "correct_answer": "塔"}, "level_3": {"options": [{"text": "塔", "is_correct": true, "explanation": "正确。“那座”指古老的建筑，“有一千年的历史”符合塔的特点。"}, {"text": "人", "is_correct": false, "explanation": "语义：人的寿命不能说“有一千年的历史”。"}, {"text": "书", "is_correct": false, "explanation": "搭配：量词“座”用于建筑、山等，不用于书；“那座书”不成立，应为“那本书”。"}, {"text": "菜", "is_correct": false, "explanation": "语义：菜不以“一千年的历史”计，句子的意思不通。"}], "explanations": {"塔": "正确。“那座”指古老的建筑，“有一千年的历史”符合塔的特点。", "人": "语义：人的寿命不能说“有一千年的历史”。", "书": "搭配：量词“座”用于建筑、山等，不用于书；“那座书”不成立，应为“那本书”。", "菜": "语义：菜不以“一千年的历史”计，句子的意思不通。"}, "sentence_index": 6, "correct_answer": "塔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公园的塔很长，把整个公园都围了起来。", "explanation": "这里应该用〈围墙〉。围墙用来把一个地方围起来；塔是又高又尖的建筑，不能围住公园。"}, {"text": "我在床边放了一个小塔，用来晾毛巾。", "explanation": "这里应该用〈架子〉。架子可以放在床边晾毛巾；塔是又高又尖的大型建筑，不能放在屋里晾东西。"}, {"text": "大厅中间的塔很粗，把屋顶撑了起来。", "explanation": "这里应该用〈柱子〉。柱子立在屋里撑住屋顶；塔是又高又尖的建筑，不能立在屋里撑屋顶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90469, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去看了一只塔。", "corrected_sentence": "我去看了一座塔。", "error_description": "“塔”是建筑，量词应用“座”，“只”只用于动物。“一只塔”应改为“一座塔”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90469, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那片塔在山顶上，很多人都来看。", "corrected_sentence": "那座塔在山顶上，很多人都来看。", "error_description": "量词错误：“塔”是建筑，量词应用“座”；“片”用于云、叶子等平面或成片的事物。“那片塔”应改为“那座塔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90470, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
