INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90470, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种高耸的建筑物，多为多层，常用于佛教或观景。", "primary_collocate": null, "pronunciation": "tǎ", "ipa": "tʰa˨˩˦", "syllable_count": 1, "sentences": [{"text": "寺里有一座塔。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座塔是和尚们盖的。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多人来塔上看风景。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "站在塔上，能看到远处的河。", "target_word": "塔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座塔一共有九层。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我去过那座塔两次。", "target_word": "塔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们都想爬上塔看看。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山里的寺庙旁边有一座很老的塔。", "target_word": "塔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "塔里面很安静，也有点儿黑。", "target_word": "塔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿着相机，站在塔下等朋友。", "target_word": "塔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座塔", "label": "量词"}, {"form": "铁塔", "label": "复合"}, {"form": "宝塔", "label": "复合"}], "register": "通用", "sense_fingerprint": "塔：多层高耸建筑，用于佛教或登高观景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d48bf1a-fcce-4795-8810-0494f4f470de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90470, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "塔", "is_correct": true, "explanation": "正确答案。塔（第三声）指多层、高耸的建筑，常用于佛教或观景。"}, {"text": "他", "is_correct": false, "explanation": "他 tā（第一声）与 tǎ（第三声）声调不同，意思是“他”（人称代词）。"}, {"text": "踏", "is_correct": false, "explanation": "踏 tà（第四声）与 tǎ（第三声）声调不同，意思是“踩”。"}, {"text": "哪", "is_correct": false, "explanation": "哪 nǎ 与 tǎ 声母不同（n 与 t），意思是“哪里”。"}, {"text": "躺", "is_correct": false, "explanation": "躺 tǎng 与 tǎ 韵母不同（多了 ng），意思是“躺下”。"}], "explanations": {"塔": "正确答案。塔（第三声）指多层、高耸的建筑，常用于佛教或观景。", "他": "他 tā（第一声）与 tǎ（第三声）声调不同，意思是“他”（人称代词）。", "踏": "踏 tà（第四声）与 tǎ（第三声）声调不同，意思是“踩”。", "哪": "哪 nǎ 与 tǎ 声母不同（n 与 t），意思是“哪里”。", "躺": "躺 tǎng 与 tǎ 韵母不同（多了 ng），意思是“躺下”。"}, "sentence_index": null, "correct_answer": "塔"}, "level_3": {"options": [{"text": "塔", "is_correct": true, "explanation": "正确。“寺里有一座”的量词“座”用于建筑，塔符合句意。"}, {"text": "人", "is_correct": false, "explanation": "搭配：量词“座”不用于人，“一座人”不成立。"}, {"text": "河", "is_correct": false, "explanation": "语义：河是水道，不会在寺里“有一座”。"}, {"text": "书", "is_correct": false, "explanation": "语义：书应说“有一本”，而且不是建筑，不能说“寺里有一座书”。"}], "explanations": {"塔": "正确。“寺里有一座”的量词“座”用于建筑，塔符合句意。", "人": "搭配：量词“座”不用于人，“一座人”不成立。", "河": "语义：河是水道，不会在寺里“有一座”。", "书": "语义：书应说“有一本”，而且不是建筑，不能说“寺里有一座书”。"}, "sentence_index": 0, "correct_answer": "塔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座塔很长，横跨在河面上，连接两岸。", "explanation": "这里应该用〈桥〉。桥横跨河流、连接两岸；塔是高耸的建筑，不能用来连接两岸。"}, {"text": "我每天坐塔去学校。", "explanation": "这里应该用〈地铁〉（或其他交通工具）。塔是建筑，不能当作交通工具乘坐。"}, {"text": "晚上睡觉的时候，我把头放在塔上。", "explanation": "这里应该用〈枕头〉。枕头柔软，睡觉时垫在头下；塔是高耸的建筑，不能垫在头下睡觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90470, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "塔", "is_correct": true, "explanation": "正确答案。塔（第三声）指多层、高耸的建筑，常用于佛教或观景。"}, {"text": "她", "is_correct": false, "explanation": "她 tā（第一声）与 tǎ（第三声）声调不同，意思是“她”（女性人称代词）。"}, {"text": "打", "is_correct": false, "explanation": "打 dǎ 与 tǎ 声母不同（d 与 t），意思是“打”。"}, {"text": "卡", "is_correct": false, "explanation": "卡 kǎ 与 tǎ 声母不同（k 与 t），意思是“卡住”或“卡片”。"}, {"text": "讨", "is_correct": false, "explanation": "讨 tǎo 与 tǎ 韵母不同（多了 o），意思是“讨论”或“讨好”。"}, {"text": "把", "is_correct": false, "explanation": "把 bǎ 与 tǎ 声母不同（b 与 t），意思是“把手”或“把握”。"}], "explanations": {"塔": "正确答案。塔（第三声）指多层、高耸的建筑，常用于佛教或观景。", "她": "她 tā（第一声）与 tǎ（第三声）声调不同，意思是“她”（女性人称代词）。", "打": "打 dǎ 与 tǎ 声母不同（d 与 t），意思是“打”。", "卡": "卡 kǎ 与 tǎ 声母不同（k 与 t），意思是“卡住”或“卡片”。", "讨": "讨 tǎo 与 tǎ 韵母不同（多了 o），意思是“讨论”或“讨好”。", "把": "把 bǎ 与 tǎ 声母不同（b 与 t），意思是“把手”或“把握”。"}, "sentence_index": null, "correct_answer": "塔"}, "level_3": {"options": [{"text": "塔", "is_correct": true, "explanation": "正确。“爬上”的对象是可以攀登的高大建筑，塔符合句意。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不能被“爬上”去看，“爬上水看看”不通。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“爬上”的对象应是可攀爬的物体，书不说“爬上书”。"}, {"text": "字", "is_correct": false, "explanation": "语义：字是写下来的符号，不能爬上去看看。"}], "explanations": {"塔": "正确。“爬上”的对象是可以攀登的高大建筑，塔符合句意。", "水": "语义：水不能被“爬上”去看，“爬上水看看”不通。", "书": "搭配：“爬上”的对象应是可攀爬的物体，书不说“爬上书”。", "字": "语义：字是写下来的符号，不能爬上去看看。"}, "sentence_index": 6, "correct_answer": "塔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公园中间有一座塔，大家在里面下棋。", "explanation": "这里应该用〈亭子〉。亭子有顶、四面通风，供人休息下棋；塔是高耸的多层建筑，供佛教或观景，不作下棋场所。"}, {"text": "寺庙的塔很长，把整个院子都围了起来。", "explanation": "这里应该用〈围墙〉。围墙用来把地方围起来；塔是高耸的建筑，不能围住院子。"}, {"text": "我在床边放了一个小塔，用来晾毛巾。", "explanation": "这里应该用〈架子〉。架子可以放在屋里晾毛巾；塔是用于佛教或观景的高耸建筑，不能放在床边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去寺里看了一只塔。", "corrected_sentence": "我去寺里看了一座塔。", "error_description": "“塔”是建筑，量词应用“座”，“只”只用于动物。“一只塔”应改为“一座塔”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "游客们都想爬上一只塔看看。", "corrected_sentence": "游客们都想爬上一座塔看看。", "error_description": "“塔”是建筑，量词应用“座”，“只”只用于动物。“一只塔”应改为“一座塔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
