INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90471, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "分析学是数学里研究变化和极限的一门学问。", "primary_collocate": null, "pronunciation": "fēn xī xué", "ipa": "fən˥ ɕi˥ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "分析学研究变化和极限。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王教授教分析学已经十年了。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学分析学要多做题。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分析学是数学里的一门学问。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在看一本分析学的书。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们下午有分析学的课。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分析学帮助我们了解变化。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就喜欢分析学。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分析学的考试很难。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学系的学生都要学分析学。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分析学家", "label": "复合"}], "register": "书面", "sense_fingerprint": "分析学：数学中研究变化与极限的一门学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3040b130-1c83-4aba-a0d1-f87d0f162c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90471, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不研究变化和极限，句子说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是研究的主体，与句意不符。"}, {"text": "节日", "is_correct": false, "explanation": "搭配：“研究”的主语要是学科或学者，“节日”不能研究变化和极限。"}, {"text": "分析学", "is_correct": true, "explanation": "分析学研究函数与极限的变化，符合句意和定义。"}], "explanations": {"汽车": "语义：汽车是交通工具，不研究变化和极限，句子说不通。", "厨房": "语义：厨房是做饭的地方，不是研究的主体，与句意不符。", "节日": "搭配：“研究”的主语要是学科或学者，“节日”不能研究变化和极限。", "分析学": "分析学研究函数与极限的变化，符合句意和定义。"}, "sentence_index": 0, "correct_answer": "分析学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "分析学研究物质的变化和反应。", "explanation": "这里应该用〈化学〉。物质的变化和反应属于化学，分析学研究的是数学中的变化与极限。"}, {"text": "分析学研究运动和力。", "explanation": "这里应该用〈物理学〉。运动和力属于物理学，分析学研究的是数学中的函数与极限。"}, {"text": "分析学研究过去发生的变化。", "explanation": "这里应该用〈历史学〉。过去发生的事情属于历史学，分析学不研究历史事件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90471, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不能帮助人了解变化，句子说不通。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，与了解变化无关。"}, {"text": "篮球", "is_correct": false, "explanation": "搭配：“帮助我们了解”要接抽象的学问或方法，“篮球”不能这样搭配。"}, {"text": "分析学", "is_correct": true, "explanation": "分析学是一门学问，可以帮助人了解变化，符合句意。"}], "explanations": {"钢琴": "语义：钢琴是乐器，不能帮助人了解变化，句子说不通。", "沙发": "语义：沙发是家具，与了解变化无关。", "篮球": "搭配：“帮助我们了解”要接抽象的学问或方法，“篮球”不能这样搭配。", "分析学": "分析学是一门学问，可以帮助人了解变化，符合句意。"}, "sentence_index": 6, "correct_answer": "分析学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "分析学研究植物的光合作用。", "explanation": "这里应该用〈生物学〉。植物的光合作用属于生物学，分析学研究的是数学中的函数与极限。"}, {"text": "分析学研究山脉和河流的形成。", "explanation": "这里应该用〈地理学〉。山脉和河流的形成属于地理学，分析学不研究地貌。"}, {"text": "分析学研究星球的运动。", "explanation": "这里应该用〈天文学〉。星球的运动属于天文学，分析学是数学分支，不研究天体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90471, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹从小就喜欢分析学们。", "corrected_sentence": "我妹妹从小就喜欢分析学。", "error_description": "错误在于给学科名加了复数后缀“们”。“分析学”是学科名，不能带“们”，应说“喜欢分析学”，去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90471, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们都要学一个分析学。", "corrected_sentence": "学生们都要学一门分析学。", "error_description": "错误在于量词。“分析学”是学科，量词应用“门”，不能用“个”，应改为“一门分析学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
