INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90472, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数学的一个分支，研究函数、极限、微分、积分等。", "primary_collocate": null, "pronunciation": "fēn xī xué", "ipa": "fən˥ ɕi˥ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "分析学是数学的一个分支。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学里学分析学。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分析学研究函数和极限。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是讲分析学的。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得分析学很难。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分析学的老师今天不在。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的专业是分析学。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分析学里有微分和积分。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对分析学很有兴趣。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆有很多分析学的书。", "target_word": "分析学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分析学家", "label": "复合"}], "register": "书面", "sense_fingerprint": "分析学：数学分支，研究函数、极限、微分和积分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3040b130-1c83-4aba-a0d1-f87d0f162c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "语言学", "is_correct": false, "explanation": "语义：语言学研究语言本身，不是数学的分支，与定义不符。"}, {"text": "文学", "is_correct": false, "explanation": "语义：文学研究文字作品，与数学无关，不能是数学的分支。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“是……的一个分支”要接学科名称，“音乐”是艺术门类，与数学搭配不当。"}, {"text": "分析学", "is_correct": true, "explanation": "分析学是数学的一个分支，符合定义。"}], "explanations": {"语言学": "语义：语言学研究语言本身，不是数学的分支，与定义不符。", "文学": "语义：文学研究文字作品，与数学无关，不能是数学的分支。", "音乐": "搭配：“是……的一个分支”要接学科名称，“音乐”是艺术门类，与数学搭配不当。", "分析学": "分析学是数学的一个分支，符合定义。"}, "sentence_index": 0, "correct_answer": "分析学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "分析学研究未知数和方程。", "explanation": "这里应该用〈代数学〉。分析学研究函数与极限，未知数和方程属于代数学。"}, {"text": "分析学研究人体的消化过程。", "explanation": "这里应该用〈生理学〉。人体的消化过程属于生理学，分析学是数学分支，不研究生理过程。"}, {"text": "分析学研究图形和空间。", "explanation": "这里应该用〈几何学〉。分析学研究函数与极限，图形和空间属于几何学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "北京", "is_correct": false, "explanation": "语义：北京是城市，不是学科，不能作专业。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是学科，不能作专业。"}, {"text": "苹果", "is_correct": false, "explanation": "搭配：“专业”要接学科名称，“苹果”是食物，搭配不当。"}, {"text": "分析学", "is_correct": true, "explanation": "分析学是数学的一个分支，可以作专业，符合句意。"}], "explanations": {"北京": "语义：北京是城市，不是学科，不能作专业。", "天气": "语义：天气是自然现象，不是学科，不能作专业。", "苹果": "搭配：“专业”要接学科名称，“苹果”是食物，搭配不当。", "分析学": "分析学是数学的一个分支，可以作专业，符合句意。"}, "sentence_index": 6, "correct_answer": "分析学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "分析学研究物体的运动规律。", "explanation": "这里应该用〈物理学〉。物体的运动规律属于物理学，分析学研究的是函数与极限。"}, {"text": "分析学研究细胞的生长和分裂。", "explanation": "这里应该用〈生物学〉。细胞的生长和分裂属于生物学的研究范围。"}, {"text": "这本小说的分析学很深刻。", "explanation": "这里应该用〈分析〉。分析学专指数学分支，对小说的分析要说分析，不能加“学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他学了一个分析学。", "corrected_sentence": "他学了一门分析学。", "error_description": "错误在于量词。“分析学”是学科，量词应用“门”，不能用“个”，应改为“一门分析学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没学了分析学。", "corrected_sentence": "他没学过分析学。", "error_description": "错误在于“了”。表示否定的经历要用“没……过”，“没……了”不成立，应改为“没学过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
