INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90473, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很好很好的朋友。", "primary_collocate": null, "pronunciation": "hǎo yǒu", "ipa": "xaʊ˨˩˦ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是我从小的好友。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和好友一起去看电影。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的好友住在上海。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好友过生日，我送了他一本书。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常和好友聊天。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的好友今天从北京来看她。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把这个好消息告诉了好友。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和好友吃过很多次饭。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好友病了，我去医院看他。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和好友在一个班学习。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "好友们", "label": "复数"}], "register": "中性", "sense_fingerprint": "很好很好的朋友", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b382258-1d1c-4078-8cdf-3ee7f594def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90473, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好友", "is_correct": true, "explanation": "正确：好友指很好很好的朋友，与“从小的”相符。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：“从小的”说明两人从小相识，“陌生人”与之矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“他是……”指人，桌子不能用来指“他”的身份。"}, {"text": "外人", "is_correct": false, "explanation": "语义：“外人”指不属于自己圈子的人，与“从小的”这种亲近关系矛盾。"}], "explanations": {"好友": "正确：好友指很好很好的朋友，与“从小的”相符。", "陌生人": "语义：“从小的”说明两人从小相识，“陌生人”与之矛盾。", "桌子": "搭配：“他是……”指人，桌子不能用来指“他”的身份。", "外人": "语义：“外人”指不属于自己圈子的人，与“从小的”这种亲近关系矛盾。"}, "sentence_index": 0, "correct_answer": "好友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和邻居只说过几句话，他是我的好友。", "explanation": "这里应该用〈熟人〉。好友指很好很好的朋友，只说过几句话的邻居不能称好友；只是认识的人要用“熟人”。"}, {"text": "我在公园里遇到一只好友。", "explanation": "这里应该用〈位〉。好友指人，量词不能用“只”（“只”多用于动物或物品），指人要用“位”或“个”。"}, {"text": "我和好友在路上相遇，互相不认识。", "explanation": "这里应该用〈陌生人〉。好友指很好的朋友，不能用于互不认识的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90473, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好友", "is_correct": true, "explanation": "正确：好友是很好很好的朋友，可以分享好消息，与句意相符。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“告诉”的对象要能接收消息，空气不能作为受话对象。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：石头不能听消息，“告诉了”后应是能接收信息的人。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“告诉”的对象要能接收消息，窗户不能听消息。"}], "explanations": {"好友": "正确：好友是很好很好的朋友，可以分享好消息，与句意相符。", "空气": "搭配：“告诉”的对象要能接收消息，空气不能作为受话对象。", "石头": "搭配：石头不能听消息，“告诉了”后应是能接收信息的人。", "窗户": "搭配：“告诉”的对象要能接收消息，窗户不能听消息。"}, "sentence_index": 6, "correct_answer": "好友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和他只是在楼下见过几次，他是我的好友。", "explanation": "这里应该用〈熟人〉。好友指很好很好的朋友，只在楼下见过几次的人不能称好友；只是认识的人要用“熟人”。"}, {"text": "这个人是我的仇人，我们从不往来，这个人也是我的好友。", "explanation": "这里应该用〈对头〉。好友指很好很好的朋友，彼此仇视、从不往来的人不能称好友，这种关系应说成“对头”。"}, {"text": "我和路人从来不认识，我和好友也从来不认识。", "explanation": "这里应该用〈陌生人〉。好友指很好很好的朋友，从来不认识的人不能称好友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90473, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一个好友们。", "corrected_sentence": "我有一个好友。", "error_description": "“一个”是数量短语，“好友”后面不能再加复数词尾“们”，应说“一个好友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90473, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我请了两好友来家里吃饭。", "corrected_sentence": "我请了两位好友来家里吃饭。", "error_description": "数词“两”后面要有量词，应说“两位好友”，不能说“两好友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
