INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90474, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "交情深厚的朋友。", "primary_collocate": null, "pronunciation": "hǎo yǒu", "ipa": "xaʊ˨˩˦ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们是多年的好友。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和我是二十年的好友。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好友有难，我一定会帮他。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老好友见面，有说不完的话。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们成了一辈子的好友。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我最难过的时候，好友一直陪着我。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好友之间不用说谢谢。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位好友帮过我很多次。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是同学，也是一生的好友。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和好友十年没见，还像以前一样。", "target_word": "好友", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "好友们", "label": "复数"}], "register": "中性", "sense_fingerprint": "交情深厚的朋友", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b382258-1d1c-4078-8cdf-3ee7f594def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90474, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好友", "is_correct": true, "explanation": "正确：好友指交情深厚的朋友，与“多年的”相符。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：“多年的”说明长期相识，“陌生人”与之矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“我们是……”指人际关系，桌子不能表示人际关系。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有感情，不能和人建立多年的交往关系。"}], "explanations": {"好友": "正确：好友指交情深厚的朋友，与“多年的”相符。", "陌生人": "语义：“多年的”说明长期相识，“陌生人”与之矛盾。", "桌子": "搭配：“我们是……”指人际关系，桌子不能表示人际关系。", "石头": "语义：石头没有感情，不能和人建立多年的交往关系。"}, "sentence_index": 0, "correct_answer": "好友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和他只是认识，平时很少来往，他是我的好友。", "explanation": "这里应该用〈熟人〉。好友指交情深厚的朋友，只是认识、很少来往的人只能称熟人，不能称好友。"}, {"text": "我家来了一只老好友。", "explanation": "这里应该用〈位〉。好友指人，量词不能用“只”（“只”多用于动物或物品），指人要用“位”。"}, {"text": "我和同学只见过几次面，他是我的好友。", "explanation": "这里应该用〈点头之交〉。好友指交情深厚的朋友，只见过几次面的同学不能称好友；只是点头相识的人要用“点头之交”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好友", "is_correct": true, "explanation": "正确：好友之间关系亲密，不用说谢谢，与句意相符。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“不用说谢谢”的对象是人，窗户不能与之搭配。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是人，不能与“不用说谢谢”的情境相合。"}, {"text": "树", "is_correct": false, "explanation": "搭配：树不能说谢谢，也不能接受道谢，与“不用说谢谢”搭配不当。"}], "explanations": {"好友": "正确：好友之间关系亲密，不用说谢谢，与句意相符。", "窗户": "搭配：“不用说谢谢”的对象是人，窗户不能与之搭配。", "电脑": "语义：电脑不是人，不能与“不用说谢谢”的情境相合。", "树": "搭配：树不能说谢谢，也不能接受道谢，与“不用说谢谢”搭配不当。"}, "sentence_index": 6, "correct_answer": "好友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和这位店员只在买东西时打过招呼，他是我的好友。", "explanation": "这里应该用〈点头之交〉。好友指交情深厚的朋友，只在买东西时打过招呼的人不能称好友。"}, {"text": "我在电视上见过这个人几次，他是我的好友。", "explanation": "这里应该用〈陌生人〉。好友指交情深厚的朋友，只在电视上见过的人不能称好友。"}, {"text": "我和那个人从没打过交道，他是我的好友。", "explanation": "这里应该用〈路人〉。好友指交情深厚的朋友，从没打过交道的人不能称好友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他和我曾经是好友过。", "corrected_sentence": "他和我曾经是好友。", "error_description": "“是”后面的“好友”是名词，不能加动态助词“过”，应说“他和我曾经是好友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他和我是三十年地好友。", "corrected_sentence": "他和我是三十年的好友。", "error_description": "“三十年”修饰“好友”，修饰名词要用“的”，不能用“地”；应说“三十年的好友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
