INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90475, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示数量或幅度很大，程度深。", "primary_collocate": null, "pronunciation": "dà dà", "ipa": "ta˥˩ ta˥˩", "syllable_count": 2, "sentences": [{"text": "今年的游客人数大大增加了。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的雨水比去年大大减少。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的收入大大超过了我们的想象。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁比开车大大节省了时间。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新路修好后，路上的时间大大缩短了。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市打折以后，客人大大增多。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷，出门的人大大减少了。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的成绩大大高于平时。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作的机会比以前大大增加了。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的差距大大缩小了。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词；修饰增减、缩短等动词，表示数量或幅度很大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc92a6b-6dc2-4a5f-9877-7bf97a1744bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90475, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大大", "is_correct": true, "explanation": "正确答案：大大（dà dà），副词，表示程度深、幅度大。"}, {"text": "大地", "is_correct": false, "explanation": "后一音节 dà 与 dì 韵母不同（a 与 i），意思是大地。"}, {"text": "嗒嗒", "is_correct": false, "explanation": "两个音节均为第一声（dā dā），与 dà dà 仅声调不同，是象声词，形容轻敲或马蹄的声音。"}, {"text": "打打", "is_correct": false, "explanation": "两个音节均为第三声（dǎ dǎ），与 dà dà 仅声调不同；作动词重叠，表示动作短暂随意，如“打打球”。"}], "explanations": {"大大": "正确答案：大大（dà dà），副词，表示程度深、幅度大。", "大地": "后一音节 dà 与 dì 韵母不同（a 与 i），意思是大地。", "嗒嗒": "两个音节均为第一声（dā dā），与 dà dà 仅声调不同，是象声词，形容轻敲或马蹄的声音。", "打打": "两个音节均为第三声（dǎ dǎ），与 dà dà 仅声调不同；作动词重叠，表示动作短暂随意，如“打打球”。"}, "sentence_index": null, "correct_answer": "大大"}, "level_3": {"options": [{"text": "大大", "is_correct": true, "explanation": "正确：“大大”修饰“增加”，表示增加的幅度很大。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示长久不变，与“今年”这一具体时段冲突。"}, {"text": "通常", "is_correct": false, "explanation": "体貌：“通常”表示习惯性，不能与表示完成的“增加了”搭配。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与游客人数持续增加的语义相冲突。"}], "explanations": {"大大": "正确：“大大”修饰“增加”，表示增加的幅度很大。", "永远": "语义：“永远”表示长久不变，与“今年”这一具体时段冲突。", "通常": "体貌：“通常”表示习惯性，不能与表示完成的“增加了”搭配。", "偶尔": "语义：“偶尔”表示不常发生，与游客人数持续增加的语义相冲突。"}, "sentence_index": 0, "correct_answer": "大大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的成绩大大提高了一点。", "explanation": "这里应该用〈稍微〉。“大大”表示幅度很大，与“一点”的轻微程度矛盾，轻微的提高要说稍微。"}, {"text": "我大大只买了一本书。", "explanation": "这里〈大大〉表示数量多、程度深，与只买一本这种少量的情况冲突，此处应表达少量，不能用大大。"}, {"text": "他们俩的身高大大一样。", "explanation": "这里应该用〈差不多〉。大大修饰有幅度的增减变化，身高相同没有变化幅度，不能与“一样”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90475, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大大", "is_correct": true, "explanation": "正确答案：大大（dà dà），副词，表示程度深、幅度大。"}, {"text": "带带", "is_correct": false, "explanation": "两个音节均为 dài，与 dà 仅韵母多一个 i（ai 与 a），声调相同；口语动词，意为带领、照应。"}, {"text": "荡荡", "is_correct": false, "explanation": "两个音节均为 dàng，与 dà 仅韵母多一个鼻音 ng（ang 与 a），声调相同；形容词，意为广阔、开阔。"}, {"text": "达达", "is_correct": false, "explanation": "两个音节均为第二声 dá，与 dà dà 仅声调不同；音译词，如“达达主义”。"}], "explanations": {"大大": "正确答案：大大（dà dà），副词，表示程度深、幅度大。", "带带": "两个音节均为 dài，与 dà 仅韵母多一个 i（ai 与 a），声调相同；口语动词，意为带领、照应。", "荡荡": "两个音节均为 dàng，与 dà 仅韵母多一个鼻音 ng（ang 与 a），声调相同；形容词，意为广阔、开阔。", "达达": "两个音节均为第二声 dá，与 dà dà 仅声调不同；音译词，如“达达主义”。"}, "sentence_index": null, "correct_answer": "大大"}, "level_3": {"options": [{"text": "大大", "is_correct": true, "explanation": "正确：“大大”修饰“减少”，表示减少的幅度很大，与“天气变冷”相合。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示共同，不能修饰“人数减少”这种各自发生的变化。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”表示附带，与天气变冷导致的整体变化不合。"}, {"text": "没有", "is_correct": false, "explanation": "否定：“没有”与已发生的“减少了”相矛盾，“没有……了”不成立，与天气变冷后的实际变化不合。"}], "explanations": {"大大": "正确：“大大”修饰“减少”，表示减少的幅度很大，与“天气变冷”相合。", "一起": "语义：“一起”表示共同，不能修饰“人数减少”这种各自发生的变化。", "顺便": "语义：“顺便”表示附带，与天气变冷导致的整体变化不合。", "没有": "否定：“没有”与已发生的“减少了”相矛盾，“没有……了”不成立，与天气变冷后的实际变化不合。"}, "sentence_index": 6, "correct_answer": "大大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我大大地去过一次北京。", "explanation": "“大大”修饰程度，与表示次数的“一次”不协调，说次数要用“多次”。"}, {"text": "这次考试我大大及格了。", "explanation": "这里应该用〈考得很好〉。及格只表示合格与否，没有程度差别，不能用大大修饰。"}, {"text": "这件事大大地没有发生过。", "explanation": "这里应该用〈根本〉：这件事根本没有发生过。大大表示程度深，修饰否定时语义不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90475, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店的顾客大大很增加了。", "corrected_sentence": "这家店的顾客大大增加了。", "error_description": "错误：「大大」本身已表示程度，前面又加程度副词「很」，两者叠用是错误的。应删去「很」，说「大大增加了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90475, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的利润大大大增加了。", "corrected_sentence": "这家公司的利润大大增加了。", "error_description": "错误：「大大」是一个副词，不能重复成「大大大」。应说「大大增加了」，多出的「大」是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90476, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
