INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90476, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示程度深、幅度大。", "primary_collocate": null, "pronunciation": "dà dà", "ipa": "ta˥˩ ta˥˩", "syllable_count": 2, "sentences": [{"text": "这个新办法大大提高了工作效率。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动大大改善了他的身体状况。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上购物大大方便了我们的生活。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话大大鼓舞了同学们。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大雨大大缓解了干旱。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的习惯大大有利于学习。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行大大开阔了我的眼界。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机大大改变了人们的生活。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的帮助大大加快了他的恢复。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好天气大大提升了大家的心情。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词；修饰提高、改善、方便等动词，表示影响的程度很深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc92a6b-6dc2-4a5f-9877-7bf97a1744bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90476, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大大", "is_correct": true, "explanation": "正确答案：大大（dà dà），副词，修饰动词，表示影响的程度很深。"}, {"text": "大地", "is_correct": false, "explanation": "后一音节 dà 与 dì 韵母不同（a 与 i），意思是大地。"}, {"text": "嗒嗒", "is_correct": false, "explanation": "两个音节均为第一声（dā dā），与 dà dà 仅声调不同，是象声词，形容轻敲或马蹄的声音。"}, {"text": "打打", "is_correct": false, "explanation": "两个音节均为第三声（dǎ dǎ），与 dà dà 仅声调不同；作动词重叠，表示动作短暂随意，如“打打球”。"}], "explanations": {"大大": "正确答案：大大（dà dà），副词，修饰动词，表示影响的程度很深。", "大地": "后一音节 dà 与 dì 韵母不同（a 与 i），意思是大地。", "嗒嗒": "两个音节均为第一声（dā dā），与 dà dà 仅声调不同，是象声词，形容轻敲或马蹄的声音。", "打打": "两个音节均为第三声（dǎ dǎ），与 dà dà 仅声调不同；作动词重叠，表示动作短暂随意，如“打打球”。"}, "sentence_index": null, "correct_answer": "大大"}, "level_3": {"options": [{"text": "大大", "is_correct": true, "explanation": "正确：“大大”修饰“提高”，表示对工作效率的影响很深。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“提高工作效率”的整体影响不合。"}, {"text": "通常", "is_correct": false, "explanation": "体貌：“通常”表示习惯性，不能与表示完成的“提高了”搭配。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示长久不变，与“提高了”这一已经发生的变化冲突。"}], "explanations": {"大大": "正确：“大大”修饰“提高”，表示对工作效率的影响很深。", "偶尔": "语义：“偶尔”表示不常发生，与“提高工作效率”的整体影响不合。", "通常": "体貌：“通常”表示习惯性，不能与表示完成的“提高了”搭配。", "永远": "语义：“永远”表示长久不变，与“提高了”这一已经发生的变化冲突。"}, "sentence_index": 0, "correct_answer": "大大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个新办法大大提高了一点工作效率。", "explanation": "这里应该用〈稍微〉。“大大”表示影响很深，与“一点”的轻微程度矛盾，轻微的影响要说稍微。"}, {"text": "这个新办法大大提高了一小部分效率。", "explanation": "这里应该用〈略微〉。大大表示影响很深，与“一小部分”这样的少量不合；只有轻微的影响才说略微。"}, {"text": "这场大雨大大只缓解了干旱。", "explanation": "这里应该用〈稍稍〉。大大表示影响很深，与“只”的限定相矛盾；只有轻微的缓解才说稍稍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90476, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大大", "is_correct": true, "explanation": "正确答案：大大（dà dà），副词，修饰动词，表示影响的程度很深。"}, {"text": "带带", "is_correct": false, "explanation": "两个音节均为 dài，与 dà 仅韵母多一个 i（ai 与 a），声调相同；口语动词，意为带领、照应。"}, {"text": "荡荡", "is_correct": false, "explanation": "两个音节均为 dàng，与 dà 仅韵母多一个鼻音 ng（ang 与 a），声调相同；形容词，意为广阔、开阔。"}, {"text": "达达", "is_correct": false, "explanation": "两个音节均为第二声 dá，与 dà dà 仅声调不同；音译词，如“达达主义”。"}], "explanations": {"大大": "正确答案：大大（dà dà），副词，修饰动词，表示影响的程度很深。", "带带": "两个音节均为 dài，与 dà 仅韵母多一个 i（ai 与 a），声调相同；口语动词，意为带领、照应。", "荡荡": "两个音节均为 dàng，与 dà 仅韵母多一个鼻音 ng（ang 与 a），声调相同；形容词，意为广阔、开阔。", "达达": "两个音节均为第二声 dá，与 dà dà 仅声调不同；音译词，如“达达主义”。"}, "sentence_index": null, "correct_answer": "大大"}, "level_3": {"options": [{"text": "大大", "is_correct": true, "explanation": "正确：“大大”修饰“开阔”，表示对眼界的影响很深，与“这次旅行”相合。"}, {"text": "一向", "is_correct": false, "explanation": "语义：“一向”表示长期习惯，与“这次”一次性的旅行冲突。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示一直持续，与“这次”一次性事件的语义冲突。"}, {"text": "没有", "is_correct": false, "explanation": "否定：“没有”与已发生的“开阔了”相矛盾，“没有……了”不成立。"}], "explanations": {"大大": "正确：“大大”修饰“开阔”，表示对眼界的影响很深，与“这次旅行”相合。", "一向": "语义：“一向”表示长期习惯，与“这次”一次性的旅行冲突。", "始终": "语义：“始终”表示一直持续，与“这次”一次性事件的语义冲突。", "没有": "否定：“没有”与已发生的“开阔了”相矛盾，“没有……了”不成立。"}, "sentence_index": 6, "correct_answer": "大大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试我大大及格了。", "explanation": "这里应该用〈考得很好〉。及格只表示合格与否，没有程度差别，不能用大大修饰。"}, {"text": "运动大大没有改善他的身体状况。", "explanation": "这里应该用〈根本〉。大大表示程度深，直接修饰否定词“没有”语义矛盾；说完全没有改善要用根本。"}, {"text": "这个方法大大地快要成功了。", "explanation": "这里应该用〈即将〉这类时间副词，而不是程度副词大大；大大不能表示即将发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新的系统很大大方便了大家的工作。", "corrected_sentence": "新的系统大大方便了大家的工作。", "error_description": "错误：「大大」本身已是程度副词，前面不能再加「很」，「很大大」叠用不通。删去「很」即可，应说「大大方便了大家的工作」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书大大大扩大了我的知识面。", "corrected_sentence": "这本书大大扩大了我的知识面。", "error_description": "错误：「大大」是副词，不能重复成「大大大」。删去多出的一个「大」，应说「大大扩大了我的知识面」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
