INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90477, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "副主席是主席的帮手。", "primary_collocate": null, "pronunciation": "fù zhǔ xí", "ipa": "fu˥˩ tʂu˨˩˦ ɕi˧˥", "syllable_count": 3, "sentences": [{"text": "副主席坐在主席的旁边。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们学生会的副主席。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主席生病了，副主席来开会。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "副主席每天帮主席做很多事。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王被选为协会副主席。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "副主席对主席说：“我来帮你。”", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位副主席很年轻，工作也很认真。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上，副主席先介绍了今天的安排。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请副主席帮个忙。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "副主席把文件交给了主席。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "主席的帮手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36662012-8007-41fe-a78e-aaa6e4d441d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90477, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "副主席", "is_correct": true, "explanation": "副主席是职务名称，作主语，句意通顺：副主席坐在主席的旁边。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“坐”需要有生命的人作主语，“椅子”不能坐在旁边。"}, {"text": "主席", "is_correct": false, "explanation": "语义：“主席的旁边”指的就是主席自己，主席不能坐在自己旁边。"}, {"text": "大门", "is_correct": false, "explanation": "语义：大门是建筑部件，不会坐在主席旁边。"}], "explanations": {"副主席": "副主席是职务名称，作主语，句意通顺：副主席坐在主席的旁边。", "椅子": "搭配：“坐”需要有生命的人作主语，“椅子”不能坐在旁边。", "主席": "语义：“主席的旁边”指的就是主席自己，主席不能坐在自己旁边。", "大门": "语义：大门是建筑部件，不会坐在主席旁边。"}, "sentence_index": 0, "correct_answer": "副主席"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我的私人副主席，每天帮我整理房间。", "explanation": "这里应该用〈管家〉。副主席是组织内的职务，不用来指照料个人生活的帮手。"}, {"text": "比赛下半场，副主席替下了受伤的队员。", "explanation": "这里应该用〈替补〉。副主席是会内职务，不指比赛中替换上场的队员。"}, {"text": "副主席每天在工厂的流水线上装配零件。", "explanation": "这里应该用〈工人〉。副主席是组织中的职务，不指在流水线上做工的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90477, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "副主席", "is_correct": true, "explanation": "“这位”指人，副主席是人，与“很年轻”“工作认真”相符。"}, {"text": "老人", "is_correct": false, "explanation": "语义：“老人”与“很年轻”相互矛盾。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能说“这位房子”。"}, {"text": "老爷爷", "is_correct": false, "explanation": "语义：“老爷爷”与“很年轻”相互矛盾。"}], "explanations": {"副主席": "“这位”指人，副主席是人，与“很年轻”“工作认真”相符。", "老人": "语义：“老人”与“很年轻”相互矛盾。", "房子": "搭配：量词“位”只用于人，不能说“这位房子”。", "老爷爷": "语义：“老爷爷”与“很年轻”相互矛盾。"}, "sentence_index": 6, "correct_answer": "副主席"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的副主席坏了，需要修理。", "explanation": "这里应该用〈部件〉。副主席指人，不用来指机器上的零件。"}, {"text": "他饿了，就买了一个副主席当午饭。", "explanation": "这里应该用〈面包〉。副主席是职务名称，不指食物。"}, {"text": "这次考试他考了第二名，成了副主席。", "explanation": "这里应该用〈亚军〉。考试排名第二称为亚军，副主席是协助主席的职务，不指名次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90477, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是我们学生会的一只副主席，很热心。", "corrected_sentence": "她是我们学生会的一位副主席，很热心。", "error_description": "量词错误：副主席指人，量词应用“位”，不能用“只”（“只”多用于动物或成对物品中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90477, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位副主席们刚到，正在和主席说话。", "corrected_sentence": "这位副主席刚到，正在和主席说话。", "error_description": "错误：“这位”表示单数，后面的“副主席”不能再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
