INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90478, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "协助主席工作的人，职位低于主席。", "primary_collocate": null, "pronunciation": "fù zhǔ xí", "ipa": "fu˥˩ tʂu˨˩˦ ɕi˧˥", "syllable_count": 3, "sentences": [{"text": "她担任公司工会的副主席。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "副主席的职位比主席低一级。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们协会有一位主席和两位副主席。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从副主席做起，后来当上了主席。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "副主席负责协助主席管理日常工作。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个委员会的副主席是一位老教授。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "副主席没有主席的权力大。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主席出国时，副主席负责处理事务。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大会选出了一位新的副主席。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经当过三年副主席了。", "target_word": "副主席", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "协助主席工作、职位低于主席的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36662012-8007-41fe-a78e-aaa6e4d441d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "副主席", "is_correct": true, "explanation": "“担任”后接职务名称，“副主席”是职务，句意通顺。"}, {"text": "会员", "is_correct": false, "explanation": "搭配：“担任”后接职务，“会员”不是职务，不能说“担任会员”。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不能担任工会的职务。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不能担任职务。"}], "explanations": {"副主席": "“担任”后接职务名称，“副主席”是职务，句意通顺。", "会员": "搭配：“担任”后接职务，“会员”不是职务，不能说“担任会员”。", "小猫": "语义：小猫不能担任工会的职务。", "厨房": "语义：厨房是场所，不能担任职务。"}, "sentence_index": 0, "correct_answer": "副主席"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在餐厅当副主席，负责给客人端菜。", "explanation": "这里应该用〈服务员〉。副主席是组织中的职务，不指餐厅里端菜的工作人员。"}, {"text": "这场足球比赛，副主席踢进了三个球。", "explanation": "这里应该用〈前锋〉。副主席是协会职务，不指在球场上得分的球员。"}, {"text": "我和我的副主席是同一个妈妈生的。", "explanation": "这里应该用〈哥哥〉。副主席是组织职务，不指家庭成员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "副主席", "is_correct": true, "explanation": "副主席是职务，与“主席的权力”比较，语义通顺。"}, {"text": "主席", "is_correct": false, "explanation": "语义：“主席”与“主席的权力”比较自己，句义不通。"}, {"text": "白开水", "is_correct": false, "explanation": "语义：白开水不是人或机构，不能与权力比较。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“权力大”的比较对象须是人或机构，不能用“窗户”。"}], "explanations": {"副主席": "副主席是职务，与“主席的权力”比较，语义通顺。", "主席": "语义：“主席”与“主席的权力”比较自己，句义不通。", "白开水": "语义：白开水不是人或机构，不能与权力比较。", "窗户": "搭配：“权力大”的比较对象须是人或机构，不能用“窗户”。"}, "sentence_index": 6, "correct_answer": "副主席"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台冰箱的副主席坏了，需要换掉。", "explanation": "这里应该用〈零件〉。副主席指人，不用来指冰箱上的零件。"}, {"text": "他每天早上吃一个副主席当早饭。", "explanation": "这里应该用〈包子〉。副主席是职务名称，不指食物。"}, {"text": "他这个月把副主席存进了银行。", "explanation": "这里应该用〈存款〉。副主席是职务名称，不是钱，不能存进银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是这家公司的一只副主席。", "corrected_sentence": "她是这家公司的一位副主席。", "error_description": "量词错误：副主席指人，量词应用“位”，不能用“只”（“只”多用于动物或成对物品中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "协会里来了一位副主席们，大家都很欢迎他。", "corrected_sentence": "协会里来了一位副主席，大家都很欢迎他。", "error_description": "错误：“一位”表示单数，“副主席”后不能再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
