INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90479, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "好像，像一样。", "primary_collocate": null, "pronunciation": "rú tóng", "ipa": "ɻu˧˥ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他对邻居如同对家人一样热情。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨如同从天上倒下来一样。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师如同我的母亲。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的湖面如同镜子一样平。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手冰凉，如同冰块。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听到消息，如同没听见一样。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间如同兄弟，不用客气。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的冬天如同春天一样暖和。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的雾如同一条白色的河。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着我，如同不认识我。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "如同……一样", "label": "固定搭配"}], "register": "书面", "sense_fingerprint": "表示比喻或相似，相当于“好像”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9007a2d-4d18-4039-ac90-907ce20042f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90479, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "如同", "is_correct": true, "explanation": "“如同”表示比拟，与句末的“一样”呼应，符合句意。"}, {"text": "属于", "is_correct": false, "explanation": "语义：“属于”表示归属关系，句中要的是比拟，不能表示对待方式的相似。"}, {"text": "成为", "is_correct": false, "explanation": "语义：“成为”表示变化为某种身份，与“对邻居……对家人一样热情”的比较不合。"}, {"text": "配", "is_correct": false, "explanation": "语义：“配”表示配合、相配，不能用于“对邻居……对家人一样热情”这种比拟结构。"}], "explanations": {"如同": "“如同”表示比拟，与句末的“一样”呼应，符合句意。", "属于": "语义：“属于”表示归属关系，句中要的是比拟，不能表示对待方式的相似。", "成为": "语义：“成为”表示变化为某种身份，与“对邻居……对家人一样热情”的比较不合。", "配": "语义：“配”表示配合、相配，不能用于“对邻居……对家人一样热情”这种比拟结构。"}, "sentence_index": 0, "correct_answer": "如同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天很冷，如同我们没去公园。", "explanation": "这里应该用〈所以〉。如同表示比拟，不能表示因果关系，前后的因果要用“所以”。"}, {"text": "他先看书，如同睡觉。", "explanation": "这里应该用〈然后〉。如同表示比拟，不能表示动作的先后顺序。"}, {"text": "他会说几种语言，如同英语。", "explanation": "这里应该用〈比如〉。如同表示比拟，不能用来举例。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90479, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "如同", "is_correct": true, "explanation": "“如同”表示比拟，与“不用客气”的亲近语境相合，符合句意。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示反感，与“朋友之间”的亲近关系矛盾。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”要接请求、邀请等对象，不能以“兄弟”为宾语。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗”含有不诚实的意思，与“不用客气”的亲近语境不合。"}], "explanations": {"如同": "“如同”表示比拟，与“不用客气”的亲近语境相合，符合句意。", "讨厌": "语义：“讨厌”表示反感，与“朋友之间”的亲近关系矛盾。", "拒绝": "搭配：“拒绝”要接请求、邀请等对象，不能以“兄弟”为宾语。", "欺骗": "语义：“欺骗”含有不诚实的意思，与“不用客气”的亲近语境不合。"}, "sentence_index": 6, "correct_answer": "如同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书很厚，如同很贵。", "explanation": "这里应该用〈而且〉。如同表示比拟，不能用来连接并列的分句。"}, {"text": "如同健康，他每天早上跑步。", "explanation": "这里应该用〈为了〉。如同表示比拟，不能引出目的。"}, {"text": "如同你有空，就来帮我一下。", "explanation": "这里应该用〈如果〉。如同表示比拟，不能引出假设条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90479, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的声音好像如同天使一样甜美。", "corrected_sentence": "她的声音如同天使一样甜美。", "error_description": "错误：“好像”与“如同”叠用。两者都表示比拟，只用“如同……一样”即可，应删去“好像”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90479, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座老房子如同城堡温暖。", "corrected_sentence": "这座老房子如同城堡一样温暖。", "error_description": "错误：漏掉了“一样”。“如同……一样”后接形容词时，书面语通常保留“一样”，此句漏掉后不通顺；应在“城堡”之后补上“一样”，写作“这座老房子如同城堡一样温暖。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
