INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90480, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90480, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "好像；像……一样。", "primary_collocate": null, "pronunciation": "rú tóng", "ipa": "ɻu˧˥ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "她对我如同亲姐姐一样。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的夏天如同火炉一样热。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对学生如同朋友。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他如同变了一个人。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间如同流水，一去不回。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们相处得如同一家人。", "target_word": "如同", "complexity_tier": "T3", "furigana": "lín jū men xiāng chǔ de rú tóng yì jiā rén.", "sentence_source": "generated"}, {"text": "孩子的笑声如同音乐一样好听。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市如同一幅画。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶照顾我，如同照顾自己的孩子。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新同学的发音如同中国人一样标准。", "target_word": "如同", "complexity_tier": "T3", "furigana": "xīn tóng xué de fā yīn rú tóng zhōng guó rén yí yàng biāo zhǔn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "如同……一样", "label": "固定搭配"}], "register": "书面", "sense_fingerprint": "表示比喻，相当于“好像……一样”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9007a2d-4d18-4039-ac90-907ce20042f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90480, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "如同", "is_correct": true, "explanation": "“如同”引出比拟对象，与句末的“一样”呼应，表示“好像……一样”。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示反感，与“亲姐姐一样”的亲近态度矛盾。"}, {"text": "变成", "is_correct": false, "explanation": "语义：“变成”表示转变为另一种状态，句意是比拟，不是转变。"}, {"text": "充当", "is_correct": false, "explanation": "语义：“充当”指担任某种角色，与“对我……一样”表示的情感比拟不合。"}], "explanations": {"如同": "“如同”引出比拟对象，与句末的“一样”呼应，表示“好像……一样”。", "讨厌": "语义：“讨厌”表示反感，与“亲姐姐一样”的亲近态度矛盾。", "变成": "语义：“变成”表示转变为另一种状态，句意是比拟，不是转变。", "充当": "语义：“充当”指担任某种角色，与“对我……一样”表示的情感比拟不合。"}, "sentence_index": 0, "correct_answer": "如同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我喜欢吃水果，如同苹果。", "explanation": "这里应该用〈比如〉。如同表示比拟，不能用来举例说明，举例要用“比如”。"}, {"text": "我们先吃饭，如同去散步。", "explanation": "这里应该用〈然后〉。如同表示比拟，不能表示动作的先后顺序。"}, {"text": "如同明天下雨，我们就不去了。", "explanation": "这里应该用〈如果〉。如同表示比拟，不能引出假设条件，假设要用“如果……就……”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "如同", "is_correct": true, "explanation": "“如同”表示比拟，与“一样好听”呼应，符合句意。"}, {"text": "成为", "is_correct": false, "explanation": "语义：“成为”表示变为某种身份或状态，句中要的是比拟，不是变化。"}, {"text": "看作", "is_correct": false, "explanation": "搭配：“看作”要接“把……看作……”的判断宾语，不能与“笑声”和“一样好听”的比拟搭配。"}, {"text": "具有", "is_correct": false, "explanation": "配价：“具有”后接属性名词，不能直接带“音乐一样好听”这样的比拟结构。"}], "explanations": {"如同": "“如同”表示比拟，与“一样好听”呼应，符合句意。", "成为": "语义：“成为”表示变为某种身份或状态，句中要的是比拟，不是变化。", "看作": "搭配：“看作”要接“把……看作……”的判断宾语，不能与“笑声”和“一样好听”的比拟搭配。", "具有": "配价：“具有”后接属性名词，不能直接带“音乐一样好听”这样的比拟结构。"}, "sentence_index": 6, "correct_answer": "如同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "如同考试，她每天复习到深夜。", "explanation": "这里应该用〈为了〉。如同表示比拟，不能引出目的，目的要用“为了”。"}, {"text": "如同天冷，我们取消了郊游。", "explanation": "这里应该用〈因为〉。如同表示比拟，不能引出原因，因果关系要用“因为”。"}, {"text": "他很努力，如同没考好。", "explanation": "这里应该用〈但是〉。如同表示比拟，不能表示转折，转折要用“但是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子说话很如同大人一样。", "corrected_sentence": "这个孩子说话如同大人一样。", "error_description": "错误：“很”修饰了“如同”。“如同”表示比拟，不能被程度副词修饰；应去掉“很”，写作“这个孩子说话如同大人一样。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇的夜晚如同童话安静。", "corrected_sentence": "这个小镇的夜晚如同童话一样安静。", "error_description": "错误：漏掉了“一样”。“如同……一样”后接形容词时，书面语通常保留“一样”，此句漏掉后不通顺；应在“童话”之后补上“一样”，写作“这个小镇的夜晚如同童话一样安静。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
