INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90481, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "加钱是在原来的钱上再多给一些。", "primary_collocate": null, "pronunciation": "jiā qián", "ipa": "tɕja˥ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我想加钱换个靠窗的座位。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别着急，我可以加钱，请快一点。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不肯加钱，所以没买到。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房东让我加钱，我没同意。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了尽快拿到票，他愿意加钱。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们加钱订了大一点的蛋糕。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想让师傅今天来修，你得加钱。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说：“我再加钱，行吗？”", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟想换个大一点的书包，爸爸让他加钱。", "target_word": "加钱", "complexity_tier": "T3", "furigana": "dì di xiǎng huàn ge dà yì diǎn de shū bāo, bà ba ràng tā jiā qián.", "sentence_source": "generated"}, {"text": "你加钱，老板就多送你一份。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加了钱", "label": "体标"}, {"form": "加过钱", "label": "体标"}, {"form": "加錢", "label": "繁体"}], "register": "口语", "sense_fingerprint": "在原来给的钱之外再多给一些", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0164a193-a1b9-4b34-a43a-61ec32a530f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90481, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加钱", "is_correct": true, "explanation": "加钱：在原来给的钱之外再多给一些，与“换个靠窗的座位”的意思相合。"}, {"text": "还钱", "is_correct": false, "explanation": "语义：“还钱”是归还所欠的钱，与为换座位而额外给钱的意思不合。"}, {"text": "收钱", "is_correct": false, "explanation": "语义：“收钱”是接受对方的钱，方向与“加钱”相反，不能用在这里。"}, {"text": "买钱", "is_correct": false, "explanation": "搭配：“买”不与“钱”组成动宾，不能说买钱。"}], "explanations": {"加钱": "加钱：在原来给的钱之外再多给一些，与“换个靠窗的座位”的意思相合。", "还钱": "语义：“还钱”是归还所欠的钱，与为换座位而额外给钱的意思不合。", "收钱": "语义：“收钱”是接受对方的钱，方向与“加钱”相反，不能用在这里。", "买钱": "搭配：“买”不与“钱”组成动宾，不能说买钱。"}, "sentence_index": 0, "correct_answer": "加钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我不小心弄坏了他的伞，加了他一百块钱。", "explanation": "这里应该用〈赔〉。加钱是在原来给的钱之外多给，因损坏而补偿的钱要说赔钱。"}, {"text": "我向同学加了一百块钱。", "explanation": "这里应该用〈借〉。加钱是额外给钱，向同学借钱是取得钱款，方向相反。"}, {"text": "妈妈每周从我的零花钱里加一百块钱，我的零花钱越来越少。", "explanation": "这里应该用〈扣〉。加钱是在原来的钱上再多给，从零花钱里取走一百块要说扣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90481, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加钱", "is_correct": true, "explanation": "加钱：在原来给的钱之外再多给一些，与“想让师傅今天来修”的语境相合。"}, {"text": "退钱", "is_correct": false, "explanation": "语义：“退钱”是把钱退还给对方，与为请师傅上门而需要多给钱的意思相反。"}, {"text": "收钱", "is_correct": false, "explanation": "语义：“收钱”是接受对方的钱。请师傅上门的人是付钱的一方，不是收钱的一方，不能用在这里。"}, {"text": "罚款", "is_correct": false, "explanation": "语义：“罚款”是因违规被处罚而交钱，与请师傅上门修理的意思无关。"}], "explanations": {"加钱": "加钱：在原来给的钱之外再多给一些，与“想让师傅今天来修”的语境相合。", "退钱": "语义：“退钱”是把钱退还给对方，与为请师傅上门而需要多给钱的意思相反。", "收钱": "语义：“收钱”是接受对方的钱。请师傅上门的人是付钱的一方，不是收钱的一方，不能用在这里。", "罚款": "语义：“罚款”是因违规被处罚而交钱，与请师傅上门修理的意思无关。"}, "sentence_index": 6, "correct_answer": "加钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在工地加两百块钱，累得不行。", "explanation": "这里应该用〈赚〉。加钱是在原来的钱上多给，靠劳动得到钱要说赚钱。"}, {"text": "他迟到了，被老板从工资里加走了三百块钱。", "explanation": "这里应该用〈扣〉。加钱是额外给钱，从工资里减去钱要说扣。"}, {"text": "他偷偷把朋友的三百块钱加走了，朋友很生气。", "explanation": "这里应该用〈拿〉。加钱是额外给钱，把别人的钱拿走要说拿走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90481, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想换个靠窗的座位，得很加钱才行。", "corrected_sentence": "我想换个靠窗的座位，得加钱才行。", "error_description": "错误：程度副词“很”不能修饰动宾结构“加钱”，“很”一般修饰形容词。正确形式是“得加钱才行”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90481, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他为了快点拿到票，愿意加钱一百块钱。", "corrected_sentence": "他为了快点拿到票，愿意加一百块钱。", "error_description": "错误：宾语“钱”重复出现，“加钱”之后又接了“一百块钱”。正确形式是“加一百块钱”，数量短语放在动词与宾语“钱”之间，只保留一个“钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
