INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90482, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在原来的价钱上再增加钱款。", "primary_collocate": null, "pronunciation": "jiā qián", "ipa": "tɕja˥ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "想住大房间，你就得加钱。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机说去机场路远，要加钱。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人想多要一份菜，得加钱。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店送货上门要加钱。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想让东西快一点送到，需要加钱。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他愿意加钱，才买到那张票。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板，我加钱，能不能今天做好？", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服要加钱才能定做。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店说多住一个人就得加钱。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原价已经很高了，别再加钱了。", "target_word": "加钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加了钱", "label": "体标"}, {"form": "加过钱", "label": "体标"}, {"form": "加錢", "label": "繁体"}], "register": "口语", "sense_fingerprint": "在原价基础上再多付钱款", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0164a193-a1b9-4b34-a43a-61ec32a530f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加钱", "is_correct": true, "explanation": "加钱：在原价基础上再多付钱，与“想住大房间”需要多付钱的意思相合。"}, {"text": "降价", "is_correct": false, "explanation": "语义：“降价”是降低价格，与“想住大房间”需要多付钱的意思相反。"}, {"text": "退钱", "is_correct": false, "explanation": "语义：“退钱”是把钱退还给对方，与需要多付钱的意思相反。"}, {"text": "买钱", "is_correct": false, "explanation": "搭配：“买”不与“钱”组成动宾，不能说买钱。"}], "explanations": {"加钱": "加钱：在原价基础上再多付钱，与“想住大房间”需要多付钱的意思相合。", "降价": "语义：“降价”是降低价格，与“想住大房间”需要多付钱的意思相反。", "退钱": "语义：“退钱”是把钱退还给对方，与需要多付钱的意思相反。", "买钱": "搭配：“买”不与“钱”组成动宾，不能说买钱。"}, "sentence_index": 0, "correct_answer": "加钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "收银员加给我十块钱。", "explanation": "这里应该用〈找〉。加钱是在原价上多付钱，找钱是把多收的钱退还给顾客，方向相反。"}, {"text": "他向灾区加了一千块钱。", "explanation": "这里应该用〈捐〉。加钱是为了买到东西或服务而在原价上多付，捐钱是无偿送给别人。"}, {"text": "他把我的伞弄坏了，加了我一百块钱。", "explanation": "这里应该用〈赔〉。加钱指买东西时在原价上多付，因损坏而付的补偿要说赔钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加钱", "is_correct": true, "explanation": "加钱：在原价基础上再多付钱，与“老板，我”请求加急的语境相合。"}, {"text": "还钱", "is_correct": false, "explanation": "语义：“还钱”是归还欠款，与请老板今天做好的请求不相合。"}, {"text": "催促", "is_correct": false, "explanation": "配价：“催促”要带受催促的对象，如“催促老板”，这里单独不能成立。"}, {"text": "投诉", "is_correct": false, "explanation": "语义：“投诉”是向有关方面反映不满，与请老板今天做好的请求无关。"}], "explanations": {"加钱": "加钱：在原价基础上再多付钱，与“老板，我”请求加急的语境相合。", "还钱": "语义：“还钱”是归还欠款，与请老板今天做好的请求不相合。", "催促": "配价：“催促”要带受催促的对象，如“催促老板”，这里单独不能成立。", "投诉": "语义：“投诉”是向有关方面反映不满，与请老板今天做好的请求无关。"}, "sentence_index": 6, "correct_answer": "加钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他按时加了朋友的钱。", "explanation": "这里应该用〈还〉。加钱指在原价上多付，偿还所借的钱要说还钱。"}, {"text": "我向朋友加了一千块钱。", "explanation": "这里应该用〈借〉。加钱是在原价上多付，向朋友取得钱款要说借钱。"}, {"text": "他违规停车，被交警加了两百块钱。", "explanation": "这里应该用〈罚〉。因违规被处罚交的钱要说“罚了两百块钱”。加钱是自愿在原价上多付，不能表示强制收取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "想要升级房型，就得很加钱。", "corrected_sentence": "想要升级房型，就得加钱。", "error_description": "错误：程度副词“很”不能修饰动宾结构“加钱”，“很”一般修饰形容词。正确形式是“就得加钱”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板，我加钱一百块钱，能不能今天做好？", "corrected_sentence": "老板，我加一百块钱，能不能今天做好？", "error_description": "错误：宾语“钱”重复出现，“加钱”之后又接了“一百块钱”。正确形式是“加一百块钱”，数量短语放在动词与宾语“钱”之间，只保留一个“钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90483, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小号", "is_correct": true, "explanation": "正确。小号与大号是尺寸上相对的一对反义词。"}, {"text": "尺码", "is_correct": false, "explanation": "不构成反义：尺码只是尺寸的标号，本身并不与“大号”相对。"}, {"text": "尺寸", "is_correct": false, "explanation": "不构成反义：尺寸泛指大小，与“大号”不是相对的一对词。"}, {"text": "码数", "is_correct": false, "explanation": "不构成反义：码数只是尺码的数字说法，不与“大号”相对。"}], "correct_answer": "小号", "explanations": {"小号": "正确。小号与大号是尺寸上相对的一对反义词。", "尺码": "不构成反义：尺码只是尺寸的标号，本身并不与“大号”相对。", "尺寸": "不构成反义：尺寸泛指大小，与“大号”不是相对的一对词。", "码数": "不构成反义：码数只是尺码的数字说法，不与“大号”相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90483, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小号", "is_correct": true, "explanation": "正确。小号与大号是尺寸上相对的一对反义词。"}, {"text": "体积", "is_correct": false, "explanation": "不构成反义：体积指物体所占的空间，与“大号”不是相对的词。"}, {"text": "容量", "is_correct": false, "explanation": "不构成反义：容量说能装多少，不与“大号”相对。"}, {"text": "尺度", "is_correct": false, "explanation": "不构成反义：尺度指衡量的标准，不与“大号”相对。"}], "correct_answer": "小号", "explanations": {"小号": "正确。小号与大号是尺寸上相对的一对反义词。", "体积": "不构成反义：体积指物体所占的空间，与“大号”不是相对的词。", "容量": "不构成反义：容量说能装多少，不与“大号”相对。", "尺度": "不构成反义：尺度指衡量的标准，不与“大号”相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90483, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "大号是比一般的更大的尺寸。", "primary_collocate": null, "pronunciation": "dà hào", "ipa": "ta˥˩ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这件外套有大号和小号。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里没有大号的运动鞋了。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一个大号的书包。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个子高，要穿大号的衬衫。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的大号披萨很便宜。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子穿不了大号的衣服。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问这种帽子有大号吗？", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把大号的盒子放在最下面。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大号的雨伞可以两个人用。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子是大号的，能装很多水。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词；衣物、用品等比一般更大的尺寸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc92a6b-6dc2-4a5f-9877-7bf97a1744bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90483, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大号", "is_correct": true, "explanation": "正确。大号指衣物、用品等比一般更大的尺寸。"}, {"text": "代号", "is_correct": false, "explanation": "dài 与 dà 只差韵母（多一个 i），意思是代号，指代替真实名称的符号。"}, {"text": "大好", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，意思是大好，即很好。"}, {"text": "打好", "is_correct": false, "explanation": "dǎ hǎo 与 dà hào 两个音节的声调都不同，意思是打好，即做好。"}], "explanations": {"大号": "正确。大号指衣物、用品等比一般更大的尺寸。", "代号": "dài 与 dà 只差韵母（多一个 i），意思是代号，指代替真实名称的符号。", "大好": "hǎo（第三声）与 hào（第四声）声调不同，意思是大好，即很好。", "打好": "dǎ hǎo 与 dà hào 两个音节的声调都不同，意思是打好，即做好。"}, "sentence_index": null, "correct_answer": "大号"}, "level_3": {"options": [{"text": "大号", "is_correct": true, "explanation": "正确。“有大号和小号”是衣物的两种尺寸并列，“大号”正好填入。"}, {"text": "长袖", "is_correct": false, "explanation": "语义：“长袖”说袖子的长短，与“小号”不是同类尺寸，不能并列。"}, {"text": "红色", "is_correct": false, "explanation": "语义：“红色”说颜色，与“小号”不能并列为同类选项。"}, {"text": "圆领", "is_correct": false, "explanation": "搭配：“和小号”并列的必须是尺码，“圆领”是领口形状，不作尺码。"}], "explanations": {"大号": "正确。“有大号和小号”是衣物的两种尺寸并列，“大号”正好填入。", "长袖": "语义：“长袖”说袖子的长短，与“小号”不是同类尺寸，不能并列。", "红色": "语义：“红色”说颜色，与“小号”不能并列为同类选项。", "圆领": "搭配：“和小号”并列的必须是尺码，“圆领”是领口形状，不作尺码。"}, "sentence_index": 0, "correct_answer": "大号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在乐队里吹大号，声音很响亮。", "explanation": "这里的“大号”指铜管乐器，与衬衫的尺寸无关。"}, {"text": "这个大号的任务很难完成。", "explanation": "“大号”只用于衣服、用品等有尺码的物品，不能修饰任务；任务难度大应说“艰巨”。"}, {"text": "今天的风是大号的，我们别出去了。", "explanation": "“大号”只用于衣物、用品等有尺码的东西，不能形容风；应说“风很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90483, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大号", "is_correct": true, "explanation": "正确。大号指衣物、用品等比一般更大的尺寸。"}, {"text": "大道", "is_correct": false, "explanation": "dào 与 hào 声母不同（d 与 h），意思是大道，即光明正大的道理。"}, {"text": "大祸", "is_correct": false, "explanation": "huò 与 hào 韵母不同（uo 与 ao），意思是大祸，指重大的灾祸。"}, {"text": "大好", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，意思是大好，即很好、极好。"}], "explanations": {"大号": "正确。大号指衣物、用品等比一般更大的尺寸。", "大道": "dào 与 hào 声母不同（d 与 h），意思是大道，即光明正大的道理。", "大祸": "huò 与 hào 韵母不同（uo 与 ao），意思是大祸，指重大的灾祸。", "大好": "hǎo（第三声）与 hào（第四声）声调不同，意思是大好，即很好、极好。"}, "sentence_index": null, "correct_answer": "大号"}, "level_3": {"options": [{"text": "大号", "is_correct": true, "explanation": "正确。问的是这种帽子有没有大号的尺寸。"}, {"text": "袜子", "is_correct": false, "explanation": "语义：帽子不是袜子，“这种帽子有袜子吗”说不通。"}, {"text": "鞋号", "is_correct": false, "explanation": "搭配：“鞋号”是鞋的尺码，不能用于帽子。"}, {"text": "身高", "is_correct": false, "explanation": "语义：帽子没有“身高”这一规格，问“有没有身高”说不通。"}], "explanations": {"大号": "正确。问的是这种帽子有没有大号的尺寸。", "袜子": "语义：帽子不是袜子，“这种帽子有袜子吗”说不通。", "鞋号": "搭配：“鞋号”是鞋的尺码，不能用于帽子。", "身高": "语义：帽子没有“身高”这一规格，问“有没有身高”说不通。"}, "sentence_index": 6, "correct_answer": "大号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用大号在网上发了一条消息。", "explanation": "这里的“大号”指网络上的主要账号，是另一个义项，与杯子的尺寸无关。"}, {"text": "他的成绩有大号的进步。", "explanation": "这里的“大号”只说物品尺寸，不能形容进步的程度；进步大要说“大幅进步”或“进步很大”。"}, {"text": "他今天的声音是大号的，大家都听见了。", "explanation": "“大号”只说物品尺码，不能形容声音；应说“声音很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90483, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次考试遇到了一个大号的问题。", "corrected_sentence": "这次考试遇到了一个很大的问题。", "error_description": "错误：“大号”指衣物、用品的尺码，不能修饰“问题”。正确：应说“很大的问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90483, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这道题的难度是大号的。", "corrected_sentence": "这道题的难度很大。", "error_description": "错误：“大号”只用于有尺码的物品，不能形容难度。正确：应说“难度很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8bbff8-cc96-4ee9-928d-03caad23fd0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
