INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90485, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "会不会受伤、出危险的事。", "primary_collocate": null, "pronunciation": "ān quán wèn tí", "ipa": "an⁵⁵ tɕʰyɛn³⁵ wən⁵¹ tʰi³⁵", "syllable_count": 4, "sentences": [{"text": "孩子一个人出门，我担心安全问题。", "target_word": "安全问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬山时要注意安全问题。", "target_word": "安全问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路晚上没有灯，有安全问题。", "target_word": "安全问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳前先想想安全问题。", "target_word": "安全问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车不戴头盔，会有安全问题。", "target_word": "安全问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师提醒大家注意安全问题。", "target_word": "安全问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥太旧了，有安全问题。", "target_word": "安全问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在河边玩，家长很担心安全问题。", "target_word": "安全问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐车时系好安全带，就没有安全问题。", "target_word": "安全问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路滑的时候开车有安全问题。", "target_word": "安全问题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "通用", "sense_fingerprint": "会不会受伤、出危险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1bdeefd-92f9-4e14-bb18-a5d8568bc61c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90485, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安全问题", "is_correct": true, "explanation": "正确：“担心”后接“安全问题”，指孩子一个人出门可能受伤或遇到危险。"}, {"text": "价格", "is_correct": false, "explanation": "语义：孩子一个人出门，担心的是危险，“价格”与出门的危险无关，句子不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“担心”后面接“颜色”不自然，“颜色”也与一个人出门的情境无关。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”与一个人出门没有关系，整句读起来不通。"}], "explanations": {"安全问题": "正确：“担心”后接“安全问题”，指孩子一个人出门可能受伤或遇到危险。", "价格": "语义：孩子一个人出门，担心的是危险，“价格”与出门的危险无关，句子不通。", "颜色": "搭配：“担心”后面接“颜色”不自然，“颜色”也与一个人出门的情境无关。", "味道": "语义：“味道”与一个人出门没有关系，整句读起来不通。"}, "sentence_index": 0, "correct_answer": "安全问题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在陌生的城市里，她有很强的安全问题。", "explanation": "这里应该用〈安全感〉。安全感指内心踏实，“安全问题”指会受伤或出危险的事，不能用“很强”来修饰人的心理。"}, {"text": "这道数学安全问题我想了一个小时，还是没做出来。", "explanation": "这里应该用〈数学题〉。“安全问题”指会受伤或出危险的事，不能用来指一道数学题。"}, {"text": "今天的安全问题很好，我们去公园吧。", "explanation": "这里应该用〈天气〉。“安全问题”指会受伤或出危险的事，不能用来形容天气好不好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90485, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安全问题", "is_correct": true, "explanation": "正确：“有”后接“安全问题”，与“桥太旧了”的原因相符。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：桥太旧了，不能说“有歌曲”，“歌曲”与桥的状况没有关系。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“有”后接“脾气”一般指人，不能说桥“有脾气”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“有天气”与“桥太旧了”没有逻辑关系，句子读起来不通。"}], "explanations": {"安全问题": "正确：“有”后接“安全问题”，与“桥太旧了”的原因相符。", "歌曲": "语义：桥太旧了，不能说“有歌曲”，“歌曲”与桥的状况没有关系。", "脾气": "搭配：“有”后接“脾气”一般指人，不能说桥“有脾气”。", "天气": "语义：“有天气”与“桥太旧了”没有逻辑关系，句子读起来不通。"}, "sentence_index": 6, "correct_answer": "安全问题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子的安全问题很漂亮。", "explanation": "这里应该用〈画〉。“安全问题”指会不会受伤或出危险的事，不能用来说东西漂亮。"}, {"text": "他昨天有安全问题，发烧到三十八度。", "explanation": "这里应该用〈病〉。“安全问题”指会受伤或出危险的事，不能用来说人发烧、生病。"}, {"text": "这盘菜的安全问题太咸了。", "explanation": "这里应该用〈味道〉。“安全问题”指会不会受伤、出危险的事，不能用来说菜的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90485, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爬山时，我们发现了一只安全问题，需要马上处理。", "corrected_sentence": "爬山时，我们发现了一个安全问题，需要马上处理。", "error_description": "量词错误：“安全问题”的量词应为“个”。“只”用于动物或成对的东西，不能说“一只安全问题”，应说“一个安全问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90485, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "专家们把安全问题处理很好。", "corrected_sentence": "专家们把安全问题处理得很好。", "error_description": "补语错误：状态补语前漏了结构助词“得”。应说“处理得很好”，不能说“处理很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
