INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90487, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动摇是本来很坚定，后来变得不太确定了。", "primary_collocate": null, "pronunciation": "dòng yáo", "ipa": "tʊŋ˥˩ jɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "听了大家的话，他的决心开始动摇了。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直很坚定，从来没有动摇过。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对困难，他的信心有点动摇。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我本来想辞职，现在有些动摇了。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的立场动摇了，不知道该选哪边。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸很坚定，一点儿也不动摇。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到别人成功，她的想法动摇了。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里一直动摇着，下不了决心。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "连续失败后，球队的信心动摇了。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然很累，我也没有动摇。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "动摇了", "label": "体标"}, {"form": "动摇着", "label": "体标"}, {"form": "动摇过", "label": "体标"}, {"form": "動搖", "label": "繁体"}], "register": "中性", "sense_fingerprint": "原本坚定，后来变得不确定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36662012-8007-41fe-a78e-aaa6e4d441d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90487, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动摇", "is_correct": true, "explanation": "正确。“动摇”指原本坚定的变得不确定，与句意相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不能以决心作宾语。"}, {"text": "退休", "is_correct": false, "explanation": "搭配：“退休”用于人离开工作岗位，不能以决心作主语。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：“生病”的主语必须是人或动物，不能是决心。"}], "explanations": {"动摇": "正确。“动摇”指原本坚定的变得不确定，与句意相符。", "修理": "搭配：“修理”的对象是器物，不能以决心作宾语。", "退休": "搭配：“退休”用于人离开工作岗位，不能以决心作主语。", "生病": "搭配：“生病”的主语必须是人或动物，不能是决心。"}, "sentence_index": 0, "correct_answer": "动摇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的决心非常坚定，所以早就动摇了。", "explanation": "语义：“动摇”指原本坚定的变得不确定，与“非常坚定”矛盾，这里应该用〈坚定〉。"}, {"text": "他对这个决定毫不怀疑，却一直动摇。", "explanation": "语义：毫不怀疑与动摇相矛盾，这里应该用〈坚定〉。"}, {"text": "他这次考得很好，因此信心动摇了。", "explanation": "语义：考得好不会使信心动摇，这里应该用〈增强〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90487, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动摇", "is_correct": true, "explanation": "正确。“动摇”表示想法变得不确定，与句意相符。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：“发烧”是身体的状况，不能用于想法。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：“下雨”的主语不能是想法。"}, {"text": "睡着", "is_correct": false, "explanation": "语义：想法不会睡着，句中讲的是想法发生了变化。"}], "explanations": {"动摇": "正确。“动摇”表示想法变得不确定，与句意相符。", "发烧": "搭配：“发烧”是身体的状况，不能用于想法。", "下雨": "搭配：“下雨”的主语不能是想法。", "睡着": "语义：想法不会睡着，句中讲的是想法发生了变化。"}, "sentence_index": 6, "correct_answer": "动摇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经过这次训练，他的决心变得更加动摇了。", "explanation": "语义：“动摇”表示原本坚定的变得不确定，训练后决心更强，这里应该用〈坚定〉。"}, {"text": "他对这件事非常动摇，却丝毫没有犹豫。", "explanation": "语义：“动摇”表示犹豫不定，与“丝毫没有犹豫”矛盾，这里应该用〈坚决〉。"}, {"text": "他说话动摇，一点也不慌。", "explanation": "语义：“动摇”表示变得不确定，不能修饰“说话”，且与“一点也不慌”矛盾，这里应该用〈从容〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的决心很动摇了。", "corrected_sentence": "他的决心有些动摇了。", "error_description": "错误：“动摇”不能直接用“很”修饰，表示程度轻微应改用“有些”，即“有些动摇了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到这个消息，她的想法动摇着了。", "corrected_sentence": "听到这个消息，她的想法动摇了。", "error_description": "错误：“着”表示持续，“了”表示变化已完成，二者不能连用为“动摇着了”，这里应改为“动摇了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90488, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
