INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90488, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不稳固，使坚定的想法发生变化。", "primary_collocate": null, "pronunciation": "dòng yáo", "ipa": "tʊŋ˥˩ jɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "这些话动摇不了我的决心。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏消息动摇了大家的信心。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不能动摇他的想法。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次失败动摇不了我们的信念。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人想用钱动摇他的立场。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个谣言动摇了军心。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话动摇了他放弃的念头。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别让坏朋友动摇你的决定。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格下降动摇了商家的信心。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的眼泪动摇了他的态度。", "target_word": "动摇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "动摇了", "label": "体标"}, {"form": "动摇着", "label": "体标"}, {"form": "动摇过", "label": "体标"}, {"form": "動搖", "label": "繁体"}], "register": "中性", "sense_fingerprint": "使坚定的想法或信心发生变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36662012-8007-41fe-a78e-aaa6e4d441d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动摇", "is_correct": true, "explanation": "正确。“动摇不了”表示话不能使决心发生变化，与句意相符。"}, {"text": "测量", "is_correct": false, "explanation": "语义：话不能被测量，句中指的是话对决心的影响。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：决心不能被搬运，与句意不符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能以决心作宾语，表示影响决心应用“动摇”。"}], "explanations": {"动摇": "正确。“动摇不了”表示话不能使决心发生变化，与句意相符。", "测量": "语义：话不能被测量，句中指的是话对决心的影响。", "搬运": "语义：决心不能被搬运，与句意不符。", "吃": "搭配：“吃”不能以决心作宾语，表示影响决心应用“动摇”。"}, "sentence_index": 0, "correct_answer": "动摇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向前动摇了一步。", "explanation": "这里应该用〈迈〉。“动摇”表示使坚定的想法发生变化，不表示向前移动。"}, {"text": "他动摇地走过了马路。", "explanation": "这里应该用〈摇晃〉。“动摇”不用于修饰走路，走路不稳应说〈摇晃〉。"}, {"text": "他的决心非常坚定，一次失败反而动摇得更坚定。", "explanation": "语义：“动摇”表示使坚定的想法发生变化，与句中“更坚定”的意思相反，这里应该用〈增强〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动摇", "is_correct": true, "explanation": "正确。“动摇”指使想法发生变化，与“放弃的念头”相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”的对象是请求、建议等，不能用于念头。"}, {"text": "绘画", "is_correct": false, "explanation": "语义：念头不能被绘画，句中指念头受到影响。"}, {"text": "烤", "is_correct": false, "explanation": "语义：念头不能被烤，与句意不符。"}], "explanations": {"动摇": "正确。“动摇”指使想法发生变化，与“放弃的念头”相符。", "拒绝": "搭配：“拒绝”的对象是请求、建议等，不能用于念头。", "绘画": "语义：念头不能被绘画，句中指念头受到影响。", "烤": "语义：念头不能被烤，与句意不符。"}, "sentence_index": 6, "correct_answer": "动摇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的眼泪动摇了他的眼睛。", "explanation": "这里应该用〈模糊〉。“动摇”的对象是想法、态度，不能是眼睛；泪水使视线不清应用〈模糊〉。"}, {"text": "她的眼泪动摇了他的衣服。", "explanation": "这里应该用〈打湿〉。“动摇”不能用于衣服，泪水弄湿衣服应用〈打湿〉。"}, {"text": "她的眼泪动摇得他哭了。", "explanation": "这里应该用〈惹〉。“动摇”不表示使人哭，使人哭应用〈惹〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种小事动摇不了了我的决心。", "corrected_sentence": "这种小事动摇不了我的决心。", "error_description": "错误：“动摇不了”已经表示否定，后面不能再加“了”，应去掉多余的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "别把坏消息动摇你的决心。", "corrected_sentence": "别让坏消息动摇你的决心。", "error_description": "错误：“把”后应接被处置的对象（此处是“你的决心”），“坏消息”是致使者，应改用“让”，即“别让坏消息动摇你的决心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90489, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开", "is_correct": true, "explanation": "开与封互为反义：封是关闭使不能打开，开是打开。"}, {"text": "洗", "is_correct": false, "explanation": "洗与封没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱与封没有对立关系。"}, {"text": "写", "is_correct": false, "explanation": "写与封没有反义关系。"}], "correct_answer": "开", "explanations": {"开": "开与封互为反义：封是关闭使不能打开，开是打开。", "洗": "洗与封没有反义关系。", "唱": "唱与封没有对立关系。", "写": "写与封没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90489, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开", "is_correct": true, "explanation": "开与封互为反义：封使其不能打开，开即打开。"}, {"text": "画", "is_correct": false, "explanation": "画与封没有反义关系。"}, {"text": "跳", "is_correct": false, "explanation": "跳与封没有对立关系。"}, {"text": "送", "is_correct": false, "explanation": "送与封没有反义关系。"}], "correct_answer": "开", "explanations": {"开": "开与封互为反义：封使其不能打开，开即打开。", "画": "画与封没有反义关系。", "跳": "跳与封没有对立关系。", "送": "送与封没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90489, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "封是把东西关上，不让它打开。", "primary_collocate": null, "pronunciation": "fēng", "ipa": "fɤŋ˥", "syllable_count": 1, "sentences": [{"text": "他把箱子用胶带封好了。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个瓶子的口封上。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把罐子封住，放进冰箱。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "寄东西以前，要先把盒子封好。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用纸把窗户封上了。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个袋子没有封好，水都流出来了。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的外壳要封好，防止灰尘进去。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用砖把门封上了。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把包裹封好，交给了快递员。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶口封得很紧，我打不开。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "封了", "label": "体标"}, {"form": "封着", "label": "体标"}, {"form": "封过", "label": "体标"}, {"form": "封口", "label": "复合"}], "register": "中性", "sense_fingerprint": "把箱子、瓶口、门窗等关上封住，使其不能打开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2a424d-fb6a-4c27-a32b-e3eed49ee37f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90489, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "封", "is_correct": true, "explanation": "封 fēng 即本词，指把箱子、瓶口、门窗等关上封住。"}, {"text": "凤", "is_correct": false, "explanation": "fèng（第四声）与 fēng（第一声）声调不同，意思是凤凰。"}, {"text": "缝", "is_correct": false, "explanation": "féng（第二声）与 fēng（第一声）声调不同，意思是缝合。"}, {"text": "分", "is_correct": false, "explanation": "fēn 与 fēng 的韵母 en 与 eng 不同，意思是分开。"}], "explanations": {"封": "封 fēng 即本词，指把箱子、瓶口、门窗等关上封住。", "凤": "fèng（第四声）与 fēng（第一声）声调不同，意思是凤凰。", "缝": "féng（第二声）与 fēng（第一声）声调不同，意思是缝合。", "分": "fēn 与 fēng 的韵母 en 与 eng 不同，意思是分开。"}, "sentence_index": null, "correct_answer": "封"}, "level_3": {"options": [{"text": "封", "is_correct": true, "explanation": "封好指把箱子封住，与「用胶带」搭配，句意通顺。"}, {"text": "擦", "is_correct": false, "explanation": "语义：用胶带擦箱子不合常理，「擦」不表示封住。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」只说衣服、鞋袜，不能用于箱子。"}, {"text": "染", "is_correct": false, "explanation": "配价：「染」需要的对象是布料或颜料，不能用胶带来染箱子。"}], "explanations": {"封": "封好指把箱子封住，与「用胶带」搭配，句意通顺。", "擦": "语义：用胶带擦箱子不合常理，「擦」不表示封住。", "穿": "搭配：「穿」只说衣服、鞋袜，不能用于箱子。", "染": "配价：「染」需要的对象是布料或颜料，不能用胶带来染箱子。"}, "sentence_index": 0, "correct_answer": "封"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出门前，他把桌子封干净了。", "explanation": "这里应该用〈擦〉。封指封住使不能打开，不能用来表示把桌子弄干净。"}, {"text": "他用斧子把木头封断了。", "explanation": "这里应该用〈砍〉。封指封住使不能打开，不能表示用斧子把木头砍断。"}, {"text": "他把通知封在墙上。", "explanation": "这里应该用〈贴〉。封是封住口子，不能表示把纸张粘在墙面上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90489, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "封", "is_correct": true, "explanation": "封 fēng 即本词，指把东西关上封住，使其不能打开。"}, {"text": "逢", "is_correct": false, "explanation": "féng（第二声）与 fēng（第一声）声调不同，意思是遇见。"}, {"text": "奉", "is_correct": false, "explanation": "fèng（第四声）与 fēng（第一声）声调不同，意思是奉献、供奉。"}, {"text": "讽", "is_correct": false, "explanation": "fěng（第三声）与 fēng（第一声）声调不同，意思是讽刺。"}], "explanations": {"封": "封 fēng 即本词，指把东西关上封住，使其不能打开。", "逢": "féng（第二声）与 fēng（第一声）声调不同，意思是遇见。", "奉": "fèng（第四声）与 fēng（第一声）声调不同，意思是奉献、供奉。", "讽": "fěng（第三声）与 fēng（第一声）声调不同，意思是讽刺。"}, "sentence_index": null, "correct_answer": "封"}, "level_3": {"options": [{"text": "封", "is_correct": true, "explanation": "封好指封住外壳，与「防止灰尘进去」的目的相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：外壳不能煮，与防止灰尘进去的目的无关。"}, {"text": "念", "is_correct": false, "explanation": "配价：「念」的对象是文字，不能说「外壳」。"}, {"text": "切", "is_correct": false, "explanation": "语义：切外壳会破坏机器，与防止灰尘进去的目的相矛盾。"}], "explanations": {"封": "封好指封住外壳，与「防止灰尘进去」的目的相符。", "煮": "语义：外壳不能煮，与防止灰尘进去的目的无关。", "念": "配价：「念」的对象是文字，不能说「外壳」。", "切": "语义：切外壳会破坏机器，与防止灰尘进去的目的相矛盾。"}, "sentence_index": 6, "correct_answer": "封"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把饺子封熟了，端上了桌。", "explanation": "这里应该用〈煮〉。封指封住使不能打开，不能表示加热使食物变熟。"}, {"text": "他用剪刀把纸封开了。", "explanation": "这里应该用〈剪〉。封是封住口子，不能表示用剪刀把纸分开。"}, {"text": "他在合同上封了一个章。", "explanation": "这里应该用〈盖〉。封指封住使不能打开，在文件上盖章要用〈盖〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90489, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把饮料瓶的瓶口封了紧，免得洒出来。", "corrected_sentence": "他把饮料瓶的瓶口封紧了，免得洒出来。", "error_description": "了的位置错误：「封」与结果补语「紧」之间不能加「了」，应说「封紧了」，不能说「封了紧」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90489, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个盒子我已经封了好，明天寄出去。", "corrected_sentence": "这个盒子我已经封好了，明天寄出去。", "error_description": "了的位置错误：结果补语「好」之后要加「了」，应说「封好了」，不能说「封了好」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
