INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90490, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "关闭；用东西把口子盖住或粘住。", "primary_collocate": null, "pronunciation": "fēng", "ipa": "fɤŋ˥", "syllable_count": 1, "sentences": [{"text": "他用蜡把瓶口封住了。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个洞太大，要用水泥封住。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "封上口子以后，水就不会漏了。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用胶带把纸箱封起来。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用胶带把袋子口封得很紧。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以前，我们把窗户封上了。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把路封了，车不能过。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，他用布把窗缝封住。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店的门封着，没有人。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王用纸把杯口封好。", "target_word": "封", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "封了", "label": "体标"}, {"form": "封着", "label": "体标"}, {"form": "封过", "label": "体标"}, {"form": "封口", "label": "复合"}], "register": "中性", "sense_fingerprint": "用东西盖住或粘住口子、缝隙，或把路口等关闭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2a424d-fb6a-4c27-a32b-e3eed49ee37f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90490, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "封", "is_correct": true, "explanation": "封 fēng 即本词，指用东西盖住或粘住口子。"}, {"text": "凤", "is_correct": false, "explanation": "fèng（第四声）与 fēng（第一声）声调不同，意思是凤凰。"}, {"text": "缝", "is_correct": false, "explanation": "féng（第二声）与 fēng（第一声）声调不同，意思是缝合。"}, {"text": "分", "is_correct": false, "explanation": "fēn 与 fēng 的韵母 en 与 eng 不同，意思是分开。"}], "explanations": {"封": "封 fēng 即本词，指用东西盖住或粘住口子。", "凤": "fèng（第四声）与 fēng（第一声）声调不同，意思是凤凰。", "缝": "féng（第二声）与 fēng（第一声）声调不同，意思是缝合。", "分": "fēn 与 fēng 的韵母 en 与 eng 不同，意思是分开。"}, "sentence_index": null, "correct_answer": "封"}, "level_3": {"options": [{"text": "封", "is_correct": true, "explanation": "封住指用蜡把瓶口盖严，与「用蜡」相符。"}, {"text": "擦", "is_correct": false, "explanation": "语义：用蜡擦住瓶口说不通，「擦」不表示盖住或粘住。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」不能用于瓶口。"}, {"text": "切", "is_correct": false, "explanation": "配价：「切」需要切割的对象，蜡不能用来切瓶口。"}], "explanations": {"封": "封住指用蜡把瓶口盖严，与「用蜡」相符。", "擦": "语义：用蜡擦住瓶口说不通，「擦」不表示盖住或粘住。", "穿": "搭配：「穿」不能用于瓶口。", "切": "配价：「切」需要切割的对象，蜡不能用来切瓶口。"}, "sentence_index": 0, "correct_answer": "封"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请用水把衣服封干净。", "explanation": "这里应该用〈洗〉。封指盖住或粘住口子，不能表示把衣服洗干净。"}, {"text": "他把杯子封碎了。", "explanation": "这里应该用〈摔〉。封指盖住或粘住口子，不能表示把杯子弄碎。"}, {"text": "请用锅把汤封热。", "explanation": "这里应该用〈煮〉。封不能表示加热使汤变热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90490, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "封", "is_correct": true, "explanation": "封 fēng 即本词，指用东西盖住或粘住口子。"}, {"text": "逢", "is_correct": false, "explanation": "féng（第二声）与 fēng（第一声）声调不同，意思是遇见。"}, {"text": "奉", "is_correct": false, "explanation": "fèng（第四声）与 fēng（第一声）声调不同，意思是奉献、供奉。"}, {"text": "讽", "is_correct": false, "explanation": "fěng（第三声）与 fēng（第一声）声调不同，意思是讽刺。"}], "explanations": {"封": "封 fēng 即本词，指用东西盖住或粘住口子。", "逢": "féng（第二声）与 fēng（第一声）声调不同，意思是遇见。", "奉": "fèng（第四声）与 fēng（第一声）声调不同，意思是奉献、供奉。", "讽": "fěng（第三声）与 fēng（第一声）声调不同，意思是讽刺。"}, "sentence_index": null, "correct_answer": "封"}, "level_3": {"options": [{"text": "封", "is_correct": true, "explanation": "封路指把道路封闭，车辆无法通行，与「车不能过」相符。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗路与车不能过无关，不表示封闭。"}, {"text": "扛", "is_correct": false, "explanation": "配价：「扛」要求的对象是可以搬动的物品，道路不能被扛。"}, {"text": "拍", "is_correct": false, "explanation": "语义：拍路与车不能过无关，不表示封闭道路。"}], "explanations": {"封": "封路指把道路封闭，车辆无法通行，与「车不能过」相符。", "洗": "语义：洗路与车不能过无关，不表示封闭。", "扛": "配价：「扛」要求的对象是可以搬动的物品，道路不能被扛。", "拍": "语义：拍路与车不能过无关，不表示封闭道路。"}, "sentence_index": 6, "correct_answer": "封"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小王用刀把西瓜封开了。", "explanation": "这里应该用〈切〉。封指盖住或粘住口子，不能表示用刀把物体分开。"}, {"text": "小王用烤箱把面包封熟了。", "explanation": "这里应该用〈烤〉。封不能表示加热使食物变熟。"}, {"text": "他把茶叶封在水里。", "explanation": "这里应该用〈泡〉。封指盖住或粘住口子，不能表示把茶叶浸在水中，泡茶要用〈泡〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用蜡把酒瓶口封了住，防止漏气。", "corrected_sentence": "他用蜡把酒瓶口封住了，防止漏气。", "error_description": "了的位置错误：结果补语「住」之后要加「了」，应说「封住了」，不能说「封了住」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我用纸把杯口封了严，别让热气跑出来。", "corrected_sentence": "我用纸把杯口封严了，别让热气跑出来。", "error_description": "了的位置错误：「封」与结果补语「严」之间不能加「了」，应说「封严了」，不能说「封了严」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
