INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90493, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "勋章是给做出大贡献的人戴的一枚好看的徽章。", "primary_collocate": null, "pronunciation": "xūn zhāng", "ipa": "ɕyn˥ ʈʂaŋ˥", "syllable_count": 2, "sentences": [{"text": "他的胸前戴着一枚勋章。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这枚勋章是金色的。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷把勋章放在盒子里。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的勋章闪着光。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都想看看那枚勋章。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把勋章别在衣服上。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生得到了一枚勋章。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "勋章很漂亮，也很重。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给我看了爷爷的勋章。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着三枚小勋章。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "枚", "label": "量词"}, {"form": "勳章", "label": "繁体"}], "register": "通用", "sense_fingerprint": "勋章：给有大贡献的人佩戴的好看徽章", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4f307f-eef1-48f7-ab9e-281d3bff4d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90493, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "勋章", "is_correct": true, "explanation": "正确答案：勋章（xūn zhāng），授予有大贡献的人的荣誉徽章。"}, {"text": "军章", "is_correct": false, "explanation": "jūn（j）与 xūn（x）声母不同，意思是军队的徽章，不是授予个人的勋章。"}, {"text": "新张", "is_correct": false, "explanation": "xīn 与 xūn 只差元音（i 与 u），意思是新开张。"}, {"text": "宪章", "is_correct": false, "explanation": "xiàn 与 xūn 声母相同、韵母不同（ian 与 un），意思是国家或组织的基本法规，不是徽章。"}], "explanations": {"勋章": "正确答案：勋章（xūn zhāng），授予有大贡献的人的荣誉徽章。", "军章": "jūn（j）与 xūn（x）声母不同，意思是军队的徽章，不是授予个人的勋章。", "新张": "xīn 与 xūn 只差元音（i 与 u），意思是新开张。", "宪章": "xiàn 与 xūn 声母相同、韵母不同（ian 与 un），意思是国家或组织的基本法规，不是徽章。"}, "sentence_index": null, "correct_answer": "勋章"}, "level_3": {"options": [{"text": "勋章", "is_correct": true, "explanation": "正确：胸前戴着的荣誉徽章，与「戴着」「一枚」相符。"}, {"text": "邮票", "is_correct": false, "explanation": "搭配：「戴」的对象是可以佩戴的东西，邮票不能戴在胸前。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋不能戴在胸前，与「戴着」的语境不符。"}, {"text": "果核", "is_correct": false, "explanation": "语义：果核不能戴在胸前，与「戴着」的语境不符。"}], "explanations": {"勋章": "正确：胸前戴着的荣誉徽章，与「戴着」「一枚」相符。", "邮票": "搭配：「戴」的对象是可以佩戴的东西，邮票不能戴在胸前。", "鸡蛋": "语义：鸡蛋不能戴在胸前，与「戴着」的语境不符。", "果核": "语义：果核不能戴在胸前，与「戴着」的语境不符。"}, "sentence_index": 0, "correct_answer": "勋章"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中获得了一枚勋章。", "explanation": "这里应该用〈奖牌〉。勋章授予国家或组织有功人员，比赛名次用奖牌。"}, {"text": "他的校服上别着一枚勋章。", "explanation": "这里应该用〈校徽〉。勋章是荣誉，学校标志要说校徽。"}, {"text": "这次展览会给每位参观者发了一枚勋章。", "explanation": "这里应该用〈纪念章〉。勋章授予为国家或组织做出大贡献的人，展览的纪念品要说纪念章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90493, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勋章", "is_correct": true, "explanation": "正确：医生因为贡献得到的荣誉，与「得到」相符。"}, {"text": "面包", "is_correct": false, "explanation": "量词与语义：「一枚」不能修饰面包，面包也不是荣誉。"}, {"text": "钢笔", "is_correct": false, "explanation": "量词与语义：钢笔用「支」计量，不能说「一枚」，且不是荣誉。"}, {"text": "西瓜", "is_correct": false, "explanation": "量词与语义：西瓜用「个」计量，不能说「一枚西瓜」，也不是荣誉。"}], "explanations": {"勋章": "正确：医生因为贡献得到的荣誉，与「得到」相符。", "面包": "量词与语义：「一枚」不能修饰面包，面包也不是荣誉。", "钢笔": "量词与语义：钢笔用「支」计量，不能说「一枚」，且不是荣誉。", "西瓜": "量词与语义：西瓜用「个」计量，不能说「一枚西瓜」，也不是荣誉。"}, "sentence_index": 6, "correct_answer": "勋章"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位运动员赢得了一枚勋章。", "explanation": "这里应该用〈金牌〉。勋章授予有功人员，比赛冠军用金牌。"}, {"text": "他的工作证上别着一枚勋章。", "explanation": "这里应该用〈证章〉。勋章是荣誉，工作证上的标志要说证章。"}, {"text": "他在婚礼上收到一枚勋章。", "explanation": "这里应该用〈纪念章〉。勋章授予有功人员，婚礼纪念品要说纪念章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90493, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的衣服上别着一把勋章。", "corrected_sentence": "她的衣服上别着一枚勋章。", "error_description": "量词错误：勋章用「枚」计量，「把」只用于有柄的物件，应说「一枚勋章」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90493, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她终于拿到了一把勋章。", "corrected_sentence": "她终于拿到了一枚勋章。", "error_description": "量词错误：勋章用「枚」计量，「把」只用于有柄的物件，应说「一枚勋章」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
