INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90494, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家或组织授予有功人员的荣誉徽章。", "primary_collocate": null, "pronunciation": "xūn zhāng", "ipa": "ɕyn˥ ʈʂaŋ˥", "syllable_count": 2, "sentences": [{"text": "国家给他发了一枚勋章。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为救人得到了勋章。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长把勋章送给了老科学家。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老兵得到过一枚勋章。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给有功的老师发勋章。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是国家给医生的勋章。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把勋章送给了博物馆。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这枚勋章代表国家的感谢。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们因为帮助大家而获得勋章。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队给有功的人发了勋章。", "target_word": "勋章", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "枚", "label": "量词"}, {"form": "勳章", "label": "繁体"}], "register": "通用", "sense_fingerprint": "勋章：国家或组织授予有功人员的荣誉徽章", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4f307f-eef1-48f7-ab9e-281d3bff4d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90494, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "勋章", "is_correct": true, "explanation": "正确答案：勋章（xūn zhāng），国家或组织授予有功人员的荣誉徽章。"}, {"text": "军章", "is_correct": false, "explanation": "jūn（j）与 xūn（x）声母不同，意思是军队的徽章。"}, {"text": "新张", "is_correct": false, "explanation": "xīn 与 xūn 只差元音（i 与 u），意思是新开张。"}, {"text": "宪章", "is_correct": false, "explanation": "xiàn 与 xūn 声母相同、韵母不同（ian 与 un），意思是国家或组织的基本法规，不是徽章。"}], "explanations": {"勋章": "正确答案：勋章（xūn zhāng），国家或组织授予有功人员的荣誉徽章。", "军章": "jūn（j）与 xūn（x）声母不同，意思是军队的徽章。", "新张": "xīn 与 xūn 只差元音（i 与 u），意思是新开张。", "宪章": "xiàn 与 xūn 声母相同、韵母不同（ian 与 un），意思是国家或组织的基本法规，不是徽章。"}, "sentence_index": null, "correct_answer": "勋章"}, "level_3": {"options": [{"text": "勋章", "is_correct": true, "explanation": "正确：国家授予荣誉，与「国家给他发」相符。"}, {"text": "纽扣", "is_correct": false, "explanation": "语义：纽扣不是国家授予的荣誉。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋不是国家颁发的物品，与语境不符。"}, {"text": "邮票", "is_correct": false, "explanation": "搭配：「发」后接「邮票」不指颁发荣誉，邮票一般说「发行」。"}], "explanations": {"勋章": "正确：国家授予荣誉，与「国家给他发」相符。", "纽扣": "语义：纽扣不是国家授予的荣誉。", "鸡蛋": "语义：鸡蛋不是国家颁发的物品，与语境不符。", "邮票": "搭配：「发」后接「邮票」不指颁发荣誉，邮票一般说「发行」。"}, "sentence_index": 0, "correct_answer": "勋章"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在运动会上获得了一枚勋章。", "explanation": "这里应该用〈奖牌〉。勋章授予国家或组织有功人员，运动会名次用奖牌。"}, {"text": "学校给每位学生发了一枚勋章。", "explanation": "这里应该用〈校徽〉。勋章是国家或组织的荣誉，学校标志要说校徽。"}, {"text": "他在毕业典礼上得到了一枚勋章。", "explanation": "这里应该用〈纪念章〉。勋章授予有功人员，毕业典礼的纪念品要说纪念章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勋章", "is_correct": true, "explanation": "正确：送给博物馆的是有纪念价值的荣誉物，与语境相符。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不值得送进博物馆，与荣誉物的语境不符。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，一般不会作为展品捐给博物馆，与语境不符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种病，不是物品，不能送给博物馆。"}], "explanations": {"勋章": "正确：送给博物馆的是有纪念价值的荣誉物，与语境相符。", "垃圾": "语义：垃圾不值得送进博物馆，与荣誉物的语境不符。", "饼干": "语义：饼干是食品，一般不会作为展品捐给博物馆，与语境不符。", "感冒": "语义：感冒是一种病，不是物品，不能送给博物馆。"}, "sentence_index": 6, "correct_answer": "勋章"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在商店里买了一枚勋章。", "explanation": "这里应该用〈徽章〉。勋章由国家或组织授予有功人员，不能在商店里买。"}, {"text": "她的手指上戴着一枚勋章。", "explanation": "这里应该用〈戒指〉。勋章要别在胸前，不戴在手指上。"}, {"text": "他的帽子上别着一枚勋章。", "explanation": "这里应该用〈徽章〉。勋章是授予有功人员的荣誉，帽子上的一般装饰要说徽章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的收藏柜里有一把勋章。", "corrected_sentence": "他的收藏柜里有一枚勋章。", "error_description": "量词错误：勋章用「枚」计量，「把」只用于有柄的物件，应说「一枚勋章」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '722e0211-919a-4bcf-a299-aea3e95aaa4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
