INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90495, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "小过是不太大的错事。", "primary_collocate": null, "pronunciation": "xiǎo guò", "ipa": "ɕjɑʊ˨˩ kwo˥˩", "syllable_count": 2, "sentences": [{"text": "小孩偷吃糖，只是小过。", "target_word": "小过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上课说话是小过，不是大错。", "target_word": "小过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友之间的小过，说开了就好。", "target_word": "小过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "少交一次作业，算不算小过？", "target_word": "小过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把杯子打破了，这是个小过。", "target_word": "小过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乱扔垃圾也是一种小过。", "target_word": "小过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样的小过，写一份检查就行了。", "target_word": "小过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他知道自己有个小过，就主动道歉了。", "target_word": "小过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，小过要改，大错更不能犯。", "target_word": "小过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的小过不多，但他每次都认真改。", "target_word": "小过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个小过", "label": "量词搭配"}, {"form": "小過", "label": "繁体"}], "register": "书面", "sense_fingerprint": "生活中不太严重的错事，与大错相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2a424d-fb6a-4c27-a32b-e3eed49ee37f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90495, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小过", "is_correct": true, "explanation": "小过 xiǎo guò 即本词，指不太严重的错事。"}, {"text": "小锅", "is_correct": false, "explanation": "guō（第一声）与 guò（第四声）声调不同，意思是小锅。"}, {"text": "小国", "is_correct": false, "explanation": "guó（第二声）与 guò（第四声）声调不同，意思是小国。"}, {"text": "笑过", "is_correct": false, "explanation": "xiào（第四声）与 xiǎo（第三声）声调不同，意思是笑了，不是错事。"}], "explanations": {"小过": "小过 xiǎo guò 即本词，指不太严重的错事。", "小锅": "guō（第一声）与 guò（第四声）声调不同，意思是小锅。", "小国": "guó（第二声）与 guò（第四声）声调不同，意思是小国。", "笑过": "xiào（第四声）与 xiǎo（第三声）声调不同，意思是笑了，不是错事。"}, "sentence_index": null, "correct_answer": "小过"}, "level_3": {"options": [{"text": "小过", "is_correct": true, "explanation": "小过指不太严重的错事，与「只是」的轻描淡写相符。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：偷吃糖是错事，不能说成奖励。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：「身材」指人的体形，与偷吃糖这件事无关。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：「玩具」不是错事，与「只是」后的评价不合。"}], "explanations": {"小过": "小过指不太严重的错事，与「只是」的轻描淡写相符。", "奖励": "语义：偷吃糖是错事，不能说成奖励。", "身材": "体貌：「身材」指人的体形，与偷吃糖这件事无关。", "玩具": "语义：「玩具」不是错事，与「只是」后的评价不合。"}, "sentence_index": 0, "correct_answer": "小过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次做了一件小过，老师表扬了他。", "explanation": "这里应该用〈小功〉。小过是不太大的错事，应受批评，不能用于被表扬的好事；好事要说〈小功〉。"}, {"text": "这台机器出现了一次小过，已经修好了。", "explanation": "这里应该用〈故障〉。小过指人做的不太大的错事，机器的问题要说〈故障〉。"}, {"text": "这批零件有一个小过，不能使用。", "explanation": "这里应该用〈缺陷〉。小过指人做的不太大的错事，零件的问题要说〈缺陷〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90495, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小过", "is_correct": true, "explanation": "小过指不太严重的错事，与「写一份检查就行了」的处理相符。"}, {"text": "功劳", "is_correct": false, "explanation": "语义：功劳是值得肯定的事，不需要写检查。"}, {"text": "奖金", "is_correct": false, "explanation": "语义：奖金是奖励，与写检查的处理矛盾。"}, {"text": "感冒", "is_correct": false, "explanation": "配价：「写检查」需要的对象是错误，「感冒」不能成为检查的对象。"}], "explanations": {"小过": "小过指不太严重的错事，与「写一份检查就行了」的处理相符。", "功劳": "语义：功劳是值得肯定的事，不需要写检查。", "奖金": "语义：奖金是奖励，与写检查的处理矛盾。", "感冒": "配价：「写检查」需要的对象是错误，「感冒」不能成为检查的对象。"}, "sentence_index": 6, "correct_answer": "小过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他离开餐厅时给了服务员一点小过。", "explanation": "这里应该用〈小费〉。小过是不太大的错事，给服务员的钱要说〈小费〉。"}, {"text": "他最近身体有点小过，在家休息。", "explanation": "这里应该用〈小病〉。小过指不太大的错事，身体的小毛病要说〈小病〉。"}, {"text": "这次比赛他只有一次小过，没有输。", "explanation": "这里应该用〈失误〉。小过指人做的不太大的错事，比赛中的疏忽要说〈失误〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
