INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90496, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "轻微的过失。", "primary_collocate": null, "pronunciation": "xiǎo guò", "ipa": "ɕjɑʊ˨˩ kwo˥˩", "syllable_count": 2, "sentences": [{"text": "他只犯了一个小过。", "target_word": "小过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只是个小过，不用太担心。", "target_word": "小过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师原谅了他的小过。", "target_word": "小过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小过不改，会变成大错。", "target_word": "小过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "员工迟到一次，只算小过。", "target_word": "小过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司记了他一个小过。", "target_word": "小过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理为一个小过说了他一顿。", "target_word": "小过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有小过，要学会改正。", "target_word": "小过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要总是盯着别人的小过。", "target_word": "小过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小过没有影响工作，大家都忘了。", "target_word": "小过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个小过", "label": "量词搭配"}, {"form": "小過", "label": "繁体"}], "register": "书面", "sense_fingerprint": "工作或纪律上轻微的过失：记小过、犯小过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2a424d-fb6a-4c27-a32b-e3eed49ee37f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90496, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小过", "is_correct": true, "explanation": "小过 xiǎo guò 即本词，指轻微的过失。"}, {"text": "小锅", "is_correct": false, "explanation": "guō（第一声）与 guò（第四声）声调不同，意思是小锅，不是轻微的过失。"}, {"text": "小国", "is_correct": false, "explanation": "guó（第二声）与 guò（第四声）声调不同，意思是小国。"}, {"text": "笑过", "is_correct": false, "explanation": "xiào（第四声）与 xiǎo（第三声）声调不同，意思是笑了，不是轻微的过失。"}], "explanations": {"小过": "小过 xiǎo guò 即本词，指轻微的过失。", "小锅": "guō（第一声）与 guò（第四声）声调不同，意思是小锅，不是轻微的过失。", "小国": "guó（第二声）与 guò（第四声）声调不同，意思是小国。", "笑过": "xiào（第四声）与 xiǎo（第三声）声调不同，意思是笑了，不是轻微的过失。"}, "sentence_index": null, "correct_answer": "小过"}, "level_3": {"options": [{"text": "小过", "is_correct": true, "explanation": "小过指轻微的过失，与「犯了一个」搭配，「只」也强调程度轻。"}, {"text": "优点", "is_correct": false, "explanation": "语义：「犯」的对象是过错，「优点」是长处，不能被犯。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：「犯」不与「感冒」搭配，应说「得了感冒」。"}, {"text": "奖状", "is_correct": false, "explanation": "语义：「奖状」是奖励凭证，与「犯」搭配后句意不通。"}], "explanations": {"小过": "小过指轻微的过失，与「犯了一个」搭配，「只」也强调程度轻。", "优点": "语义：「犯」的对象是过错，「优点」是长处，不能被犯。", "感冒": "搭配：「犯」不与「感冒」搭配，应说「得了感冒」。", "奖状": "语义：「奖状」是奖励凭证，与「犯」搭配后句意不通。"}, "sentence_index": 0, "correct_answer": "小过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次他犯了一次小过，老师表扬了他。", "explanation": "这里应该用〈小功〉。小过指轻微的过失，应受批评，不能用于被表扬的事；立功的好事要说〈小功〉。"}, {"text": "这场比赛他犯了一个小过，丢掉了关键一分。", "explanation": "这里应该用〈失误〉。小过指工作或纪律上的过失，比赛中的疏忽要说〈失误〉。"}, {"text": "这件产品有一个小过，需要退货。", "explanation": "这里应该用〈缺陷〉。小过指人在工作或纪律上的轻微过失，产品的问题要说〈缺陷〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小过", "is_correct": true, "explanation": "小过指轻微的过失，与「为一个……说了他一顿」的责备语气相符。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：因为奖励而受到责备，与「说了他一顿」的语境相矛盾。"}, {"text": "喜事", "is_correct": false, "explanation": "语义：喜事不会引来责备，与「说了他一顿」相矛盾。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：「一个」不搭「雨」，应说「一场雨」。"}], "explanations": {"小过": "小过指轻微的过失，与「为一个……说了他一顿」的责备语气相符。", "奖励": "语义：因为奖励而受到责备，与「说了他一顿」的语境相矛盾。", "喜事": "语义：喜事不会引来责备，与「说了他一顿」相矛盾。", "雨": "搭配：「一个」不搭「雨」，应说「一场雨」。"}, "sentence_index": 6, "correct_answer": "小过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器昨天出了一次小过，已经修好了。", "explanation": "这里应该用〈故障〉。小过指人在工作或纪律上的轻微过失，机器的问题要说〈故障〉。"}, {"text": "这件瓷器上有一处小过，不太影响使用。", "explanation": "这里应该用〈瑕疵〉。小过用于人的过错，器物的毛病要说〈瑕疵〉。"}, {"text": "他最近身体有点小过，在家休息。", "explanation": "这里应该用〈小病〉。小过指轻微的过错，身体的小毛病要说〈小病〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她上次犯了一把小过，已经改正了。", "corrected_sentence": "她上次犯了一个小过，已经改正了。", "error_description": "量词错误：「小过」前应用「个」，不能用「把」（「把」多用于可握持的器物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他犯了一只小过，马上就改正了。", "corrected_sentence": "他犯了一个小过，马上就改正了。", "error_description": "量词错误：「小过」是抽象的过失，量词应用「个」，不能用「只」（「只」多用于动物等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90497, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
