INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90500, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "长度单位，等于一千个一米的长度，也叫公里。", "primary_collocate": null, "pronunciation": "qiān mǐ", "ipa": "tɕʰjɛn˥ mi˨˩", "syllable_count": 2, "sentences": [{"text": "一千米就是一公里。", "target_word": "千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "千米也叫公里。", "target_word": "千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马拉松比赛大约是四十二千米。", "target_word": "千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥长五千米，是很长的桥。", "target_word": "千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上一厘米代表一千米。", "target_word": "千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京到天津大约一百二十千米。", "target_word": "千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的速度是每小时六十千米。", "target_word": "千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一千米比一百米长很多。", "target_word": "千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河全长三百千米。", "target_word": "千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高速公路上每隔一千米有一个牌子。", "target_word": "千米", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平方千米", "label": "复合"}, {"form": "千米每小时", "label": "复合"}], "register": "中性", "sense_fingerprint": "长度单位，一千米等于一千个一米，又称公里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0164a193-a1b9-4b34-a43a-61ec32a530f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90500, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "千米", "is_correct": true, "explanation": "正确答案：千米，长度单位，等于一千个一米。"}, {"text": "铅笔", "is_correct": false, "explanation": "bǐ（第三声）与 mǐ（第三声）声母不同，意思是铅笔。"}, {"text": "千里", "is_correct": false, "explanation": "lǐ 与 mǐ 声母不同，意思是千里，指很远的距离。"}, {"text": "千亩", "is_correct": false, "explanation": "mǔ（第三声）与 mǐ（第三声）韵母不同（u 与 i），意思是千亩，指土地面积。"}], "explanations": {"千米": "正确答案：千米，长度单位，等于一千个一米。", "铅笔": "bǐ（第三声）与 mǐ（第三声）声母不同，意思是铅笔。", "千里": "lǐ 与 mǐ 声母不同，意思是千里，指很远的距离。", "千亩": "mǔ（第三声）与 mǐ（第三声）韵母不同（u 与 i），意思是千亩，指土地面积。"}, "sentence_index": null, "correct_answer": "千米"}, "level_3": {"options": [{"text": "千米", "is_correct": true, "explanation": "正确：一千米就是一公里，千米和公里是同一个单位。"}, {"text": "厘米", "is_correct": false, "explanation": "语义：一厘米远比一公里短，二者不相等。"}, {"text": "吨", "is_correct": false, "explanation": "语义：吨是重量单位，不能等于长度单位公里。"}, {"text": "个", "is_correct": false, "explanation": "搭配：“个”是通用量词，不是长度单位，不能说“一个就是一公里”。"}], "explanations": {"千米": "正确：一千米就是一公里，千米和公里是同一个单位。", "厘米": "语义：一厘米远比一公里短，二者不相等。", "吨": "语义：吨是重量单位，不能等于长度单位公里。", "个": "搭配：“个”是通用量词，不是长度单位，不能说“一个就是一公里”。"}, "sentence_index": 0, "correct_answer": "千米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥重五千米。", "explanation": "这里应该用〈吨〉。千米量长度，重量要用吨或千克。"}, {"text": "这个岛的面积是五百千米。", "explanation": "这里应该用〈平方千米〉。千米量长度，面积要用平方千米。"}, {"text": "我们班有五十千米学生。", "explanation": "这里应该用〈名〉。千米量长度，人数要用“名”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "千米", "is_correct": true, "explanation": "正确：每小时六十千米表示汽车的速度。"}, {"text": "公斤", "is_correct": false, "explanation": "语义：公斤是重量单位，不能表示每小时走的路程。"}, {"text": "元", "is_correct": false, "explanation": "语义：元是货币单位，不能表示速度。"}, {"text": "天", "is_correct": false, "explanation": "搭配：“天”是时间单位，“每小时六十天”说不通。"}], "explanations": {"千米": "正确：每小时六十千米表示汽车的速度。", "公斤": "语义：公斤是重量单位，不能表示每小时走的路程。", "元": "语义：元是货币单位，不能表示速度。", "天": "搭配：“天”是时间单位，“每小时六十天”说不通。"}, "sentence_index": 6, "correct_answer": "千米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在门口站了五千米。", "explanation": "这里应该用〈分钟〉。千米量长度，站立或等待的时间要用分钟或小时。"}, {"text": "这桶水有两千米。", "explanation": "这里应该用〈升〉。千米量长度，桶里水的多少要用升。"}, {"text": "这个城市有三千米人口。", "explanation": "这里应该用〈万〉。千米量长度，人口要用“万”或“名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市到机场有三十个千米。", "corrected_sentence": "这座城市到机场有三十千米。", "error_description": "错误：“千米”前多加了量词“个”。“千米”本身就是量词，数字后直接接“千米”。错误形式：三十个千米；正确形式：三十千米。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们每周跑千米。", "corrected_sentence": "他们每周跑五十千米。", "error_description": "错误：“千米”作量词前缺少数词。应先有数词，说“五十千米”，不能只说“千米”。错误形式：每周跑千米；正确形式：每周跑五十千米。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
