INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90501, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90501, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一件事现在是什么样子，是好还是不好。", "primary_collocate": null, "pronunciation": "jú miàn", "ipa": "tɕy˧˥ mi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "现在的局面很好。", "target_word": "局面", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛的局面对我们不太好。", "target_word": "局面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司现在的局面很不好。", "target_word": "局面", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要想办法改变这个局面。", "target_word": "局面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到这样的局面，大家都很着急。", "target_word": "局面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没想到事情会是这种局面。", "target_word": "局面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一来，局面就好多了。", "target_word": "局面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理说现在的局面还不错，大家不用怕。", "target_word": "局面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛一开始，局面就对我们不利。", "target_word": "局面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师来了以后，教室里的局面一下子好了。", "target_word": "局面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "事情眼下的样子，说明是好是坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a22d3499-ca45-4e80-9518-98ccdc905de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90501, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "局面", "is_correct": true, "explanation": "正确：“局面”指事情现在的样子，可以说“现在的局面很好”。"}, {"text": "病", "is_correct": false, "explanation": "语义：“病”本身是负面的，“现在的病很好”不通。"}, {"text": "债务", "is_correct": false, "explanation": "语义：“债务”是负担，不能用“很好”来评价，“现在的债务很好”不通。"}, {"text": "战争", "is_correct": false, "explanation": "搭配：“很好”不能用来评价战争，二者不搭配。"}], "explanations": {"局面": "正确：“局面”指事情现在的样子，可以说“现在的局面很好”。", "病": "语义：“病”本身是负面的，“现在的病很好”不通。", "债务": "语义：“债务”是负担，不能用“很好”来评价，“现在的债务很好”不通。", "战争": "搭配：“很好”不能用来评价战争，二者不搭配。"}, "sentence_index": 0, "correct_answer": "局面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只猫的局面很可爱。", "explanation": "这里应该用〈样子〉。可爱形容外形，动物的外形要说样子。"}, {"text": "这幅画的局面很鲜艳。", "explanation": "这里应该用〈颜色〉。鲜艳形容颜色，画的颜色不能说局面。"}, {"text": "他的局面很高。", "explanation": "这里应该用〈身高〉。局面不能用来形容人的身材，高矮要说身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90501, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "局面", "is_correct": true, "explanation": "正确：“局面”指事情的形势，他一来，形势就好多了。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不会因“他一来”而“好多了”，“他一来，年龄就好多了”不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”不能表示情况的好坏变化，“闹钟就好多了”不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体型特征，不能因为“他一来”而“好多了”。"}], "explanations": {"局面": "正确：“局面”指事情的形势，他一来，形势就好多了。", "年龄": "语义：“年龄”不会因“他一来”而“好多了”，“他一来，年龄就好多了”不通。", "闹钟": "语义：“闹钟”不能表示情况的好坏变化，“闹钟就好多了”不通。", "身高": "体貌：身高是人的体型特征，不能因为“他一来”而“好多了”。"}, "sentence_index": 6, "correct_answer": "局面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的局面很好吃。", "explanation": "这里应该用〈味道〉。局面指事情的形势，菜的滋味要说味道。"}, {"text": "这首歌的局面很好听。", "explanation": "这里应该用〈声音〉。好听形容声音，歌的声音不能说局面。"}, {"text": "这件衣服的局面很便宜。", "explanation": "这里应该用〈价格〉。便宜形容价格，衣服的价钱要说价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90501, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们遇到了一只新局面。", "corrected_sentence": "我们遇到了一种新局面。", "error_description": "错误形式：“一只新局面”。正确形式：“局面”的量词应用“种”或“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90501, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛开始后，局面变很有利。", "corrected_sentence": "比赛开始后，局面变得很有利。", "error_description": "错误形式：“局面变很有利”。正确形式：“局面变得很有利”。“变”后面要用“得”引出状态补语“很有利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
