INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90502, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一段时期内事情的状态、形势。", "primary_collocate": null, "pronunciation": "jú miàn", "ipa": "tɕy˧˥ mi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这几年，市场的局面变了。", "target_word": "局面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国之间出现了紧张的局面。", "target_word": "局面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那年冬天，公司面临着困难的局面。", "target_word": "局面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一年努力，新的局面出现了。", "target_word": "局面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种局面已经持续了很久。", "target_word": "局面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛后半段，场上的局面完全变了。", "target_word": "局面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想看到混乱的局面。", "target_word": "局面", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "政府希望打开新局面。", "target_word": "局面", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那几年，国家的局面很稳定。", "target_word": "局面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁也没想到，会出现这样的局面。", "target_word": "局面", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "一段时期里事态发展的形势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a22d3499-ca45-4e80-9518-98ccdc905de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "局面", "is_correct": true, "explanation": "正确：“局面”指一段时期内事态的形势，可以说“市场的局面变了”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：市场没有年龄，“市场的年龄变了”不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是有形体的东西的特征，市场不能说有体重。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高用于人或动物，不能说市场的身高。"}], "explanations": {"局面": "正确：“局面”指一段时期内事态的形势，可以说“市场的局面变了”。", "年龄": "语义：市场没有年龄，“市场的年龄变了”不通。", "体重": "体貌：体重是有形体的东西的特征，市场不能说有体重。", "身高": "体貌：身高用于人或动物，不能说市场的身高。"}, "sentence_index": 0, "correct_answer": "局面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的局面很长。", "explanation": "这里应该用〈篇幅〉。局面指事态的形势，文章的长短要说篇幅。"}, {"text": "他的身体局面不太好。", "explanation": "这里应该用〈状况〉。局面指一段时期内事态的形势，人的身体情况要说身体状况。"}, {"text": "他今天的局面很好，一直在笑。", "explanation": "这里应该用〈心情〉。局面指事态的形势，人的情绪要说心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "局面", "is_correct": true, "explanation": "正确：“局面”指事态的形势，“混乱的局面”搭配自然。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“混乱”不能形容名字，“混乱的名字”不通。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不能说混乱，“混乱的阳光”不通。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "搭配：“混乱”不与“鸡蛋”搭配，鸡蛋只说新鲜或变质。"}], "explanations": {"局面": "正确：“局面”指事态的形势，“混乱的局面”搭配自然。", "名字": "语义：“混乱”不能形容名字，“混乱的名字”不通。", "阳光": "语义：阳光不能说混乱，“混乱的阳光”不通。", "鸡蛋": "搭配：“混乱”不与“鸡蛋”搭配，鸡蛋只说新鲜或变质。"}, "sentence_index": 6, "correct_answer": "局面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的局面很漂亮。", "explanation": "这里应该用〈样式〉。局面指事态的形势，衣服的式样要说样式。"}, {"text": "他的局面很开朗。", "explanation": "这里应该用〈性格〉。开朗形容性格，局面不能用来描述人的性格。"}, {"text": "这道菜的局面很香。", "explanation": "这里应该用〈味道〉。香形容气味，菜的气味不能说局面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那段时间，行业遇到了一件局面。", "corrected_sentence": "那段时间，行业遇到了一种局面。", "error_description": "错误形式：“一件局面”。正确形式：“局面”应用量词“种”或“个”，“件”多用于事情、衣物，不能用来修饰“局面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次谈判后，局面得变很紧张。", "corrected_sentence": "这次谈判后，局面变得很紧张。", "error_description": "错误形式：“得变”。正确形式：“变得”是固定组合，“得”后接形容词，应写成“变得很紧张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
