INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90503, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "去信是写信寄给别人。", "primary_collocate": null, "pronunciation": "qù xìn", "ipa": "tɕʰy˥˩ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "我想给老同学去信。", "target_word": "去信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每个月都给家里去信。", "target_word": "去信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我去信向他道谢。", "target_word": "去信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去信邀请朋友来玩。", "target_word": "去信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我昨天给王先生去信了。", "target_word": "去信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去信向我借书。", "target_word": "去信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷不会用手机，只能去信联系老朋友。", "target_word": "去信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么问题，就去信问我吧。", "target_word": "去信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们去信感谢那位老师。", "target_word": "去信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我去信问了他两次，他还没回信。", "target_word": "去信", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "去信了", "label": "体标"}], "register": "书面", "sense_fingerprint": "去信：写信并寄给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d48bf1a-fcce-4795-8810-0494f4f470de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90503, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "去信", "is_correct": true, "explanation": "正确。“我想给老同学去信”表示想写信寄给老同学，符合句意。"}, {"text": "笑", "is_correct": false, "explanation": "搭配：“笑”不能与“给老同学”组合，句子不通。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭”不能与“给老同学”组合，句子不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”是不及物动词，不能带“给老同学”这样的间接对象，句子不通。"}], "explanations": {"去信": "正确。“我想给老同学去信”表示想写信寄给老同学，符合句意。", "笑": "搭配：“笑”不能与“给老同学”组合，句子不通。", "哭": "搭配：“哭”不能与“给老同学”组合，句子不通。", "睡": "语义：“睡”是不及物动词，不能带“给老同学”这样的间接对象，句子不通。"}, "sentence_index": 0, "correct_answer": "去信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上都去信日记。", "explanation": "这里应该用〈写〉。去信指写信寄给别人，日记不寄给别人，应说“写日记”。"}, {"text": "我拿起手机给妈妈去信，听到了她的声音。", "explanation": "这里应该用〈打电话〉。去信是写信寄出，听不到对方的声音。"}, {"text": "我把礼物去信给了奶奶。", "explanation": "这里应该用〈寄〉。去信指写信，礼物要用“寄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90503, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "去信", "is_correct": true, "explanation": "正确。“只能去信联系老朋友”表示用写信的方式联系，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱歌不能用来联系老朋友。"}, {"text": "笑", "is_correct": false, "explanation": "搭配：“笑”无法与“联系”搭配，句子不通。"}, {"text": "看", "is_correct": false, "explanation": "语义：看只能看到，不能用来“联系”老朋友。"}], "explanations": {"去信": "正确。“只能去信联系老朋友”表示用写信的方式联系，符合句意。", "唱": "语义：唱歌不能用来联系老朋友。", "笑": "搭配：“笑”无法与“联系”搭配，句子不通。", "看": "语义：看只能看到，不能用来“联系”老朋友。"}, "sentence_index": 6, "correct_answer": "去信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们约好明天去信，一起吃饭。", "explanation": "这里应该用〈见面〉。去信是寄信，不能用来约定见面吃饭。"}, {"text": "我很喜欢这首歌，每天都去信它。", "explanation": "这里应该用〈听〉。去信指写信寄给对方，不能用来指听歌。"}, {"text": "这篇文章很长，我花了一个小时才去信完。", "explanation": "这里应该用〈读〉。去信指写信寄给对方，不能用来指读文章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90503, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天给小王去信着。", "corrected_sentence": "我昨天给小王去信了。", "error_description": "体标错误：“昨天”指已完成的动作，应用“了”，不用表示持续或状态的“着”。“我昨天给小王去信着”应改为“我昨天给小王去信了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90503, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我给他去信三个了。", "corrected_sentence": "我给他去信三次了。", "error_description": "动量词错误：“去信”计算次数要用动量词“次”，不用名量词“个”。应说“去信三次”，不说“去信三个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
