INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90504, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "寄信给对方。", "primary_collocate": null, "pronunciation": "qù xìn", "ipa": "tɕʰy˥˩ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "我给朋友去信了。", "target_word": "去信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去信问老师什么时候考试。", "target_word": "去信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你尽快给我们去信。", "target_word": "去信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我去信告诉她，我下个月回国。", "target_word": "去信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司去信通知了每一位客人。", "target_word": "去信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我已经去信两次了，他还没回信。", "target_word": "去信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈让我给奶奶去信，问她身体好不好。", "target_word": "去信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去信说自己很想家。", "target_word": "去信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校去信请家长来开会。", "target_word": "去信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你要是想知道，可以去信问问他。", "target_word": "去信", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "去信了", "label": "体标"}], "register": "书面", "sense_fingerprint": "去信：寄信给对方，多用于询问、通知、联系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d48bf1a-fcce-4795-8810-0494f4f470de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "去信", "is_correct": true, "explanation": "正确。“给朋友去信”表示写信寄给朋友，“了”表示完成，符合句意。"}, {"text": "笑", "is_correct": false, "explanation": "搭配：“笑”不能带“给朋友”这样的间接对象，不说“给朋友笑”。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭”不能与“给朋友”组合，句子不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”是不及物动词，不能带“给朋友”这样的间接对象，“给朋友睡了”不成立。"}], "explanations": {"去信": "正确。“给朋友去信”表示写信寄给朋友，“了”表示完成，符合句意。", "笑": "搭配：“笑”不能带“给朋友”这样的间接对象，不说“给朋友笑”。", "哭": "搭配：“哭”不能与“给朋友”组合，句子不通。", "睡": "语义：“睡”是不及物动词，不能带“给朋友”这样的间接对象，“给朋友睡了”不成立。"}, "sentence_index": 0, "correct_answer": "去信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在他门上去信了一张纸条，告诉他我来过了。", "explanation": "这里应该用〈贴〉。去信是写信寄给对方，纸条要贴在门上，不能说“去信”。"}, {"text": "我把包裹去信给了朋友。", "explanation": "这里应该用〈寄〉。去信只指写信寄给对方，包裹要用“寄”。"}, {"text": "我去信了一段视频，想传给老师看看。", "explanation": "这里应该用〈录〉。去信只指写信寄给对方，不能用来指拍视频；视频要说“录”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "去信", "is_correct": true, "explanation": "正确。“给奶奶去信，问她身体好不好”表示写信问候，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱歌不能用来“问她身体好不好”，与句意冲突。"}, {"text": "画", "is_correct": false, "explanation": "语义：画画无法表达“问她身体好不好”，画中传递不了问候，句意不通。"}, {"text": "跳", "is_correct": false, "explanation": "语义：跳舞无法表达“问她身体好不好”，与句意冲突。"}], "explanations": {"去信": "正确。“给奶奶去信，问她身体好不好”表示写信问候，符合句意。", "唱": "语义：唱歌不能用来“问她身体好不好”，与句意冲突。", "画": "语义：画画无法表达“问她身体好不好”，画中传递不了问候，句意不通。", "跳": "语义：跳舞无法表达“问她身体好不好”，与句意冲突。"}, "sentence_index": 6, "correct_answer": "去信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上在书桌前去信作业，写到很晚。", "explanation": "这里应该用〈写〉。去信指寄信，不能用于写作业。"}, {"text": "他在电话里跟我去信了很久。", "explanation": "这里应该用〈说〉或〈聊〉。去信是书面寄信，不能用于电话里的口头交谈。"}, {"text": "妈妈给我去信了一幅画。", "explanation": "这里应该用〈寄〉。去信只指写信寄给对方，不能用来寄一幅画；寄画或包裹要说“寄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经给老朋友去信着。", "corrected_sentence": "我已经给老朋友去信了。", "error_description": "体标误用。“去信”是一次完成的动作，句中有“已经”，表示动作已完成，要用“了”，不能用表示持续的“着”：应说“已经给老朋友去信了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经给他去信两个了，他还没回信。", "corrected_sentence": "我已经给他去信两次了，他还没回信。", "error_description": "表示动作次数的量词错误。“去信”的次数要用“次”，应说“给他去信两次”，不能用“个”说“两个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
