INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90505, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把好看的东西摆出来，请大家来看。", "primary_collocate": null, "pronunciation": "zhǎn lǎn", "ipa": "tʂan˨˩˦ lan˨˩˦", "syllable_count": 2, "sentences": [{"text": "学校在大厅里展览他做的小船。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在学校门口展览春天的花。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把同学们的好字展览了一周。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里展览着各种漂亮的灯。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把收藏的旧邮票拿出来展览。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们想展览自己做的手工，请大家来看。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个花园每年春天展览新品种的花。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商场大门口展览着一辆红色的新车。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她织的毛衣在社区中心展览。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的人展览了自己种的大南瓜。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "展览了", "label": "体标（了）"}, {"form": "展览过", "label": "体标（过）"}, {"form": "展览着", "label": "体标（着）"}, {"form": "展览会", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把漂亮、有特色的东西摆出来让大家看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9007a2d-4d18-4039-ac90-907ce20042f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90505, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "配价：“唱”的宾语须是歌曲，不能说“唱他做的小船”。"}, {"text": "展览", "is_correct": true, "explanation": "正确：“展览”指把做好的东西摆出来让大家看，与“他做的小船”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”表示进食，小船不能吃。"}, {"text": "喂", "is_correct": false, "explanation": "配价：“喂”的对象须是人或动物，不能用于小船。"}], "explanations": {"唱": "配价：“唱”的宾语须是歌曲，不能说“唱他做的小船”。", "展览": "正确：“展览”指把做好的东西摆出来让大家看，与“他做的小船”搭配。", "吃": "语义：“吃”表示进食，小船不能吃。", "喂": "配价：“喂”的对象须是人或动物，不能用于小船。"}, "sentence_index": 0, "correct_answer": "展览"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房展览了一锅汤。", "explanation": "这里应该用〈烹饪〉。展览指把物品陈列给人看，做饭要用烹饪。"}, {"text": "他一开口就把心里的喜悦展览出来了。", "explanation": "这里应该用〈表达〉。展览指把好看的东西摆出来供人看，情绪要用表达。"}, {"text": "乐队在广场上展览了一首歌。", "explanation": "这里应该用〈演奏〉。展览的对象是实物，歌曲要用演奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90505, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吞下", "is_correct": false, "explanation": "语义：“吞下”指把东西咽进肚子，花不能被吞下陈列。"}, {"text": "展览", "is_correct": true, "explanation": "正确：“展览”指把新品种的花摆出来让大家看，与花园的语境相合。"}, {"text": "喂养", "is_correct": false, "explanation": "配价：“喂养”的对象须是动物，花不能被喂养。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”表示用牙齿夹住，花店不会咬新到的花。"}], "explanations": {"吞下": "语义：“吞下”指把东西咽进肚子，花不能被吞下陈列。", "展览": "正确：“展览”指把新品种的花摆出来让大家看，与花园的语境相合。", "喂养": "配价：“喂养”的对象须是动物，花不能被喂养。", "咬": "语义：“咬”表示用牙齿夹住，花店不会咬新到的花。"}, "sentence_index": 6, "correct_answer": "展览"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房展览了她的一个朋友。", "explanation": "这里应该用〈介绍〉。展览的对象是物品，人不能当作展品陈列，向大家引见朋友要用介绍。"}, {"text": "她在窗前展览了一阵风。", "explanation": "这里应该用〈吹〉。展览指把好看的东西摆出来给人看，风要用吹。"}, {"text": "他在教室里展览了一场雨。", "explanation": "这里应该用〈下〉。展览指把好看的东西摆出来给人看，雨要用下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90505, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政厅正在展览了一批老地图。", "corrected_sentence": "市政厅正在展览一批老地图。", "error_description": "“正在”表示动作进行，与“了”不能同时用，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90505, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家小店每周都在展览了新做的手工。", "corrected_sentence": "这家小店每周都在展览新做的手工。", "error_description": "“在”表示动作进行，与“了”不能同时用，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
