INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90506, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公开陈列物品供人参观。", "primary_collocate": null, "pronunciation": "zhǎn lǎn", "ipa": "tʂan˨˩˦ lan˨˩˦", "syllable_count": 2, "sentences": [{"text": "美术馆正在展览一批新画。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些古代的瓷器在博物馆里展览。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把学生的作品展览了一个星期。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的照片在城里展览过。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民可以免费参观，那里展览着很多老照片。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆展览了孩子们画的画。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件国宝只在春节时展览。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把新车放在大厅里展览。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在展览馆里展览新产品。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅名画展览了三天，来看的人很多。", "target_word": "展览", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "展览了", "label": "体标（了）"}, {"form": "展览过", "label": "体标（过）"}, {"form": "展览着", "label": "体标（着）"}, {"form": "展览馆", "label": "复合词"}, {"form": "展览会", "label": "复合词"}], "register": "中性", "sense_fingerprint": "在博物馆、美术馆等地方公开陈列物品给人参观", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9007a2d-4d18-4039-ac90-907ce20042f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”表示毁坏，美术馆不会把正在陈列的新画烧掉。"}, {"text": "展览", "is_correct": true, "explanation": "正确：“展览”指公开陈列物品供人参观，与美术馆和新画搭配。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”的宾语须是歌曲，不能说“唱一批新画”。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：“撕碎”表示毁坏，与美术馆陈列新画的语境相反。"}], "explanations": {"烧毁": "语义：“烧毁”表示毁坏，美术馆不会把正在陈列的新画烧掉。", "展览": "正确：“展览”指公开陈列物品供人参观，与美术馆和新画搭配。", "唱": "配价：“唱”的宾语须是歌曲，不能说“唱一批新画”。", "撕碎": "语义：“撕碎”表示毁坏，与美术馆陈列新画的语境相反。"}, "sentence_index": 0, "correct_answer": "展览"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛展览了三天，观众很多。", "explanation": "这里应该用〈举行〉。展览指把物品公开陈列供人参观，比赛这类活动要用举行。"}, {"text": "政府在河上展览了一座新桥。", "explanation": "这里应该用〈修建〉。展览的对象是可以陈列的物品，桥是建造出来的工程，要用修建。"}, {"text": "他们在会上展览了一个问题。", "explanation": "这里应该用〈讨论〉。展览的对象是实物，问题要通过讨论来处理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消费", "is_correct": false, "explanation": "语义：“消费”指花费或使用物品，国宝不能被消费。"}, {"text": "展览", "is_correct": true, "explanation": "正确：“展览”指公开陈列，国宝只在春节时陈列，与语境相合。"}, {"text": "打印", "is_correct": false, "explanation": "语义：“打印”指把文字或图像印出来，不能用于国宝。"}, {"text": "喂", "is_correct": false, "explanation": "配价：“喂”的对象须是人或动物，不能用于国宝。"}], "explanations": {"消费": "语义：“消费”指花费或使用物品，国宝不能被消费。", "展览": "正确：“展览”指公开陈列，国宝只在春节时陈列，与语境相合。", "打印": "语义：“打印”指把文字或图像印出来，不能用于国宝。", "喂": "配价：“喂”的对象须是人或动物，不能用于国宝。"}, "sentence_index": 6, "correct_answer": "展览"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司展览了它的利润。", "explanation": "这里应该用〈公布〉。展览指把实物公开陈列供人参观，利润是抽象数字，不能陈列，要用公布。"}, {"text": "我们在广场上展览了我的老师。", "explanation": "这里应该用〈介绍〉。展览的对象是物品，不能把人当作展品陈列，向大家引见人物要用介绍。"}, {"text": "孩子们在操场上展览踢球。", "explanation": "这里应该用〈表演〉。展览是把实物摆出来给人看，踢球是动作，要用表演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些老照片在图书馆展览了过。", "corrected_sentence": "这些老照片在图书馆展览过。", "error_description": "体标重复：“了”与“过”不能同时用，“展览了过”应去掉“了”，应为“展览过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套老邮票正在展览了。", "corrected_sentence": "这套老邮票正在展览。", "error_description": "“正在”表示动作进行，与“了”不能同时用，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0908f3a-095e-453c-96f6-9a5fd358bd47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
