INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90507, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "反科学是不相信科学，和科学作对。", "primary_collocate": null, "pronunciation": "fǎn kē xué", "ipa": "fan˨˩ kʰɤ˥ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "他这个人很反科学，从不看医生。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人很反科学，什么都不信。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的态度太反科学了，大家都不同意。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要这么反科学，要听医生的话。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就反科学，不相信书里的话。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人很反科学，总和专家作对。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷有点反科学，只信老办法。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友不反科学，他很爱看科学书。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么这么反科学？", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一家人都很反科学。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容人的态度不信科学、与科学对立", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2b2c253-1912-4008-90c3-ad21f0ccc4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90507, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反科学", "is_correct": true, "explanation": "正确：反科学指不信科学、与科学作对，用来形容人的态度。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：潮湿用于天气或地面，不能用来形容一个人。"}, {"text": "鲜艳", "is_correct": false, "explanation": "语义：鲜艳指颜色明亮，与人的态度无关。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：沙哑形容嗓音，不能用来形容一个人的性格。"}], "explanations": {"反科学": "正确：反科学指不信科学、与科学作对，用来形容人的态度。", "潮湿": "搭配：潮湿用于天气或地面，不能用来形容一个人。", "鲜艳": "语义：鲜艳指颜色明亮，与人的态度无关。", "沙哑": "搭配：沙哑形容嗓音，不能用来形容一个人的性格。"}, "sentence_index": 0, "correct_answer": "反科学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子很反科学。", "explanation": "误用：把“反科学”当成形容物件性质的词，如“结实”“舒服”一类。“反科学”只用来形容人不相信科学、和科学作对的态度。"}, {"text": "今天的天气很反科学。", "explanation": "误用：把“反科学”当成形容天气状况的词，如“晴朗”“阴冷”一类。“反科学”只形容人的态度，不用于天气。"}, {"text": "我的书包很反科学，总是装满东西。", "explanation": "误用：把“反科学”当成形容物品整洁或杂乱的词。“反科学”只形容人不相信科学的态度，不能用于书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90507, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反科学", "is_correct": true, "explanation": "正确：反科学指不信科学，用来形容人的态度，与“只信老办法”相合。"}, {"text": "新潮", "is_correct": false, "explanation": "语义：新潮表示赶时髦、接受新事物，与“只信老办法”的说法矛盾。"}, {"text": "小巧", "is_correct": false, "explanation": "体貌：小巧形容物体或人的体型不大，不能用来形容爷爷的态度。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：年轻指年龄小，与“爷爷”的身份矛盾。"}], "explanations": {"反科学": "正确：反科学指不信科学，用来形容人的态度，与“只信老办法”相合。", "新潮": "语义：新潮表示赶时髦、接受新事物，与“只信老办法”的说法矛盾。", "小巧": "体貌：小巧形容物体或人的体型不大，不能用来形容爷爷的态度。", "年轻": "语义：年轻指年龄小，与“爷爷”的身份矛盾。"}, "sentence_index": 6, "correct_answer": "反科学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间教室很反科学。", "explanation": "误用：把“反科学”当成形容场所环境的词，如“安静”“明亮”一类。“反科学”只形容人的态度，不能用于房间。"}, {"text": "那家饭店的菜很反科学。", "explanation": "误用：把“反科学”当成评价食物口味的词，如“咸”“鲜”一类。“反科学”只形容人不相信科学的态度。"}, {"text": "这首歌的旋律很反科学。", "explanation": "误用：把“反科学”当成评价音乐好听与否的词，如“动听”“悦耳”一类。“反科学”只形容人的态度，不用于音乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90507, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她太反科学地，什么都不愿意试。", "corrected_sentence": "她太反科学了，什么都不愿意试。", "error_description": "错误：“反科学”作谓语时后面不能加“地”（“地”只用于后接动词的状语）。正确应为“太反科学了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90507, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我叔叔是个反科学地人，只信老中医。", "corrected_sentence": "我叔叔是个反科学的人，只信老中医。", "error_description": "错误：修饰名词“人”要用“的”，写成“地”是错误。正确应为“反科学的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
