INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90508, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "违背科学、否定科学的。", "primary_collocate": null, "pronunciation": "fǎn kē xué", "ipa": "fan˨˩ kʰɤ˥ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "这种说法很反科学。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法太反科学了。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不吃药就想治病，这样做很反科学。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个做法反科学。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目里的内容有点反科学。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得这种减肥方法很反科学。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的说法听起来非常反科学。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把水变成油，这件事太反科学了。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话一点也不反科学。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多反科学的地方。", "target_word": "反科学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容说法、做法违背科学道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2b2c253-1912-4008-90c3-ad21f0ccc4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反科学", "is_correct": true, "explanation": "正确：反科学指违背科学，可以修饰说法，这里说这种说法违背科学道理。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：高大形容人或物的体形，不能用来形容说法。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：潮湿用于天气或环境，不能说说法潮湿。"}, {"text": "凉快", "is_correct": false, "explanation": "搭配：凉快说温度或感觉，不能用来形容说法。"}], "explanations": {"反科学": "正确：反科学指违背科学，可以修饰说法，这里说这种说法违背科学道理。", "高大": "体貌：高大形容人或物的体形，不能用来形容说法。", "潮湿": "搭配：潮湿用于天气或环境，不能说说法潮湿。", "凉快": "搭配：凉快说温度或感觉，不能用来形容说法。"}, "sentence_index": 0, "correct_answer": "反科学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子的颜色很反科学。", "explanation": "误用：把“反科学”当成形容外观的词，如“好看”“鲜艳”一类。“反科学”只表示违背科学、否定科学，不用于描写物品的外观。"}, {"text": "他的身高在班里很反科学。", "explanation": "误用：把“反科学”当成描述高矮、大小的程度词。“反科学”只表示违背科学、否定科学，不用于描述身材。"}, {"text": "这把伞的形状很反科学。", "explanation": "误用：把“反科学”当成描述物体形状的词，如“圆”“扁”一类。“反科学”只表示违背科学、否定科学，不用于形容物体形状。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反科学", "is_correct": true, "explanation": "正确：反科学指违背科学，修饰说法，这里说这样的说法违背科学道理。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：冷清形容场所或气氛，不能用来形容说法。"}, {"text": "蓬松", "is_correct": false, "explanation": "搭配：蓬松用于头发、棉被等物体，不能用来形容说法。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：胖形容人或动物的体态，不能用来形容说法。"}], "explanations": {"反科学": "正确：反科学指违背科学，修饰说法，这里说这样的说法违背科学道理。", "冷清": "搭配：冷清形容场所或气氛，不能用来形容说法。", "蓬松": "搭配：蓬松用于头发、棉被等物体，不能用来形容说法。", "胖": "体貌：胖形容人或动物的体态，不能用来形容说法。"}, "sentence_index": 6, "correct_answer": "反科学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个杯子的形状很反科学。", "explanation": "误用：把“反科学”当成描述物体形状的词。“反科学”只表示违背科学、否定科学，不用于形容杯子这样的日常器物。"}, {"text": "他的名字很反科学。", "explanation": "误用：把“反科学”当成评价事物好坏或特点的词，如“好听”“特别”。“反科学”只表示违背科学，不能用来评价名字。"}, {"text": "这首歌唱得很反科学。", "explanation": "误用：把“反科学”当成评价表演水平的程度词，如“好”“差”。“反科学”只表示违背科学，不用于评价演唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个说法很反科学地，大家都不信。", "corrected_sentence": "这个说法很反科学，大家都不信。", "error_description": "错误：“很反科学”作谓语时后面不能接“地”（“地”只用于后接动词的状语）。正确应为“这个说法很反科学，大家都不信。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种反科学地说法，大家都不信。", "corrected_sentence": "这种反科学的说法，大家都不信。", "error_description": "错误：修饰名词“说法”要用“的”，写成“地”是错误。正确应为“反科学的说法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
