INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90509, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "取决于是说结果要看某一件事怎么样。", "primary_collocate": null, "pronunciation": "qǔ jué yú", "ipa": "tɕʰy˨˩˦ tɕɥe˧˥ y˧˥", "syllable_count": 3, "sentences": [{"text": "比赛能不能赢，取决于大家努力不努力。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天去不去爬山，取决于天气怎么样。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜好不好吃，取决于厨师的手艺。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行去哪儿，取决于你的假期有多长。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子学得好不好，很大程度上取决于老师。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果甜不甜，取决于太阳晒得多不多。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚饭吃什么，取决于冰箱里还有什么。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上要走多久，取决于今天堵不堵车。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试成绩好不好，取决于你复习得怎么样。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们几点出发，取决于他几点能到。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "结果要看某件事怎么样，常与“……不……”的疑问形式连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75b6c6b-1a83-43ea-bf8d-cebf12c05e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90509, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取决于", "is_correct": true, "explanation": "正确：「取决于」表示比赛结果由大家努力与否决定，句意通顺。"}, {"text": "决定", "is_correct": false, "explanation": "语义：「A决定B」表示A使B成为某种结果；填入「决定」就成了比赛能不能赢决定大家努力不努力，因果方向颠倒。正确的是结果「取决于」努力。"}, {"text": "等待", "is_correct": false, "explanation": "配价：「等待」后面要接可以等待的对象，「大家努力不努力」这样的正反问结构不能作它的宾语。"}, {"text": "依靠", "is_correct": false, "explanation": "配价：「依靠」后面要接可以凭借的人或事物，不能接「大家努力不努力」这样的小句。"}], "explanations": {"取决于": "正确：「取决于」表示比赛结果由大家努力与否决定，句意通顺。", "决定": "语义：「A决定B」表示A使B成为某种结果；填入「决定」就成了比赛能不能赢决定大家努力不努力，因果方向颠倒。正确的是结果「取决于」努力。", "等待": "配价：「等待」后面要接可以等待的对象，「大家努力不努力」这样的正反问结构不能作它的宾语。", "依靠": "配价：「依靠」后面要接可以凭借的人或事物，不能接「大家努力不努力」这样的小句。"}, "sentence_index": 0, "correct_answer": "取决于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们取决于大家的努力，才完成了任务。", "explanation": "这里应该用〈依靠〉。取决于的主语必须是待定的结果，不能指人；说人凭借别人的力量要用「依靠」。"}, {"text": "这个孩子取决于父母的照顾。", "explanation": "这里应该用〈依赖〉。取决于表示结果由某因素决定，不能用来说人对别人的依赖。"}, {"text": "学生们取决于老师的安排。", "explanation": "这里应该用〈听从〉。取决于的主语是待定的结果，「学生们」是人，表示服从安排要用「听从」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90509, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取决于", "is_correct": true, "explanation": "正确：「取决于」表示晚饭吃什么由冰箱里的东西决定，句意通顺。"}, {"text": "保存", "is_correct": false, "explanation": "配价：「保存」要接可以保存的具体物品，不能接「冰箱里还有什么」这样的疑问结构。"}, {"text": "询问", "is_correct": false, "explanation": "语义：「询问」是向人打听，「冰箱里还有什么」是事实，与「晚饭吃什么」的选择关系不通。"}, {"text": "通知", "is_correct": false, "explanation": "配价：「通知」要说明通知的对象，不能直接以「冰箱里还有什么」作宾语。"}], "explanations": {"取决于": "正确：「取决于」表示晚饭吃什么由冰箱里的东西决定，句意通顺。", "保存": "配价：「保存」要接可以保存的具体物品，不能接「冰箱里还有什么」这样的疑问结构。", "询问": "语义：「询问」是向人打听，「冰箱里还有什么」是事实，与「晚饭吃什么」的选择关系不通。", "通知": "配价：「通知」要说明通知的对象，不能直接以「冰箱里还有什么」作宾语。"}, "sentence_index": 6, "correct_answer": "取决于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "取决于努力，他终于考上了大学。", "explanation": "这里应该用〈通过〉。取决于表示结果由某因素决定，不能用来引出达成目标的途径；表示凭借努力要用「通过」。"}, {"text": "取决于天气预报，我们改期了。", "explanation": "这里应该用〈根据〉。取决于的主语应是待定的结果，不能用来引出作为依据的消息；引出依据要用「根据」。"}, {"text": "取决于计划，我们明天出发。", "explanation": "这里应该用〈按照〉。取决于表示结果受因素影响，不能用来引出行动所依照的计划；依照计划要用「按照」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90509, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次旅行去哪儿，取决于了天气怎么样。", "corrected_sentence": "这次旅行去哪儿，取决于天气怎么样。", "error_description": "错误形式：「取决于」后面多加了「了」。正确形式：「取决于天气怎么样」。原因：「取决于」是动词，后面不能直接加「了」表示完成，这里应删去「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90509, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末去哪儿玩，取决于了天气好不好。", "corrected_sentence": "周末去哪儿玩，取决于天气好不好。", "error_description": "错误形式：「取决于」后面多加了「了」。正确形式：「取决于天气好不好」。原因：「了」不能附着在「取决于」后面表示完成，这里应删去「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
