INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90510, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "由某种因素决定，以某事为条件。", "primary_collocate": null, "pronunciation": "qǔ jué yú", "ipa": "tɕʰy˨˩˦ tɕɥe˧˥ y˧˥", "syllable_count": 3, "sentences": [{"text": "一个人的成功，取决于他的努力。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东西的价格取决于质量和数量。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果的味道取决于天气和土地。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人的身体状况取决于生活习惯。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花开的时间取决于温度的高低。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工资的多少取决于工作的难度。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机什么时候起飞，取决于天气情况。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习的效果主要取决于方法。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机电池能用多久取决于使用习惯。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的大小取决于你的预算。", "target_word": "取决于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "某事物由某个因素或条件决定，后面常接名词性的因素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75b6c6b-1a83-43ea-bf8d-cebf12c05e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90510, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取决于", "is_correct": true, "explanation": "正确：「取决于」表示一个人的成功由他的努力决定，句意通顺。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：「嘲笑」的对象是别人的言行，不能说成功是被「嘲笑」来决定的，与句意不符。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：「忽视」是不重视，说成功「忽视他的努力」自相矛盾，因果关系不对。"}, {"text": "等待", "is_correct": false, "explanation": "配价：「等待」后面接的是人或事件，不能用「他的努力」作为决定成功的因素。"}], "explanations": {"取决于": "正确：「取决于」表示一个人的成功由他的努力决定，句意通顺。", "嘲笑": "语义：「嘲笑」的对象是别人的言行，不能说成功是被「嘲笑」来决定的，与句意不符。", "忽视": "语义：「忽视」是不重视，说成功「忽视他的努力」自相矛盾，因果关系不对。", "等待": "配价：「等待」后面接的是人或事件，不能用「他的努力」作为决定成功的因素。"}, "sentence_index": 0, "correct_answer": "取决于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老人取决于子女的照顾。", "explanation": "这里应该用〈依赖〉。取决于的主语是待定的结果，不能指人；说人依赖别人要用「依赖」。"}, {"text": "士兵取决于命令。", "explanation": "这里应该用〈服从〉。取决于表示结果由某因素决定，不表示人接受指挥；服从命令要用「服从」。"}, {"text": "学生取决于老师的安排。", "explanation": "这里应该用〈听从〉。取决于的主语是结果，不能指人；听从别人的安排要用「听从」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取决于", "is_correct": true, "explanation": "正确：「取决于」表示飞机起飞时间由天气情况决定，句意通顺。"}, {"text": "预报", "is_correct": false, "explanation": "语义：「预报」是预先告知天气，不能说起飞时间由天气情况来「预报」，句意不通。"}, {"text": "通知", "is_correct": false, "explanation": "配价：「通知」要说明通知的对象，不能直接以「天气情况」作宾语来表示决定。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：「嫌弃」表示不喜欢，天气情况不能被用来「嫌弃」起飞时间，与句意不符。"}], "explanations": {"取决于": "正确：「取决于」表示飞机起飞时间由天气情况决定，句意通顺。", "预报": "语义：「预报」是预先告知天气，不能说起飞时间由天气情况来「预报」，句意不通。", "通知": "配价：「通知」要说明通知的对象，不能直接以「天气情况」作宾语来表示决定。", "嫌弃": "语义：「嫌弃」表示不喜欢，天气情况不能被用来「嫌弃」起飞时间，与句意不符。"}, "sentence_index": 6, "correct_answer": "取决于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "取决于好的方法，他很快学会了。", "explanation": "这里应该用〈凭借〉。取决于表示结果由某因素决定，不能用来引出凭借的手段；凭借方法要用「凭借」。"}, {"text": "取决于老师的要求，我们写了作文。", "explanation": "这里应该用〈依照〉。取决于的主语应是待定的结果，不能引出行动所依照的要求；依照要求要用「依照」。"}, {"text": "取决于字典，我看懂了这篇文章。", "explanation": "这里应该用〈借助〉。取决于不能引出借助的工具；借助字典要用「借助」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件衣服的价格取决于在面料。", "corrected_sentence": "这件衣服的价格取决于面料。", "error_description": "错误形式：「取决于」后面多加了「在」。正确形式：「取决于面料」。原因：「取决于」中的「于」已经起介词作用，后面直接接决定因素，不能再加「在」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这款手机能用多久，取决于了电池容量。", "corrected_sentence": "这款手机能用多久，取决于电池容量。", "error_description": "错误形式：「取决于」后面多加了「了」。正确形式：「取决于电池容量」。原因：「取决于」是动词，后面不能直接加「了」，这里应删去「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
