INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90511, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人活了多少岁。", "primary_collocate": null, "pronunciation": "nián jì", "ipa": "njɛn˧˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "你多大年纪了？", "target_word": "年纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的年纪很大，走路要慢一点。", "target_word": "年纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来年纪不大，已经是经理了。", "target_word": "年纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人年纪虽然大，身体还很好。", "target_word": "年纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问您多大年纪？", "target_word": "年纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年纪小的孩子，不能一个人出门。", "target_word": "年纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她年纪比我大，我叫她姐姐。", "target_word": "年纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的年纪不大，却懂很多事。", "target_word": "年纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我年纪大了，记不住这么多名字。", "target_word": "年纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了这个年纪，他才开始学游泳。", "target_word": "年纪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小小年纪", "label": "固定短语"}], "register": "中性", "sense_fingerprint": "一个人活了多少岁，指年龄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '741a067b-35ee-42ee-a9a5-e70920a0d4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90511, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年纪", "is_correct": true, "explanation": "正确。问人的岁数要说“多大年纪”。"}, {"text": "年代", "is_correct": false, "explanation": "语义：“年代”指一段时期，多用于建筑、物品，不能用来指人的岁数，“你多大年代了”不合语义。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：询问体重要用“多重”，不能用“多大”搭配“体重”。"}, {"text": "岁月", "is_correct": false, "explanation": "语义：“岁月”指漫长的时间，与具体询问某人的年龄不合。"}], "explanations": {"年纪": "正确。问人的岁数要说“多大年纪”。", "年代": "语义：“年代”指一段时期，多用于建筑、物品，不能用来指人的岁数，“你多大年代了”不合语义。", "体重": "搭配：询问体重要用“多重”，不能用“多大”搭配“体重”。", "岁月": "语义：“岁月”指漫长的时间，与具体询问某人的年龄不合。"}, "sentence_index": 0, "correct_answer": "年纪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的年纪有一米八，在篮球队里很突出。", "explanation": "这里应该用〈身高〉。身高用“一米八”这类长度来说，“年纪”只能表示岁数。"}, {"text": "他的年纪有七十公斤，看起来很健壮。", "explanation": "这里应该用〈体重〉。体重才用公斤计量，“年纪”不能用公斤来说。"}, {"text": "这座城市的年纪有三百年了。", "explanation": "这里应该用〈历史〉。说城市的久远要用“有三百年历史”，“年纪”只用于说人的岁数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90511, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年纪", "is_correct": true, "explanation": "正确。比较两人的岁数要说“年纪大”，只有“年纪”符合。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：比较学历要说“高”或“低”，不说“大”。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：比较身高应说“高”，说“大”不当。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，与“大”不搭配，也无法说明谁年长。"}], "explanations": {"年纪": "正确。比较两人的岁数要说“年纪大”，只有“年纪”符合。", "学历": "搭配：比较学历要说“高”或“低”，不说“大”。", "身高": "搭配：比较身高应说“高”，说“大”不当。", "体温": "语义：“体温”指身体的温度，与“大”不搭配，也无法说明谁年长。"}, "sentence_index": 6, "correct_answer": "年纪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位厨师有二十年年纪，做的菜很好吃。", "explanation": "这里应该用〈经验〉。说从业时间要用“经验”，“年纪”只能指一个人的岁数。"}, {"text": "这件衣服的年纪是两百元。", "explanation": "这里应该用〈价格〉。价格用“元”计量，“年纪”不能用来表示钱数。"}, {"text": "今天的年纪是三十度。", "explanation": "这里应该用〈温度〉。温度用“度”计量，“年纪”只能表示岁数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90511, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年纪得小，还不懂这些道理。", "corrected_sentence": "他年纪很小，还不懂这些道理。", "error_description": "表示程度要用副词「很」修饰形容词「小」。「得」是补语标记，不能用在「年纪」后面；「年纪得小」是错误的，正确为「年纪很小」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90511, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她年纪的轻轻就当上了老师。", "corrected_sentence": "她年纪轻轻就当上了老师。", "error_description": "「年纪轻轻」是固定说法，「的」不能插在「年纪」和「轻轻」之间。「年纪的轻轻」是错误的，正确为「年纪轻轻」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
