INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90516, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，询问方式或原因，相当于“怎么”。", "primary_collocate": null, "pronunciation": "zěn", "ipa": "tsən˨˩˦", "syllable_count": 1, "sentences": [{"text": "你怎不吃饭？", "target_word": "怎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字怎写？", "target_word": "怎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怎还没回来？", "target_word": "怎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题这么难，我怎做得出来？", "target_word": "怎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天你怎没给我打电话？", "target_word": "怎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱都用完了，我们怎过日子？", "target_word": "怎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜怎做才好吃？", "target_word": "怎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑怎关机？", "target_word": "怎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着这么多菜，我怎吃得完？", "target_word": "怎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子怎哭了？", "target_word": "怎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "怎么", "label": "复合词"}, {"form": "怎样", "label": "复合词"}, {"form": "怎么样", "label": "复合词"}], "register": "口语", "sense_fingerprint": "相当于“怎么”的疑问代词，问方式或原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b74abb-82e7-47f8-a7df-97bad8dedd21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谁", "is_correct": false, "explanation": "语义：“谁”问人，不问原因，与“不吃饭”不相符。"}, {"text": "怎", "is_correct": true, "explanation": "怎：疑问代词，相当于“怎么”，问原因，与“不吃饭”搭配。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”问事物，不能问“为什么不吃饭”。"}, {"text": "这么", "is_correct": false, "explanation": "搭配：“这么”表示程度，不能用来问“为什么不吃饭”。"}], "explanations": {"谁": "语义：“谁”问人，不问原因，与“不吃饭”不相符。", "怎": "怎：疑问代词，相当于“怎么”，问原因，与“不吃饭”搭配。", "什么": "语义：“什么”问事物，不能问“为什么不吃饭”。", "这么": "搭配：“这么”表示程度，不能用来问“为什么不吃饭”。"}, "sentence_index": 0, "correct_answer": "怎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想问你这件事的怎。", "explanation": "〈怎〉是疑问代词，不能做名词，也不能接在“的”后面。"}, {"text": "这是怎的一种菜？", "explanation": "〈怎〉不能修饰名词，问种类要用“什么样的”。"}, {"text": "他怎很高兴。", "explanation": "〈怎〉不能放在“很”前面，表示程度应说“怎么这么”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪", "is_correct": false, "explanation": "语义：“哪”表示选择或地点，不能问“怎样做才好吃”。"}, {"text": "怎", "is_correct": true, "explanation": "怎：问方式，与“做好吃”的语境相符。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”是程度副词，不能直接修饰动词“做”，“这道菜很做才好吃”不通。"}, {"text": "何", "is_correct": false, "explanation": "语域：“何”是书面语，口语里不说“这道菜何做好吃”。"}], "explanations": {"哪": "语义：“哪”表示选择或地点，不能问“怎样做才好吃”。", "怎": "怎：问方式，与“做好吃”的语境相符。", "很": "搭配：“很”是程度副词，不能直接修饰动词“做”，“这道菜很做才好吃”不通。", "何": "语域：“何”是书面语，口语里不说“这道菜何做好吃”。"}, "sentence_index": 6, "correct_answer": "怎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为生病，怎没来上班。", "explanation": "〈怎〉表示疑问，与“因为生病”已说明的原因相冲突，应直接说“他因为生病没来上班”。"}, {"text": "我们班怎几个人迟到了。", "explanation": "〈怎〉与“几”不能叠用两个疑问词，问数量应只用“几”。"}, {"text": "我有怎一本书。", "explanation": "〈怎〉是疑问代词，不能放在数量词前面修饰名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "怎他今天不上学？", "corrected_sentence": "他今天怎不上学？", "error_description": "词序错误：“怎”要放在主语后面、动词前面，应说“他今天怎不上学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
