INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90518, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过电话或软件呼叫出租车、网约车等。", "primary_collocate": null, "pronunciation": "jiào chē", "ipa": "tɕjɑʊ˥˩ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "我用手机软件叫车去机场。", "target_word": "叫车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，你可以在网上叫车。", "target_word": "叫车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上很晚了，我在手机上叫车回家。", "target_word": "叫车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在叫车的人太多，要等十分钟。", "target_word": "叫车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不会用软件叫车，只好打电话。", "target_word": "叫车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前我已经叫车了。", "target_word": "叫车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用这个软件叫车比较便宜。", "target_word": "叫车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国外叫车，最好先看价格。", "target_word": "叫车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你帮我叫车，好吗？", "target_word": "叫车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上叫车去公司。", "target_word": "叫车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "叫了车", "label": "体标"}, {"form": "叫过车", "label": "体标"}, {"form": "叫车软件", "label": "复合词"}], "register": "口语", "sense_fingerprint": "叫车：用电话或软件呼叫出租车、网约车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b588376-c1a7-4853-aa69-24c24846ed71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90518, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "叫车", "is_correct": true, "explanation": "“叫车”指用电话或软件呼叫出租车、网约车，是本词的意思。"}, {"text": "校车", "is_correct": false, "explanation": "xiào 与 jiào 声母不同（x 与 j），意思是学校的班车。"}, {"text": "较差", "is_correct": false, "explanation": "chà 与 chē 韵母不同，意思是比较差。"}, {"text": "交车", "is_correct": false, "explanation": "jiāo（第一声）与 jiào（第四声）声调不同，意思是把车交付给对方。"}], "explanations": {"叫车": "“叫车”指用电话或软件呼叫出租车、网约车，是本词的意思。", "校车": "xiào 与 jiào 声母不同（x 与 j），意思是学校的班车。", "较差": "chà 与 chē 韵母不同，意思是比较差。", "交车": "jiāo（第一声）与 jiào（第四声）声调不同，意思是把车交付给对方。"}, "sentence_index": null, "correct_answer": "叫车"}, "level_3": {"options": [{"text": "叫车", "is_correct": true, "explanation": "“叫车”指用电话或软件呼叫车辆，符合“用手机软件”和“去机场”的语境，是正确答案。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”与“用手机软件”不搭，句子说不通。"}, {"text": "买", "is_correct": false, "explanation": "配价：“买”后面要带所买的东西，如“买票”，这里缺少宾语，不能这样单独使用。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与“去机场”的语境冲突，不能用游泳的方式去机场。"}], "explanations": {"叫车": "“叫车”指用电话或软件呼叫车辆，符合“用手机软件”和“去机场”的语境，是正确答案。", "洗澡": "语义：“洗澡”与“用手机软件”不搭，句子说不通。", "买": "配价：“买”后面要带所买的东西，如“买票”，这里缺少宾语，不能这样单独使用。", "游泳": "语义：“游泳”与“去机场”的语境冲突，不能用游泳的方式去机场。"}, "sentence_index": 0, "correct_answer": "叫车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚饭懒得做，我就在手机上叫车吃。", "explanation": "这里应该用〈点外卖〉。叫车只指呼叫出租车、网约车，不能用于订餐。"}, {"text": "这道题太难，我叫车老师来帮我。", "explanation": "这里应该用〈请〉。叫车只指呼叫车辆，不能用来请老师帮忙。"}, {"text": "我在手机上叫车了一份披萨。", "explanation": "这里应该用〈点〉。叫车只指呼叫出租车、网约车，不能用来订披萨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
